CREATE OR REPLACE FUNCTION public.aqari_allocate_credit_forward(p_workspace_id uuid, p_credit_entry_id uuid, p_lease_id uuid, p_start_period date)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  w uuid:=p_workspace_id; credit private.aqari_tenant_ledger_entries; lease_row public.aqari_leases;
  used numeric(15,3); remaining numeric(15,3); outstanding numeric(15,3); applied numeric(15,3);
  row_data record; allocation_id uuid; allocation_count integer:=0; actor_name text;
begin
  if auth.uid() is null or not private.aqari_manager(w) or not private.aqari_can(w,'collections','write') then
    raise insufficient_privilege using message='ACCESS_DENIED';
  end if;
  perform private.aqari_require_sensitive_aal2(w);
  if p_start_period is null or p_start_period<>date_trunc('month',p_start_period)::date then
    raise exception 'CREDIT_PERIOD_REQUIRED' using errcode='23514';
  end if;

  select * into credit from private.aqari_tenant_ledger_entries
   where workspace_id=w and id=p_credit_entry_id and direction='credit' for update;
  if not found then raise exception 'CREDIT_ENTRY_REQUIRED' using errcode='23514'; end if;
  select * into lease_row from public.aqari_leases
   where workspace_id=w and id=p_lease_id and tenant_id=credit.tenant_id and status='signed' for update;
  if not found then raise exception 'CREDIT_TENANT_MISMATCH' using errcode='23514'; end if;

  perform private.aqari_refresh_rent_due_schedule(w,p_lease_id);
  select coalesce(sum(amount),0)::numeric(15,3) into used
   from private.aqari_credit_allocations where workspace_id=w and credit_entry_id=credit.id;
  remaining:=credit.amount-used;
  if remaining<=0 then
    return jsonb_build_object('allocated','0.000','remaining','0.000','allocations',0,'schedule',public.aqari_rent_due_schedule(w,p_lease_id)->'periods');
  end if;

  for row_data in
    select d.period,d.due_amount,d.paid_amount,d.credit_amount
    from private.aqari_rent_due_periods d
    where d.workspace_id=w and d.lease_id=p_lease_id and d.period>=p_start_period
    order by d.period
    for update
  loop
    exit when remaining<=0;
    outstanding:=greatest(row_data.due_amount-row_data.paid_amount-row_data.credit_amount,0);
    continue when outstanding<=0;
    perform private.aqari_financial_open(w,row_data.period);
    applied:=least(remaining,outstanding);
    allocation_id:=gen_random_uuid();
    insert into private.aqari_credit_allocations(
      id,workspace_id,credit_entry_id,lease_id,period,amount,actor_id
    ) values(allocation_id,w,credit.id,p_lease_id,row_data.period,applied,auth.uid());
    remaining:=remaining-applied;
    allocation_count:=allocation_count+1;
  end loop;

  perform private.aqari_refresh_rent_due_schedule(w,p_lease_id);
  select coalesce(nullif(display_name,''),auth.uid()::text) into actor_name
   from public.aqari_profiles where user_id=auth.uid();
  insert into private.aqari_operations_audit(
    workspace_id,domain,entity_id,action,actor_id,actor_name,reason,after_value
  ) values(
    w,'tenant_credit',credit.id,'allocate_forward',auth.uid(),coalesce(actor_name,auth.uid()::text),
    'تخصيص رصيد دائن على الاستحقاقات المستقبلية',
    jsonb_build_object('lease_id',p_lease_id,'start_period',p_start_period,'allocated',credit.amount-used-remaining,'remaining',remaining,'allocations',allocation_count)
  );

  return jsonb_build_object(
    'allocated',(credit.amount-used-remaining)::numeric(15,3),
    'remaining',remaining::numeric(15,3),
    'allocations',allocation_count,
    'schedule',public.aqari_rent_due_schedule(w,p_lease_id)->'periods'
  );
end $function$

CREATE OR REPLACE FUNCTION public.aqari_cancel_document(p_document_id uuid, p_reason text)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare target public.aqari_documents%rowtype; why text:=btrim(coalesce(p_reason,'')); actor text; after_snapshot jsonb;
begin
  if auth.uid() is null then raise insufficient_privilege using message='ACCESS_DENIED'; end if;
  select * into target from public.aqari_documents where id=p_document_id for update;
  if not found or not private.aqari_can(target.workspace_id,'documents','write')
     or not private.aqari_document_entity(target.workspace_id,target.entity_type,target.entity_ref,'write') then
    raise insufficient_privilege using message='ACCESS_DENIED';
  end if;
  if target.status='cancelled' then return target.id; end if;
  if target.status<>'draft' then raise exception 'DOCUMENT_IMMUTABLE' using errcode='23514'; end if;
  if length(why) not between 3 and 500 then raise exception 'DOCUMENT_CANCELLATION_REASON_REQUIRED' using errcode='23514'; end if;
  select coalesce(nullif(p.display_name,''),auth.uid()::text) into actor from public.aqari_profiles p where p.user_id=auth.uid();
  actor:=coalesce(actor,auth.uid()::text);
  after_snapshot:=jsonb_set(to_jsonb(target),'{status}','"cancelled"'::jsonb,false);
  insert into private.aqari_cancellation_audit(workspace_id,entity_type,entity_id,action,reason,actor_id,actor_name,before_value,after_value)
  values(target.workspace_id,'document',target.id::text,'cancel',why,auth.uid(),actor,to_jsonb(target),after_snapshot);
  update public.aqari_documents set status='cancelled' where id=target.id;
  return target.id;
end $function$

CREATE OR REPLACE FUNCTION public.aqari_compliance_register(p_workspace_id uuid, p_domain text, p_action text, p_data jsonb DEFAULT '{}'::jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
 w uuid:=p_workspace_id; d jsonb:=coalesce(p_data,'{}'); ident uuid:=nullif(p_data->>'id','')::uuid;
 actor uuid:=auth.uid(); lease_row public.aqari_leases; unit_row public.aqari_units; target_property_id uuid;
 current_revision integer; expected integer:=coalesce((d->>'revision')::integer,0);
 total numeric(15,3); allocated numeric(15,3); item jsonb; doc_id uuid; result jsonb;
begin
 if actor is null or not private.aqari_manager(w) then raise insufficient_privilege using message='ACCESS_DENIED'; end if;
 if p_domain not in ('commercial','common_charges','inspections') then raise exception 'INVALID_COMPLIANCE_DOMAIN' using errcode='22023'; end if;
 if p_action='list' then
  if not (private.aqari_can(w,'contracts','read') or private.aqari_can(w,'finance','read') or private.aqari_can(w,'maintenance','read')) then raise insufficient_privilege using message='ACCESS_DENIED'; end if;
  return jsonb_build_object(
   'leases',(select coalesce(jsonb_agg(jsonb_build_object('id',l.id,'contract_no',l.contract_no,'status',l.status,'start_date',l.start_date,'end_date',l.end_date,'unit_id',l.unit_id,'property_id',u.property_id) order by l.contract_no),'[]') from public.aqari_leases l join public.aqari_units u on u.workspace_id=l.workspace_id and u.id=l.unit_id where l.workspace_id=w),
   'properties',(select coalesce(jsonb_agg(jsonb_build_object('id',p.id,'name',p.name) order by p.name),'[]') from public.aqari_properties p where p.workspace_id=w),
   'documents',(select coalesce(jsonb_agg(jsonb_build_object('id',doc.id,'title',doc.title,'property_id',p.id) order by doc.created_at desc),'[]') from public.aqari_documents doc join public.aqari_properties p on p.workspace_id=doc.workspace_id and p.external_ref=doc.entity_ref join storage.objects o on o.bucket_id=doc.storage_bucket and o.name=doc.storage_path where doc.workspace_id=w and doc.entity_type='property' and doc.status='uploaded' and doc.checksum_sha256~'^[a-f0-9]{64}$' and doc.size_bytes>0 and (o.metadata->>'size')::bigint=doc.size_bytes),
   'commercial',(select coalesce(jsonb_agg(to_jsonb(x) order by x.lease_id),'[]') from private.aqari_commercial_terms x where x.workspace_id=w),
   'allocations',(select coalesce(jsonb_agg(to_jsonb(x) order by x.created_at desc),'[]') from private.aqari_common_charge_allocations x where x.workspace_id=w),
   'inspections',(select coalesce(jsonb_agg(to_jsonb(x) order by x.inspected_at desc),'[]') from private.aqari_unit_inspections x where x.workspace_id=w)
  );
 end if;
 perform private.aqari_require_sensitive_aal2(w);
 if ident is null then raise exception 'ID_REQUIRED' using errcode='22023'; end if;
 if p_domain='commercial' and p_action='save' then
  select l.* into lease_row from public.aqari_leases l where l.workspace_id=w and l.id=ident for update;
  if not found then raise insufficient_privilege using message='ACCESS_DENIED'; end if;
  select u.property_id into target_property_id from public.aqari_units u where u.workspace_id=w and u.id=lease_row.unit_id;
  if not private.aqari_can_property(w,target_property_id,'contracts','write') then raise insufficient_privilege using message='ACCESS_DENIED'; end if;
  if coalesce(d->>'grace_days','') !~ '^[0-9]{1,3}$'
   or coalesce(d->>'sales_percentage','') !~ '^[0-9]{1,3}(\.[0-9]{1,4})?$'
   or coalesce(d->>'cam_amount','') !~ '^[0-9]{1,9}(\.[0-9]{1,3})?$'
   or length(btrim(coalesce(d->>'permitted_activity','')))<2 or length(btrim(coalesce(d->>'license_no','')))<2
   or coalesce((d->>'grace_days')::integer,-1) not between 0 and 366
   or coalesce((d->>'sales_percentage')::numeric,-1) not between 0 and 100
   or coalesce((d->>'cam_amount')::numeric,-1)<0
   or length(btrim(coalesce(d->>'compliance_reference','')))<5
  then raise exception 'INVALID_COMMERCIAL_TERMS' using errcode='22023'; end if;
  select revision into current_revision from private.aqari_commercial_terms where workspace_id=w and lease_id=ident for update;
  if (found and current_revision<>expected) or (not found and expected<>0) then raise serialization_failure using message='REVISION_CONFLICT'; end if;
  insert into private.aqari_commercial_terms(lease_id,workspace_id,grace_days,sales_percentage,cam_amount,permitted_activity,license_no,license_expires_on,compliance_reviewed_by,compliance_reviewed_at,compliance_reference)
  values(ident,w,(d->>'grace_days')::integer,(d->>'sales_percentage')::numeric,(d->>'cam_amount')::numeric,btrim(d->>'permitted_activity'),btrim(d->>'license_no'),nullif(d->>'license_expires_on','')::date,actor,now(),btrim(d->>'compliance_reference'))
  on conflict(lease_id) do update set grace_days=excluded.grace_days,sales_percentage=excluded.sales_percentage,cam_amount=excluded.cam_amount,permitted_activity=excluded.permitted_activity,license_no=excluded.license_no,license_expires_on=excluded.license_expires_on,compliance_reviewed_by=actor,compliance_reviewed_at=now(),compliance_reference=excluded.compliance_reference,revision=aqari_commercial_terms.revision+1
  returning to_jsonb(aqari_commercial_terms) into result;
  insert into private.aqari_operations_audit(workspace_id,domain,entity_id,action,actor_id,actor_name,reason,after_value) values(w,p_domain,ident,p_action,actor,coalesce(auth.jwt()->>'email',actor::text),btrim(d->>'compliance_reference'),result);
  return result;
 elsif p_domain='common_charges' and p_action='allocate' then
  target_property_id:=nullif(d->>'property_id','')::uuid; total:=private.aqari_hr_money(d->'total_amount');
  if not private.aqari_can_property(w,target_property_id,'finance','write') then raise insufficient_privilege using message='ACCESS_DENIED'; end if;
  perform private.aqari_financial_open(w,(now() at time zone 'Asia/Kuwait')::date);
  if d->>'basis' not in ('area','consumption') or length(btrim(coalesce(d->>'invoice_reference','')))<3 or jsonb_typeof(d->'allocations')<>'array' or jsonb_array_length(d->'allocations')=0 then raise exception 'INVALID_COMMON_CHARGE' using errcode='22023'; end if;
  if (select count(*)<>count(distinct x->>'unit_id') from jsonb_array_elements(d->'allocations') x) then raise exception 'DUPLICATE_ALLOCATION_UNIT' using errcode='23505'; end if;
  allocated:=0;
  for item in select value from jsonb_array_elements(d->'allocations') loop
   select * into unit_row from public.aqari_units u where u.workspace_id=w and u.id=(item->>'unit_id')::uuid and u.property_id=target_property_id;
   if not found or private.aqari_hr_money(item->'amount')<=0 then raise exception 'INVALID_ALLOCATION_LINE' using errcode='22023'; end if;
   allocated:=allocated+private.aqari_hr_money(item->'amount');
  end loop;
  if allocated<>total then raise exception 'ALLOCATION_TOTAL_MISMATCH' using errcode='23514'; end if;
  insert into private.aqari_common_charge_allocations(id,workspace_id,property_id,invoice_reference,basis,total_amount,allocations,approved_by,approved_at)
  values(ident,w,target_property_id,btrim(d->>'invoice_reference'),d->>'basis',total,d->'allocations',actor,now());
  for item in select value from jsonb_array_elements(d->'allocations') loop
   select l.* into lease_row from public.aqari_leases l where l.workspace_id=w and l.unit_id=(item->>'unit_id')::uuid and l.status='signed' and l.start_date<=(now() at time zone 'Asia/Kuwait')::date and l.end_date>=(now() at time zone 'Asia/Kuwait')::date for share;
   if not found then raise exception 'ACTIVE_LEASE_REQUIRED_FOR_ALLOCATION' using errcode='23514'; end if;
   insert into private.aqari_tenant_adjustments(id,workspace_id,lease_id,kind,direction,amount,occurred_on,source_type,source_id,reason,actor_id)
   values(gen_random_uuid(),w,lease_row.id,'common_charge','debit',private.aqari_hr_money(item->'amount'),(now() at time zone 'Asia/Kuwait')::date,'common_charge:'||(item->>'unit_id'),ident,'توزيع فاتورة خدمات '||btrim(d->>'invoice_reference'),actor);
  end loop;
  select to_jsonb(x) into result from private.aqari_common_charge_allocations x where x.id=ident; insert into private.aqari_operations_audit(workspace_id,domain,entity_id,action,actor_id,actor_name,reason,after_value) values(w,p_domain,ident,p_action,actor,coalesce(auth.jwt()->>'email',actor::text),btrim(d->>'invoice_reference'),result); return result;
 elsif p_domain='inspections' and p_action='create' then
  select l.* into lease_row from public.aqari_leases l where l.workspace_id=w and l.id=(d->>'lease_id')::uuid;
  select u.* into unit_row from public.aqari_units u where u.workspace_id=w and u.id=lease_row.unit_id;
  target_property_id:=unit_row.property_id;
  if not private.aqari_can_property(w,target_property_id,'maintenance','write') or d->>'kind' not in ('move_in','periodic','renewal','move_out') or jsonb_typeof(d->'checklist')<>'array' or jsonb_array_length(d->'checklist')=0 then raise exception 'INVALID_INSPECTION' using errcode='22023'; end if;
  for item in select value from jsonb_array_elements(coalesce(d->'photo_document_ids','[]')) loop
   if not private.aqari_operations_document(w,target_property_id,trim(both '"' from item::text)::uuid) then raise exception 'INSPECTION_PHOTO_UNVERIFIED' using errcode='23514'; end if;
  end loop;
  insert into private.aqari_unit_inspections(id,workspace_id,lease_id,unit_id,kind,inspected_at,checklist,photo_document_ids)
  values(ident,w,lease_row.id,unit_row.id,d->>'kind',coalesce(nullif(d->>'inspected_at','')::timestamptz,now()),d->'checklist',coalesce(d->'photo_document_ids','[]')) returning to_jsonb(aqari_unit_inspections) into result; insert into private.aqari_operations_audit(workspace_id,domain,entity_id,action,actor_id,actor_name,reason,after_value) values(w,p_domain,ident,p_action,actor,coalesce(auth.jwt()->>'email',actor::text),'inspection draft',result); return result;
 elsif p_domain='inspections' and p_action='sign' then
  select i.revision,u.property_id into current_revision,target_property_id from private.aqari_unit_inspections i join public.aqari_units u on u.workspace_id=i.workspace_id and u.id=i.unit_id where i.workspace_id=w and i.id=ident and i.status='draft' for update of i;
  if not found or current_revision<>expected then raise serialization_failure using message='INSPECTION_REVISION_CONFLICT'; end if;
  doc_id:=nullif(d->>'tenant_signature_document_id','')::uuid;
  if not private.aqari_operations_document(w,target_property_id,doc_id) or not private.aqari_operations_document(w,target_property_id,nullif(d->>'inspector_signature_document_id','')::uuid) then raise exception 'SIGNATURE_DOCUMENT_UNVERIFIED' using errcode='23514'; end if;
  update private.aqari_unit_inspections set status='signed',tenant_signature_document_id=doc_id,inspector_signature_document_id=(d->>'inspector_signature_document_id')::uuid,signed_by=actor,signed_at=now(),revision=revision+1 where id=ident returning to_jsonb(aqari_unit_inspections) into result; insert into private.aqari_operations_audit(workspace_id,domain,entity_id,action,actor_id,actor_name,reason,after_value) values(w,p_domain,ident,p_action,actor,coalesce(auth.jwt()->>'email',actor::text),'inspection signed',result); return result;
 else raise exception 'INVALID_COMPLIANCE_ACTION' using errcode='22023'; end if;
end $function$

CREATE OR REPLACE FUNCTION public.aqari_control_center(p_workspace_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare c jsonb;
begin
 if not private.aqari_manager(p_workspace_id) then raise exception 'ACCESS_DENIED' using errcode='42501';end if;
 select to_jsonb(x) into c from public.aqari_workspace_controls x where workspace_id=p_workspace_id;
 return jsonb_build_object('control',coalesce(c,jsonb_build_object('workspace_id',p_workspace_id,'settings','{"sections":{},"permissions":{},"labels":{}}'::jsonb,'revision',0)),
 'members',(select coalesce(jsonb_agg(jsonb_build_object('user_id',m.user_id,'role',m.role,'is_active',m.is_active,'display_name',p.display_name) order by m.created_at),'[]') from public.aqari_memberships m left join public.aqari_profiles p on p.user_id=m.user_id where m.workspace_id=p_workspace_id));
end $function$

CREATE OR REPLACE FUNCTION public.aqari_deposit_register(p_workspace_id uuid, p_action text, p_data jsonb DEFAULT '{}'::jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare w uuid:=p_workspace_id;d jsonb:=p_data;action text:=p_action;k text;allowed text[];ident uuid;lid uuid;
 e private.aqari_deposit_entries;contract public.aqari_leases;lease_json jsonb;normalized jsonb;amount_value numeric;v_date date;
 v_method text;v_ref text;why text;v_kind text;actor text;available numeric;rows jsonb;options jsonb;v_seq text;minimum_balance numeric;maximum_balance numeric;
begin
 if auth.uid() is null or not private.aqari_can(w,'collections','read') then raise insufficient_privilege using message='ACCESS_DENIED';end if;
 if d is null or jsonb_typeof(d)<>'object' or octet_length(d::text)>8000 then raise exception 'DEPOSIT_INVALID_DATA' using errcode='22023';end if;
 allowed:=case action when 'list' then array['lease_id'] when 'get' then array['id']
  when 'receive' then array['id','lease_id','amount','on_date','method','reference','reason']
  when 'refund' then array['id','lease_id','amount','on_date','method','reference','reason'] else null end;
 if allowed is null then raise exception 'DEPOSIT_UNKNOWN_ACTION' using errcode='22023';end if;
 for k in select jsonb_object_keys(d) loop if not(k=any(allowed)) then raise exception 'DEPOSIT_UNKNOWN_FIELD' using errcode='22023';end if;end loop;
 if action='list' then
  if d ? 'lease_id' then
   if jsonb_typeof(d->'lease_id')<>'string' then raise exception 'DEPOSIT_INVALID_LEASE' using errcode='22023';end if;
   lid:=(d->>'lease_id')::uuid;
   if not private.aqari_can_lease(w,lid,'collections','read') then raise insufficient_privilege using message='ACCESS_DENIED';end if;
  end if;
  if (select count(*) from public.aqari_leases l where l.workspace_id=w and private.aqari_can_lease(w,l.id,'collections','read'))>2000 then raise exception 'DEPOSIT_LIST_LIMIT' using errcode='22023';end if;
  select coalesce(jsonb_agg(private.aqari_deposit_lease_json(w,l.id) order by l.contract_no,l.id),'[]') into options
   from public.aqari_leases l where l.workspace_id=w and private.aqari_can_lease(w,l.id,'collections','read');
  if (select count(*) from private.aqari_deposit_entries x where x.workspace_id=w and x.lease_id=lid)>2000 then raise exception 'DEPOSIT_HISTORY_LIMIT' using errcode='22023';end if;
  select coalesce(jsonb_agg(private.aqari_deposit_entry_json(x) order by x.created_at desc,x.id),'[]') into rows
   from private.aqari_deposit_entries x where x.workspace_id=w and x.lease_id=lid;
  return jsonb_build_object('manager',private.aqari_manager(w),'leases',options,'entries',rows);
 end if;
 if jsonb_typeof(d->'id') is distinct from 'string' or nullif(d->>'id','') is null then raise exception 'DEPOSIT_INVALID_REQUEST_ID' using errcode='22023';end if;
 ident:=(d->>'id')::uuid;
 if action='get' then
  select * into e from private.aqari_deposit_entries x where x.workspace_id=w and x.id=ident;
  if not found then return jsonb_build_object('entry',null,'lease',null);end if;
  if not private.aqari_can_lease(w,e.lease_id,'collections','read') then raise insufficient_privilege using message='ACCESS_DENIED';end if;
  return jsonb_build_object('entry',private.aqari_deposit_entry_json(e),'lease',private.aqari_deposit_lease_json(w,e.lease_id));
 end if;
 if jsonb_typeof(d->'lease_id') is distinct from 'string' then raise exception 'DEPOSIT_INVALID_LEASE' using errcode='22023';end if;
 lid:=(d->>'lease_id')::uuid;
 if not private.aqari_can_lease(w,lid,'collections','write') or (action='refund' and not private.aqari_manager(w)) then raise insufficient_privilege using message='ACCESS_DENIED';end if;
 if jsonb_typeof(d->'amount') is distinct from 'string' or d->>'amount' !~ '^[0-9]{1,12}(\.[0-9]{1,3})?$' then raise exception 'DEPOSIT_INVALID_AMOUNT' using errcode='22023';end if;
 amount_value:=(d->>'amount')::numeric;
 if amount_value<=0 or amount_value>999999999999.999 then raise exception 'DEPOSIT_INVALID_AMOUNT' using errcode='22023';end if;
 if jsonb_typeof(d->'on_date') is distinct from 'string' or d->>'on_date' !~ '^\d{4}-\d{2}-\d{2}$' then raise exception 'DEPOSIT_INVALID_DATE' using errcode='22023';end if;
 v_date:=(d->>'on_date')::date;
 if v_date>(now() at time zone 'Asia/Kuwait')::date then raise exception 'DEPOSIT_FUTURE_DATE' using errcode='22023';end if;
 if jsonb_typeof(d->'method') is distinct from 'string' or d->>'method' not in ('cash','knet','bank','cheque') then raise exception 'DEPOSIT_INVALID_METHOD' using errcode='22023';end if;
 v_method:=d->>'method';
 if d ? 'reference' and jsonb_typeof(d->'reference') is distinct from 'string' then raise exception 'DEPOSIT_INVALID_REFERENCE' using errcode='22023';end if;
 if d ? 'reason' and jsonb_typeof(d->'reason') is distinct from 'string' then raise exception 'DEPOSIT_INVALID_REASON' using errcode='22023';end if;
 v_ref:=btrim(coalesce(d->>'reference',''));why:=btrim(coalesce(d->>'reason',''));
 if length(v_ref)>120 or (v_method<>'cash' and length(v_ref)<3) then raise exception 'DEPOSIT_INVALID_REFERENCE' using errcode='22023';end if;
 if length(why)>500 or (action='refund' and length(why)<3) then raise exception 'DEPOSIT_INVALID_REASON' using errcode='22023';end if;
 v_kind:=case action when 'receive' then 'receipt' else 'refund' end;
 normalized:=jsonb_build_object('id',ident,'lease_id',lid,'kind',v_kind,'amount',amount_value::numeric(15,3)::text,
  'on_date',v_date,'method',v_method,'reference',v_ref,'reason',why);
 perform 1 from public.aqari_app_state where workspace_id=w for update;
 if not found then raise exception 'DEPOSIT_WORKSPACE_UNAVAILABLE' using errcode='22023';end if;
 select * into contract from public.aqari_leases l where l.workspace_id=w and l.id=lid for update;
 if not found or not private.aqari_can_lease(w,lid,'collections','write') or (action='refund' and not private.aqari_manager(w)) then raise insufficient_privilege using message='ACCESS_DENIED';end if;
 select * into e from private.aqari_deposit_entries x where x.workspace_id=w and x.id=ident;
 if found then
  if e.actor_id<>auth.uid() or e.request_data<>normalized then raise exception 'DEPOSIT_REQUEST_CONFLICT' using errcode='22023';end if;
  return jsonb_build_object('entry',private.aqari_deposit_entry_json(e),'lease',private.aqari_deposit_lease_json(w,lid));
 end if;
 begin
  perform private.aqari_financial_open(w,v_date);
 exception when raise_exception then
  if sqlerrm='الفترة المالية مقفلة؛ لا يمكن تسجيل أو تغيير عملية فيها.' then raise exception 'DEPOSIT_PERIOD_CLOSED' using errcode='22023';end if;
  raise;
 end;
 if action='receive' and contract.status<>'signed' then raise exception 'DEPOSIT_SIGNED_CONTRACT_REQUIRED' using errcode='22023';end if;
 if action='receive' and contract.deposit is null then raise exception 'DEPOSIT_DOCUMENTED_AMOUNT_REQUIRED' using errcode='22023';end if;
 lease_json:=private.aqari_deposit_lease_json(w,lid);available:=(lease_json->>'balance')::numeric;
 if action='refund' and amount_value>available then raise exception 'DEPOSIT_REFUND_EXCEEDS_BALANCE' using errcode='22023';end if;
 with dates as (select x.on_date,sum(case x.kind when 'receipt' then x.amount else -x.amount end) delta from private.aqari_deposit_entries x where x.workspace_id=w and x.lease_id=lid group by x.on_date
   union all select v_date,0::numeric), daily as(select on_date,sum(delta) delta from dates group by on_date),
   running as(select on_date,sum(delta) over(order by on_date rows unbounded preceding) balance from daily)
  select min(balance),max(balance) into minimum_balance,maximum_balance from running where on_date>=v_date;
 if action='refund' and amount_value>coalesce(minimum_balance,0) then raise exception 'DEPOSIT_REFUND_DATE_BALANCE' using errcode='22023';end if;
 if action='receive' and coalesce(maximum_balance,0)+amount_value>contract.deposit then raise exception 'DEPOSIT_RECEIPT_EXCEEDS_CONTRACT' using errcode='22023';end if;
 if action='receive' and available+amount_value>contract.deposit then raise exception 'DEPOSIT_RECEIPT_EXCEEDS_CONTRACT' using errcode='22023';end if;
 if v_method<>'cash' and exists(select 1 from private.aqari_deposit_entries x where x.workspace_id=w and x.kind=v_kind and x.method=v_method and lower(x.reference)=lower(v_ref)) then raise exception 'DEPOSIT_REFERENCE_EXISTS' using errcode='22023';end if;
 select coalesce(nullif(p.display_name,''),auth.uid()::text) into actor from public.aqari_profiles p where p.user_id=auth.uid();
 v_seq:=nextval('private.aqari_deposit_voucher_seq')::text;
 insert into private.aqari_deposit_entries(id,workspace_id,lease_id,kind,voucher_no,amount,on_date,method,reference,reason,actor_id,actor_name,snapshot,balance_after,request_data)
 values(ident,w,lid,v_kind,(case action when 'receive' then 'DP-' else 'DF-' end)||to_char(v_date,'YYYYMMDD')||'-'||repeat('0',greatest(0,8-length(v_seq)))||v_seq,
  amount_value,v_date,v_method,v_ref,why,auth.uid(),coalesce(actor,auth.uid()::text),
  jsonb_build_object('lease_id',lid,'contract_no',lease_json->>'contract_no','tenant_id',lease_json->>'tenant_id','tenant_name',lease_json->>'tenant_name',
   'property_id',lease_json->>'property_id','property_name',lease_json->>'property_name','unit_id',lease_json->>'unit_id','unit_no',lease_json->>'unit_no'),
  available+(case action when 'receive' then amount_value else -amount_value end),normalized) returning * into e;
 return jsonb_build_object('entry',private.aqari_deposit_entry_json(e),'lease',private.aqari_deposit_lease_json(w,lid));
end $function$

CREATE OR REPLACE FUNCTION public.aqari_document_entities(p_workspace_id uuid, p_type text, p_query text DEFAULT ''::text)
 RETURNS TABLE(entity_ref text, title text)
 LANGUAGE plpgsql
 STABLE
 SET search_path TO ''
AS $function$
begin
 if not private.aqari_can(p_workspace_id,'documents','read') then raise exception 'ACCESS_DENIED' using errcode='42501';end if;
 if length(coalesce(p_query,''))>100 then raise exception 'INVALID_QUERY';end if;
 if p_type='property' then return query select p.external_ref,p.name from public.aqari_properties p where p.workspace_id=p_workspace_id and (p_query='' or strpos(lower(p.name),lower(p_query))>0) order by p.name,p.id limit 50;
 elsif p_type='tenant' then return query select t.external_ref,t.full_name from public.aqari_tenants t where t.workspace_id=p_workspace_id and (p_query='' or strpos(lower(t.full_name),lower(p_query))>0 or strpos(t.civil_id,p_query)>0) order by t.full_name,t.id limit 50;
 elsif p_type='lease' then return query select l.external_ref,l.contract_no||' • '||coalesce(l.snapshot->>'property','')||' • '||coalesce(l.snapshot->>'unit','') from public.aqari_leases l where l.workspace_id=p_workspace_id and (p_query='' or strpos(lower(l.contract_no||' '||coalesce(l.snapshot->>'tenant','')||' '||coalesce(l.snapshot->>'unit','')),lower(p_query))>0) order by l.contract_no,l.id limit 50;
 else raise exception 'INVALID_ENTITY_TYPE';end if;
end $function$

CREATE OR REPLACE FUNCTION public.aqari_document_handoff(p_workspace_id uuid, p_document_id uuid, p_action text, p_data jsonb DEFAULT '{}'::jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare d public.aqari_documents%rowtype; saved_handoff public.aqari_document_handoffs%rowtype; actor uuid:=auth.uid(); dir text; delivered text; received text; at_time timestamptz; memo text;
begin
 if actor is null then raise exception 'AUTH_REQUIRED' using errcode='42501'; end if;
 select * into d from public.aqari_documents where id=p_document_id and workspace_id=p_workspace_id;
 if d.id is null then raise exception 'DOCUMENT_NOT_FOUND'; end if;
 if not private.aqari_can(p_workspace_id,'documents','read') or not private.aqari_document_entity(p_workspace_id,d.entity_type,d.entity_ref,'read') then raise exception 'ACCESS_DENIED' using errcode='42501'; end if;
 if p_action='list' then
  return (select coalesce(jsonb_agg(to_jsonb(x)),'[]'::jsonb) from (
   select hh.id,hh.document_id,hh.document_no,hh.direction,hh.delivered_by_name,hh.received_by_name,hh.handed_at,hh.note,hh.recorded_by,hh.recorded_at,coalesce(p.display_name,'مستخدم محفوظ') recorded_by_name
   from public.aqari_document_handoffs hh left join public.aqari_profiles p on p.user_id=hh.recorded_by
   where hh.workspace_id=p_workspace_id and hh.document_id=p_document_id order by hh.handed_at desc,hh.id desc limit 100
  ) x);
 end if;
 if p_action<>'record' then raise exception 'INVALID_ACTION'; end if;
 if d.status<>'uploaded' then raise exception 'UPLOADED_DOCUMENT_REQUIRED'; end if;
 if not private.aqari_can(p_workspace_id,'documents','write') or not private.aqari_document_entity(p_workspace_id,d.entity_type,d.entity_ref,'write') then raise exception 'ACCESS_DENIED' using errcode='42501'; end if;
 dir:=coalesce(p_data->>'direction',''); delivered:=btrim(coalesce(p_data->>'delivered_by_name','')); received:=btrim(coalesce(p_data->>'received_by_name','')); memo:=btrim(coalesce(p_data->>'note',''));
 begin at_time:=(p_data->>'handed_at')::timestamptz; exception when others then raise exception 'INVALID_HANDED_AT'; end;
 if dir not in ('received','delivered','returned') then raise exception 'INVALID_DIRECTION'; end if;
 if length(delivered)<2 or length(delivered)>180 then raise exception 'INVALID_DELIVERED_BY'; end if;
 if length(received)<2 or length(received)>180 then raise exception 'INVALID_RECEIVED_BY'; end if;
 if at_time is null or at_time>now()+interval '5 minutes' then raise exception 'INVALID_HANDED_AT'; end if;
 if length(memo)>2000 then raise exception 'NOTE_TOO_LONG'; end if;
 insert into public.aqari_document_handoffs(workspace_id,document_id,entity_type,entity_ref,document_no,direction,delivered_by_name,received_by_name,handed_at,note,recorded_by)
 values(p_workspace_id,d.id,d.entity_type,d.entity_ref,d.document_no,dir,delivered,received,at_time,memo,actor) returning * into saved_handoff;
 return jsonb_build_object('id',saved_handoff.id,'document_id',saved_handoff.document_id,'document_no',saved_handoff.document_no,'direction',saved_handoff.direction,'delivered_by_name',saved_handoff.delivered_by_name,'received_by_name',saved_handoff.received_by_name,'handed_at',saved_handoff.handed_at,'note',saved_handoff.note,'recorded_by',saved_handoff.recorded_by,'recorded_at',saved_handoff.recorded_at);
end $function$

CREATE OR REPLACE FUNCTION public.aqari_document_listing(p_workspace_id uuid, p_entity_type text, p_entity_ref text, p_page integer DEFAULT 0)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
begin
 if not private.aqari_can(p_workspace_id,'documents','read') or not private.aqari_document_entity(p_workspace_id,p_entity_type,p_entity_ref,'read') then raise exception 'ACCESS_DENIED' using errcode='42501';end if;
 if p_page is null or p_page<0 or p_page>10000 then raise exception 'INVALID_PAGE';end if;
 return (select coalesce(jsonb_agg(to_jsonb(rows)),'[]') from (
  select d.id,d.document_no,d.document_type,d.title,d.entity_type,d.entity_ref,d.status,d.created_by,d.created_at,d.uploaded_at,d.storage_path,d.mime_type,d.size_bytes,d.metadata,p.display_name as author_name
  from public.aqari_documents d left join public.aqari_profiles p on p.user_id=d.created_by
  where d.workspace_id=p_workspace_id and d.entity_type=p_entity_type and d.entity_ref=p_entity_ref
  order by d.created_at desc,d.id desc limit 20 offset p_page*20
 ) rows);
end $function$

CREATE OR REPLACE FUNCTION public.aqari_exit_review(p_workspace_id uuid, p_action text, p_data jsonb DEFAULT '{}'::jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare w uuid:=p_workspace_id;d jsonb:=p_data;allowed text[];k text;lid uuid;req uuid;rev integer;
 c public.aqari_leases;e private.aqari_exit_reviews;doc uuid;v_date date;why text;normalized jsonb;
 checks_value jsonb;item jsonb;actor text;snap jsonb;seq_value text;rows jsonb;
begin
 -- Settlement review contains financial records; contract visibility alone is insufficient.
 if auth.uid() is null or not private.aqari_manager(w) or not private.aqari_can(w,'contracts','read')
  or not private.aqari_can(w,'collections','read') or not private.aqari_can(w,'finance','read')
  or not private.aqari_can(w,'documents','read') then raise insufficient_privilege using message='ACCESS_DENIED';end if;
 if d is null or jsonb_typeof(d)<>'object' or octet_length(d::text)>12000 then raise exception 'EXIT_INVALID_DATA' using errcode='22023';end if;
 allowed:=case p_action when 'list' then array['lease_id'] when 'get' then array['request_id']
  when 'save' then array['request_id','lease_id','revision','vacate_on','reason','document_id','checks'] else null end;
 if allowed is null then raise exception 'EXIT_UNKNOWN_ACTION' using errcode='22023';end if;
 for k in select jsonb_object_keys(d) loop if not(k=any(allowed)) then raise exception 'EXIT_UNKNOWN_FIELD' using errcode='22023';end if;end loop;
 if p_action='get' then
  if jsonb_typeof(d->'request_id') is distinct from 'string' then raise exception 'EXIT_INVALID_REQUEST' using errcode='22023';end if;
  req:=(d->>'request_id')::uuid;
  select * into e from private.aqari_exit_reviews x where x.workspace_id=w and x.request_id=req;
  if not found then return jsonb_build_object('entry',null);end if;
  if not private.aqari_can_lease(w,e.lease_id,'contracts','read') then raise insufficient_privilege using message='ACCESS_DENIED';end if;
  return jsonb_build_object('entry',to_jsonb(e)-'request_data');
 end if;
 if d ? 'lease_id' then
  if jsonb_typeof(d->'lease_id') is distinct from 'string' then raise exception 'EXIT_INVALID_LEASE' using errcode='22023';end if;
  lid:=(d->>'lease_id')::uuid;
  if not private.aqari_can_lease(w,lid,'contracts','read') then raise insufficient_privilege using message='ACCESS_DENIED';end if;
 end if;
 if p_action='list' then
  if (select count(*) from public.aqari_leases l where l.workspace_id=w and private.aqari_can_lease(w,l.id,'contracts','read'))>2000
   or (select count(*) from private.aqari_exit_reviews x where x.workspace_id=w and x.lease_id=lid)>2000 then raise exception 'EXIT_LIST_LIMIT' using errcode='22023';end if;
  select coalesce(jsonb_agg(to_jsonb(x)-'request_data' order by x.revision desc),'[]') into rows from private.aqari_exit_reviews x where x.workspace_id=w and x.lease_id=lid;
  return jsonb_build_object('can_write',private.aqari_can(w,'contracts','write'),
   'leases',coalesce((select jsonb_agg(jsonb_build_object('id',l.id,'contract_no',l.contract_no,'tenant_name',t.full_name,'property_name',p.name,'unit_no',u.unit_no,'start_date',l.start_date,'status',l.status) order by l.contract_no,l.id)
    from public.aqari_leases l join public.aqari_tenants t on t.workspace_id=w and t.id=l.tenant_id
    join public.aqari_units u on u.workspace_id=w and u.id=l.unit_id join public.aqari_properties p on p.workspace_id=w and p.id=u.property_id
    where l.workspace_id=w and private.aqari_can_lease(w,l.id,'contracts','read')),'[]'),
   'documents',coalesce((select jsonb_agg(jsonb_build_object('id',x.id,'title',x.title,'document_no',x.document_no) order by x.created_at desc,x.id)
    from public.aqari_documents x join public.aqari_leases l on l.workspace_id=w and l.id=lid and x.entity_ref=l.external_ref
    where x.workspace_id=w and x.entity_type='lease' and x.status='uploaded' and private.aqari_document_entity(w,'lease',x.entity_ref,'read')),'[]'),
   'entries',rows);
 end if;
 if lid is null or not private.aqari_can_lease(w,lid,'contracts','write') then raise insufficient_privilege using message='ACCESS_DENIED';end if;
 if jsonb_typeof(d->'request_id') is distinct from 'string' then raise exception 'EXIT_INVALID_REQUEST' using errcode='22023';end if;
 req:=(d->>'request_id')::uuid;
 if jsonb_typeof(d->'revision') is distinct from 'number' or d->>'revision' !~ '^[0-9]{1,8}$' then raise exception 'EXIT_INVALID_REVISION' using errcode='22023';end if;
 rev:=(d->>'revision')::integer;
 if jsonb_typeof(d->'vacate_on') is distinct from 'string' or d->>'vacate_on' !~ '^\d{4}-\d{2}-\d{2}$' then raise exception 'EXIT_INVALID_DATE' using errcode='22023';end if;
 v_date:=(d->>'vacate_on')::date;
 if jsonb_typeof(d->'reason') is distinct from 'string' or length(btrim(d->>'reason')) not between 3 and 1000 then raise exception 'EXIT_INVALID_REASON' using errcode='22023';end if;
 why:=btrim(d->>'reason');
 if d->'document_id' is not null and d->'document_id'<>'null'::jsonb then
  if jsonb_typeof(d->'document_id')<>'string' then raise exception 'EXIT_INVALID_DOCUMENT' using errcode='22023';end if;
  doc:=(d->>'document_id')::uuid;
 end if;
 checks_value:=d->'checks';
 if jsonb_typeof(checks_value) is distinct from 'object' or (select count(*) from jsonb_object_keys(checks_value))<>6 then raise exception 'EXIT_INVALID_CHECKS' using errcode='22023';end if;
 foreach k in array array['rent','deposit','utilities','maintenance','keys','other'] loop
  item:=checks_value->k;
  if item is null or jsonb_typeof(item)<>'object' or (select array_agg(key order by key) from jsonb_object_keys(item) key) is distinct from array['note','status']
   or jsonb_typeof(item->'status') is distinct from 'string' or item->>'status' not in ('pending','reviewed','outstanding')
   or jsonb_typeof(item->'note') is distinct from 'string' or length(item->>'note')>500
   or (item->>'status'<>'pending' and length(btrim(item->>'note'))<3) then raise exception 'EXIT_INVALID_CHECKS' using errcode='22023';end if;
 end loop;
 normalized:=jsonb_build_object('request_id',req,'lease_id',lid,'revision',rev,'vacate_on',v_date,'reason',why,'document_id',doc,'checks',checks_value);
 -- Same lock order as rent/deposit writes. Retry identity checked before a later lease change.
 perform 1 from public.aqari_app_state where workspace_id=w for update;
 if not found then raise exception 'EXIT_WORKSPACE_UNAVAILABLE' using errcode='22023';end if;
 select * into c from public.aqari_leases l where l.workspace_id=w and l.id=lid for update;
 if not found or not private.aqari_manager(w) or not private.aqari_can_lease(w,lid,'contracts','write') then raise insufficient_privilege using message='ACCESS_DENIED';end if;
 select * into e from private.aqari_exit_reviews x where x.workspace_id=w and x.request_id=req;
 if found then
  if e.actor_id<>auth.uid() or e.request_data<>normalized then raise exception 'EXIT_REQUEST_CONFLICT' using errcode='22023';end if;
  return jsonb_build_object('entry',to_jsonb(e)-'request_data');
 end if;
 if c.status not in ('signed','expired') then raise exception 'EXIT_CONTRACT_REQUIRED' using errcode='22023';end if;
 if v_date<c.start_date then raise exception 'EXIT_BEFORE_CONTRACT' using errcode='22023';end if;
 if rev<>(select coalesce(max(x.revision),0) from private.aqari_exit_reviews x where x.workspace_id=w and x.lease_id=lid) then raise exception 'EXIT_STALE_REVISION' using errcode='22023';end if;
 if doc is not null and not exists(select 1 from public.aqari_documents x where x.id=doc and x.workspace_id=w and x.entity_type='lease'
  and x.entity_ref=c.external_ref and x.status='uploaded' and private.aqari_document_entity(w,'lease',x.entity_ref,'read')) then raise exception 'EXIT_INVALID_DOCUMENT' using errcode='22023';end if;
 select jsonb_build_object('lease_id',c.id,'contract_no',c.contract_no,'tenant_id',t.id,'tenant_name',t.full_name,
  'property_id',p.id,'property_name',p.name,'unit_id',u.id,'unit_no',u.unit_no,'start_date',c.start_date,'end_date',c.end_date,
  'lease_status',c.status,'contract_deposit',c.deposit::text,
  'rent_payments_total',coalesce((select sum(r.amount) from public.aqari_rent_payments r where r.workspace_id=w and r.lease_id=lid and r.status in ('مدفوع','جزئي','paid','partial')),0)::numeric(18,3)::text,
  'deposit_balance',coalesce((select sum(case x.kind when 'receipt' then x.amount else -x.amount end) from private.aqari_deposit_entries x where x.workspace_id=w and x.lease_id=lid),0)::numeric(18,3)::text,
  'document',case when doc is null then null else (select jsonb_build_object('id',x.id,'document_no',x.document_no,'title',x.title,'checksum_sha256',x.checksum_sha256) from public.aqari_documents x where x.id=doc and x.workspace_id=w) end,
  'clearance_issued',false,'lease_terminated',false,'final_balance_verified',false)
 into snap from public.aqari_tenants t join public.aqari_units u on u.workspace_id=w and u.id=c.unit_id
 join public.aqari_properties p on p.workspace_id=w and p.id=u.property_id where t.workspace_id=w and t.id=c.tenant_id;
 select coalesce(nullif(p.display_name,''),auth.uid()::text) into actor from public.aqari_profiles p where p.user_id=auth.uid();
 seq_value:=nextval('private.aqari_exit_review_seq')::text;
 insert into private.aqari_exit_reviews(id,workspace_id,lease_id,revision,request_id,document_no,vacate_on,reason,document_id,checks,snapshot,actor_id,actor_name,request_data)
 values(gen_random_uuid(),w,lid,rev+1,req,'EX-'||repeat('0',greatest(0,8-length(seq_value)))||seq_value,v_date,why,doc,checks_value,snap,auth.uid(),coalesce(actor,auth.uid()::text),normalized) returning * into e;
 return jsonb_build_object('entry',to_jsonb(e)-'request_data');
end $function$

CREATE OR REPLACE FUNCTION public.aqari_external_integrations(p_workspace_id uuid, p_action text, p_data jsonb DEFAULT '{}'::jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare w uuid:=p_workspace_id;d jsonb:=p_data;row private.aqari_integration_configs;expected integer;ident uuid;
begin
 if auth.uid() is null or not private.aqari_manager(w) then raise insufficient_privilege using message='ACCESS_DENIED';end if;
 if p_action not in('list','save','enqueue_test') or d is null or jsonb_typeof(d)<>'object' or octet_length(d::text)>32000 then raise exception 'INVALID_INTEGRATION_REQUEST' using errcode='22023';end if;
 if p_action='list' then return jsonb_build_object('configs',coalesce((select jsonb_agg(jsonb_build_object('id',c.id,'provider',c.provider,'purpose',c.purpose,'mode',c.mode,'endpoint_origin',c.endpoint_origin,'secret_reference',c.secret_reference,'public_metadata',c.public_metadata,'revision',c.revision,'updated_at',c.updated_at) order by c.provider,c.purpose) from private.aqari_integration_configs c where c.workspace_id=w),'[]'::jsonb),'outbox',coalesce((select jsonb_agg(to_jsonb(x) order by x.created_at desc) from(select id,event_type,aggregate_id,schema_version,idempotency_key,status,attempts,available_at,provider_reference,last_error,created_at,delivered_at from private.aqari_integration_outbox where workspace_id=w order by created_at desc limit 100)x),'[]'::jsonb),'webhooks',coalesce((select jsonb_agg(to_jsonb(x) order by x.received_at desc) from(select id,provider,provider_event_id,event_type,body_sha256,occurred_at,received_at,status,rejection_reason from private.aqari_webhook_receipts where workspace_id=w order by received_at desc limit 100)x),'[]'::jsonb));end if;
 perform private.aqari_require_sensitive_aal2(w);
 if p_action='save' then ident:=(d->>'id')::uuid;expected:=coalesce((d->>'revision')::integer,0);if pg_catalog.jsonb_typeof(coalesce(d->'public_metadata','{}'::jsonb))<>'object' or not private.aqari_integration_public_metadata_safe(coalesce(d->'public_metadata','{}'::jsonb)) then raise exception 'PUBLIC_METADATA_SECRET_FORBIDDEN' using errcode='23514';end if;if d->>'mode'='live' and nullif(d->>'secret_reference','') is null then raise exception 'LIVE_SECRET_REFERENCE_REQUIRED' using errcode='23514';end if;if coalesce(d->>'endpoint_origin','')<>'' and d->>'endpoint_origin'!~'^https://[A-Za-z0-9.-]+(?::[0-9]+)?$' then raise exception 'HTTPS_ORIGIN_REQUIRED' using errcode='23514';end if;select * into row from private.aqari_integration_configs where workspace_id=w and id=ident for update;if found and row.revision<>expected then raise exception 'REVISION_CONFLICT' using errcode='40001';end if;insert into private.aqari_integration_configs(id,workspace_id,provider,purpose,mode,endpoint_origin,secret_reference,public_metadata,revision,created_by,updated_by) values(ident,w,d->>'provider',d->>'purpose',d->>'mode',nullif(d->>'endpoint_origin',''),nullif(d->>'secret_reference',''),coalesce(d->'public_metadata','{}'),1,auth.uid(),auth.uid()) on conflict(workspace_id,id) do update set provider=excluded.provider,purpose=excluded.purpose,mode=excluded.mode,endpoint_origin=excluded.endpoint_origin,secret_reference=excluded.secret_reference,public_metadata=excluded.public_metadata,revision=private.aqari_integration_configs.revision+1,updated_by=auth.uid(),updated_at=now() returning * into row;return to_jsonb(row)-'created_by'-'updated_by';end if;
 if d->>'idempotency_key'!~'^[A-Za-z0-9:_-]{8,200}$' then raise exception 'IDEMPOTENCY_KEY_REQUIRED' using errcode='23514';end if;
 insert into private.aqari_integration_outbox(id,workspace_id,event_type,aggregate_id,schema_version,payload,idempotency_key) values((d->>'id')::uuid,w,'integration.test',d->>'config_id',1,jsonb_build_object('config_id',d->>'config_id','probe',true),d->>'idempotency_key') on conflict(workspace_id,idempotency_key) do nothing;return(select to_jsonb(x)-'payload' from private.aqari_integration_outbox x where x.workspace_id=w and x.idempotency_key=d->>'idempotency_key');
end $function$

CREATE OR REPLACE FUNCTION public.aqari_finalize_document(p_document_id uuid, p_size_bytes bigint, p_mime_type text, p_checksum text DEFAULT NULL::text)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare target public.aqari_documents%rowtype;
begin
 select * into target from public.aqari_documents where id=p_document_id for update;
 if not found or target.created_by is distinct from auth.uid() or not private.aqari_can(target.workspace_id,'documents','write') or not private.aqari_document_entity(target.workspace_id,target.entity_type,target.entity_ref,'write') then raise exception 'ACCESS_DENIED' using errcode='42501';end if;
 if target.status='uploaded' and target.size_bytes=p_size_bytes and target.mime_type=p_mime_type and target.checksum_sha256 is not distinct from p_checksum then return target.id;end if;
 if target.status<>'draft' then raise exception 'DOCUMENT_IMMUTABLE';end if;
 if p_size_bytes is null or p_size_bytes not between 1 and 26214400 or p_mime_type is distinct from target.mime_type or (p_checksum is not null and p_checksum !~ '^[a-f0-9]{64}$') then raise exception 'INVALID_DOCUMENT';end if;
 update public.aqari_documents set status='uploaded',size_bytes=p_size_bytes,checksum_sha256=p_checksum where id=target.id;
 return target.id;
end $function$

CREATE OR REPLACE FUNCTION public.aqari_financial_register(p_workspace_id uuid, p_action text, p_data jsonb DEFAULT '{}'::jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare w uuid:=p_workspace_id; d jsonb:=p_data; e private.aqari_financial_expenses; b jsonb; v_month date; v_date date; prop uuid; ident uuid;
 v_amount numeric; v_doc uuid; actor text; why text; k text; allowed text[]; summary jsonb;
begin
 if auth.uid() is null or not private.aqari_can(w,'finance','read') then raise insufficient_privilege using message='ACCESS_DENIED';end if;
 if d is null or jsonb_typeof(d)<>'object' or octet_length(d::text)>16000 then raise exception 'بيانات غير صالحة.';end if;
 allowed:=case p_action when 'list' then array['month'] when 'save' then array['id','revision','property_id','expense_date','category','payee','amount','method','reference','description','document_id']
 when 'approve' then array['id','revision','reason'] when 'cancel' then array['id','revision','reason'] when 'close_period' then array['month','reason'] else null end;
 if allowed is null then raise exception 'عملية غير معروفة.';end if;
 for k in select jsonb_object_keys(d) loop if not(k=any(allowed)) then raise exception 'حقل غير مسموح.';end if;end loop;
 select coalesce(nullif(p.display_name,''),auth.uid()::text) into actor from public.aqari_profiles p where p.user_id=auth.uid();
 actor:=coalesce(actor,auth.uid()::text);
 if p_action in ('list','close_period') then
  if coalesce(d->>'month','') !~ '^\d{4}-(0[1-9]|1[0-2])$' then raise exception 'اختر شهراً صحيحاً.';end if;
  v_month:=((d->>'month')||'-01')::date;
 end if;
 if p_action='list' then
  select jsonb_build_object('approved_expenses',coalesce(sum(x.amount) filter(where x.state='approved'),0)::text,'count',count(*) filter(where x.state='approved')) into summary
  from private.aqari_financial_expenses x where x.workspace_id=w and x.expense_date>=v_month and x.expense_date<(v_month+interval '1 month')::date and private.aqari_can_property(w,x.property_id,'finance','read');
  return jsonb_build_object('manager',private.aqari_manager(w),'can_write',private.aqari_can(w,'finance','write'),
   'properties',coalesce((select jsonb_agg(jsonb_build_object('id',p.id,'name',p.name) order by p.name,p.id) from public.aqari_properties p where p.workspace_id=w and private.aqari_can_property(w,p.id,'finance','read')),'[]'),
   'documents',coalesce((select jsonb_agg(jsonb_build_object('id',doc.id,'property_id',p.id,'title',doc.title,'document_no',doc.document_no) order by doc.created_at desc,doc.id) from public.aqari_documents doc join public.aqari_properties p on p.workspace_id=doc.workspace_id and p.external_ref=doc.entity_ref
    where doc.workspace_id=w and doc.entity_type='property' and doc.status='uploaded' and private.aqari_can(w,'documents','read') and private.aqari_can_property(w,p.id,'finance','read')),'[]'),
   'expenses',coalesce((select jsonb_agg(to_jsonb(x) order by x.expense_date desc,x.created_at desc,x.id) from private.aqari_financial_expenses x where x.workspace_id=w and x.expense_date>=v_month and x.expense_date<(v_month+interval '1 month')::date and private.aqari_can_property(w,x.property_id,'finance','read')),'[]'),
   'period',case when private.aqari_manager(w) then (select to_jsonb(p) from private.aqari_financial_periods p where p.workspace_id=w and p.month=v_month)
    else (select jsonb_build_object('month',p.month,'closed_at',p.closed_at) from private.aqari_financial_periods p where p.workspace_id=w and p.month=v_month) end,
   'history',coalesce((select jsonb_agg(to_jsonb(a) order by a.id desc) from (select x.entity_id,x.action,x.actor_name,x.recorded_at,x.reason,x.id from private.aqari_financial_audit x where x.workspace_id=w and
     (private.aqari_manager(w) or (x.property_id is not null and private.aqari_can_property(w,x.property_id,'finance','read'))) and
     (x.entity_id=v_month::text or exists(select 1 from private.aqari_financial_expenses ex where ex.workspace_id=w and ex.id::text=x.entity_id and ex.expense_date>=v_month and ex.expense_date<(v_month+interval '1 month')::date)) order by x.id desc limit 100) a),'[]'),'summary',summary);
 end if;
 if not private.aqari_can(w,'finance','write') then raise insufficient_privilege using message='ACCESS_DENIED';end if;
 perform 1 from public.aqari_app_state where workspace_id=w for update;
 if not found then raise insufficient_privilege using message='ACCESS_DENIED';end if;
 if p_action='close_period' then
  if not private.aqari_manager(w) then raise insufficient_privilege using message='ACCESS_DENIED';end if;
  why:=btrim(d->>'reason');if why is null or length(why) not between 3 and 500 then raise exception 'سبب الإقفال مطلوب من ٣ إلى ٥٠٠ حرف.';end if;
  if v_month>=date_trunc('month',now() at time zone 'Asia/Kuwait')::date then raise exception 'يمكن إقفال الأشهر المنتهية فقط.';end if;
  if exists(select 1 from private.aqari_financial_periods p where p.workspace_id=w and p.month=v_month) then return public.aqari_financial_register(w,'list',jsonb_build_object('month',d->>'month'));end if;
  if exists(select 1 from private.aqari_financial_expenses x where x.workspace_id=w and x.expense_date>=v_month and x.expense_date<(v_month+interval '1 month')::date and x.state='draft') then raise exception 'توجد مصروفات مسودة في الشهر؛ اعتمدها أو ألغها قبل الإقفال.';end if;
  if exists(select 1 from private.aqari_hr_payroll p where p.workspace_id=w and p.month=v_month and p.state<>'paid') then raise exception 'توجد رواتب غير مكتملة في الشهر؛ لا يمكن الإقفال.';end if;
  summary:=jsonb_build_object('scope','posted_rent_payments_and_approved_expenses_only','rent_payments',
   (select coalesce(sum(p.amount),0) from public.aqari_rent_payments p where p.workspace_id=w and p.paid_at>=v_month and p.paid_at<(v_month+interval '1 month')::date),
   'rent_payment_count',(select count(*) from public.aqari_rent_payments p where p.workspace_id=w and p.paid_at>=v_month and p.paid_at<(v_month+interval '1 month')::date),
   'approved_expenses',(select coalesce(sum(x.amount),0) from private.aqari_financial_expenses x where x.workspace_id=w and x.expense_date>=v_month and x.expense_date<(v_month+interval '1 month')::date and x.state='approved'),
   'approved_expense_count',(select count(*) from private.aqari_financial_expenses x where x.workspace_id=w and x.expense_date>=v_month and x.expense_date<(v_month+interval '1 month')::date and x.state='approved'),
   'legacy_finance_reconciled',false);
  insert into private.aqari_financial_periods(workspace_id,month,closed_by,closed_by_name,reason,snapshot) values(w,v_month,auth.uid(),actor,why,summary);
  insert into private.aqari_financial_audit(workspace_id,entity_id,action,actor_id,actor_name,reason,after_value) values(w,v_month::text,'period.close',auth.uid(),actor,why,summary);
  return public.aqari_financial_register(w,'list',jsonb_build_object('month',d->>'month'));
 end if;
 ident:=(d->>'id')::uuid;if ident is null then raise exception 'معرف المصروف مطلوب.';end if;
 select * into e from private.aqari_financial_expenses x where x.id=ident for update;
 if found and (e.workspace_id<>w or not private.aqari_can_property(w,e.property_id,'finance','write')) then raise insufficient_privilege using message='ACCESS_DENIED';end if;
 if coalesce(e.revision,0) is distinct from (d->>'revision')::bigint then raise exception 'تغير السجل؛ حدّث البيانات قبل الحفظ.' using errcode='40001';end if;
 b:=case when e.id is not null then to_jsonb(e) end;
 if p_action='save' then
  if e.id is not null and e.state<>'draft' then raise exception 'المصروف المعتمد أو الملغى لا يقبل التعديل.';end if;
  prop:=(d->>'property_id')::uuid;
  if prop is null or not private.aqari_can_property(w,prop,'finance','write') then raise insufficient_privilege using message='ACCESS_DENIED';end if;
  if coalesce(d->>'expense_date','') !~ '^\d{4}-\d{2}-\d{2}$' then raise exception 'تاريخ المصروف مطلوب.';end if;
  v_date:=(d->>'expense_date')::date;
  if v_date>(now() at time zone 'Asia/Kuwait')::date then raise exception 'تاريخ المصروف لا يكون مستقبلياً.';end if;
  perform private.aqari_financial_open(w,v_date);
  if e.id is not null then perform private.aqari_financial_open(w,e.expense_date);end if;
  foreach k in array array['category','payee','method'] loop if jsonb_typeof(d->k)<>'string' or nullif(btrim(d->>k),'') is null then raise exception 'أكمل فئة المصروف والمستفيد وطريقة الصرف.';end if;end loop;
  if length(btrim(d->>'category'))>120 or length(btrim(d->>'payee'))>200 or length(coalesce(d->>'reference',''))>200 or length(coalesce(d->>'description',''))>2000 or d->>'method' not in ('cash','bank','cheque') then raise exception 'بيانات المصروف غير صالحة.';end if;
  if d->>'method'<>'cash' and nullif(btrim(d->>'reference'),'') is null then raise exception 'رقم مرجع التحويل أو الشيك مطلوب.';end if;
  v_amount:=private.aqari_hr_money(d->'amount');if v_amount<=0 then raise exception 'مبلغ المصروف يجب أن يكون أكبر من صفر.';end if;
  v_doc:=nullif(d->>'document_id','')::uuid;
  if v_doc is not null and not exists(select 1 from public.aqari_documents doc join public.aqari_properties p on p.workspace_id=doc.workspace_id and p.external_ref=doc.entity_ref where doc.id=v_doc and doc.workspace_id=w and doc.entity_type='property' and p.id=prop and doc.status='uploaded') then raise exception 'اختر مستنداً محفوظاً للعقار نفسه.';end if;
  insert into private.aqari_financial_expenses(id,workspace_id,property_id,expense_date,category,payee,amount,method,reference,description,document_id,created_by)
   values(ident,w,prop,v_date,btrim(d->>'category'),btrim(d->>'payee'),v_amount,d->>'method',btrim(coalesce(d->>'reference','')),btrim(coalesce(d->>'description','')),v_doc,auth.uid())
  on conflict(id) do update set property_id=excluded.property_id,expense_date=excluded.expense_date,category=excluded.category,payee=excluded.payee,amount=excluded.amount,method=excluded.method,reference=excluded.reference,description=excluded.description,document_id=excluded.document_id,revision=aqari_financial_expenses.revision+1,updated_at=now()
  returning * into e;
  why:='حفظ مسودة المصروف';
 else
  if e.id is null then raise insufficient_privilege using message='ACCESS_DENIED';end if;
  if not private.aqari_manager(w) then raise insufficient_privilege using message='ACCESS_DENIED';end if;
  why:=btrim(d->>'reason');if why is null or length(why) not between 3 and 500 then raise exception 'سبب الإجراء مطلوب من ٣ إلى ٥٠٠ حرف.';end if;
  perform private.aqari_financial_open(w,e.expense_date);
  if p_action='approve' then
   if e.state<>'draft' then raise exception 'يُعتمد المصروف المسودة فقط.';end if;
   if e.document_id is null or not exists(select 1 from public.aqari_documents doc join public.aqari_properties p on p.workspace_id=doc.workspace_id and p.external_ref=doc.entity_ref
    join storage.objects o on o.bucket_id=doc.storage_bucket and o.name=doc.storage_path
    where doc.id=e.document_id and doc.workspace_id=w and doc.entity_type='property' and p.id=e.property_id and doc.status='uploaded' and doc.checksum_sha256 ~ '^[a-f0-9]{64}$'
    and doc.size_bytes>0 and (o.metadata->>'size')::bigint=doc.size_bytes and o.metadata->>'mimetype'=doc.mime_type) then raise exception 'اربط فاتورة مرفوعة ومؤكد حفظها قبل اعتماد المصروف.';end if;
   update private.aqari_financial_expenses x set state='approved',voucher_no='EX-'||to_char(now() at time zone 'Asia/Kuwait','YYYYMMDD')||'-'||lpad(nextval('private.aqari_expense_voucher_seq')::text,8,'0'),approved_by=auth.uid(),approved_by_name=actor,approved_at=now(),approval_reason=why,revision=x.revision+1,updated_at=now() where x.id=ident returning * into e;
  else
   if e.state='cancelled' then raise exception 'المصروف ملغى ومحفوظ مسبقاً.';end if;
   update private.aqari_financial_expenses x set state='cancelled',cancelled_by=auth.uid(),cancelled_by_name=actor,cancelled_at=now(),cancel_reason=why,revision=x.revision+1,updated_at=now() where x.id=ident returning * into e;
  end if;
 end if;
 insert into private.aqari_financial_audit(workspace_id,property_id,entity_id,action,actor_id,actor_name,reason,before_value,after_value)
 values(w,e.property_id,e.id::text,'expense.'||p_action,auth.uid(),actor,why,b,to_jsonb(e));
 return to_jsonb(e);
end $function$

CREATE OR REPLACE FUNCTION public.aqari_hr_cycle(p_workspace_id uuid, p_action text, p_data jsonb DEFAULT '{}'::jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare w uuid:=p_workspace_id; d jsonb:=coalesce(p_data,'{}'::jsonb); e private.aqari_hr_employees;
 r private.aqari_hr_records; p private.aqari_hr_payroll; s private.aqari_hr_salary_registry;
 ident uuid; property uuid; period date; props uuid[]; payload jsonb; n integer; expected bigint; total_share numeric;
begin
 if auth.uid() is null or jsonb_typeof(d)<>'object' then raise insufficient_privilege using message='ACCESS_DENIED'; end if;
 ident:=nullif(d->>'employee_id','')::uuid;
 if ident is not null then select * into e from private.aqari_hr_employees where workspace_id=w and id=ident for update; end if;

 if p_action='context' then
  if not private.aqari_can(w,'employees','read') and not exists(select 1 from private.aqari_hr_employees x where x.workspace_id=w and x.user_id=auth.uid()) then raise insufficient_privilege using message='ACCESS_DENIED'; end if;
  return jsonb_build_object(
   'manager',private.aqari_manager(w),
   'self_employee_id',(select id from private.aqari_hr_employees x where x.workspace_id=w and x.user_id=auth.uid()),
   'employees',coalesce((select jsonb_agg(jsonb_build_object('id',x.id,'profile',x.profile,'status',x.status,'property_ids',x.property_ids,'basic',x.basic,'allowances',x.allowances) order by x.profile->>'name_ar')
     from private.aqari_hr_employees x where x.workspace_id=w and (x.user_id=auth.uid() or private.aqari_hr_can(w,x.property_ids,'read'))),'[]'::jsonb),
   'properties',coalesce((select jsonb_agg(jsonb_build_object('id',q.id,'name',q.name,'metadata',q.metadata) order by q.name) from public.aqari_properties q where q.workspace_id=w and (private.aqari_manager(w) or private.aqari_hr_can(w,array[q.id],'read'))),'[]'::jsonb),
   'expiry_alerts',coalesce((select jsonb_agg(z order by z.expires_on) from (
      select x.id as employee_id,x.profile->>'name_ar' employee_name,'civil_id' kind,a.civil_expires_on expires_on from private.aqari_hr_employee_details a join private.aqari_hr_employees x on x.id=a.employee_id where a.workspace_id=w and a.civil_expires_on<=current_date+60 and private.aqari_hr_can(w,x.property_ids,'read')
      union all select x.id,x.profile->>'name_ar','passport',a.passport_expires_on from private.aqari_hr_employee_details a join private.aqari_hr_employees x on x.id=a.employee_id where a.workspace_id=w and a.passport_expires_on<=current_date+60 and private.aqari_hr_can(w,x.property_ids,'read')
      union all select x.id,x.profile->>'name_ar','work_permit',a.work_permit_expires_on from private.aqari_hr_employee_details a join private.aqari_hr_employees x on x.id=a.employee_id where a.workspace_id=w and a.work_permit_expires_on<=current_date+60 and private.aqari_hr_can(w,x.property_ids,'read')
    ) z),'[]'::jsonb)
  );
 end if;

 if e.id is null or not private.aqari_hr_cycle_can(w,e.id,'read') then raise insufficient_privilege using message='ACCESS_DENIED'; end if;

 if p_action='employee' then
  return jsonb_build_object('employee',to_jsonb(e),
   'details',coalesce((select to_jsonb(x) from private.aqari_hr_employee_details x where x.employee_id=e.id),'{}'::jsonb),
   'allocations',coalesce((select jsonb_agg(to_jsonb(x) order by property_id) from private.aqari_hr_cost_allocations x where x.employee_id=e.id and x.active),'[]'::jsonb),
   'records',coalesce((select jsonb_agg(to_jsonb(x) order by starts_at desc) from private.aqari_hr_records x where x.employee_id=e.id),'[]'::jsonb),
   'documents',coalesce((select jsonb_agg(to_jsonb(x)||jsonb_build_object('metadata',coalesce((select to_jsonb(m) from private.aqari_hr_document_metadata m where m.document_id=x.id),'{}'::jsonb)) order by x.created_at desc) from private.aqari_hr_documents x where x.employee_id=e.id),'[]'::jsonb),
   'payroll',coalesce((select jsonb_agg(to_jsonb(x)||jsonb_build_object('registry',coalesce((select jsonb_agg(to_jsonb(g) order by g.version desc) from private.aqari_hr_salary_registry g where g.payroll_id=x.id),'[]'::jsonb)) order by x.month desc) from private.aqari_hr_payroll x where x.employee_id=e.id),'[]'::jsonb),
   'settlement',coalesce((select to_jsonb(x) from private.aqari_hr_exit_settlements x where x.employee_id=e.id),'{}'::jsonb),
   'self',private.aqari_hr_cycle_self(w,e.id));
 end if;

 if p_action='save_details' then
  if not private.aqari_hr_can(w,e.property_ids,'edit') then raise insufficient_privilege using message='ACCESS_DENIED'; end if;
  expected:=coalesce((d->>'revision')::bigint,0);
  if length(coalesce(d->>'email',''))>254 or (coalesce(d->>'email','')<>'' and d->>'email' !~ '^[^[:space:]@]+@[^[:space:]@]+[.][^[:space:]@]+$') then raise exception 'INVALID_EMPLOYEE_EMAIL'; end if;
  payload:=coalesce(d->'employment','{}'::jsonb); if jsonb_typeof(payload)<>'object' then raise exception 'INVALID_EMPLOYMENT_DETAILS'; end if;
  insert into private.aqari_hr_employee_details(workspace_id,employee_id,email,civil_expires_on,passport_expires_on,work_permit_expires_on,contract_starts_on,contract_ends_on,emergency_contact,employment)
  select w,e.id,coalesce(d->>'email',''),nullif(d->>'civil_expires_on','')::date,nullif(d->>'passport_expires_on','')::date,nullif(d->>'work_permit_expires_on','')::date,nullif(d->>'contract_starts_on','')::date,nullif(d->>'contract_ends_on','')::date,coalesce(d->'emergency_contact','{}'::jsonb),payload where expected=0
  on conflict(employee_id) do nothing; get diagnostics n=row_count;
  if n=0 then update private.aqari_hr_employee_details set email=coalesce(d->>'email',''),civil_expires_on=nullif(d->>'civil_expires_on','')::date,passport_expires_on=nullif(d->>'passport_expires_on','')::date,work_permit_expires_on=nullif(d->>'work_permit_expires_on','')::date,contract_starts_on=nullif(d->>'contract_starts_on','')::date,contract_ends_on=nullif(d->>'contract_ends_on','')::date,emergency_contact=coalesce(d->'emergency_contact','{}'::jsonb),employment=payload,revision=revision+1,updated_at=now() where employee_id=e.id and revision=expected;get diagnostics n=row_count;if n=0 then raise serialization_failure using message='REVISION_CONFLICT';end if;end if;
  return (select to_jsonb(x) from private.aqari_hr_employee_details x where x.employee_id=e.id);
 end if;

 if p_action='save_allocations' then
  if not private.aqari_hr_can(w,e.property_ids,'edit') or jsonb_typeof(d->'allocations')<>'array' then raise insufficient_privilege using message='ACCESS_DENIED'; end if;
  -- HR_COST_ALLOCATION_INTEGRITY_V1
  if jsonb_typeof(d->'allocations') is distinct from 'array' or jsonb_array_length(d->'allocations')=0 then raise exception 'ALLOCATIONS_REQUIRED';end if;
  if exists(select 1 from jsonb_array_elements(d->'allocations') x where
   jsonb_typeof(x) is distinct from 'object' or x->>'property_id' is null or
   coalesce(x->>'share','') !~ '^[0-9]+([.][0-9]{1,2})?$'
  ) then raise exception 'INVALID_ALLOCATION_SHARE';end if;
  if exists(select 1 from jsonb_array_elements(d->'allocations') x where (x->>'share')::numeric<=0 or (x->>'share')::numeric>100) then raise exception 'INVALID_ALLOCATION_SHARE';end if;
  select coalesce(sum((x->>'share')::numeric),0),array_agg((x->>'property_id')::uuid) into total_share,props from jsonb_array_elements(d->'allocations') x;
  if total_share<>100 or props is null or not props <@ e.property_ids or exists(select 1 from unnest(props) x group by x having count(*)>1) then raise exception 'ALLOCATIONS_MUST_TOTAL_100';end if;
  update private.aqari_hr_cost_allocations set active=false,revision=revision+1,updated_at=now() where employee_id=e.id and active;
  insert into private.aqari_hr_cost_allocations(workspace_id,employee_id,property_id,share)
  select w,e.id,(x->>'property_id')::uuid,(x->>'share')::numeric from jsonb_array_elements(d->'allocations') x
  on conflict(employee_id,property_id) do update set share=excluded.share,active=true,revision=private.aqari_hr_cost_allocations.revision+1,updated_at=now();
  return jsonb_build_object('saved',true,'allocations',(select jsonb_agg(to_jsonb(x)) from private.aqari_hr_cost_allocations x where x.employee_id=e.id and x.active));
 end if;

 if p_action='add_record' then
  if private.aqari_hr_cycle_self(w,e.id) then
   if d->>'kind' not in ('leave_request','advance_request','salary_certificate','document_update','general_request') then raise insufficient_privilege using message='SELF_SERVICE_KIND_DENIED'; end if;
  elsif not private.aqari_hr_can(w,e.property_ids,'add') then raise insufficient_privilege using message='ACCESS_DENIED'; end if;
  property:=nullif(d->>'property_id','')::uuid;
  if property is not null and not property=any(e.property_ids) then raise insufficient_privilege using message='PROPERTY_SCOPE_DENIED'; end if;
  insert into private.aqari_hr_records(id,workspace_id,employee_id,property_id,kind,status,starts_at,ends_at,minutes,amount,title,details,created_by)
  values((d->>'id')::uuid,w,e.id,property,d->>'kind','submitted',(d->>'starts_at')::timestamptz,nullif(d->>'ends_at','')::timestamptz,nullif(d->>'minutes','')::integer,nullif(d->>'amount','')::numeric,d->>'title',coalesce(d->>'details',''),auth.uid()) returning * into r;
  return to_jsonb(r);
 end if;

 if p_action='decide_record' then
  if not private.aqari_hr_can(w,e.property_ids,'edit') or d->>'status' not in ('approved','rejected','completed','cancelled') or length(btrim(coalesce(d->>'reason',''))) not between 3 and 1000 then raise insufficient_privilege using message='ACCESS_DENIED';end if;
  update private.aqari_hr_records set status=d->>'status',decision_reason=d->>'reason',decided_by=auth.uid(),decided_at=now(),revision=revision+1,updated_at=now() where id=(d->>'id')::uuid and employee_id=e.id and revision=(d->>'revision')::bigint and status='submitted' returning * into r;
  if r.id is null then raise serialization_failure using message='REVISION_CONFLICT';end if;return to_jsonb(r);
 end if;

 if p_action='save_document_metadata' then
  if not private.aqari_hr_can(w,e.property_ids,'edit') or d->>'document_type' not in ('civil_id','passport','work_permit','employment_contract','certificate','custody','other') then raise insufficient_privilege using message='ACCESS_DENIED';end if;
  if not exists(select 1 from private.aqari_hr_documents x where x.id=(d->>'document_id')::uuid and x.workspace_id=w and x.employee_id=e.id and x.status='ready') then raise exception 'READY_DOCUMENT_REQUIRED';end if;
  expected:=coalesce((d->>'revision')::bigint,0);
  insert into private.aqari_hr_document_metadata(document_id,workspace_id,employee_id,document_type,document_number,issued_on,expires_on)
  select (d->>'document_id')::uuid,w,e.id,d->>'document_type',coalesce(d->>'document_number',''),nullif(d->>'issued_on','')::date,nullif(d->>'expires_on','')::date where expected=0
  on conflict(document_id) do nothing;get diagnostics n=row_count;
  if n=0 then update private.aqari_hr_document_metadata set document_type=d->>'document_type',document_number=coalesce(d->>'document_number',''),issued_on=nullif(d->>'issued_on','')::date,expires_on=nullif(d->>'expires_on','')::date,revision=revision+1,updated_at=now() where document_id=(d->>'document_id')::uuid and employee_id=e.id and revision=expected;get diagnostics n=row_count;if n=0 then raise serialization_failure using message='REVISION_CONFLICT';end if;end if;
  return (select to_jsonb(x) from private.aqari_hr_document_metadata x where x.document_id=(d->>'document_id')::uuid);
 end if;

 if p_action='sync_payroll' then
  if not private.aqari_hr_can(w,e.property_ids,'edit') then raise insufficient_privilege using message='ACCESS_DENIED'; end if;
  period:=(d->>'month')::date; select * into p from private.aqari_hr_payroll where employee_id=e.id and month=period for update;
  if p.id is null or p.state<>'draft' then raise exception 'PAYROLL_DRAFT_REQUIRED';end if;
  update private.aqari_hr_payroll x set
   overtime=coalesce((select sum(amount) from private.aqari_hr_records where employee_id=e.id and kind='overtime' and status='approved' and starts_at>=period and starts_at<period+interval '1 month'),0),
   reward=coalesce((select sum(amount) from private.aqari_hr_records where employee_id=e.id and kind='bonus' and status='approved' and starts_at>=period and starts_at<period+interval '1 month'),0),
   late=coalesce((select sum(amount) from private.aqari_hr_records where employee_id=e.id and kind='late' and status='approved' and starts_at>=period and starts_at<period+interval '1 month'),0),
   absence=coalesce((select sum(amount) from private.aqari_hr_records where employee_id=e.id and kind='absence' and status='approved' and starts_at>=period and starts_at<period+interval '1 month'),0),
   deductions=coalesce((select sum(amount) from private.aqari_hr_records where employee_id=e.id and kind='deduction' and status='approved' and starts_at>=period and starts_at<period+interval '1 month'),0),
   revision=x.revision+1,updated_at=now() where x.id=p.id returning * into p;return to_jsonb(p);
 end if;

 if p_action='month_report' then
  period:=(d->>'month')::date;property:=(d->>'property_id')::uuid;
  if not private.aqari_hr_can(w,array[property],'read') then raise insufficient_privilege using message='ACCESS_DENIED';end if;
  return jsonb_build_object('month',coalesce((select to_jsonb(x) from private.aqari_hr_months x where x.workspace_id=w and x.property_id=property and x.month=period),jsonb_build_object('workspace_id',w,'property_id',property,'month',period,'state','open','revision',0)),
   'rows',coalesce((select jsonb_agg(jsonb_build_object('employee_id',x.employee_id,'name_ar',x.snapshot->>'name_ar','name_en',x.snapshot->>'name_en','state',x.state,'basic',x.basic,'allowances',x.allowances,'additions',x.basic+x.allowances+x.overtime+x.reward+x.loan_payment+x.housing+x.indemnity+x.holidays,'deductions',x.late+x.absence+x.deductions+x.advance_repayment,'net',x.net,'share',a.share,'allocated_net',a.allocated_net) order by x.snapshot->>'name_ar') from private.aqari_hr_payroll x join private.aqari_hr_employees q on q.id=x.employee_id join lateral private.aqari_hr_cost_split(w,x.employee_id,x.net) a on a.property_id=property where x.workspace_id=w and x.month=period and property=any(q.property_ids)),'[]'::jsonb));
 end if;

 if p_action='month_action' then
  period:=(d->>'month')::date;property:=(d->>'property_id')::uuid;
  if not private.aqari_hr_can(w,array[property],case when d->>'state'='closed' then 'approve_chairman' else 'approve_admin' end) then raise insufficient_privilege using message='ACCESS_DENIED';end if;
  if d->>'state' not in ('reviewed','approved','closed') or length(btrim(coalesce(d->>'reason',''))) not between 3 and 1000 then raise exception 'MONTH_ACTION_REASON_REQUIRED';end if;
  if d->>'state'='closed' and exists(select 1 from private.aqari_hr_payroll x join private.aqari_hr_employees q on q.id=x.employee_id where x.workspace_id=w and x.month=period and property=any(q.property_ids) and x.state<>'paid') then raise exception 'UNPAID_PAYROLL_EXISTS';end if;
  perform a.allocated_net from private.aqari_hr_payroll x join private.aqari_hr_employees q on q.id=x.employee_id
   cross join lateral private.aqari_hr_cost_split(w,x.employee_id,x.net) a
   where x.workspace_id=w and x.month=period and property=any(q.property_ids) and a.property_id=property;
  insert into private.aqari_hr_months(workspace_id,property_id,month,state,reason,reviewed_by,reviewed_at,approved_by,approved_at,closed_by,closed_at)
  values(w,property,period,d->>'state',d->>'reason',case when d->>'state'='reviewed' then auth.uid() end,case when d->>'state'='reviewed' then now() end,case when d->>'state'='approved' then auth.uid() end,case when d->>'state'='approved' then now() end,case when d->>'state'='closed' then auth.uid() end,case when d->>'state'='closed' then now() end)
  on conflict(workspace_id,property_id,month) do update set state=excluded.state,reason=excluded.reason,reviewed_by=coalesce(private.aqari_hr_months.reviewed_by,excluded.reviewed_by),reviewed_at=coalesce(private.aqari_hr_months.reviewed_at,excluded.reviewed_at),approved_by=coalesce(private.aqari_hr_months.approved_by,excluded.approved_by),approved_at=coalesce(private.aqari_hr_months.approved_at,excluded.approved_at),closed_by=coalesce(private.aqari_hr_months.closed_by,excluded.closed_by),closed_at=coalesce(private.aqari_hr_months.closed_at,excluded.closed_at),revision=private.aqari_hr_months.revision+1
  where private.aqari_hr_months.revision=(d->>'revision')::bigint and private.aqari_hr_months.state<>'closed';
  get diagnostics n=row_count;if n=0 then raise serialization_failure using message='REVISION_CONFLICT';end if;return (select to_jsonb(x) from private.aqari_hr_months x where x.workspace_id=w and x.property_id=property and x.month=period);
 end if;

 if p_action in ('annual_report','cost_report') then
  if not private.aqari_can(w,'employees','read') then raise insufficient_privilege using message='ACCESS_DENIED';end if;
  period:=make_date((d->>'year')::integer,1,1);property:=nullif(d->>'property_id','')::uuid;
  if property is not null and not private.aqari_hr_can(w,array[property],'read') then raise insufficient_privilege using message='ACCESS_DENIED';end if;
  return jsonb_build_object('year',extract(year from period)::integer,'rows',coalesce((
   select jsonb_agg(row_to_json(z) order by z.month,z.employee_name) from (
    select to_char(x.month,'YYYY-MM') as "month",x.employee_id,x.snapshot->>'name_ar' as employee_name,x.state,x.net,
     q.id as property_id,q.name as property_name,a.share as share,
     a.allocated_net as allocated_cost
    from private.aqari_hr_payroll x join private.aqari_hr_employees employee_scope on employee_scope.id=x.employee_id
    join public.aqari_properties q on q.id=any(employee_scope.property_ids) and q.workspace_id=w
    join lateral private.aqari_hr_cost_split(w,x.employee_id,x.net) a on a.property_id=q.id
    where x.workspace_id=w and x.month>=period and x.month<period+interval '1 year'
     and (property is null or q.id=property) and private.aqari_hr_can(w,array[q.id],'read')
   ) z),'[]'::jsonb));
 end if;

 if p_action='archive_employee' then
  if not private.aqari_manager(w) or length(btrim(coalesce(d->>'reason',''))) not between 3 and 1000 then raise insufficient_privilege using message='ACCESS_DENIED';end if;
  insert into private.aqari_hr_exit_settlements(id,workspace_id,employee_id,last_working_day,reason,salary_due,leave_due,indemnity,deductions,custody_cleared,clearance_notes)
  values((d->>'id')::uuid,w,e.id,(d->>'last_working_day')::date,d->>'reason',coalesce((d->>'salary_due')::numeric,0),coalesce((d->>'leave_due')::numeric,0),coalesce((d->>'indemnity')::numeric,0),coalesce((d->>'deductions')::numeric,0),coalesce((d->>'custody_cleared')::boolean,false),coalesce(d->>'clearance_notes','')) returning to_jsonb(private.aqari_hr_exit_settlements.*) into payload;
  update private.aqari_hr_employees set status='inactive',revision=revision+1,updated_at=now() where id=e.id;
  insert into private.aqari_hr_employee_details(workspace_id,employee_id,archived_at,archived_by,archive_reason) values(w,e.id,now(),auth.uid(),d->>'reason') on conflict(employee_id) do update set archived_at=now(),archived_by=auth.uid(),archive_reason=d->>'reason',revision=private.aqari_hr_employee_details.revision+1,updated_at=now();
  return payload;
 end if;

 if p_action='settlement_action' then
  if not private.aqari_manager(w) or d->>'state' not in ('approved','paid') then raise insufficient_privilege using message='ACCESS_DENIED';end if;
  if d->>'state'='paid' and exists(select 1 from private.aqari_hr_records x where x.employee_id=e.id and x.kind='custody' and x.status not in ('completed','cancelled')) then raise exception 'OPEN_CUSTODY_EXISTS';end if;
  update private.aqari_hr_exit_settlements set state=d->>'state',approved_by=case when d->>'state'='approved' then auth.uid() else approved_by end,approved_at=case when d->>'state'='approved' then now() else approved_at end,paid_by=case when d->>'state'='paid' then auth.uid() else paid_by end,paid_at=case when d->>'state'='paid' then now() else paid_at end,revision=revision+1,updated_at=now() where employee_id=e.id and revision=(d->>'revision')::bigint and ((d->>'state'='approved' and state='draft') or (d->>'state'='paid' and state='approved')) returning to_jsonb(private.aqari_hr_exit_settlements.*) into payload;
  if payload is null then raise serialization_failure using message='REVISION_CONFLICT';end if;return payload;
 end if;

 if p_action='salary_export' then
  select * into p from private.aqari_hr_payroll where id=(d->>'payroll_id')::uuid and employee_id=e.id and workspace_id=w;
  if p.id is null or p.state='draft' then raise exception 'ISSUED_PAYROLL_REQUIRED';end if;
  select * into s from private.aqari_hr_salary_registry where payroll_id=p.id and status='active';
  if s.id is null then
   payload:=private.aqari_hr_cycle_payload(p);
   insert into private.aqari_hr_salary_registry(workspace_id,employee_id,payroll_id,version,voucher_no,snapshot,snapshot_sha256,issued_by)
   values(w,e.id,p.id,1,coalesce(p.voucher_no,p.id::text),payload,encode(extensions.digest(convert_to(payload::text,'utf8'),'sha256'),'hex'),auth.uid()) returning * into s;
  end if;
  return jsonb_build_object('registry',to_jsonb(s)-'verification_token','verification_token',s.verification_token,'payload',s.snapshot);
 end if;

 if p_action='void_salary' then
  if not private.aqari_manager(w) or length(btrim(coalesce(d->>'reason',''))) not between 3 and 1000 then raise insufficient_privilege using message='ACCESS_DENIED';end if;
  update private.aqari_hr_salary_registry set status='void',voided_by=auth.uid(),voided_at=now(),reason=d->>'reason' where id=(d->>'registry_id')::uuid and employee_id=e.id and status='active' returning * into s;
  if s.id is null then raise exception 'ACTIVE_SALARY_NOT_FOUND';end if;return to_jsonb(s)-'verification_token';
 end if;

 if p_action='correct_salary' then
  if not private.aqari_manager(w) or length(btrim(coalesce(d->>'reason',''))) not between 3 and 1000 or jsonb_typeof(d->'snapshot')<>'object' then raise insufficient_privilege using message='ACCESS_DENIED';end if;
  select * into s from private.aqari_hr_salary_registry where id=(d->>'replaces_id')::uuid and employee_id=e.id and status='void' for update;
  if s.id is null or exists(select 1 from private.aqari_hr_salary_registry where payroll_id=s.payroll_id and status='active') then raise exception 'VOID_SALARY_REQUIRED';end if;
  payload:=d->'snapshot';
  insert into private.aqari_hr_salary_registry(workspace_id,employee_id,payroll_id,version,voucher_no,snapshot,snapshot_sha256,issued_by,replaces_id,reason)
  values(w,e.id,s.payroll_id,s.version+1,(select lpad(v.n,greatest(4,length(v.n)),'0') from (select nextval('private.aqari_hr_voucher_seq')::text as n) v),payload,encode(extensions.digest(convert_to(payload::text,'utf8'),'sha256'),'hex'),auth.uid(),s.id,d->>'reason') returning * into s;
  update private.aqari_hr_salary_registry set status='corrected' where id=s.replaces_id;
  return to_jsonb(s)-'verification_token';
 end if;

 raise exception 'UNKNOWN_HR_CYCLE_ACTION';
end $function$

CREATE OR REPLACE FUNCTION public.aqari_hr_payroll_cycle(p_workspace_id uuid, p_action text, p_data jsonb DEFAULT '{}'::jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare w uuid:=p_workspace_id;d jsonb:=coalesce(p_data,'{}'::jsonb);e private.aqari_hr_employees;p private.aqari_hr_payroll;result jsonb;k text;
begin
 if auth.uid() is null or jsonb_typeof(d)<>'object' then raise insufficient_privilege using message='ACCESS_DENIED';end if;
 select * into e from private.aqari_hr_employees where workspace_id=w and id=(d->>'employee_id')::uuid for update;
 if e.id is null or not private.aqari_hr_can(w,e.property_ids,case when p_action='get' then 'read' else 'edit' end) then raise insufficient_privilege using message='ACCESS_DENIED';end if;
 select * into p from private.aqari_hr_payroll where workspace_id=w and employee_id=e.id and id=(d->>'payroll_id')::uuid for update;
 if p.id is null then raise exception 'PAYROLL_NOT_FOUND';end if;
 if p_action='get' then return to_jsonb(p);end if;
 if p_action='save_draft' then
  if p.state<>'draft' or p.revision<>(d->>'revision')::bigint then raise serialization_failure using message='REVISION_CONFLICT';end if;
  if d->>'method' not in ('cash','cheque','transfer','knet') or (d->>'method'<>'cash' and length(btrim(coalesce(d->>'reference','')))<1) or length(coalesce(d->>'reference',''))>120 or length(coalesce(d->>'notes',''))>1000 then raise exception 'INVALID_PAYMENT_DETAILS';end if;
  foreach k in array array['overtime','reward','loan_payment','housing','indemnity','holidays','late','absence','deductions','advance_repayment'] loop perform private.aqari_hr_money(d->k);end loop;
  update private.aqari_hr_payroll x set overtime=private.aqari_hr_money(d->'overtime'),reward=private.aqari_hr_money(d->'reward'),loan_payment=private.aqari_hr_money(d->'loan_payment'),housing=private.aqari_hr_money(d->'housing'),indemnity=private.aqari_hr_money(d->'indemnity'),holidays=private.aqari_hr_money(d->'holidays'),late=private.aqari_hr_money(d->'late'),absence=private.aqari_hr_money(d->'absence'),deductions=private.aqari_hr_money(d->'deductions'),advance_repayment=private.aqari_hr_money(d->'advance_repayment'),method=d->>'method',reference=coalesce(d->>'reference',''),notes=coalesce(d->>'notes',''),revision=x.revision+1,updated_at=now() where x.id=p.id returning * into p;
  return to_jsonb(p);
 end if;
 if p_action in ('issue','approve_admin','approve_chairman','paid') then
  result:=public.aqari_hr(w,p_action,jsonb_build_object('employee_id',e.id,'payroll_id',p.id,'revision',p.revision));return result;
 end if;
 raise exception 'UNKNOWN_PAYROLL_ACTION';
end $function$

CREATE OR REPLACE FUNCTION public.aqari_hr(p_workspace_id uuid, p_action text, p_data jsonb DEFAULT '{}'::jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare w uuid:=p_workspace_id; d jsonb:=p_data; e private.aqari_hr_employees; p private.aqari_hr_payroll; doc private.aqari_hr_documents;
 props uuid[]; profile jsonb; result jsonb; key text; uid uuid; ident uuid; n integer; balance numeric; period date; approval jsonb;
begin
 if not private.aqari_can(w,'employees','read') then raise insufficient_privilege using message='ACCESS_DENIED';end if;
 if jsonb_typeof(d)<>'object' then raise exception 'بيانات غير صالحة.';end if;
 if p_action not in ('list','get','access') then perform 1 from public.aqari_app_state where workspace_id=w for update; end if;
 if p_action='list' then
  return jsonb_build_object('manager',private.aqari_manager(w),'employees',coalesce((select jsonb_agg(to_jsonb(x) order by x.profile->>'name_ar') from private.aqari_hr_employees x where x.workspace_id=w and private.aqari_hr_can(w,x.property_ids,'read')),'[]'),
   'members',case when private.aqari_manager(w) then (select jsonb_agg(jsonb_build_object('user_id',m.user_id,'name',q.display_name)) from public.aqari_memberships m left join public.aqari_profiles q on q.user_id=m.user_id where m.workspace_id=w and m.is_active) else '[]'::jsonb end,
   'properties',coalesce((select jsonb_agg(jsonb_build_object('id',q.id,'name',q.name) order by q.name) from public.aqari_properties q where q.workspace_id=w and private.aqari_hr_can(w,array[q.id],'read')),'[]'));
 end if;
 if p_action in ('access','grant') then
  if not private.aqari_manager(w) then raise insufficient_privilege using message='ACCESS_DENIED';end if;
  if p_action='grant' then
   if not private.aqari_can(w,'employees','write') then raise insufficient_privilege using message='SECTION_WRITE_DENIED';end if;
   uid:=(d->>'user_id')::uuid;select array_agg(distinct x::uuid) into props from jsonb_array_elements_text(d->'property_ids') x;
   if not exists(select 1 from public.aqari_memberships where workspace_id=w and user_id=uid and is_active) or cardinality(props) is null
    or exists(select 1 from unnest(props) x where not exists(select 1 from public.aqari_properties where id=x and workspace_id=w)) then raise exception 'اختر حساباً نشطاً وعقاراً محفوظاً.';end if;
   profile:=d->'permissions';
   if jsonb_typeof(profile)<>'object' or (select count(*) from jsonb_object_keys(profile))<>5 then raise exception 'صلاحيات غير مكتملة.';end if;
   foreach key in array array['read','add','edit','approve_admin','approve_chairman'] loop
    if jsonb_typeof(profile->key) is distinct from 'boolean' then raise exception 'صلاحية غير صالحة.';end if;
   end loop;
   -- CAS also covers revocation; read=false revokes all HR access immediately.
   insert into private.aqari_hr_grants(workspace_id,user_id,property_ids,permissions) select w,uid,props,profile where coalesce((d->>'revision')::bigint,0)=0
    on conflict do nothing;
   get diagnostics n=row_count;
   if n=0 then
    update private.aqari_hr_grants set property_ids=props,permissions=profile,revision=revision+1 where workspace_id=w and user_id=uid and revision=(d->>'revision')::bigint;
    get diagnostics n=row_count;if n=0 then raise serialization_failure using message='REVISION_CONFLICT';end if;
   end if;
  end if;
  return jsonb_build_object('members',(select jsonb_agg(jsonb_build_object('user_id',m.user_id,'role',m.role,'name',q.display_name)) from public.aqari_memberships m left join public.aqari_profiles q on q.user_id=m.user_id where m.workspace_id=w and m.is_active),
   'grants',coalesce((select jsonb_agg(to_jsonb(g)) from private.aqari_hr_grants g where g.workspace_id=w),'[]'),
   'audit',coalesce((select jsonb_agg(to_jsonb(x) order by x.id desc) from (select * from private.aqari_hr_audit where workspace_id=w and entity='aqari_hr_grants' order by id desc limit 100) x),'[]'));
 end if;
 ident:=(d->>'employee_id')::uuid;
 -- Lock employee first for every mutation; serializes advance repayment and property reassignment.
 select * into e from private.aqari_hr_employees where id=ident and workspace_id=w for update;
 if p_action='save_employee' then
  select array_agg(distinct x::uuid) into props from jsonb_array_elements_text(d->'property_ids') x;
  if cardinality(props) is null or exists(select 1 from unnest(props) x where not exists(select 1 from public.aqari_properties where id=x and workspace_id=w)) then raise exception 'اختر عقاراً محفوظاً واحداً على الأقل.';end if;
  if not private.aqari_hr_can(w,props,case when e.id is null then 'add' else 'edit' end) or (e.id is not null and not private.aqari_hr_can(w,e.property_ids,'edit')) then raise insufficient_privilege using message='ACCESS_DENIED';end if;
  uid:=case when d ? 'user_id' then nullif(d->>'user_id','')::uuid else e.user_id end;
  if uid is distinct from e.user_id and not private.aqari_manager(w) then raise insufficient_privilege using message='ACCESS_DENIED';end if;
  if uid is not null and not exists(select 1 from public.aqari_memberships where workspace_id=w and user_id=uid and is_active) then raise exception 'اختر حساب دخول نشطاً في مساحة العمل.';end if;
  profile:=d->'profile';
  if jsonb_typeof(profile)<>'object' or (select count(*) from jsonb_object_keys(profile)) not between 9 and 10 or exists(select 1 from jsonb_object_keys(profile) k where k not in ('name_ar','name_en','civil_id','passport','nationality','nationality_en','phone','job_ar','job_en','work_location')) then raise exception 'أكمل بيانات الموظف.';end if;
  foreach key in array array['name_ar','name_en','civil_id','passport','nationality','phone','job_ar','job_en','work_location'] loop
   if jsonb_typeof(profile->key) is distinct from 'string' or length(btrim(profile->>key)) not between 1 and 200 or (profile->>key) ~ '[<>[:cntrl:]]' then raise exception 'أكمل جميع الحقول النصية دون رموز HTML.';end if;
  end loop;
  if profile ? 'nationality_en' and (jsonb_typeof(profile->'nationality_en')<>'string' or length(profile->>'nationality_en')>200 or (profile->>'nationality_en') ~ '[<>[:cntrl:]]') then raise exception 'راجع الجنسية بالإنجليزي.';end if;
  if coalesce(d->>'hired_on','') !~ '^\d{4}-\d{2}-\d{2}$' or (d->>'hired_on')::date<'1900-01-01'::date or d->>'status' not in ('active','leave','inactive') then raise exception 'راجع تاريخ التعيين والحالة.';end if;
  if e.id is null then
   if coalesce((d->>'revision')::bigint,0)<>0 then raise serialization_failure using message='REVISION_CONFLICT';end if;
   insert into private.aqari_hr_employees(id,workspace_id,user_id,profile,property_ids,basic,allowances,hired_on,status) values(ident,w,uid,profile,props,private.aqari_hr_money(d->'basic'),private.aqari_hr_money(d->'allowances'),(d->>'hired_on')::date,d->>'status');
  else
   if e.revision is distinct from (d->>'revision')::bigint then raise serialization_failure using message='REVISION_CONFLICT';end if;
   update private.aqari_hr_employees x set user_id=uid,profile=d->'profile',property_ids=props,basic=private.aqari_hr_money(d->'basic'),allowances=private.aqari_hr_money(d->'allowances'),hired_on=(d->>'hired_on')::date,status=d->>'status',revision=x.revision+1,updated_at=now() where x.id=e.id;
  end if;
  select * into e from private.aqari_hr_employees where id=ident;
 else
  if e.id is null or not private.aqari_hr_can(w,e.property_ids,'read') then raise insufficient_privilege using message='ACCESS_DENIED';end if;
 end if;
 if p_action in ('event','prepare','save_payroll','issue','paid','reserve','finalize') and not private.aqari_hr_can(w,e.property_ids,case when p_action in ('event','prepare','reserve','finalize') then 'add' else 'edit' end) then raise insufficient_privilege using message='ACCESS_DENIED';end if;
 if p_action in ('event','edit_event') then
  if p_action='edit_event' and not private.aqari_hr_can(w,e.property_ids,'edit') then raise insufficient_privilege using message='ACCESS_DENIED';end if;
  if d->>'kind' not in ('leave','advance') or length(btrim(d->>'notes')) not between 1 and 1000 then raise exception 'أدخل نوع السجل ومرجعه.';end if;
  if p_action='event' then
  insert into private.aqari_hr_events(id,workspace_id,employee_id,kind,on_date,until_date,amount,notes) values((d->>'id')::uuid,w,e.id,d->>'kind',(d->>'on_date')::date,case when d->>'kind'='leave' then (d->>'until_date')::date end,case when d->>'kind'='advance' then private.aqari_hr_money(d->'amount') end,d->>'notes');
  else
   update private.aqari_hr_events set kind=d->>'kind',on_date=(d->>'on_date')::date,until_date=case when d->>'kind'='leave' then (d->>'until_date')::date end,amount=case when d->>'kind'='advance' then private.aqari_hr_money(d->'amount') end,notes=d->>'notes',revision=revision+1 where id=(d->>'id')::uuid and employee_id=e.id and workspace_id=w and revision=(d->>'revision')::bigint;
   get diagnostics n=row_count;if n=0 then raise serialization_failure using message='REVISION_CONFLICT';end if;
   select coalesce((select sum(amount) from private.aqari_hr_events where employee_id=e.id and kind='advance'),0)-coalesce((select sum(advance_repayment-loan_payment) from private.aqari_hr_payroll where employee_id=e.id and state='paid'),0) into balance;
   if balance<0 then raise exception 'التصحيح يقلل السلف عن الأقساط المصروفة بالفعل.';end if;
  end if;
 elsif p_action='prepare' then
  period:=(d->>'month')::date;
  if period is null or period<'2000-01-01' or period>date_trunc('month',now() at time zone 'Asia/Kuwait')::date+interval '1 month' then raise exception 'اختر شهر راتب صحيحاً.';end if;
  n:=private.aqari_hr_prepare(w,period,e.id);
  if n=0 and not exists(select 1 from private.aqari_hr_payroll where employee_id=e.id and month=period) then raise exception 'راجع حالة الموظف وتاريخ تعيينه.';end if;
 elsif p_action in ('save_payroll','issue','approve_admin','approve_chairman','paid') then
  select * into p from private.aqari_hr_payroll where id=(d->>'payroll_id')::uuid and employee_id=e.id and workspace_id=w for update;
  if p.id is null then raise exception 'الراتب غير موجود.';end if;
  if p.revision is distinct from (d->>'revision')::bigint then raise serialization_failure using message='REVISION_CONFLICT';end if;
  if p_action='save_payroll' then
   if p.state<>'draft' then raise exception 'الراتب الصادر ثابت ولا يمكن تعديله.';end if;
   if d->>'method' not in ('cash','cheque','transfer') or length(coalesce(d->>'reference',''))>120 or length(coalesce(d->>'notes',''))>1000 then raise exception 'راجع طريقة الصرف والمرجع.';end if;
   update private.aqari_hr_payroll set loan_payment=case when d ? 'loan_payment' then private.aqari_hr_money(d->'loan_payment') else p.loan_payment end,reward=case when d ? 'reward' then private.aqari_hr_money(d->'reward') else p.reward end,housing=case when d ? 'housing' then private.aqari_hr_money(d->'housing') else p.housing end,indemnity=case when d ? 'indemnity' then private.aqari_hr_money(d->'indemnity') else p.indemnity end,holidays=case when d ? 'holidays' then private.aqari_hr_money(d->'holidays') else p.holidays end,late=case when d ? 'late' then private.aqari_hr_money(d->'late') else p.late end,absence=case when d ? 'absence' then private.aqari_hr_money(d->'absence') else p.absence end,slip_details=case when d ? 'slip_details' then private.aqari_hr_slip_details(d->'slip_details') else p.slip_details end,overtime=private.aqari_hr_money(d->'overtime'),deductions=private.aqari_hr_money(d->'deductions'),advance_repayment=private.aqari_hr_money(d->'advance_repayment'),method=d->>'method',reference=coalesce(d->>'reference',''),notes=coalesce(d->>'notes',''),revision=revision+1,updated_at=now() where id=p.id;
  elsif p_action='issue' then
   if p.state<>'draft' or (p.method<>'cash' and btrim(p.reference)='') then raise exception 'أكمل مرجع الشيك أو التحويل قبل الإصدار.';end if;
   if p.slip_details->>'template'='dhahawi-v1' and (btrim(coalesce(p.slip_details->>'payer_ar',''))='' or btrim(coalesce(p.slip_details->>'payer_en',''))='') then raise exception 'أكمل اسم مسؤول الصرف بالعربي والإنجليزي في السند.';end if;
   update private.aqari_hr_payroll set issued_at=now(),voucher_no=(select lpad(v.n,greatest(4,length(v.n)),'0') from (select nextval('private.aqari_hr_voucher_seq')::text as n) v),state='issued',revision=revision+1,updated_at=now() where id=p.id;
  elsif p_action in ('approve_admin','approve_chairman') then
   if not private.aqari_hr_can(w,e.property_ids,p_action) then raise insufficient_privilege using message='ACCESS_DENIED';end if;
   if p.state<>'issued' then raise exception 'يلزم إصدار الراتب أولاً.';end if;
   if (p_action='approve_admin' and p.admin_approval is not null) or (p_action='approve_chairman' and p.chairman_approval is not null) then raise exception 'الاعتماد محفوظ بالفعل.';end if;
   if (p_action='approve_admin' and p.chairman_approval->>'user_id'=auth.uid()::text) or (p_action='approve_chairman' and p.admin_approval->>'user_id'=auth.uid()::text) then raise exception 'يلزم حساب مختلف للاعتماد الثاني.';end if;
   select jsonb_build_object('user_id',auth.uid(),'name',coalesce(display_name,auth.uid()::text),'at',now()) into approval from public.aqari_profiles where user_id=auth.uid();
   update private.aqari_hr_payroll set admin_approval=case when p_action='approve_admin' then approval else admin_approval end,chairman_approval=case when p_action='approve_chairman' then approval else chairman_approval end,revision=revision+1,updated_at=now() where id=p.id;
  else
   if p.state<>'issued' or p.admin_approval is null or p.chairman_approval is null or not exists(select 1 from private.aqari_hr_documents where payroll_id=p.id and status='ready' and attestations='{"signature":true,"fingerprint":true,"stamp":true}'::jsonb) then raise exception 'يلزم الاعتمادان والنسخة الموقعة مع البصمة والختم قبل إثبات الصرف.';end if;
   select coalesce((select sum(amount) from private.aqari_hr_events where employee_id=e.id and kind='advance'),0)-coalesce((select sum(advance_repayment-loan_payment) from private.aqari_hr_payroll where employee_id=e.id and state='paid'),0) into balance;
   if p.advance_repayment>balance then raise exception 'قسط السلفة يتجاوز الرصيد المتبقي.';end if;
   update private.aqari_hr_payroll set state='paid',paid_at=now(),revision=revision+1,updated_at=now() where id=p.id;
  end if;
 elsif p_action='reserve' then
  if d->>'kind' not in ('document','employment_contract','salary_contract','signed_salary') or length(coalesce(d->>'filename','')) not between 1 and 200 or (d->>'filename')~'[/\\[:cntrl:]]' then raise exception 'اسم أو نوع المستند غير صالح.';end if;
  if d->>'kind'='signed_salary' then
   select * into p from private.aqari_hr_payroll where id=(d->>'payroll_id')::uuid and employee_id=e.id and workspace_id=w;
   if p.id is null or p.state='draft' then raise exception 'أصدر الراتب قبل رفع نسخته الموقعة.';end if;
  end if;
  uid:=(d->>'id')::uuid;
  insert into private.aqari_hr_documents(id,workspace_id,employee_id,payroll_id,kind,filename,mime_type,size_bytes,storage_path,created_by)
  values(uid,w,e.id,p.id,d->>'kind',d->>'filename',d->>'mime_type',(d->>'size_bytes')::bigint,w::text||'/'||e.id::text||'/'||case when p.id is not null then to_char(p.month,'YYYY/MM')||'/' else 'documents/' end||uid::text,auth.uid()) on conflict(id) do nothing;
  select * into doc from private.aqari_hr_documents where id=uid and employee_id=e.id and workspace_id=w and created_by=auth.uid();
  if doc.id is null or doc.filename<>d->>'filename' or doc.mime_type<>d->>'mime_type' or doc.size_bytes<>(d->>'size_bytes')::bigint or doc.payroll_id is distinct from p.id or doc.kind<>d->>'kind' then raise exception 'تعارض مرجع الرفع.';end if;
  return to_jsonb(doc);
 elsif p_action='finalize' then
  select * into doc from private.aqari_hr_documents where id=(d->>'id')::uuid and employee_id=e.id and workspace_id=w for update;
  if doc.id is null then raise exception 'المستند غير موجود.';end if;
  if doc.status='ready' then return to_jsonb(doc);end if;
  if doc.kind='signed_salary' and d->'attestations' is distinct from '{"signature":true,"fingerprint":true,"stamp":true}'::jsonb then raise exception 'أكد وجود التوقيع والبصمة وختم الإدارة في النسخة الفعلية.';end if;
  if not exists(select 1 from storage.objects where bucket_id='aqari-hr-private' and name=doc.storage_path and (metadata->>'size')::bigint=doc.size_bytes and metadata->>'mimetype'=doc.mime_type) then raise exception 'STORED_FILE_NOT_CONFIRMED';end if;
  update private.aqari_hr_documents set status='ready',uploaded_at=now(),attestations=case when kind='signed_salary' then d->'attestations' else '{}' end where id=doc.id returning * into doc;
  return to_jsonb(doc);
 elsif p_action not in ('get','save_employee') then raise exception 'عملية غير معروفة.';
 end if;
 select coalesce((select sum(amount) from private.aqari_hr_events where employee_id=e.id and kind='advance'),0)-coalesce((select sum(advance_repayment-loan_payment) from private.aqari_hr_payroll where employee_id=e.id and state='paid'),0) into balance;
 return jsonb_build_object('employee',to_jsonb(e),'advance_balance',balance,
  'permissions',jsonb_build_object('read',true,'add',private.aqari_hr_can(w,e.property_ids,'add'),'edit',private.aqari_hr_can(w,e.property_ids,'edit'),'approve_admin',private.aqari_hr_can(w,e.property_ids,'approve_admin'),'approve_chairman',private.aqari_hr_can(w,e.property_ids,'approve_chairman')),
  'payroll',coalesce((select jsonb_agg(to_jsonb(x) order by x.month desc) from private.aqari_hr_payroll x where employee_id=e.id),'[]'),
  'events',coalesce((select jsonb_agg(to_jsonb(x) order by x.on_date desc) from private.aqari_hr_events x where employee_id=e.id),'[]'),
  'documents',coalesce((select jsonb_agg(to_jsonb(x) order by x.created_at desc) from private.aqari_hr_documents x where employee_id=e.id),'[]'),
  'audit',coalesce((select jsonb_agg(to_jsonb(x) order by x.id desc) from (select * from private.aqari_hr_audit where workspace_id=w and employee_id=e.id order by id desc limit 100) x),'[]'));
end $function$

CREATE OR REPLACE FUNCTION public.aqari_integration_dispatch_claim(p_limit integer DEFAULT 5)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare r private.aqari_integration_outbox%rowtype;c private.aqari_integration_configs%rowtype;notification public.aqari_notification_outbox%rowtype;due private.aqari_rent_due_periods%rowtype;channel text;purpose_value text;recipient text;template_value text;variables jsonb;attachment jsonb;receipt_source jsonb;items jsonb:='[]'::jsonb;tenant_name text;tenant_email text;tenant_phone text;property_name text;unit_no text;contract_no text;payment_reference text;payment_id uuid;artifact private.aqari_rent_receipt_pdf_artifacts%rowtype;claimed integer:=0;
begin
 if current_setting('role',true) is distinct from 'service_role' then raise insufficient_privilege using message='SERVER_ONLY';end if;if p_limit is null or p_limit<1 or p_limit>20 then raise invalid_parameter_value using message='INVALID_DISPATCH_LIMIT';end if;
 update private.aqari_integration_outbox set status='failed',last_error='DELIVERY_LEASE_EXPIRED',available_at=now() where status='sending' and available_at<=now() and delivered_at is null and attempts<20;update private.aqari_integration_outbox set status='dead_letter',last_error='DELIVERY_ATTEMPTS_EXHAUSTED' where status in('sending','failed') and attempts>=20 and delivered_at is null;
 for r in select * from private.aqari_integration_outbox o where o.status in('pending','failed') and o.available_at<=now() and o.attempts<20 order by o.available_at,o.created_at,o.id for update skip locked limit p_limit*8 loop
  exit when claimed>=p_limit;c:=null;channel:=null;purpose_value:=null;recipient:=null;template_value:=null;variables:='{}'::jsonb;attachment:=null;receipt_source:=null;
  if r.event_type='integration.test' then if coalesce(r.payload->>'config_id','') !~ '^[0-9a-fA-F-]{36}$' then continue;end if;select * into c from private.aqari_integration_configs x where x.workspace_id=r.workspace_id and x.id=(r.payload->>'config_id')::uuid and x.mode in('sandbox','live') and x.endpoint_origin is not null and x.secret_reference is not null;if not found then continue;end if;channel:=c.provider;recipient:=nullif(btrim(c.public_metadata->>'testRecipientReference'),'');if recipient is null or channel not in('email','whatsapp','sms','push') then continue;end if;template_value:='integration_test';variables:=jsonb_build_object('probe',true,'configId',c.id);
  elsif r.event_type='notification.rent_reminder' then if r.aggregate_id !~ '^[0-9a-fA-F-]{36}$' then update private.aqari_integration_outbox set status='dead_letter',last_error='REMINDER_ID_INVALID' where id=r.id;continue;end if;select * into notification from public.aqari_notification_outbox n where n.workspace_id=r.workspace_id and n.id=r.aggregate_id::uuid for update;if not found or notification.kind<>'rent_reminder' or notification.status='cancelled' then update private.aqari_integration_outbox set status='dead_letter',last_error='REMINDER_CANCELLED_BEFORE_DELIVERY' where id=r.id;continue;end if;perform private.aqari_refresh_rent_due_schedule(notification.workspace_id,notification.lease_id);select * into due from private.aqari_rent_due_periods d where d.workspace_id=notification.workspace_id and d.lease_id=notification.lease_id and d.period=notification.period;if not found or due.balance<=0 then update public.aqari_notification_outbox set status='cancelled' where id=notification.id;update private.aqari_integration_outbox set status='dead_letter',last_error='REMINDER_SETTLED_BEFORE_DELIVERY' where id=r.id;continue;end if;channel:=nullif(btrim(r.payload->>'channel'),'');recipient:=nullif(btrim(r.payload->>'recipientReference'),'');if channel not in('email','whatsapp') or recipient is null then update public.aqari_notification_outbox set status='failed' where id=notification.id;update private.aqari_integration_outbox set status='dead_letter',last_error='REMINDER_RECIPIENT_INVALID' where id=r.id;continue;end if;select * into c from private.aqari_integration_configs x where x.workspace_id=r.workspace_id and x.provider=channel and x.purpose in('rent_reminder','notifications','default') and x.mode in('sandbox','live') and x.endpoint_origin is not null and x.secret_reference is not null order by case x.purpose when 'rent_reminder' then 0 when 'notifications' then 1 else 2 end,x.updated_at desc,x.id limit 1;if not found then update public.aqari_notification_outbox set status='awaiting_configuration' where id=notification.id;continue;end if;template_value:='rent_reminder';variables:=coalesce(r.payload->'variables','{}'::jsonb)||jsonb_build_object('remainingBalance',due.balance,'paidAmount',due.paid_amount,'dueAmount',due.due_amount);update public.aqari_notification_outbox set status='sending' where id=notification.id;
  elsif r.event_type in('collection.receipt','collection.owner_whatsapp_summary') then channel:=nullif(btrim(r.payload->>'channel'),'');if channel not in('email','whatsapp','sms','push') then continue;end if;purpose_value:=case r.event_type when 'collection.receipt' then 'collection_receipt' else 'collection_owner_summary' end;select * into c from private.aqari_integration_configs x where x.workspace_id=r.workspace_id and x.provider=channel and x.purpose in(purpose_value,'notifications','default') and x.mode in('sandbox','live') and x.endpoint_origin is not null and x.secret_reference is not null order by case x.purpose when purpose_value then 0 when 'notifications' then 1 else 2 end,x.updated_at desc,x.id limit 1;if not found then continue;end if;
   if r.event_type='collection.receipt' then if r.aggregate_id !~ '^[0-9a-fA-F-]{36}$' then continue;end if;payment_id:=r.aggregate_id::uuid;begin receipt_source:=private.aqari_rent_receipt_pdf_system_source(r.workspace_id,payment_id);exception when others then continue;end;select t.full_name,t.email,t.phone,p.name,u.unit_no,l.contract_no,rp.reference into tenant_name,tenant_email,tenant_phone,property_name,unit_no,contract_no,payment_reference from public.aqari_rent_payments rp join public.aqari_leases l on l.workspace_id=rp.workspace_id and l.id=rp.lease_id join public.aqari_units u on u.workspace_id=l.workspace_id and u.id=l.unit_id join public.aqari_properties p on p.workspace_id=u.workspace_id and p.id=u.property_id join public.aqari_tenants t on t.workspace_id=l.workspace_id and t.id=l.tenant_id where rp.workspace_id=r.workspace_id and rp.id=payment_id;if not found then continue;end if;recipient:=case channel when 'email' then nullif(btrim(tenant_email),'') when 'whatsapp' then nullif(btrim(tenant_phone),'') when 'sms' then nullif(btrim(tenant_phone),'') else null end;if recipient is null then continue;end if;select * into artifact from private.aqari_rent_receipt_pdf_artifacts a where a.workspace_id=r.workspace_id and a.payment_id=payment_id;if found then attachment:=jsonb_build_object('filename','rent-receipt.pdf','content_type','application/pdf','base64',replace(encode(artifact.pdf_bytes,'base64'),E'\n',''),'sha256',artifact.pdf_sha256);end if;template_value:='collection_receipt';variables:=jsonb_build_object('tenantName',tenant_name,'propertyName',property_name,'unitNo',unit_no,'contractNo',contract_no,'amount',r.payload->>'amount','period',r.payload->>'period','paidAt',r.payload->>'paidAt','paymentMethod',r.payload->>'paymentMethod','receiptReference',payment_reference);
   else recipient:=nullif(btrim(r.payload->>'ownerWhatsapp'),'');if recipient is null then continue;end if;template_value:='collection_owner_summary';variables:=jsonb_build_object('ownerName',r.payload->>'ownerName','tenantName',r.payload->>'tenantName','propertyName',r.payload->>'propertyName','unitNo',r.payload->>'unitNo','amount',r.payload->>'amount','period',r.payload->>'period','paidAt',r.payload->>'paidAt','paymentMethod',r.payload->>'paymentMethod','receiptReference',r.payload->>'receiptReference');end if;
  else continue;end if;
  update private.aqari_integration_outbox set status='sending',attempts=attempts+1,available_at=now()+interval '5 minutes',last_error=null where workspace_id=r.workspace_id and id=r.id;claimed:=claimed+1;items:=items||jsonb_build_array(jsonb_strip_nulls(jsonb_build_object('eventId',r.id,'workspaceId',r.workspace_id,'eventType',r.event_type,'idempotencyKey',r.idempotency_key,'attempt',r.attempts+1,'provider',c.provider,'mode',c.mode,'endpointOrigin',c.endpoint_origin,'secretReference',c.secret_reference,'channel',channel,'recipientReference',recipient,'template',template_value,'variables',variables,'locale','ar','attachment',attachment,'receiptSource',case when attachment is null then receipt_source else null end)));
 end loop;return items;end $function$

CREATE OR REPLACE FUNCTION public.aqari_integration_dispatch_completion_claim(p_limit integer DEFAULT 5)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
 r private.aqari_integration_outbox%rowtype;c private.aqari_integration_configs%rowtype;dispatch_payload jsonb;source_id uuid;items jsonb:='[]'::jsonb;claimed integer:=0;purpose_value text;
begin
 if current_setting('role',true) is distinct from 'service_role' then raise insufficient_privilege using message='SERVER_ONLY';end if;
 if p_limit is null or p_limit<1 or p_limit>20 then raise invalid_parameter_value using message='INVALID_DISPATCH_LIMIT';end if;
 update private.aqari_integration_outbox set status='failed',last_error='DELIVERY_LEASE_EXPIRED',available_at=now() where event_type in('notification.payment_thanks','notification.operational') and status='sending' and available_at<=now() and delivered_at is null and attempts<20;
 update private.aqari_integration_outbox set status='dead_letter',last_error='DELIVERY_ATTEMPTS_EXHAUSTED' where event_type in('notification.payment_thanks','notification.operational') and status in('sending','failed') and attempts>=20 and delivered_at is null;
 for r in select * from private.aqari_integration_outbox o where o.event_type in('notification.payment_thanks','notification.operational') and o.status in('pending','failed') and o.available_at<=now() and o.attempts<20 order by o.available_at,o.created_at,o.id for update skip locked limit p_limit loop
  begin source_id:=r.aggregate_id::uuid;exception when invalid_text_representation then update private.aqari_integration_outbox set status='dead_letter',last_error='SOURCE_ID_INVALID' where id=r.id;continue;end;
  if r.event_type='notification.payment_thanks' then
   dispatch_payload:=private.aqari_payment_thanks_dispatch_payload(r.workspace_id,source_id);
   if dispatch_payload is null then update public.aqari_notification_outbox set status='cancelled' where workspace_id=r.workspace_id and id=source_id and status<>'sent';update private.aqari_integration_outbox set status='dead_letter',last_error='PAYMENT_THANKS_NOT_DELIVERABLE' where id=r.id;continue;end if;
  else
   dispatch_payload:=private.aqari_operational_dispatch_payload(r.workspace_id,source_id);
   if dispatch_payload is null then update private.aqari_notification_deliveries set status='cancelled',last_error='SOURCE_NOT_DELIVERABLE' where workspace_id=r.workspace_id and id=source_id and status not in('delivered','read');update private.aqari_integration_outbox set status='dead_letter',last_error='OPERATIONAL_NOTIFICATION_NOT_DELIVERABLE' where id=r.id;continue;end if;
  end if;
  purpose_value:=dispatch_payload->>'purpose';
  select * into c from private.aqari_integration_configs x where x.workspace_id=r.workspace_id and x.provider=dispatch_payload->>'channel' and x.purpose in(purpose_value,'notifications','default') and x.mode in('sandbox','live') and x.endpoint_origin is not null and x.secret_reference is not null order by case x.purpose when purpose_value then 0 when 'notifications' then 1 else 2 end,x.updated_at desc,x.id limit 1;
  if not found then
   update private.aqari_integration_outbox set status='failed',last_error='PROVIDER_CONFIGURATION_MISSING',available_at=now()+interval '15 minutes' where id=r.id;
   if r.event_type='notification.payment_thanks' then update public.aqari_notification_outbox set status='awaiting_configuration' where workspace_id=r.workspace_id and id=source_id;
   else update private.aqari_notification_deliveries set status='queued',last_error='PROVIDER_CONFIGURATION_MISSING' where workspace_id=r.workspace_id and id=source_id;end if;
   continue;
  end if;
  update private.aqari_integration_outbox o set payload=dispatch_payload,status='sending',attempts=o.attempts+1,available_at=now()+interval '5 minutes',last_error=null where o.id=r.id;
  if r.event_type='notification.payment_thanks' then update public.aqari_notification_outbox set status='sending' where workspace_id=r.workspace_id and id=source_id;
  else update private.aqari_notification_deliveries set status='sending',attempts=attempts+1,last_error=null where workspace_id=r.workspace_id and id=source_id;end if;
  claimed:=claimed+1;
  items:=items||jsonb_build_array(jsonb_build_object('eventId',r.id,'workspaceId',r.workspace_id,'eventType',r.event_type,'idempotencyKey',r.idempotency_key,'attempt',r.attempts+1,'provider',c.provider,'mode',c.mode,'endpointOrigin',c.endpoint_origin,'secretReference',c.secret_reference,'channel',dispatch_payload->>'channel','recipientReference',dispatch_payload->>'recipientReference','template',dispatch_payload->>'template','variables',dispatch_payload->'variables','locale','ar'));
 end loop;
 return items;
end $function$

CREATE OR REPLACE FUNCTION public.aqari_knet_payment_intent(p_workspace_id uuid, p_action text, p_data jsonb DEFAULT '{}'::jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare w uuid:=p_workspace_id;d jsonb:=coalesce(p_data,'{}'::jsonb);ident uuid;lid uuid;mon date;amount_value numeric;expires timestamptz;idem text;l public.aqari_leases%rowtype;property_ref uuid;due private.aqari_rent_due_periods%rowtype;existing private.aqari_knet_payment_intents%rowtype;initial_status text;
begin
 if auth.uid() is null or jsonb_typeof(d)<>'object' or not private.aqari_can(w,'collections','read') then raise insufficient_privilege using message='ACCESS_DENIED';end if;
 if p_action='get' then begin ident:=(d->>'id')::uuid;exception when others then raise invalid_parameter_value using message='KNET_INTENT_ID_REQUIRED';end;select * into existing from private.aqari_knet_payment_intents x where x.workspace_id=w and x.id=ident;if not found then raise no_data_found using message='KNET_INTENT_NOT_FOUND';end if;select u.property_id into property_ref from public.aqari_leases z join public.aqari_units u on u.workspace_id=z.workspace_id and u.id=z.unit_id where z.workspace_id=w and z.id=existing.lease_id;if property_ref is null or not private.aqari_can_property(w,property_ref,'properties','read') then raise insufficient_privilege using message='ACCESS_DENIED';end if;return private.aqari_knet_intent_snapshot(existing)||jsonb_build_object('user_id',auth.uid());end if;
 if p_action<>'create' or not private.aqari_can(w,'collections','write') then raise insufficient_privilege using message='KNET_INTENT_WRITE_DENIED';end if;
 if exists(select 1 from jsonb_object_keys(d) k where k not in('id','idempotencyKey','leaseId','period','amount','expiresAt')) then raise invalid_parameter_value using message='INVALID_KNET_INTENT_FIELDS';end if;
 begin ident:=(d->>'id')::uuid;lid:=(d->>'leaseId')::uuid;mon:=(d->>'period')::date;amount_value:=(d->>'amount')::numeric;expires:=(d->>'expiresAt')::timestamptz;exception when others then raise invalid_parameter_value using message='INVALID_KNET_INTENT_FIELDS';end;idem:=btrim(coalesce(d->>'idempotencyKey',''));
 if ident is null or lid is null or mon<>date_trunc('month',mon)::date or amount_value<=0 or amount_value<>round(amount_value,3) or idem!~'^[A-Za-z0-9:_-]{8,200}$' or expires<=now() or expires>now()+interval '24 hours' then raise invalid_parameter_value using message='INVALID_KNET_INTENT_FIELDS';end if;
 select * into l from public.aqari_leases x where x.workspace_id=w and x.id=lid and x.status='signed';if not found then raise check_violation using message='SIGNED_LEASE_REQUIRED';end if;select u.property_id into property_ref from public.aqari_units u where u.workspace_id=w and u.id=l.unit_id;if property_ref is null or not private.aqari_can_property(w,property_ref,'properties','read') then raise insufficient_privilege using message='KNET_PROPERTY_ACCESS_DENIED';end if;
 perform private.aqari_refresh_rent_due_schedule(w,lid);select * into due from private.aqari_rent_due_periods x where x.workspace_id=w and x.lease_id=lid and x.period=mon;if not found or due.balance<=0 or amount_value>due.balance then raise check_violation using message='KNET_AMOUNT_EXCEEDS_CURRENT_BALANCE';end if;
 select * into existing from private.aqari_knet_payment_intents x where x.workspace_id=w and x.idempotency_key=idem for update;if found then if existing.id<>ident or existing.lease_id<>lid or existing.period<>mon or existing.amount<>amount_value or existing.expires_at<>expires then raise unique_violation using message='KNET_IDEMPOTENCY_CONFLICT';end if;return private.aqari_knet_intent_snapshot(existing)||jsonb_build_object('user_id',auth.uid(),'replayed',true);end if;
 initial_status:=case when exists(select 1 from private.aqari_integration_configs c where c.workspace_id=w and c.provider='knet' and c.purpose in('rent_payment','payments','default') and c.mode in('sandbox','live') and c.endpoint_origin is not null and c.secret_reference is not null) then 'pending' else 'awaiting_configuration' end;
 insert into private.aqari_knet_payment_intents(id,workspace_id,lease_id,period,amount,idempotency_key,status,expires_at,created_by) values(ident,w,lid,mon,amount_value,idem,initial_status,expires,auth.uid()) returning * into existing;insert into private.aqari_knet_payment_events(workspace_id,intent_id,action,actor_kind,actor_id,reason,details) values(w,ident,'create','authenticated',auth.uid(),'إنشاء رابط دفع KNET',jsonb_build_object('leaseId',lid,'period',mon,'amount',amount_value,'expiresAt',expires));insert into private.aqari_integration_outbox(id,workspace_id,event_type,aggregate_id,schema_version,payload,idempotency_key,status,attempts,available_at) values(extensions.gen_random_uuid(),w,'knet.payment_link',ident::text,1,jsonb_build_object('intentId',ident),'knet-link:'||ident::text,'pending',0,now()) on conflict(workspace_id,idempotency_key) do nothing;return private.aqari_knet_intent_snapshot(existing)||jsonb_build_object('user_id',auth.uid(),'replayed',false);
end $function$

CREATE OR REPLACE FUNCTION public.aqari_knet_payment_link_claim(p_limit integer DEFAULT 3)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare r private.aqari_integration_outbox%rowtype;i private.aqari_knet_payment_intents%rowtype;c private.aqari_integration_configs%rowtype;l public.aqari_leases%rowtype;due private.aqari_rent_due_periods%rowtype;items jsonb:='[]'::jsonb;claimed integer:=0;
begin
 if current_setting('role',true) is distinct from 'service_role' then raise insufficient_privilege using message='SERVER_ONLY';end if;if p_limit is null or p_limit<1 or p_limit>10 then raise invalid_parameter_value using message='INVALID_KNET_CLAIM_LIMIT';end if;
 update private.aqari_integration_outbox set status='failed',last_error='KNET_LINK_LEASE_EXPIRED',available_at=now() where event_type='knet.payment_link' and status='sending' and available_at<=now() and delivered_at is null and attempts<20;
 for r in select * from private.aqari_integration_outbox o where o.event_type='knet.payment_link' and o.status in('pending','failed') and o.available_at<=now() and o.attempts<20 order by o.available_at,o.created_at,o.id for update skip locked limit p_limit*5 loop
  exit when claimed>=p_limit;begin select * into i from private.aqari_knet_payment_intents x where x.workspace_id=r.workspace_id and x.id=r.aggregate_id::uuid for update;exception when invalid_text_representation then i:=null;end;if i.id is null then update private.aqari_integration_outbox set status='dead_letter',last_error='KNET_INTENT_NOT_FOUND' where id=r.id;continue;end if;if i.status in('paid','cancelled','expired') then update private.aqari_integration_outbox set status='dead_letter',last_error='KNET_INTENT_CLOSED' where id=r.id;continue;end if;
  if i.expires_at<=now() then update private.aqari_knet_payment_intents set status='expired',updated_at=now() where id=i.id;update private.aqari_integration_outbox set status='dead_letter',last_error='KNET_INTENT_EXPIRED' where id=r.id;insert into private.aqari_knet_payment_events(workspace_id,intent_id,action,actor_kind,reason) values(i.workspace_id,i.id,'expire','system','انتهت صلاحية رابط الدفع قبل إرساله');continue;end if;
  perform private.aqari_refresh_rent_due_schedule(i.workspace_id,i.lease_id);select * into due from private.aqari_rent_due_periods d where d.workspace_id=i.workspace_id and d.lease_id=i.lease_id and d.period=i.period;if not found or due.balance<i.amount then update private.aqari_knet_payment_intents set status='cancelled',updated_at=now() where id=i.id;update private.aqari_integration_outbox set status='dead_letter',last_error='KNET_BALANCE_CHANGED' where id=r.id;insert into private.aqari_knet_payment_events(workspace_id,intent_id,action,actor_kind,reason) values(i.workspace_id,i.id,'cancel','system','تغير الرصيد قبل توليد رابط الدفع');continue;end if;
  select * into l from public.aqari_leases z where z.workspace_id=i.workspace_id and z.id=i.lease_id and z.status='signed';if not found then update private.aqari_integration_outbox set status='dead_letter',last_error='KNET_SIGNED_LEASE_REQUIRED' where id=r.id;continue;end if;
  select * into c from private.aqari_integration_configs x where x.workspace_id=i.workspace_id and x.provider='knet' and x.purpose in('rent_payment','payments','default') and x.mode in('sandbox','live') and x.endpoint_origin is not null and x.secret_reference is not null order by case x.purpose when 'rent_payment' then 0 when 'payments' then 1 else 2 end,x.updated_at desc limit 1;if not found then update private.aqari_knet_payment_intents set status='awaiting_configuration',updated_at=now() where id=i.id;update private.aqari_integration_outbox set status='failed',last_error='KNET_PROVIDER_CONFIGURATION_MISSING',available_at=now()+interval '15 minutes' where id=r.id;continue;end if;
  update private.aqari_knet_payment_intents set status='pending',updated_at=now() where id=i.id;update private.aqari_integration_outbox o set status='sending',attempts=o.attempts+1,available_at=now()+interval '5 minutes',last_error=null where o.id=r.id;claimed:=claimed+1;items:=items||jsonb_build_array(jsonb_build_object('eventId',r.id,'workspaceId',i.workspace_id,'eventType','knet.payment_link','intentId',i.id,'idempotencyKey',i.idempotency_key,'leaseId',i.lease_id,'contractNo',l.contract_no,'amount',i.amount,'currency',i.currency,'expiresAt',i.expires_at,'endpointOrigin',c.endpoint_origin,'secretReference',c.secret_reference,'callbackPath','/api/provider-webhook?workspace='||i.workspace_id::text||'&provider=knet','returnPath','/app?release=V267&knet_intent='||i.id::text));
 end loop;return items;
end $function$

CREATE OR REPLACE FUNCTION public.aqari_knet_payment_link_result(p_event_id uuid, p_ok boolean, p_retryable boolean DEFAULT true, p_provider_reference text DEFAULT NULL::text, p_payment_url text DEFAULT NULL::text, p_error text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare r private.aqari_integration_outbox%rowtype;i private.aqari_knet_payment_intents%rowtype;next_status text;err text;ref text;url_value text;delay_minutes integer;
begin
 if current_setting('role',true) is distinct from 'service_role' then raise insufficient_privilege using message='SERVER_ONLY';end if;select * into r from private.aqari_integration_outbox where id=p_event_id and event_type='knet.payment_link' for update;if not found then raise no_data_found using message='KNET_LINK_EVENT_NOT_FOUND';end if;select * into i from private.aqari_knet_payment_intents where workspace_id=r.workspace_id and id=r.aggregate_id::uuid for update;if not found then raise no_data_found using message='KNET_INTENT_NOT_FOUND';end if;if r.status='sent' and i.status='link_ready' then return private.aqari_knet_intent_snapshot(i)||jsonb_build_object('replayed',true);end if;if r.status<>'sending' then raise serialization_failure using message='KNET_LINK_EVENT_NOT_CLAIMED';end if;
 ref:=nullif(left(regexp_replace(coalesce(p_provider_reference,''),'[[:cntrl:]]','','g'),300),'');url_value:=nullif(btrim(coalesce(p_payment_url,'')),'');err:=nullif(left(regexp_replace(coalesce(p_error,''),'[[:cntrl:]]','','g'),1000),'');
 if p_ok then if ref is null or url_value is null or length(url_value)>2048 or url_value not like 'https://%' or url_value~'[[:space:][:cntrl:]]' then raise check_violation using message='INVALID_KNET_PROVIDER_RESULT';end if;update private.aqari_knet_payment_intents set status='link_ready',provider_reference=ref,payment_url=url_value,updated_at=now() where id=i.id returning * into i;update private.aqari_integration_outbox set status='sent',provider_reference=ref,last_error=null,delivered_at=now(),available_at=now() where id=r.id;insert into private.aqari_integration_delivery_events(workspace_id,event_id,attempt,outcome,provider_reference) values(r.workspace_id,r.id,r.attempts,'sent',ref);insert into private.aqari_knet_payment_events(workspace_id,intent_id,action,actor_kind,reason,details) values(i.workspace_id,i.id,'link_ready','system','تم توليد رابط دفع KNET',jsonb_build_object('providerReference',ref));
 else if coalesce(p_retryable,true) and r.attempts<20 then next_status:='failed';else next_status:='dead_letter';end if;delay_minutes:=least(60,greatest(1,power(2,least(r.attempts,6)-1)::integer));update private.aqari_integration_outbox set status=next_status,last_error=coalesce(err,'KNET_PROVIDER_LINK_FAILED'),available_at=case when next_status='failed' then now()+make_interval(mins=>delay_minutes) else now() end where id=r.id;update private.aqari_knet_payment_intents set status=case when next_status='dead_letter' then 'failed' else 'pending' end,updated_at=now() where id=i.id returning * into i;insert into private.aqari_integration_delivery_events(workspace_id,event_id,attempt,outcome,error_code) values(r.workspace_id,r.id,r.attempts,next_status,coalesce(err,'KNET_PROVIDER_LINK_FAILED'));insert into private.aqari_knet_payment_events(workspace_id,intent_id,action,actor_kind,reason,details) values(i.workspace_id,i.id,'link_failed','system',coalesce(err,'فشل توليد رابط دفع KNET'),jsonb_build_object('retryable',coalesce(p_retryable,true)));end if;return private.aqari_knet_intent_snapshot(i)||jsonb_build_object('replayed',false);
end $function$

CREATE OR REPLACE FUNCTION public.aqari_kpi_dashboard(p_workspace_id uuid, p_from date, p_to date)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare w uuid:=p_workspace_id;from_date date:=p_from;to_date date:=p_to;units_count integer;occupied_count integer;expected numeric;collected numeric;expenses numeric;lag numeric;
begin
 if auth.uid() is null or not private.aqari_manager(w) or not private.aqari_can(w,'finance','read') then raise insufficient_privilege using message='ACCESS_DENIED';end if;
 if from_date is null or to_date is null or from_date>to_date or to_date-from_date>366 then raise exception 'INVALID_KPI_PERIOD' using errcode='22023';end if;
 select count(*) into units_count from public.aqari_units u where u.workspace_id=w;
 select count(distinct l.unit_id),coalesce(sum(l.monthly_rent),0) into occupied_count,expected from public.aqari_leases l
  where l.workspace_id=w and l.status='signed' and l.start_date<=to_date and l.end_date>=from_date;
 select coalesce(sum(p.amount),0),avg(greatest(0,p.paid_at::date-p.period::date)) into collected,lag from public.aqari_rent_payments p
  where p.workspace_id=w and p.status<>'cancelled' and p.paid_at::date between from_date and to_date;
 select coalesce(sum(e.amount),0) into expenses from private.aqari_financial_expenses e
  where e.workspace_id=w and e.state='approved' and e.expense_date between from_date and to_date;
 return jsonb_build_object(
  'period',jsonb_build_object('from',from_date,'to',to_date),
  'units',jsonb_build_object('total',units_count,'occupied',occupied_count,'vacant',greatest(units_count-occupied_count,0),
   'vacancy_rate',case when units_count=0 then null else round((greatest(units_count-occupied_count,0)::numeric/units_count)*100,2) end),
  'collections',jsonb_build_object('expected_monthly_snapshot',expected::text,'actual',collected::text,
   'rate',case when expected=0 then null else round((collected/expected)*100,2) end,
   'average_days',case when lag is null then null else round(lag,2) end),
  'profit',jsonb_build_object('actual_income',collected::text,'approved_expenses',expenses::text,'actual_net',(collected-expenses)::text,
   'projected_net',(expected-expenses)::text,'projection_basis','active_contract_monthly_rent_minus_period_approved_expenses'),
  'sources',jsonb_build_array('public.aqari_units','public.aqari_leases','public.aqari_rent_payments','private.aqari_financial_expenses'),
  'generated_at',now()
 );
end $function$

CREATE OR REPLACE FUNCTION public.aqari_link_property_statement(p_workspace_id uuid, p_property_id uuid, p_period date, p_source_sha256 text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare st public.aqari_property_statements%rowtype; saved public.aqari_app_state%rowtype; d jsonb; r jsonb; prof jsonb; con jsonb; prov jsonb;
 t_id uuid;l_id uuid;u_id uuid;profile_ref text;contract_ref text;identity_key text;raw_phone text;valid_phone text;valid_civil text;display_name text;start_on date;end_on date;linked integer:=0;new_profiles integer:=0;new_leases integer:=0;
begin
 if auth.uid() is null or not private.aqari_manager(p_workspace_id) or not private.aqari_can(p_workspace_id,'tenants','write') or not private.aqari_can(p_workspace_id,'contracts','write') or not private.aqari_can(p_workspace_id,'properties','write') then raise exception 'ACCESS_DENIED' using errcode='42501';end if;
 perform pg_advisory_xact_lock(hashtextextended(p_workspace_id::text,0));
 select * into strict st from public.aqari_property_statements where workspace_id=p_workspace_id and property_id=p_property_id and period=p_period;
 if st.source_sha256 is distinct from p_source_sha256 or st.content->>'property_key'<>'shaikhah-tower' then raise exception 'SOURCE_MISMATCH';end if;
 select * into strict saved from public.aqari_app_state where workspace_id=p_workspace_id for update;
 d:=private.aqari_unwrap(saved.payload);
 if not exists(select 1 from jsonb_array_elements(coalesce(d->'properties','[]')) x where x->>0=st.content->>'property_name') then
  d:=jsonb_set(d,'{properties}',coalesce(d->'properties','[]')||jsonb_build_array(jsonb_build_array(st.content->>'property_name','غير مدون',jsonb_array_length(st.content->'rows'),st.content#>'{summary,printed_totals,rent_kd}')));
 end if;
 for r in select value from jsonb_array_elements(st.content->'rows') loop
  if exists(select 1 from public.aqari_statement_links where workspace_id=p_workspace_id and property_id=p_property_id and period=p_period and unit_no=r->>'unit') then linked:=linked+1;continue;end if;
  select id into strict u_id from public.aqari_units where workspace_id=p_workspace_id and property_id=p_property_id and unit_no=r->>'unit';
  raw_phone:=nullif(r->>'phone_raw',''); valid_phone:=case when raw_phone ~ '^[+]?[0-9]{8,15}$' then raw_phone else null end;
  valid_civil:=case when r->>'civil_id_raw' ~ '^[0-9]{12}$' then r->>'civil_id_raw' else null end;
  identity_key:=md5(coalesce(r->>'civil_id_raw','')||':'||coalesce(raw_phone,'')||':'||coalesce(r->>'name_en_raw',''));
  profile_ref:='source:'||p_property_id::text||':tenant:'||identity_key;
  t_id:=md5(p_workspace_id::text||':tenant:'||profile_ref)::uuid;
  display_name:=nullif(r->>'name_en_raw','');
  prov:=jsonb_build_object('property_id',p_property_id,'period',p_period,'source_sha256',st.source_sha256,'contact_page',r->'contact_source_page','financial_page',r->'financial_source_page','linked_by',auth.uid());
  if not exists(select 1 from public.aqari_tenants where workspace_id=p_workspace_id and id=t_id) then
   if exists(select 1 from public.aqari_tenants where workspace_id=p_workspace_id and ((valid_civil is not null and civil_id=valid_civil) or (valid_phone is not null and phone=valid_phone))) then raise exception 'TENANT_IDENTITY_REVIEW_REQUIRED';end if;
   prof:=jsonb_build_object('id',profile_ref,'nameAr','','nameEn',coalesce(display_name,''),'civilId',coalesce(valid_civil,''),'phone',coalesce(valid_phone,''),'email','','nationality',coalesce(r->>'nationality_raw',''),'address','','attachments','[]'::jsonb,'source','statement-import','importStatus','source_saved','sourceValues',r,'sourceReference',prov);
   insert into public.aqari_tenants(id,workspace_id,external_ref,full_name,civil_id,phone,email,profile,import_source) values(t_id,p_workspace_id,profile_ref,display_name,valid_civil,valid_phone,null,prof,prov);
   d:=jsonb_set(d,'{tenantProfilesV267}',coalesce(d->'tenantProfilesV267','[]')||jsonb_build_array(prof));
   d:=jsonb_set(d,'{tenants}',coalesce(d->'tenants','[]')||jsonb_build_array(jsonb_build_array(coalesce(display_name,''),st.content->>'property_name',raw_phone,'ملف مصدر محفوظ',profile_ref)));
   new_profiles:=new_profiles+1;
  else select profile into prof from public.aqari_tenants where workspace_id=p_workspace_id and id=t_id;end if;
  contract_ref:='source:'||p_property_id::text||':lease:'||(r->>'contract_no_raw');
  l_id:=md5(p_workspace_id::text||':lease:'||contract_ref)::uuid;
  start_on:=private.aqari_source_date(r->>'contract_start_raw');end_on:=private.aqari_source_date(r->>'contract_end_raw');
  if (r->'pending') ? 'contract_dates' or end_on<start_on then start_on:=null;end_on:=null;end if;
  con:=jsonb_build_object('id',contract_ref,'source','statement-import','contract_no',r->>'contract_no_raw','tenantId',profile_ref,'tenant',coalesce(display_name,''),'tenantProfile',prof,'property',st.content->>'property_name','unit',r->>'unit','rent',r->'contract_rent_kd','currentRent',r->'current_rent_kd','deposit',null,'status','draft','start_date',start_on,'end_date',end_on,'clauses','[]'::jsonb,'sourceReference',prov,'sourceValues',r,'pending',r->'pending','importStatus','source_saved');
  insert into public.aqari_leases(id,workspace_id,external_ref,tenant_id,unit_id,contract_no,start_date,end_date,monthly_rent,deposit,status,snapshot,import_source) values(l_id,p_workspace_id,contract_ref,t_id,u_id,r->>'contract_no_raw',start_on,end_on,(r->>'contract_rent_kd')::numeric,null,'draft',con,prov);
  d:=jsonb_set(d,'{contractsV202}',coalesce(d->'contractsV202','[]')||jsonb_build_array(con));
  d:=jsonb_set(d,'{leases}',coalesce(d->'leases','[]')||jsonb_build_array(jsonb_build_array(coalesce(display_name,''),r->>'unit',r->'contract_rent_kd',end_on,contract_ref)));
  d:=jsonb_set(d,'{tenantDirectoryV202}',coalesce(d->'tenantDirectoryV202','[]')||jsonb_build_array(jsonb_build_object('property',st.content->>'property_name','unit',r->>'unit','tenant',coalesce(display_name,''),'contractNo',r->>'contract_no_raw','phone',valid_phone,'civilId',valid_civil,'nationality',r->>'nationality_raw','email','','source','statement-import','verified',false,'tenantProfileId',profile_ref)));
  insert into public.aqari_statement_links(workspace_id,property_id,period,unit_no,tenant_id,lease_id,source_sha256,linked_by) values(p_workspace_id,p_property_id,p_period,r->>'unit',t_id,l_id,st.source_sha256,auth.uid());
  linked:=linked+1;new_leases:=new_leases+1;
 end loop;
 -- The legacy tenant table columns are name / units / rent / status / profile id.
 d:=jsonb_set(d,'{tenants}',
  coalesce((select jsonb_agg(x) from jsonb_array_elements(coalesce(d->'tenants','[]')) x where not exists(select 1 from public.aqari_tenants t where t.workspace_id=p_workspace_id and t.external_ref=x->>4 and t.import_source->>'property_id'=p_property_id::text)),'[]'::jsonb)
  ||coalesce((select jsonb_agg(row_value) from (select jsonb_build_array(coalesce(t.full_name,''),string_agg(lk.unit_no,' / ' order by lk.unit_no),sum((sr->>'current_rent_kd')::numeric),'ملف مصدر محفوظ',t.external_ref) row_value from public.aqari_statement_links lk join public.aqari_tenants t on t.workspace_id=lk.workspace_id and t.id=lk.tenant_id join lateral jsonb_array_elements(st.content->'rows') sr on sr->>'unit'=lk.unit_no where lk.workspace_id=p_workspace_id and lk.property_id=p_property_id and lk.period=p_period group by t.id,t.full_name,t.external_ref order by min(lk.unit_no)) rows_for_tenants),'[]'::jsonb));
 if new_profiles>0 or new_leases>0 or d is distinct from private.aqari_unwrap(saved.payload) then
  update public.aqari_app_state set payload=case when saved.payload->>'format'='aqari-cloud-state-v1' then jsonb_set(saved.payload,'{snapshot,values,aqari_v30}',d) when saved.payload->>'schema'='aqari-local-snapshot-v1' then jsonb_set(saved.payload,'{values,aqari_v30}',d) else d end,revision=saved.revision+1,updated_by=auth.uid(),updated_at=now() where workspace_id=p_workspace_id;
  insert into public.aqari_operation_audit(workspace_id,user_id,action,revision) values(p_workspace_id,auth.uid(),'source_statement_linked:'||p_property_id::text||':'||p_period::text,saved.revision+1);
 end if;
 return jsonb_build_object('linked_rows',linked,'new_tenants',new_profiles,'new_leases',new_leases,'posted_payments',0);
end $function$

CREATE OR REPLACE FUNCTION public.aqari_maintenance_attachment_cancel(p_attachment_id uuid)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare target public.aqari_maintenance_attachments%rowtype;
begin
 select * into target from public.aqari_maintenance_attachments where id=p_attachment_id for update;
 if not found or target.created_by is distinct from auth.uid()
  or not private.aqari_maintenance_attachment_access(target.workspace_id,target.request_id,'write') then raise insufficient_privilege using message='ACCESS_DENIED';end if;
 if target.status='cancelled' then return target.id;end if;
 if target.status<>'draft' then raise exception 'INVALID_MAINTENANCE_ATTACHMENT_STATE';end if;
 if exists(select 1 from storage.objects where bucket_id=target.storage_bucket and name=target.storage_path) then raise exception 'STORAGE_OBJECT_STILL_PRESENT';end if;
 update public.aqari_maintenance_attachments set status='cancelled' where id=target.id;
 return target.id;
end $function$

CREATE OR REPLACE FUNCTION public.aqari_maintenance_attachment_finalize(p_attachment_id uuid, p_size_bytes bigint, p_checksum text)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare target public.aqari_maintenance_attachments%rowtype; saved storage.objects%rowtype;
begin
 select * into target from public.aqari_maintenance_attachments where id=p_attachment_id for update;
 if not found or target.created_by is distinct from auth.uid()
  or not private.aqari_maintenance_attachment_access(target.workspace_id,target.request_id,'write') then raise insufficient_privilege using message='ACCESS_DENIED';end if;
 if target.status='uploaded' and target.size_bytes=p_size_bytes and target.checksum_sha256 is not distinct from p_checksum then return target.id;end if;
 if target.status<>'draft' or p_size_bytes not between 1 and 10485760 or p_checksum !~ '^[a-f0-9]{64}$' then raise exception 'INVALID_MAINTENANCE_ATTACHMENT';end if;
 select * into saved from storage.objects where bucket_id=target.storage_bucket and name=target.storage_path;
 if not found or coalesce((saved.metadata->>'size')::bigint,0)<>p_size_bytes or saved.metadata->>'mimetype' is distinct from target.mime_type then raise exception 'STORED_FILE_NOT_CONFIRMED';end if;
 update public.aqari_maintenance_attachments set status='uploaded',size_bytes=p_size_bytes,checksum_sha256=p_checksum,uploaded_at=now() where id=target.id;
 return target.id;
end $function$

CREATE OR REPLACE FUNCTION public.aqari_maintenance_attachment_reserve(p_workspace_id uuid, p_request_id uuid, p_original_filename text, p_mime_type text)
 RETURNS TABLE(attachment_id uuid, storage_bucket text, storage_path text)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare new_id uuid:=gen_random_uuid(); ext text; new_path text;
begin
 if auth.uid() is null or not private.aqari_maintenance_attachment_access(p_workspace_id,p_request_id,'write') then raise insufficient_privilege using message='ACCESS_DENIED';end if;
 if p_original_filename is null or length(p_original_filename) not between 1 and 250
  or p_mime_type not in ('image/jpeg','image/png','image/webp','image/heic','image/heif') then raise exception 'INVALID_MAINTENANCE_ATTACHMENT';end if;
 ext:=case p_mime_type when 'image/png' then 'png' when 'image/webp' then 'webp' when 'image/heic' then 'heic' when 'image/heif' then 'heif' else 'jpg' end;
 new_path:=p_workspace_id::text||'/maintenance/'||p_request_id::text||'/'||new_id::text||'.'||ext;
 insert into public.aqari_maintenance_attachments(id,workspace_id,request_id,storage_path,original_filename,mime_type,created_by)
 values(new_id,p_workspace_id,p_request_id,new_path,p_original_filename,p_mime_type,auth.uid());
 return query select new_id,'aqari-documents'::text,new_path;
end $function$

CREATE OR REPLACE FUNCTION public.aqari_maintenance_evidence(p_workspace_id uuid, p_property_id uuid, p_action text DEFAULT 'context'::text, p_data jsonb DEFAULT '{}'::jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
 w uuid:=p_workspace_id;p uuid:=p_property_id;d jsonb:=coalesce(p_data,'{}'::jsonb);task_id uuid;document_id uuid;stage_value text;why text;actor text;task private.aqari_property_maintenance_tasks;record_json jsonb;
begin
 if auth.uid() is null or jsonb_typeof(d) is distinct from 'object' then raise insufficient_privilege using message='ACCESS_DENIED';end if;
 if not private.aqari_can(w,'maintenance','read') or not private.aqari_can_property(w,p,'maintenance','read') then raise insufficient_privilege using message='MAINTENANCE_EVIDENCE_ACCESS_DENIED';end if;
 if p_action='context' then
  return jsonb_build_object(
   'workspace_id',w,'propertyId',p,'user_id',auth.uid(),
   'canWrite',private.aqari_can(w,'maintenance','write') and private.aqari_can_property(w,p,'maintenance','write') and private.aqari_can(w,'documents','read'),
   'tasks',coalesce((select jsonb_agg(jsonb_build_object(
      'id',t.id,'taskNo',t.task_no,'description',t.description,'status',t.status,'dueOn',t.due_on,
      'assignedAt',t.assigned_at,'startedAt',t.started_at,'completedAt',t.completed_at,'policyVersion',t.evidence_policy_version,
      'overdueDays',case when t.status in('completed','cancelled') then greatest(0,((coalesce(t.completed_at,t.cancelled_at) at time zone 'Asia/Kuwait')::date-t.due_on)) else greatest(0,((now() at time zone 'Asia/Kuwait')::date-t.due_on)) end,
      'needsEscalation',t.status not in('completed','cancelled') and (now() at time zone 'Asia/Kuwait')::date>t.due_on,
      'responseMinutes',case when t.assigned_at is null then null else greatest(0,floor(extract(epoch from (coalesce(t.started_at,t.completed_at,now())-t.assigned_at))/60)) end,
      'resolutionMinutes',case when t.started_at is null then null else greatest(0,floor(extract(epoch from (coalesce(t.completed_at,now())-t.started_at))/60)) end
    ) order by t.due_on desc,t.task_no) from private.aqari_property_maintenance_tasks t where t.workspace_id=w and t.property_id=p),'[]'::jsonb),
   'evidence',coalesce((select jsonb_agg(jsonb_build_object('id',e.id,'taskId',e.task_id,'documentId',e.document_id,'stage',e.stage,'note',e.note,'capturedAt',e.captured_at,'capturedBy',coalesce(nullif(pr.display_name,''),e.captured_by::text)) order by e.captured_at,e.id)
      from private.aqari_maintenance_evidence e left join public.aqari_profiles pr on pr.user_id=e.captured_by where e.workspace_id=w and e.property_id=p),'[]'::jsonb),
   'imageDocuments',coalesce((select jsonb_agg(jsonb_build_object('id',x.id,'title',x.title,'documentNo',x.document_no,'mimeType',x.mime_type) order by x.created_at desc,x.id)
      from public.aqari_documents x where x.workspace_id=w and x.status='uploaded' and x.mime_type in('image/jpeg','image/png','image/webp','image/heic','image/heif') and private.aqari_operations_document(w,p,x.id) and private.aqari_document_entity(w,x.entity_type,x.entity_ref,'read')),'[]'::jsonb)
  );
 end if;
 if p_action<>'add' then raise invalid_parameter_value using message='UNKNOWN_MAINTENANCE_EVIDENCE_ACTION';end if;
 if not private.aqari_can(w,'maintenance','write') or not private.aqari_can_property(w,p,'maintenance','write') or not private.aqari_can(w,'documents','read') then raise insufficient_privilege using message='MAINTENANCE_EVIDENCE_WRITE_DENIED';end if;
 perform private.aqari_require_sensitive_aal2(w);
 task_id:=nullif(d->>'taskId','')::uuid;document_id:=nullif(d->>'documentId','')::uuid;stage_value:=d->>'stage';why:=btrim(coalesce(d->>'reason',''));
 if task_id is null or document_id is null or stage_value not in('before','after') or length(why) not between 3 and 1000 then raise invalid_parameter_value using message='INVALID_MAINTENANCE_EVIDENCE';end if;
 select * into task from private.aqari_property_maintenance_tasks t where t.workspace_id=w and t.property_id=p and t.id=task_id for update;
 if not found then raise insufficient_privilege using message='MAINTENANCE_TASK_SCOPE_MISMATCH';end if;
 if stage_value='before' and task.status not in('scheduled','assigned') then raise check_violation using message='MAINTENANCE_BEFORE_EVIDENCE_WINDOW_CLOSED';end if;
 if stage_value='after' and task.status<>'in_progress' then raise check_violation using message='MAINTENANCE_AFTER_EVIDENCE_REQUIRES_IN_PROGRESS';end if;
 if not private.aqari_operations_document(w,p,document_id) or not exists(select 1 from public.aqari_documents x where x.workspace_id=w and x.id=document_id and x.status='uploaded' and x.mime_type in('image/jpeg','image/png','image/webp','image/heic','image/heif') and private.aqari_document_entity(w,x.entity_type,x.entity_ref,'read')) then raise check_violation using message='MAINTENANCE_EVIDENCE_IMAGE_NOT_VERIFIED';end if;
 insert into private.aqari_maintenance_evidence as evidence_row(workspace_id,property_id,task_id,document_id,stage,note,captured_by)
 values(w,p,task_id,document_id,stage_value,why,auth.uid())
 returning jsonb_build_object('id',evidence_row.id,'workspace_id',evidence_row.workspace_id,'property_id',evidence_row.property_id,'task_id',evidence_row.task_id,'document_id',evidence_row.document_id,'stage',evidence_row.stage,'note',evidence_row.note,'captured_by',evidence_row.captured_by,'captured_at',evidence_row.captured_at) into record_json;
 select coalesce(nullif(display_name,''),auth.uid()::text) into actor from public.aqari_profiles where user_id=auth.uid();actor:=coalesce(actor,auth.uid()::text);
 insert into private.aqari_operations_audit(workspace_id,domain,entity_id,action,actor_id,actor_name,reason,before_value,after_value)
 values(w,'maintenance',task_id,'evidence_'||stage_value,auth.uid(),actor,why,null,record_json);
 return jsonb_build_object('workspace_id',w,'propertyId',p,'user_id',auth.uid(),'record',record_json);
end $function$

CREATE OR REPLACE FUNCTION public.aqari_maintenance_sla(p_workspace_id uuid, p_property_id uuid, p_action text DEFAULT 'context'::text, p_data jsonb DEFAULT '{}'::jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare w uuid:=p_workspace_id;p uuid:=p_property_id;d jsonb:=coalesce(p_data,'{}'::jsonb);existing private.aqari_property_maintenance_sla;expected bigint;actor text;why text;after_row jsonb;run_result jsonb;
begin
 if auth.uid() is null or jsonb_typeof(d) is distinct from 'object' then raise insufficient_privilege using message='ACCESS_DENIED';end if;
 if not private.aqari_can(w,'maintenance','read') or not private.aqari_can_property(w,p,'maintenance','read') then raise insufficient_privilege using message='MAINTENANCE_SLA_ACCESS_DENIED';end if;
 if p_action='context' then
  return jsonb_build_object(
   'workspace_id',w,'propertyId',p,'user_id',auth.uid(),'manager',private.aqari_manager(w),
   'canWrite',private.aqari_manager(w) and private.aqari_can(w,'maintenance','write') and private.aqari_can_property(w,p,'maintenance','write'),
   'policy',(select jsonb_build_object('responseMinutes',s.response_minutes,'resolutionMinutes',s.resolution_minutes,'channel',s.escalation_channel,'active',s.is_active,'revision',s.revision,'updatedAt',s.updated_at) from private.aqari_property_maintenance_sla s where s.workspace_id=w and s.property_id=p),
   'tasks',coalesce((select jsonb_agg(jsonb_build_object('id',t.id,'taskNo',t.task_no,'status',t.status,'revision',t.revision,'assignedAt',t.assigned_at,'startedAt',t.started_at,'responseBreached',s.is_active and t.status='assigned' and t.assigned_at is not null and t.started_at is null and now()>=t.assigned_at+make_interval(mins=>s.response_minutes),'resolutionBreached',s.is_active and t.status='in_progress' and t.started_at is not null and t.completed_at is null and now()>=t.started_at+make_interval(mins=>s.resolution_minutes)) order by t.due_on desc,t.id) from private.aqari_property_maintenance_tasks t left join private.aqari_property_maintenance_sla s on s.workspace_id=t.workspace_id and s.property_id=t.property_id where t.workspace_id=w and t.property_id=p),'[]'::jsonb),
   'escalations',coalesce((select jsonb_agg(jsonb_build_object('id',e.id,'taskId',e.task_id,'stage',e.stage,'thresholdMinutes',e.threshold_minutes,'breachedAt',e.breached_at,'preparedAt',e.prepared_at,'notificationId',e.notification_id) order by e.prepared_at desc,e.id) from private.aqari_maintenance_sla_escalations e where e.workspace_id=w and e.property_id=p),'[]'::jsonb)
  );
 end if;
 if not private.aqari_manager(w) or not private.aqari_can(w,'maintenance','write') or not private.aqari_can_property(w,p,'maintenance','write') then raise insufficient_privilege using message='MAINTENANCE_SLA_MANAGER_ONLY';end if;
 perform private.aqari_require_sensitive_aal2(w);
 if p_action='prepare' then run_result:=private.aqari_run_maintenance_sla_escalations(now());return jsonb_build_object('workspace_id',w,'propertyId',p,'user_id',auth.uid(),'run',run_result);end if;
 if p_action<>'save' then raise invalid_parameter_value using message='UNKNOWN_MAINTENANCE_SLA_ACTION';end if;
 why:=btrim(coalesce(d->>'reason',''));if length(why) not between 3 and 1000 then raise invalid_parameter_value using message='MAINTENANCE_SLA_REASON_REQUIRED';end if;
 expected:=coalesce((d->>'revision')::bigint,0);
 select * into existing from private.aqari_property_maintenance_sla s where s.workspace_id=w and s.property_id=p for update;
 if found and existing.revision<>expected then raise serialization_failure using message='MAINTENANCE_SLA_REVISION_CONFLICT';end if;
 if not found and expected<>0 then raise serialization_failure using message='MAINTENANCE_SLA_REVISION_CONFLICT';end if;
 if coalesce((d->>'responseMinutes')::integer,0) not between 5 and 10080 or coalesce((d->>'resolutionMinutes')::integer,0) not between 5 and 43200 or d->>'channel' not in('push','email') then raise invalid_parameter_value using message='INVALID_MAINTENANCE_SLA';end if;
 insert into private.aqari_property_maintenance_sla(workspace_id,property_id,response_minutes,resolution_minutes,escalation_channel,is_active,revision,created_by,updated_by)
 values(w,p,(d->>'responseMinutes')::integer,(d->>'resolutionMinutes')::integer,d->>'channel',coalesce((d->>'active')::boolean,true),1,auth.uid(),auth.uid())
 on conflict(workspace_id,property_id) do update set response_minutes=excluded.response_minutes,resolution_minutes=excluded.resolution_minutes,escalation_channel=excluded.escalation_channel,is_active=excluded.is_active,revision=private.aqari_property_maintenance_sla.revision+1,updated_by=auth.uid(),updated_at=now();
 select to_jsonb(s) into after_row from private.aqari_property_maintenance_sla s where s.workspace_id=w and s.property_id=p;
 select coalesce(nullif(display_name,''),auth.uid()::text) into actor from public.aqari_profiles where user_id=auth.uid();actor:=coalesce(actor,auth.uid()::text);
 insert into private.aqari_operations_audit(workspace_id,domain,entity_id,action,actor_id,actor_name,reason,before_value,after_value)
 values(w,'maintenance',p,'sla_policy_save',auth.uid(),actor,why,case when existing.property_id is null then null else to_jsonb(existing) end,after_row);
 return jsonb_build_object('workspace_id',w,'propertyId',p,'user_id',auth.uid(),'record',after_row);
end $function$

CREATE OR REPLACE FUNCTION public.aqari_notification_dispatch_bridge(p_limit integer DEFAULT 50)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare o public.aqari_notification_outbox%rowtype;due private.aqari_rent_due_periods%rowtype;l public.aqari_leases%rowtype;u public.aqari_units%rowtype;p public.aqari_properties%rowtype;t public.aqari_tenants%rowtype;c private.aqari_integration_configs%rowtype;recipient text;variables jsonb;bridged integer:=0;cancelled integer:=0;waiting integer:=0;
begin
 if current_setting('role',true) is distinct from 'service_role' then raise insufficient_privilege using message='SERVER_ONLY';end if;if p_limit is null or p_limit<1 or p_limit>200 then raise invalid_parameter_value using message='INVALID_NOTIFICATION_BRIDGE_LIMIT';end if;
 for o in select * from public.aqari_notification_outbox q where q.kind='rent_reminder' and q.status in('awaiting_configuration','queued','failed') and q.scheduled_at<=now() order by q.scheduled_at,q.id for update skip locked limit p_limit loop
  perform private.aqari_refresh_rent_due_schedule(o.workspace_id,o.lease_id);select * into due from private.aqari_rent_due_periods d where d.workspace_id=o.workspace_id and d.lease_id=o.lease_id and d.period=o.period;
  if not found or due.balance<=0 then update public.aqari_notification_outbox set status='cancelled' where id=o.id;cancelled:=cancelled+1;continue;end if;
  select * into l from public.aqari_leases where workspace_id=o.workspace_id and id=o.lease_id;select * into u from public.aqari_units where workspace_id=l.workspace_id and id=l.unit_id;select * into p from public.aqari_properties where workspace_id=u.workspace_id and id=u.property_id;select * into t from public.aqari_tenants where workspace_id=l.workspace_id and id=l.tenant_id;
  if l.id is null or u.id is null or p.id is null or t.id is null or not private.aqari_contact_channel_allowed(t.profile,o.channel) then update public.aqari_notification_outbox set status='cancelled' where id=o.id;cancelled:=cancelled+1;continue;end if;
  recipient:=case o.channel when 'email' then nullif(btrim(t.email),'') when 'whatsapp' then nullif(btrim(t.phone),'') else null end;if recipient is null then update public.aqari_notification_outbox set status='cancelled' where id=o.id;cancelled:=cancelled+1;continue;end if;
  select * into c from private.aqari_integration_configs x where x.workspace_id=o.workspace_id and x.provider=o.channel and x.purpose in('rent_reminder','notifications','default') and x.mode in('sandbox','live') and x.endpoint_origin is not null and x.secret_reference is not null order by case x.purpose when 'rent_reminder' then 0 when 'notifications' then 1 else 2 end,x.updated_at desc,x.id limit 1;
  if not found then update public.aqari_notification_outbox set status='awaiting_configuration' where id=o.id;waiting:=waiting+1;continue;end if;
  variables:=jsonb_build_object('tenantName',t.full_name,'propertyName',p.name,'unitNo',u.unit_no,'contractNo',l.contract_no,'period',to_char(o.period,'YYYY-MM'),'dueAmount',due.due_amount,'paidAmount',due.paid_amount,'remainingBalance',due.balance,'scheduledAt',o.scheduled_at);
  insert into private.aqari_integration_outbox(id,workspace_id,event_type,aggregate_id,schema_version,payload,idempotency_key,status,attempts,available_at) values(gen_random_uuid(),o.workspace_id,'notification.rent_reminder',o.id::text,1,jsonb_build_object('notificationId',o.id,'leaseId',o.lease_id,'propertyId',p.id,'tenantId',t.id,'channel',o.channel,'recipientReference',recipient,'template','rent_reminder','variables',variables),'notification:'||o.id::text,'pending',0,greatest(o.scheduled_at,now())) on conflict(workspace_id,idempotency_key) do nothing;
  if exists(select 1 from private.aqari_integration_outbox x where x.workspace_id=o.workspace_id and x.idempotency_key='notification:'||o.id::text and x.status='sent') then update public.aqari_notification_outbox set status='sent' where id=o.id;elsif exists(select 1 from private.aqari_integration_outbox x where x.workspace_id=o.workspace_id and x.idempotency_key='notification:'||o.id::text and x.status='dead_letter') then update public.aqari_notification_outbox set status='failed' where id=o.id;else update public.aqari_notification_outbox set status='queued' where id=o.id;end if;bridged:=bridged+1;
 end loop;return jsonb_build_object('bridged',bridged,'cancelled',cancelled,'awaitingConfiguration',waiting);end $function$

CREATE OR REPLACE FUNCTION public.aqari_official_document_context(p_workspace_id uuid, p_kind text, p_entity_id uuid DEFAULT NULL::uuid, p_source_id uuid DEFAULT NULL::uuid, p_fields jsonb DEFAULT '{}'::jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare w uuid:=p_workspace_id;k text:=p_kind;t text;entities jsonb;sources jsonb:='[]';defaults jsonb:='{}';source_required boolean;
begin
 if auth.uid() is null or not private.aqari_official_document_access(w,false) then raise insufficient_privilege using message='ACCESS_DENIED';end if;
 if p_fields is null or jsonb_typeof(p_fields)<>'object' or octet_length(p_fields::text)>16000 then raise exception 'INVALID_DOCUMENT_REQUEST' using errcode='22023';end if;
 t:=case when k in ('payment_voucher','expense_approval','daily_collection') then 'property' when k='work_order' then 'work_order'
 when k in ('rent_receipt','deposit_receipt','deposit_refund','tenant_statement','debt_notice','renewal_notice','nonrenewal_notice','receipt_voucher','key_handover','damage_report','final_settlement','clearance') then 'lease' else null end;
 if t is null then raise exception 'DOCUMENT_KIND_ENTITY_MISMATCH' using errcode='22023';end if;
 source_required:=k in ('rent_receipt','receipt_voucher','deposit_receipt','deposit_refund','payment_voucher','expense_approval');
 if t='lease' then
  select coalesce(jsonb_agg(jsonb_build_object('id',x.id,'label',x.label) order by x.label),'[]') into entities from (
   select l.id,l.contract_no||' — '||q.full_name||' — '||p.name||' / '||u.unit_no label from public.aqari_leases l
   join public.aqari_tenants q on q.workspace_id=w and q.id=l.tenant_id join public.aqari_units u on u.workspace_id=w and u.id=l.unit_id
   join public.aqari_properties p on p.workspace_id=w and p.id=u.property_id
   where l.workspace_id=w and private.aqari_official_entity_scope(w,t,l.id,'read') order by l.contract_no,l.id limit 2001)x;
 elsif t='property' then
  select coalesce(jsonb_agg(jsonb_build_object('id',x.id,'label',x.name) order by x.name),'[]') into entities from
   (select id,name from public.aqari_properties where workspace_id=w and private.aqari_official_entity_scope(w,t,id,'read') order by name,id limit 2001)x;
 else
  select coalesce(jsonb_agg(jsonb_build_object('id',x.id,'label',x.order_no||' — '||x.description) order by x.order_no),'[]') into entities from
   (select id,order_no,description from private.aqari_work_orders where workspace_id=w and status in ('approved','assigned','in_progress','completed') and private.aqari_official_entity_scope(w,t,id,'read') order by order_no,id limit 2001)x;
 end if;
 if jsonb_array_length(entities)>2000 then raise exception 'DOCUMENT_OPTIONS_LIMIT' using errcode='22023';end if;
 if p_entity_id is not null then
  if not private.aqari_official_entity_scope(w,t,p_entity_id,'read') then raise insufficient_privilege using message='DOCUMENT_ENTITY_NOT_FOUND';end if;
  if source_required and not private.aqari_can(w,'collections','read') then raise insufficient_privilege using message='ACCESS_DENIED';end if;
  if k in ('rent_receipt','receipt_voucher') then
   select coalesce(jsonb_agg(jsonb_build_object('id',x.id,'label',x.paid_at::text||' — '||x.amount::text||' د.ك — '||x.reference) order by x.paid_at desc),'[]') into sources from
    (select p.id,p.paid_at,p.amount,p.reference from public.aqari_rent_payments p where p.workspace_id=w and p.lease_id=p_entity_id and p.status in ('paid','partial','مدفوع','جزئي') and p.amount>0
      and not exists(select 1 from private.aqari_receipt_cancellations c where c.workspace_id=w and c.payment_id=p.id) order by p.paid_at desc,p.id limit 2001)x;
  elsif k in ('deposit_receipt','deposit_refund') then
   select coalesce(jsonb_agg(jsonb_build_object('id',x.id,'label',x.voucher_no||' — '||x.amount::text||' د.ك') order by x.on_date desc),'[]') into sources from
    (select id,voucher_no,amount,on_date from private.aqari_deposit_entries where workspace_id=w and lease_id=p_entity_id and kind=case k when 'deposit_receipt' then 'receipt' else 'refund' end order by on_date desc,id limit 2001)x;
  elsif k in ('payment_voucher','expense_approval') then
   select coalesce(jsonb_agg(jsonb_build_object('id',x.id,'label',x.voucher_no||' — '||x.payee||' — '||x.amount::text||' د.ك') order by x.expense_date desc),'[]') into sources from
    (select id,voucher_no,payee,amount,expense_date from private.aqari_financial_expenses where workspace_id=w and property_id=p_entity_id and state='approved' order by expense_date desc,id limit 2001)x;
  end if;
  if jsonb_array_length(sources)>2000 then raise exception 'DOCUMENT_OPTIONS_LIMIT' using errcode='22023';end if;
  if not source_required or p_source_id is not null then defaults:=private.aqari_official_source(w,k,t,p_entity_id,p_source_id,p_fields);end if;
 end if;
 return jsonb_build_object('workspace_id',w,'user_id',auth.uid(),'kind',k,'entity_type',t,'entity_id',p_entity_id,'source_id',p_source_id,
  'source_required',source_required,'entities',entities,'sources',sources,'defaults',defaults);
end $function$

CREATE OR REPLACE FUNCTION public.aqari_official_document_number(p_workspace_id uuid, p_request_id uuid, p_kind text, p_entity_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare w uuid:=p_workspace_id;r private.aqari_official_number_reservations;t text;
begin
 if auth.uid() is null or not private.aqari_official_document_access(w,true) then raise insufficient_privilege using message='ACCESS_DENIED';end if;
 perform private.aqari_require_sensitive_aal2(w);
 t:=case when p_kind in ('payment_voucher','expense_approval','daily_collection') then 'property' when p_kind='work_order' then 'work_order' else 'lease' end;
 if private.aqari_official_template(p_kind) is null or not private.aqari_official_entity_scope(w,t,p_entity_id,'write') then raise insufficient_privilege using message='DOCUMENT_ENTITY_NOT_FOUND';end if;
 perform 1 from public.aqari_workspaces where id=w for update;
 select * into r from private.aqari_official_number_reservations where id=p_request_id;
 if found then
  if r.workspace_id<>w or r.actor_id<>auth.uid() or r.kind<>p_kind or r.entity_id<>p_entity_id then raise exception 'DOCUMENT_IDEMPOTENCY_CONFLICT' using errcode='23505';end if;
 else
  insert into private.aqari_official_number_reservations(id,workspace_id,document_no,kind,entity_id,actor_id)
   values(p_request_id,w,'AQ-'||to_char(now() at time zone 'Asia/Kuwait','YYYYMMDD')||'-'||lpad(nextval('private.aqari_official_document_no_seq')::text,8,'0'),p_kind,p_entity_id,auth.uid()) returning * into r;
 end if;
 return jsonb_build_object('id',r.id,'workspace_id',r.workspace_id,'document_no',r.document_no,'kind',r.kind,'entity_id',r.entity_id);
end $function$

CREATE OR REPLACE FUNCTION public.aqari_official_document_register(p_workspace_id uuid, p_action text, p_data jsonb DEFAULT '{}'::jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
 w uuid:=p_workspace_id; d jsonb:=p_data; series private.aqari_official_document_series;
 version_row private.aqari_official_document_versions; actor text; next_version integer; doc_no text;
 ident uuid; reason_text text; supplied_hash text;
begin
 if auth.uid() is null or not private.aqari_official_document_access(w,p_action<>'list' and p_action<>'get') then
  raise insufficient_privilege using message='ACCESS_DENIED';
 end if;
 if p_action not in ('list','get','issue','supersede','void') or d is null or jsonb_typeof(d)<>'object' or octet_length(d::text)>131072 then
  raise exception 'INVALID_DOCUMENT_REQUEST' using errcode='22023';
 end if;
 if p_action not in ('list','get') then perform private.aqari_require_sensitive_aal2(w); end if;
 select coalesce(nullif(display_name,''),auth.uid()::text) into actor from public.aqari_profiles where user_id=auth.uid();
 actor:=coalesce(actor,auth.uid()::text);

 if p_action='list' then
  return jsonb_build_object('items',coalesce((select jsonb_agg(jsonb_build_object(
   'id',s.id,'kind',s.kind,'document_no',s.document_no,'entity_type',s.entity_type,'entity_id',s.entity_id,
   'status',s.status,'current_version',s.current_version,'created_at',s.created_at,'void_reason',s.void_reason,
   'version',jsonb_build_object('id',v.id,'title',v.title,'content_sha256',v.content_sha256,'issued_at',v.issued_at,'issued_by_name',v.issued_by_name)
  ) order by s.created_at desc) from private.aqari_official_document_series s join private.aqari_official_document_versions v on v.workspace_id=s.workspace_id and v.series_id=s.id and v.version=s.current_version where s.workspace_id=w),'[]'::jsonb));
 end if;

 if p_action='get' then
  ident:=(d->>'id')::uuid;
  return coalesce((select jsonb_build_object('series',to_jsonb(s),'versions',coalesce(jsonb_agg(to_jsonb(v) order by v.version),'[]'::jsonb))
   from private.aqari_official_document_series s join private.aqari_official_document_versions v on v.workspace_id=s.workspace_id and v.series_id=s.id
   where s.workspace_id=w and s.id=ident group by s.id),'{}'::jsonb);
 end if;

 reason_text:=btrim(coalesce(d->>'reason',''));
 if length(reason_text)<3 then raise exception 'DOCUMENT_REASON_REQUIRED' using errcode='23514'; end if;

 if p_action='issue' then
  perform 1 from public.aqari_workspaces where id=w for update;
  ident:=(d->>'id')::uuid; doc_no:=btrim(coalesce(d->>'document_no',''));
  if doc_no='' then doc_no:='AQ-'||to_char(now() at time zone 'Asia/Kuwait','YYYYMMDD')||'-'||lpad(nextval('private.aqari_official_document_no_seq')::text,8,'0'); end if;
  supplied_hash:=lower(coalesce(d->>'content_sha256',''));
  if supplied_hash!~'^[a-f0-9]{64}$' or length(btrim(coalesce(d->>'kind','')))<2 or length(btrim(coalesce(d->>'title','')))<2 or length(btrim(coalesce(d->>'body','')))<5 then raise exception 'INVALID_DOCUMENT_SNAPSHOT' using errcode='23514'; end if;
  select * into series from private.aqari_official_document_series where workspace_id=w and id=ident;
  if found then
   select * into strict version_row from private.aqari_official_document_versions where workspace_id=w and series_id=ident and version=1;
   if series.kind=d->>'kind' and series.entity_type=d->>'entity_type' and series.entity_id=(d->>'entity_id')::uuid and version_row.content_sha256=supplied_hash
    and version_row.title is not distinct from d->>'title'
    and version_row.body is not distinct from d->>'body'
    and version_row.payload is not distinct from d->'payload'
    and version_row.template_version=coalesce((d->>'template_version')::integer,1)
    and series.document_no=coalesce(nullif(btrim(d->>'document_no'),''),series.document_no) then
    return jsonb_build_object('series',to_jsonb(series),'version',to_jsonb(version_row),'replayed',true);
   end if;
   raise exception 'DOCUMENT_IDEMPOTENCY_CONFLICT' using errcode='23505';
  end if;
  insert into private.aqari_official_document_series(id,workspace_id,kind,document_no,entity_type,entity_id,created_by)
  values(ident,w,d->>'kind',doc_no,d->>'entity_type',(d->>'entity_id')::uuid,auth.uid()) returning * into series;
  insert into private.aqari_official_document_versions(id,workspace_id,series_id,version,template_version,title,body,payload,content_sha256,issued_by,issued_by_name)
  values((d->>'version_id')::uuid,w,ident,1,coalesce((d->>'template_version')::integer,1),d->>'title',d->>'body',d->'payload',supplied_hash,auth.uid(),actor) returning * into version_row;
  insert into private.aqari_official_document_events(id,workspace_id,series_id,action,reason,actor_id,details)
  values((d->>'event_id')::uuid,w,ident,'issue',reason_text,auth.uid(),jsonb_build_object('version',1,'hash',supplied_hash));
  return jsonb_build_object('series',to_jsonb(series),'version',to_jsonb(version_row));
 end if;

 ident:=(d->>'id')::uuid;
 select * into series from private.aqari_official_document_series where workspace_id=w and id=ident for update;
 if not found then raise exception 'DOCUMENT_NOT_FOUND' using errcode='P0002'; end if;
 if series.status<>'issued' then raise exception 'DOCUMENT_ALREADY_VOID' using errcode='23514'; end if;

 if p_action='supersede' then
  if (d->>'expected_version')::integer is distinct from series.current_version then raise exception 'STALE_DOCUMENT_VERSION' using errcode='40001'; end if;
  next_version:=series.current_version+1; supplied_hash:=lower(coalesce(d->>'content_sha256',''));
  if supplied_hash!~'^[a-f0-9]{64}$' or length(btrim(coalesce(d->>'title','')))<2 or length(btrim(coalesce(d->>'body','')))<5 then raise exception 'INVALID_DOCUMENT_SNAPSHOT' using errcode='23514'; end if;
  insert into private.aqari_official_document_versions(id,workspace_id,series_id,version,template_version,title,body,payload,content_sha256,supersedes_version,issued_by,issued_by_name)
  values((d->>'version_id')::uuid,w,ident,next_version,coalesce((d->>'template_version')::integer,1),d->>'title',d->>'body',d->'payload',supplied_hash,series.current_version,auth.uid(),actor) returning * into version_row;
  update private.aqari_official_document_series set current_version=next_version where workspace_id=w and id=ident returning * into series;
  insert into private.aqari_official_document_events(id,workspace_id,series_id,action,reason,actor_id,details)
  values((d->>'event_id')::uuid,w,ident,'supersede',reason_text,auth.uid(),jsonb_build_object('version',next_version,'hash',supplied_hash));
  return jsonb_build_object('series',to_jsonb(series),'version',to_jsonb(version_row));
 end if;

 update private.aqari_official_document_series set status='void',voided_by=auth.uid(),voided_at=now(),void_reason=reason_text where workspace_id=w and id=ident returning * into series;
 insert into private.aqari_official_document_events(id,workspace_id,series_id,action,reason,actor_id,details)
 values((d->>'event_id')::uuid,w,ident,'void',reason_text,auth.uid(),jsonb_build_object('version',series.current_version));
 return jsonb_build_object('series',to_jsonb(series));
end $function$

CREATE OR REPLACE FUNCTION public.aqari_operations_register(p_workspace_id uuid, p_domain text, p_action text, p_data jsonb DEFAULT '{}'::jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  invoice_ref text;
begin
  if auth.uid() is null or not private.aqari_manager(p_workspace_id) then
    raise insufficient_privilege using message='ACCESS_DENIED';
  end if;

  if p_domain='petty_cash'
     and p_action='entry'
     and coalesce(p_data->>'kind','')='spend' then
    invoice_ref:=btrim(coalesce(p_data->>'invoice_id',''));
    if length(invoice_ref) not between 2 and 160
       or invoice_ref ~ '[[:cntrl:]]' then
      raise invalid_parameter_value using message='PETTY_CASH_INVOICE_REQUIRED';
    end if;
  end if;

  return private.aqari_operations_register_core(
    p_workspace_id,p_domain,p_action,p_data
  );
end $function$

CREATE OR REPLACE FUNCTION public.aqari_owner_experience_settings(p_workspace_id uuid, p_action text, p_data jsonb DEFAULT '{}'::jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  r text; current_row private.aqari_owner_experience_settings%rowtype;
  expected bigint; next_recipient text; next_channel text; next_schedule text; next_hour integer;
begin
  select role::text into r from public.aqari_memberships
   where workspace_id=p_workspace_id and user_id=auth.uid() and is_active;
  if r is distinct from 'general_manager' then raise insufficient_privilege using message='ACCESS_DENIED';end if;
  if p_action='read' then
    select * into current_row from private.aqari_owner_experience_settings where workspace_id=p_workspace_id;
    return jsonb_build_object(
      'workspace_id',p_workspace_id,'guest_enabled',coalesce(current_row.guest_enabled,false),
      'assistant_enabled',coalesce(current_row.assistant_enabled,true),'report_enabled',coalesce(current_row.report_enabled,false),
      'report_channel',coalesce(current_row.report_channel,'email'),'report_schedule',coalesce(current_row.report_schedule,'weekly'),
      'report_hour',coalesce(current_row.report_hour,8),'report_recipient',coalesce(current_row.report_recipient,''),
      'revision',coalesce(current_row.revision,0),'updated_at',current_row.updated_at
    );
  elsif p_action='save' then
    perform private.aqari_require_sensitive_aal2(p_workspace_id);
    if jsonb_typeof(coalesce(p_data,'{}'::jsonb))<>'object' or exists(
      select 1 from jsonb_object_keys(coalesce(p_data,'{}'::jsonb)) k
      where k not in ('guest_enabled','assistant_enabled','report_enabled','report_channel','report_schedule','report_hour','report_recipient','expected_revision')
    ) then raise exception 'INVALID_OWNER_EXPERIENCE_SETTINGS';end if;
    if jsonb_typeof(p_data->'guest_enabled')<>'boolean' or jsonb_typeof(p_data->'assistant_enabled')<>'boolean' or jsonb_typeof(p_data->'report_enabled')<>'boolean' then raise exception 'INVALID_OWNER_EXPERIENCE_SETTINGS';end if;
    if coalesce(p_data->>'expected_revision','')!~'^\d+$' then raise exception 'INVALID_OWNER_EXPERIENCE_SETTINGS';end if;
    expected=(p_data->>'expected_revision')::bigint;
    next_channel=coalesce(nullif(p_data->>'report_channel',''),'email');
    next_schedule=coalesce(nullif(p_data->>'report_schedule',''),'weekly');
    next_hour=coalesce((p_data->>'report_hour')::integer,8);
    next_recipient=trim(coalesce(p_data->>'report_recipient',''));
    if next_channel not in ('email','whatsapp') or next_schedule not in ('daily','weekly','monthly') or next_hour not between 0 and 23 or length(next_recipient)>254 or next_recipient~'[\x00-\x1f\x7f]' then raise exception 'INVALID_OWNER_EXPERIENCE_SETTINGS';end if;
    if (p_data->>'report_enabled')::boolean and length(next_recipient)<3 then raise exception 'OWNER_REPORT_RECIPIENT_REQUIRED';end if;
    select * into current_row from private.aqari_owner_experience_settings where workspace_id=p_workspace_id for update;
    if current_row.workspace_id is null then
      if expected<>0 then raise exception 'OWNER_EXPERIENCE_REVISION_CONFLICT';end if;
      insert into private.aqari_owner_experience_settings(workspace_id,guest_enabled,assistant_enabled,report_enabled,report_channel,report_schedule,report_hour,report_recipient,revision,updated_by)
      values(p_workspace_id,(p_data->>'guest_enabled')::boolean,(p_data->>'assistant_enabled')::boolean,(p_data->>'report_enabled')::boolean,next_channel,next_schedule,next_hour,nullif(next_recipient,''),1,auth.uid())
      returning * into current_row;
    else
      if current_row.revision<>expected then raise exception 'OWNER_EXPERIENCE_REVISION_CONFLICT';end if;
      update private.aqari_owner_experience_settings set
        guest_enabled=(p_data->>'guest_enabled')::boolean,
        assistant_enabled=(p_data->>'assistant_enabled')::boolean,
        report_enabled=(p_data->>'report_enabled')::boolean,
        report_channel=next_channel,report_schedule=next_schedule,report_hour=next_hour,
        report_recipient=nullif(next_recipient,''),revision=revision+1,updated_by=auth.uid(),updated_at=now()
      where workspace_id=p_workspace_id returning * into current_row;
    end if;
    return jsonb_build_object('workspace_id',current_row.workspace_id,'guest_enabled',current_row.guest_enabled,'assistant_enabled',current_row.assistant_enabled,'report_enabled',current_row.report_enabled,'report_channel',current_row.report_channel,'report_schedule',current_row.report_schedule,'report_hour',current_row.report_hour,'report_recipient',coalesce(current_row.report_recipient,''),'revision',current_row.revision,'updated_at',current_row.updated_at);
  else
    raise exception 'INVALID_OWNER_EXPERIENCE_ACTION';
  end if;
end $function$

CREATE OR REPLACE FUNCTION public.aqari_owner_experience_status(p_workspace_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare r text;s private.aqari_owner_experience_settings%rowtype;
begin
 select role::text into r from public.aqari_memberships where workspace_id=p_workspace_id and user_id=auth.uid() and is_active;
 if r is null then raise insufficient_privilege using message='ACCESS_DENIED';end if;
 select * into s from private.aqari_owner_experience_settings where workspace_id=p_workspace_id;
 return jsonb_build_object('workspace_id',p_workspace_id,'assistant_enabled',coalesce(s.assistant_enabled,true),'report_enabled',coalesce(s.report_enabled,false));
end $function$

CREATE OR REPLACE FUNCTION public.aqari_owner_report_delivery_claim(p_target_id uuid, p_channel text, p_dispatch_key text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare row_status text;
begin
 if auth.role() is distinct from 'service_role' then raise insufficient_privilege using message='ACCESS_DENIED';end if;
 if p_target_id is null or p_channel not in('whatsapp','email') or p_dispatch_key is null or length(p_dispatch_key)>80 then raise exception 'INVALID_DELIVERY_CLAIM';end if;
 insert into private.aqari_owner_report_delivery_log(target_id,channel,dispatch_key,status) values(p_target_id,p_channel,p_dispatch_key,'pending')
 on conflict(target_id,channel,dispatch_key) do update set status='pending',attempts=private.aqari_owner_report_delivery_log.attempts+1,provider_id=null,error_code=null,updated_at=now()
 where (private.aqari_owner_report_delivery_log.status='failed' or (private.aqari_owner_report_delivery_log.status='pending' and private.aqari_owner_report_delivery_log.updated_at < now()-interval '30 minutes')) and private.aqari_owner_report_delivery_log.attempts<50
 returning status into row_status;
 if row_status is null then return jsonb_build_object('send',false);end if;
 return jsonb_build_object('send',true);
end $function$

CREATE OR REPLACE FUNCTION public.aqari_owner_report_delivery_complete(p_target_id uuid, p_channel text, p_dispatch_key text, p_success boolean, p_provider_id text, p_error_code text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare n integer;
begin
 if auth.role() is distinct from 'service_role' then raise insufficient_privilege using message='ACCESS_DENIED';end if;
 update private.aqari_owner_report_delivery_log set status=case when p_success then 'sent' else 'failed' end,provider_id=case when p_success then left(coalesce(p_provider_id,''),300) else null end,error_code=case when p_success then null else left(coalesce(p_error_code,'DELIVERY_FAILED'),160) end,updated_at=now()
 where target_id=p_target_id and channel=p_channel and dispatch_key=p_dispatch_key and status='pending';
 get diagnostics n=row_count;if n<>1 then raise exception 'DELIVERY_CLAIM_NOT_FOUND';end if;
 return jsonb_build_object('ok',true,'status',case when p_success then 'sent' else 'failed' end);
end $function$

CREATE OR REPLACE FUNCTION public.aqari_owner_report_service_v3(p_workspace_id uuid, p_property_ids uuid[], p_from date, p_to date)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare month_start date:=date_trunc('month',p_to)::date;properties_json jsonb;tenants_json jsonb;arrears_json jsonb;collection_json jsonb;alerts_json jsonb;period_collections numeric:=0;period_expenses numeric:=0;
begin
 if auth.role() is distinct from 'service_role' then raise insufficient_privilege using message='ACCESS_DENIED';end if;
 if p_from is null or p_to is null or p_from>p_to or p_to-p_from>366 or coalesce(cardinality(p_property_ids),0)<1 or cardinality(p_property_ids)>50 then raise exception 'INVALID_REPORT_PERIOD_OR_SCOPE';end if;
 if exists(select 1 from unnest(p_property_ids) id where not exists(select 1 from public.aqari_properties p where p.workspace_id=p_workspace_id and p.id=id)) then raise exception 'OWNER_REPORT_PROPERTY_NOT_FOUND';end if;
 select jsonb_agg(jsonb_build_object('id',p.id,'name',p.name) order by p.name,p.id) into properties_json from public.aqari_properties p where p.workspace_id=p_workspace_id and p.id=any(p_property_ids);
 with lines as (
  select p.id property_id,p.name property_name,l.id lease_id,l.contract_no,u.unit_no,t.full_name tenant_name,d.due_amount::numeric(15,3) due,d.paid_amount::numeric(15,3) paid,greatest(d.due_amount-d.paid_amount,0)::numeric(15,3) remaining,
   case when d.due_amount=0 then 'waived' when d.paid_amount>=d.due_amount then 'paid' when d.paid_amount>0 then 'partial' else 'unpaid' end state
  from private.aqari_rent_due_periods d
  join public.aqari_leases l on l.workspace_id=d.workspace_id and l.id=d.lease_id
  join public.aqari_units u on u.workspace_id=l.workspace_id and u.id=l.unit_id
  join public.aqari_properties p on p.workspace_id=u.workspace_id and p.id=u.property_id
  left join public.aqari_tenants t on t.workspace_id=l.workspace_id and t.id=l.tenant_id
  where d.workspace_id=p_workspace_id and d.period=month_start and p.id=any(p_property_ids)
 )
 select coalesce(jsonb_build_object('period',month_start,'due',sum(due),'collected',sum(least(paid,due)),'paid_total',sum(paid),'remaining',sum(remaining),'collection_rate_pct',case when sum(due)>0 then round(sum(least(paid,due))/sum(due)*100,2) else null end,'paid_count',count(*) filter(where state='paid'),'partial_count',count(*) filter(where state='partial'),'unpaid_count',count(*) filter(where state='unpaid'),'waived_count',count(*) filter(where state='waived')),jsonb_build_object('period',month_start,'due',0,'collected',0,'paid_total',0,'remaining',0,'paid_count',0,'partial_count',0,'unpaid_count',0,'waived_count',0)),
        coalesce(jsonb_agg(jsonb_build_object('property_id',property_id,'property_name',property_name,'lease_id',lease_id,'contract_no',contract_no,'unit_no',unit_no,'tenant_name',coalesce(tenant_name,'غير محدد'),'due',due,'paid',paid,'remaining',remaining,'state',state) order by property_name,unit_no,contract_no),'[]'::jsonb)
 into collection_json,tenants_json from lines;
 with old_due as (
  select p.id property_id,p.name property_name,u.unit_no,t.full_name tenant_name,d.period,greatest(d.due_amount-d.paid_amount,0)::numeric(15,3) remaining
  from private.aqari_rent_due_periods d
  join public.aqari_leases l on l.workspace_id=d.workspace_id and l.id=d.lease_id
  join public.aqari_units u on u.workspace_id=l.workspace_id and u.id=l.unit_id
  join public.aqari_properties p on p.workspace_id=u.workspace_id and p.id=u.property_id
  left join public.aqari_tenants t on t.workspace_id=l.workspace_id and t.id=l.tenant_id
  where d.workspace_id=p_workspace_id and d.period<month_start and p.id=any(p_property_ids) and d.due_amount>d.paid_amount
 )
 select jsonb_build_object('count',count(*),'remaining',coalesce(sum(remaining),0),'lines',coalesce(jsonb_agg(jsonb_build_object('property_id',property_id,'property_name',property_name,'unit_no',unit_no,'tenant_name',coalesce(tenant_name,'غير محدد'),'period',period,'remaining',remaining) order by period,property_name,unit_no) filter(where remaining>0),'[]'::jsonb)) into arrears_json from old_due;
 select coalesce(sum(pay.amount),0) into period_collections from public.aqari_rent_payments pay join public.aqari_leases l on l.workspace_id=pay.workspace_id and l.id=pay.lease_id join public.aqari_units u on u.workspace_id=l.workspace_id and u.id=l.unit_id where pay.workspace_id=p_workspace_id and u.property_id=any(p_property_ids) and pay.paid_at between p_from and p_to and coalesce(pay.status,'') not in('cancelled','void');
 select coalesce(sum(e.amount),0) into period_expenses from private.aqari_financial_expenses e where e.workspace_id=p_workspace_id and e.property_id=any(p_property_ids) and e.expense_date between p_from and p_to and e.state='approved';
 select jsonb_build_object(
  'leases_expiring_30',(select count(*) from public.aqari_leases l join public.aqari_units u on u.workspace_id=l.workspace_id and u.id=l.unit_id where l.workspace_id=p_workspace_id and u.property_id=any(p_property_ids) and l.status in('signed','active') and l.end_date between p_to and p_to+30),
  'maintenance_open',(select count(*) from public.aqari_maintenance_requests m join public.aqari_leases l on l.workspace_id=m.workspace_id and l.id=m.lease_id join public.aqari_units u on u.workspace_id=l.workspace_id and u.id=l.unit_id where m.workspace_id=p_workspace_id and u.property_id=any(p_property_ids) and lower(coalesce(m.status,'')) not in('completed','closed','cancelled','canceled','done')),
  'unpaid_current',coalesce((collection_json->>'unpaid_count')::integer,0)+coalesce((collection_json->>'partial_count')::integer,0),
  'arrears_count',coalesce((arrears_json->>'count')::integer,0)
 ) into alerts_json;
 return jsonb_build_object('workspace_id',p_workspace_id,'from',p_from,'to',p_to,'currency','KWD','properties',coalesce(properties_json,'[]'::jsonb),'collection',collection_json,'tenants',tenants_json,'arrears',arrears_json,'alerts',alerts_json,'period_activity',jsonb_build_object('collections',period_collections,'approved_expenses',period_expenses,'net',period_collections-period_expenses),'generated_at',now());
end $function$

CREATE OR REPLACE FUNCTION public.aqari_owner_report_targets(p_workspace_id uuid, p_action text, p_data jsonb DEFAULT '{}'::jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
 role_name text; settings private.aqari_owner_experience_settings%rowtype; expected bigint;
 targets jsonb:=coalesce(p_data->'targets','[]'::jsonb); item jsonb; canonical jsonb:='[]'::jsonb;
 target_id text; owner_name text; owner_user_text text; owner_user uuid; property_ids jsonb; channels jsonb;
 email text; whatsapp text; schedule text; report_hour integer; enabled boolean;
begin
 select role::text into role_name from public.aqari_memberships
  where workspace_id=p_workspace_id and user_id=auth.uid() and is_active;
 if role_name is distinct from 'general_manager' then raise insufficient_privilege using message='ACCESS_DENIED';end if;
 insert into private.aqari_owner_experience_settings(workspace_id) values(p_workspace_id) on conflict(workspace_id) do nothing;

 if p_action='read' then
  select * into settings from private.aqari_owner_experience_settings where workspace_id=p_workspace_id;
  return jsonb_build_object(
   'workspace_id',p_workspace_id,
   'targets',coalesce((
     select jsonb_agg((x - 'property_id') || jsonb_build_object('property_ids',case when jsonb_typeof(x->'property_ids')='array' then x->'property_ids' when nullif(x->>'property_id','') is not null then jsonb_build_array(x->>'property_id') else '[]'::jsonb end) order by x->>'owner_name',x->>'id')
     from jsonb_array_elements(coalesce(settings.report_targets,'[]'::jsonb)) x
   ),'[]'::jsonb),
   'revision',coalesce(settings.report_targets_revision,0),
   'properties',coalesce((select jsonb_agg(jsonb_build_object('id',p.id,'name',p.name) order by p.name,p.id) from public.aqari_properties p where p.workspace_id=p_workspace_id),'[]'::jsonb),
   'owners',coalesce((select jsonb_agg(jsonb_build_object('user_id',q.user_id,'display_name',q.display_name,'email',q.email,'property_ids',q.property_ids) order by q.display_name,q.user_id) from (select a.user_id,max(a.display_name) display_name,max(a.email) email,jsonb_agg(distinct a.property_id order by a.property_id) property_ids from private.aqari_partner_access a where a.workspace_id=p_workspace_id and a.is_active and a.user_id is not null group by a.user_id) q),'[]'::jsonb)
  );
 elsif p_action<>'save' then raise exception 'INVALID_OWNER_REPORT_TARGET_ACTION';end if;

 perform private.aqari_require_sensitive_aal2(p_workspace_id);
 if jsonb_typeof(coalesce(p_data,'{}'::jsonb))<>'object' or exists(select 1 from jsonb_object_keys(p_data) k where k not in('targets','expected_revision')) or jsonb_typeof(targets)<>'array' or jsonb_array_length(targets)>40 or coalesce(p_data->>'expected_revision','')!~'^\d+$' then raise exception 'INVALID_OWNER_REPORT_TARGETS';end if;
 expected=(p_data->>'expected_revision')::bigint;

 for item in select value from jsonb_array_elements(targets) loop
  if jsonb_typeof(item)<>'object' or exists(select 1 from jsonb_object_keys(item) k where k not in('id','owner_name','owner_user_id','property_ids','channels','email','whatsapp','schedule','hour','enabled')) then raise exception 'INVALID_OWNER_REPORT_TARGET';end if;
  target_id=trim(coalesce(item->>'id',''));owner_name=trim(coalesce(item->>'owner_name',''));owner_user_text=nullif(trim(coalesce(item->>'owner_user_id','')),'');owner_user=null;
  if owner_user_text is not null then
   if owner_user_text!~*'^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' then raise exception 'INVALID_OWNER_REPORT_OWNER';end if;
   owner_user=owner_user_text::uuid;
   if not exists(select 1 from private.aqari_partner_access a where a.workspace_id=p_workspace_id and a.user_id=owner_user and a.is_active) then raise exception 'OWNER_REPORT_OWNER_ACCESS_REQUIRED';end if;
   if length(owner_name)<2 then select max(a.display_name) into owner_name from private.aqari_partner_access a where a.workspace_id=p_workspace_id and a.user_id=owner_user and a.is_active;end if;
  end if;
  property_ids=coalesce(item->'property_ids','[]'::jsonb);channels=coalesce(item->'channels','[]'::jsonb);email=lower(trim(coalesce(item->>'email','')));whatsapp=regexp_replace(trim(coalesce(item->>'whatsapp','')),'[\s()\-]','','g');schedule=coalesce(nullif(item->>'schedule',''),'monthly');report_hour=coalesce((item->>'hour')::integer,8);enabled=coalesce((item->>'enabled')::boolean,false);
  if target_id!~*'^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' or length(owner_name)<2 or length(owner_name)>120 then raise exception 'INVALID_OWNER_REPORT_TARGET';end if;
  if jsonb_typeof(property_ids)<>'array' or jsonb_array_length(property_ids)>50 or exists(select 1 from jsonb_array_elements_text(property_ids) x where x!~*'^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$') or (select count(distinct value) from jsonb_array_elements_text(property_ids))<>jsonb_array_length(property_ids) then raise exception 'INVALID_OWNER_REPORT_PROPERTIES';end if;
  if exists(select 1 from jsonb_array_elements_text(property_ids) x where not exists(select 1 from public.aqari_properties p where p.workspace_id=p_workspace_id and p.id=x::uuid)) then raise exception 'INVALID_OWNER_REPORT_PROPERTY';end if;
  if owner_user is null and jsonb_array_length(property_ids)=0 then raise exception 'OWNER_REPORT_PROPERTIES_REQUIRED';end if;
  if owner_user is not null and exists(select 1 from jsonb_array_elements_text(property_ids) x where not exists(select 1 from private.aqari_partner_access a where a.workspace_id=p_workspace_id and a.user_id=owner_user and a.property_id=x::uuid and a.is_active)) then raise exception 'OWNER_REPORT_OWNER_SCOPE_MISMATCH';end if;
  if jsonb_typeof(channels)<>'array' or jsonb_array_length(channels)<1 or jsonb_array_length(channels)>2 or exists(select 1 from jsonb_array_elements_text(channels) c where c not in('whatsapp','email')) or (select count(distinct value) from jsonb_array_elements_text(channels))<>jsonb_array_length(channels) then raise exception 'INVALID_OWNER_REPORT_CHANNELS';end if;
  if schedule not in('daily','weekly','monthly') or report_hour not between 0 and 23 then raise exception 'INVALID_OWNER_REPORT_SCHEDULE';end if;
  if channels ? 'email' and email='' and owner_user is not null then select lower(max(a.email)) into email from private.aqari_partner_access a where a.workspace_id=p_workspace_id and a.user_id=owner_user and a.is_active;end if;
  if channels ? 'email' and (length(email)>254 or email!~*'^[A-Z0-9._%+\-]+@[A-Z0-9.\-]+\.[A-Z]{2,}$') then raise exception 'INVALID_OWNER_REPORT_EMAIL';end if;
  if channels ? 'whatsapp' and (length(whatsapp)<8 or length(whatsapp)>20 or whatsapp!~'^\+?[0-9]+$') then raise exception 'INVALID_OWNER_REPORT_WHATSAPP';end if;
  canonical=canonical||jsonb_build_array(jsonb_build_object('id',target_id,'owner_name',owner_name,'owner_user_id',owner_user_text,'property_ids',property_ids,'channels',channels,'email',email,'whatsapp',whatsapp,'schedule',schedule,'hour',report_hour,'enabled',enabled));
 end loop;
 if (select count(*) from jsonb_array_elements(canonical))<>(select count(distinct value->>'id') from jsonb_array_elements(canonical)) then raise exception 'DUPLICATE_OWNER_REPORT_TARGET';end if;
 select * into settings from private.aqari_owner_experience_settings where workspace_id=p_workspace_id for update;
 if settings.report_targets_revision<>expected then raise exception 'OWNER_REPORT_TARGET_REVISION_CONFLICT';end if;
 update private.aqari_owner_experience_settings set report_targets=canonical,report_targets_revision=report_targets_revision+1,updated_by=auth.uid(),updated_at=now() where workspace_id=p_workspace_id returning * into settings;
 return public.aqari_owner_report_targets(p_workspace_id,'read','{}'::jsonb);
end $function$

CREATE OR REPLACE FUNCTION public.aqari_petty_cash_close(p_workspace_id uuid, p_fund_id uuid, p_revision integer, p_reason text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
 f private.aqari_petty_cash_funds;
 before_row jsonb;
 after_row jsonb;
 actor text;
 why text:=btrim(coalesce(p_reason,''));
begin
 if auth.uid() is null or not private.aqari_manager(p_workspace_id) then
  raise insufficient_privilege using message='ACCESS_DENIED';
 end if;
 if not private.aqari_can(p_workspace_id,'finance','write') then
  raise insufficient_privilege using message='ACCESS_DENIED';
 end if;
 perform private.aqari_require_sensitive_aal2(p_workspace_id);
 if p_fund_id is null or p_revision is null or p_revision<1 then
  raise exception 'INVALID_PETTY_CASH_CLOSE' using errcode='22023';
 end if;
 if length(why)<3 then
  raise exception 'PETTY_CASH_CLOSE_REASON_REQUIRED' using errcode='22023';
 end if;
 select * into f from private.aqari_petty_cash_funds x where x.workspace_id=p_workspace_id and x.id=p_fund_id for update;
 if not found then raise insufficient_privilege using message='ACCESS_DENIED'; end if;
 if f.revision is distinct from p_revision then raise serialization_failure using message='REVISION_CONFLICT'; end if;
 if f.status='closed' then raise exception 'PETTY_CASH_ALREADY_CLOSED' using errcode='23514'; end if;
 if f.status<>'open' then raise exception 'PETTY_CASH_FUND_NOT_OPEN' using errcode='23514'; end if;
 if f.balance<>0 then raise exception 'PETTY_CASH_BALANCE_NOT_ZERO' using errcode='23514'; end if;
 before_row:=to_jsonb(f);
 update private.aqari_petty_cash_funds x set status='closed',revision=x.revision+1 where x.workspace_id=p_workspace_id and x.id=p_fund_id returning * into f;
 after_row:=to_jsonb(f);
 select coalesce(nullif(display_name,''),auth.uid()::text) into actor from public.aqari_profiles where user_id=auth.uid();
 actor:=coalesce(actor,auth.uid()::text);
 insert into private.aqari_operations_audit(workspace_id,domain,entity_id,action,actor_id,actor_name,reason,before_value,after_value)
 values(p_workspace_id,'petty_cash',p_fund_id,'close',auth.uid(),actor,why,before_row,after_row);
 return after_row;
end $function$

CREATE OR REPLACE FUNCTION public.aqari_process_knet_webhook(p_receipt_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
#variable_conflict use_variable
declare wr private.aqari_webhook_receipts%rowtype;i private.aqari_knet_payment_intents%rowtype;l public.aqari_leases%rowtype;u public.aqari_units%rowtype;p public.aqari_properties%rowtype;t public.aqari_tenants%rowtype;due private.aqari_rent_due_periods%rowtype;payload jsonb;provider_ref text;account_ref text;status_value text;event_value text;currency_value text;amount_value numeric;occurred timestamptz;paid_day date;serial jsonb;receipt_value text;contract_sequence integer;payment_value uuid;method_value text:='KNET';status_label text;period_text text;row_value jsonb;ledger jsonb;receipt_json jsonb;contract_value jsonb;breakdown jsonb;balance_after numeric;channel text;existing public.aqari_rent_payments%rowtype;
begin
 if current_setting('role',true) is distinct from 'service_role' then raise insufficient_privilege using message='SERVER_ONLY';end if;select * into wr from private.aqari_webhook_receipts x where x.id=p_receipt_id for update;if not found or wr.provider<>'knet' then raise no_data_found using message='KNET_WEBHOOK_NOT_FOUND';end if;
 payload:=wr.normalized_payload;provider_ref=btrim(coalesce(payload->>'payment_reference',''));account_ref=btrim(coalesce(payload->>'account_reference',''));status_value=lower(btrim(coalesce(payload->>'provider_status','')));event_value=lower(btrim(coalesce(wr.event_type,'')));currency_value=upper(btrim(coalesce(payload->>'currency','')));
 if event_value<>'payment.succeeded' or status_value<>'succeeded' or provider_ref='' or account_ref='' or currency_value<>'KWD' or coalesce(payload->>'amount','')!~'^[0-9]{1,14}(\.[0-9]{1,3})?$' then insert into private.aqari_webhook_processing_events(workspace_id,webhook_receipt_id,provider,outcome,entity_type,reason) values(wr.workspace_id,wr.id,'knet','rejected','knet_payment_intent','KNET_WEBHOOK_CANONICAL_FIELDS_INVALID');return jsonb_build_object('processed',false,'reason','KNET_WEBHOOK_CANONICAL_FIELDS_INVALID');end if;
 amount_value:=(payload->>'amount')::numeric;begin occurred:=(payload->>'occurred_at')::timestamptz;exception when others then occurred:=null;end;if amount_value<=0 or amount_value<>round(amount_value,3) or occurred is null or occurred>now()+interval '5 minutes' then insert into private.aqari_webhook_processing_events(workspace_id,webhook_receipt_id,provider,outcome,entity_type,reason) values(wr.workspace_id,wr.id,'knet','rejected','knet_payment_intent','KNET_WEBHOOK_VALUE_INVALID');return jsonb_build_object('processed',false,'reason','KNET_WEBHOOK_VALUE_INVALID');end if;
 select * into i from private.aqari_knet_payment_intents x where x.workspace_id=wr.workspace_id and x.idempotency_key=account_ref for update;if not found then insert into private.aqari_webhook_processing_events(workspace_id,webhook_receipt_id,provider,outcome,entity_type,reason) values(wr.workspace_id,wr.id,'knet','rejected','knet_payment_intent','KNET_INTENT_NOT_FOUND');return jsonb_build_object('processed',false,'reason','KNET_INTENT_NOT_FOUND');end if;
 if i.status='paid' then if i.provider_reference=provider_ref and i.amount=amount_value and i.currency=currency_value and i.payment_id is not null then insert into private.aqari_webhook_processing_events(workspace_id,webhook_receipt_id,provider,outcome,entity_type,entity_id,reason) values(wr.workspace_id,wr.id,'knet','replayed','knet_payment_intent',i.id::text,'KNET_PAYMENT_ALREADY_POSTED');insert into private.aqari_knet_payment_events(workspace_id,intent_id,action,actor_kind,reason,details) values(i.workspace_id,i.id,'webhook_replay','system','إعادة Webhook لنفس دفعة KNET',jsonb_build_object('providerReference',provider_ref));return private.aqari_knet_intent_snapshot(i)||jsonb_build_object('processed',true,'replayed',true);end if;raise unique_violation using message='KNET_PAID_INTENT_CONFLICT';end if;
 if i.status<>'link_ready' or i.expires_at<occurred or i.provider_reference is distinct from provider_ref or i.amount<>amount_value or i.currency<>currency_value then insert into private.aqari_webhook_processing_events(workspace_id,webhook_receipt_id,provider,outcome,entity_type,entity_id,reason) values(wr.workspace_id,wr.id,'knet','rejected','knet_payment_intent',i.id::text,'KNET_INTENT_WEBHOOK_MISMATCH');return jsonb_build_object('processed',false,'reason','KNET_INTENT_WEBHOOK_MISMATCH');end if;
 select * into l from public.aqari_leases x where x.workspace_id=i.workspace_id and x.id=i.lease_id and x.status='signed' for update;if not found then raise check_violation using message='SIGNED_LEASE_REQUIRED';end if;select * into u from public.aqari_units x where x.workspace_id=l.workspace_id and x.id=l.unit_id;select * into p from public.aqari_properties x where x.workspace_id=u.workspace_id and x.id=u.property_id;select * into t from public.aqari_tenants x where x.workspace_id=l.workspace_id and x.id=l.tenant_id;if u.id is null or p.id is null or t.id is null then raise check_violation using message='KNET_PAYMENT_SCOPE_MISSING';end if;
 perform private.aqari_refresh_rent_due_schedule(i.workspace_id,i.lease_id);select * into due from private.aqari_rent_due_periods x where x.workspace_id=i.workspace_id and x.lease_id=i.lease_id and x.period=i.period;if not found or due.balance<i.amount then raise check_violation using message='KNET_BALANCE_CHANGED_BEFORE_SETTLEMENT';end if;
 paid_day:=(occurred at time zone 'Asia/Kuwait')::date;period_text:=to_char(i.period,'YYYY-MM');status_label:=case when due.balance=i.amount then 'مدفوع' else 'جزئي' end;serial:=private.aqari_system_rent_receipt_serial(i.workspace_id,l.external_ref,i.id,extract(year from paid_day)::integer);receipt_value:=serial->>'receipt_no';contract_sequence:=(serial->>'contract_sequence')::integer;payment_value:=md5(i.workspace_id::text||':knet-payment:'||i.id::text)::uuid;contract_value:=l.snapshot||jsonb_build_object('id',l.external_ref,'contract_no',l.contract_no,'status','signed','tenant',t.full_name,'property',p.name,'unit',u.unit_no,'start_date',l.start_date,'end_date',l.end_date);
 row_value:=jsonb_build_array(receipt_value,t.full_name,i.amount,status_label,p.name,paid_day,u.unit_no,'دفع إلكتروني KNET مؤكد عبر Webhook',period_text,method_value);ledger:=jsonb_build_object('id','rent-'||receipt_value,'receiptNo',receipt_value,'property',p.name,'unit',u.unit_no,'tenant',t.full_name,'contractId',l.external_ref,'contractNo',l.contract_no,'contractReceiptSequence',contract_sequence,'period',period_text,'due',due.due_amount,'paid',i.amount,'balance',due.balance-i.amount,'paidAt',paid_day,'method',method_value,'transactionNo',provider_ref,'knetTransactionNo',provider_ref,'accountant','النظام / KNET','status',status_label,'note','دفع إلكتروني KNET مؤكد','source','knet-webhook','knetIntentId',i.id);breakdown:=case when jsonb_typeof(contract_value->'rentEntitlement')='object' then private.aqari_rent_period_breakdown(contract_value,period_text) else null end;receipt_json:=jsonb_strip_nulls(jsonb_build_object('id',receipt_value,'contractReceiptSequence',contract_sequence,'template','rent-voucher-v267-1','record',row_value,'contract',contract_value,'tenantId',t.id,'tenantNameEn',coalesce(t.profile->>'nameEn',''),'brand',jsonb_build_object('ar',p.name,'en','AQARI PROPERTY','website','myaqari.com'),'detailsVersion',2,'accountant','النظام / KNET','transactionNo',provider_ref,'rentPeriodBreakdown',breakdown));
 select * into existing from public.aqari_rent_payments x where x.id=payment_value;if found then raise unique_violation using message='KNET_PAYMENT_ID_CONFLICT';end if;insert into public.aqari_rent_payments(id,workspace_id,lease_id,reference,amount,period,paid_at,status,payment_method,record,receipt) values(payment_value,i.workspace_id,i.lease_id,receipt_value,i.amount,i.period,paid_day,status_label,method_value,ledger,receipt_json);update private.aqari_rent_receipt_serial_reservations r set consumed_at=now() where r.receipt_no=receipt_value and r.operation_ref=i.id;perform private.aqari_refresh_rent_due_schedule(i.workspace_id,i.lease_id);select balance into balance_after from private.aqari_rent_due_periods x where x.workspace_id=i.workspace_id and x.lease_id=i.lease_id and x.period=i.period;
 if balance_after=0 then channel:=private.aqari_preferred_delivery_channel(private.aqari_effective_contact_profile(i.workspace_id,t.id,t.profile),t.email,t.phone);if channel is not null then insert into public.aqari_notification_outbox(workspace_id,lease_id,period,kind,channel,idempotency_key) values(i.workspace_id,i.lease_id,i.period,'payment_thanks',channel,'thanks:'||i.lease_id::text||':'||period_text) on conflict(workspace_id,idempotency_key) do nothing;end if;end if;
 update private.aqari_knet_payment_intents set status='paid',payment_id=payment_value,receipt_no=receipt_value,contract_sequence=contract_sequence,webhook_receipt_id=wr.id,updated_at=now() where id=i.id returning * into i;insert into private.aqari_knet_payment_events(workspace_id,intent_id,action,actor_kind,reason,details) values(i.workspace_id,i.id,'webhook_paid','system','ترحيل دفعة KNET مؤكدة',jsonb_build_object('providerReference',provider_ref,'paymentId',payment_value,'receiptNo',receipt_value,'period',i.period,'amount',i.amount));insert into private.aqari_webhook_processing_events(workspace_id,webhook_receipt_id,provider,outcome,entity_type,entity_id,reason) values(wr.workspace_id,wr.id,'knet','processed','knet_payment_intent',i.id::text,'KNET_PAYMENT_POSTED');return private.aqari_knet_intent_snapshot(i)||jsonb_build_object('processed',true,'replayed',false,'remainingBalance',balance_after);
end $function$

CREATE OR REPLACE FUNCTION public.aqari_property_channel_settings(p_workspace_id uuid, p_action text, p_data jsonb DEFAULT '{}'::jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare w uuid:=p_workspace_id;d jsonb:=coalesce(p_data,'{}'::jsonb);prop uuid;ident uuid;expected bigint;why text;actor text;manager boolean;before_row jsonb;after_row jsonb;kind_value text;url_value text;label_value text;reference_value text;status_value text;visible_value boolean;sort_value integer;
begin
 if auth.uid() is null or jsonb_typeof(d) is distinct from 'object' then raise insufficient_privilege using message='ACCESS_DENIED';end if;
 prop:=nullif(d->>'propertyId','')::uuid;
 if prop is null or not private.aqari_can_property(w,prop,'properties','read') then raise insufficient_privilege using message='ACCESS_DENIED';end if;
 manager:=private.aqari_manager(w) and private.aqari_can_property(w,prop,'properties','write');
 if p_action='context' then
  return jsonb_build_object('workspace_id',w,'user_id',auth.uid(),'propertyId',prop,'manager',manager,
   'items',coalesce((select jsonb_agg(jsonb_build_object('id',c.id,'kind',c.kind,'url',c.public_url,'label',c.display_label,'managementReference',case when manager then c.management_reference else '' end,'tenantVisible',c.tenant_visible,'status',c.status,'sortOrder',c.sort_order,'revision',c.revision) order by c.sort_order,c.kind,c.created_at) from private.aqari_property_channels c where c.workspace_id=w and c.property_id=prop and (manager or (c.tenant_visible and c.status='active'))),'[]'::jsonb));
 end if;
 if p_action<>'save' or not manager then raise insufficient_privilege using message='PROPERTY_CHANNEL_MANAGER_ONLY';end if;
 perform private.aqari_require_sensitive_aal2(w);
 ident:=coalesce(nullif(d->>'id','')::uuid,gen_random_uuid());expected:=coalesce((d->>'revision')::bigint,0);why:=btrim(coalesce(d->>'reason',''));
 kind_value:=lower(btrim(coalesce(d->>'kind','')));url_value:=btrim(coalesce(d->>'url',''));label_value:=btrim(coalesce(d->>'label',''));reference_value:=btrim(coalesce(d->>'managementReference',''));status_value:=coalesce(nullif(d->>'status',''),'active');visible_value:=coalesce((d->>'tenantVisible')::boolean,false);sort_value:=coalesce((d->>'sortOrder')::integer,100);
 if length(why) not between 3 and 1000 or kind_value not in('website','instagram','tiktok','snapchat','x','facebook','youtube','whatsapp','email','phone','other') or length(label_value)>200 or length(reference_value)>1000 or status_value not in('active','hidden','archived') or sort_value not between 0 and 10000 then raise invalid_parameter_value using message='PROPERTY_CHANNEL_INVALID';end if;
 if kind_value='email' and url_value !~ '^mailto:[^[:space:]@]+@[^[:space:]@]+[.][^[:space:]@]+$' then raise invalid_parameter_value using message='PROPERTY_CHANNEL_URL_INVALID';
 elsif kind_value='phone' and url_value !~ '^tel:[+]?[0-9]{8,15}$' then raise invalid_parameter_value using message='PROPERTY_CHANNEL_URL_INVALID';
 elsif kind_value not in('email','phone') and (length(url_value)>2000 or url_value !~ '^https://[^[:space:]@/?#\\]+([/?#][^[:space:]\\]*)?$') then raise invalid_parameter_value using message='PROPERTY_CHANNEL_URL_INVALID';end if;
 if status_value<>'active' then visible_value:=false;end if;
 select to_jsonb(c) into before_row from private.aqari_property_channels c where c.workspace_id=w and c.property_id=prop and c.id=ident for update;
 if before_row is null then
  if expected<>0 then raise serialization_failure using message='PROPERTY_CHANNEL_REVISION_CONFLICT';end if;
  insert into private.aqari_property_channels(id,workspace_id,property_id,kind,public_url,management_reference,tenant_visible,status,display_label,sort_order,revision,created_by,updated_by,updated_at)
  values(ident,w,prop,kind_value,url_value,reference_value,visible_value,status_value,label_value,sort_value,1,auth.uid(),auth.uid(),now());
 else
  if (before_row->>'revision')::bigint<>expected then raise serialization_failure using message='PROPERTY_CHANNEL_REVISION_CONFLICT';end if;
  update private.aqari_property_channels set kind=kind_value,public_url=url_value,management_reference=reference_value,tenant_visible=visible_value,status=status_value,display_label=label_value,sort_order=sort_value,revision=expected+1,updated_by=auth.uid(),updated_at=now()
   where workspace_id=w and property_id=prop and id=ident;
 end if;
 select coalesce(nullif(display_name,''),auth.uid()::text) into actor from public.aqari_profiles where user_id=auth.uid();actor:=coalesce(actor,auth.uid()::text);
 select to_jsonb(c) into after_row from private.aqari_property_channels c where c.workspace_id=w and c.property_id=prop and c.id=ident;
 insert into private.aqari_property_control_audit(workspace_id,property_id,entity,entity_id,action,actor_id,actor_name,reason,before_value,after_value)
 values(w,prop,'property_channel',ident::text,'save',auth.uid(),actor,why,before_row,after_row);
 return jsonb_build_object('workspace_id',w,'user_id',auth.uid(),'record',after_row);
end $function$

CREATE OR REPLACE FUNCTION public.aqari_property_contract_context(p_workspace_id uuid, p_property_id uuid, p_unit_id uuid DEFAULT NULL::uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare p jsonb;u jsonb;active jsonb;
begin
 if not private.aqari_can_property(p_workspace_id,p_property_id,'properties','read') or not private.aqari_can(p_workspace_id,'contracts','read') then raise insufficient_privilege using message='ACCESS_DENIED';end if;
 p:=private.aqari_property_master_snapshot(p_workspace_id,p_property_id);if p is null then raise no_data_found using message='PROPERTY_NOT_FOUND';end if;
 if p_unit_id is not null then
  u:=private.aqari_unit_master_snapshot(p_workspace_id,p_unit_id);
  if u is null or u->>'propertyId'<>p_property_id::text then raise exception 'UNIT_PROPERTY_BINDING_MISMATCH' using errcode='23514';end if;
  select to_jsonb(l) into active from public.aqari_leases l where l.workspace_id=p_workspace_id and l.unit_id=p_unit_id and l.status in('ready','approved','signing','signed') and coalesce(l.vacated_on,'infinity'::date)>=current_date order by l.start_date nulls first limit 1;
 end if;
 return jsonb_build_object('workspace_id',p_workspace_id,'user_id',auth.uid(),'property',p,'unit',u,'activeLease',active,'binding',jsonb_build_object('propertyId',p_property_id,'unitId',p_unit_id,'propertyRevision',coalesce((p->>'revision')::bigint,0),'unitRevision',coalesce((u->>'revision')::bigint,0)));
end $function$

CREATE OR REPLACE FUNCTION public.aqari_property_controls(p_workspace_id uuid, p_action text, p_data jsonb DEFAULT '{}'::jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
 w uuid:=p_workspace_id; d jsonb:=coalesce(p_data,'{}'::jsonb); manager boolean; actor text; ident uuid; prop uuid; employee uuid; template uuid;
 expected bigint; next_rev bigint; why text; before_row jsonb; after_row jsonb; row_record record; props uuid[]; ftype text; val jsonb; settings jsonb;
 scope_kind text; property_type_value text; field_key_value text; label_ar_value text; label_en_value text; visibility_value text; active_value boolean;
begin
 if auth.uid() is null or jsonb_typeof(d) is distinct from 'object' then raise insufficient_privilege using message='ACCESS_DENIED';end if;
 manager:=private.aqari_manager(w) and private.aqari_can(w,'administration','write') and private.aqari_can(w,'properties','write');
 if p_action='context' then
  if not manager then raise insufficient_privilege using message='PROPERTY_CONTROLS_MANAGER_ONLY';end if;
  return jsonb_build_object(
   'workspace_id',w,'user_id',auth.uid(),'manager',true,
   'properties',coalesce((select jsonb_agg(jsonb_build_object('id',p.id,'name',p.name,'type',coalesce(m.property_type,'')) order by p.name,p.id) from public.aqari_properties p left join private.aqari_property_master m on m.workspace_id=p.workspace_id and m.property_id=p.id where p.workspace_id=w),'[]'::jsonb),
   'fields',coalesce((select jsonb_agg(jsonb_build_object('id',f.id,'key',f.field_key,'labelAr',f.label_ar,'labelEn',f.label_en,'type',f.field_type,'visibility',f.visibility,'propertyIds',to_jsonb(f.property_ids),'active',f.is_active,'revision',f.revision) order by f.label_ar,f.id) from private.aqari_property_custom_fields f where f.workspace_id=w),'[]'::jsonb),
   'values',coalesce((select jsonb_agg(jsonb_build_object('propertyId',v.property_id,'fieldId',v.field_id,'value',v.value,'revision',v.revision) order by v.property_id,v.field_id) from private.aqari_property_custom_values v where v.workspace_id=w),'[]'::jsonb),
   'features',coalesce((select jsonb_agg(jsonb_build_object('propertyId',s.property_id,'settings',s.settings,'revision',s.revision) order by s.property_id) from private.aqari_property_feature_settings s where s.workspace_id=w),'[]'::jsonb),
   'technicians',coalesce((select jsonb_agg(jsonb_build_object('propertyId',t.property_id,'employeeId',t.employee_id,'publicToTenant',t.public_to_tenant,'phone',t.phone,'whatsapp',t.whatsapp,'active',t.is_active,'revision',t.revision,'profile',e.profile) order by t.property_id,t.employee_id) from private.aqari_property_technicians t join private.aqari_hr_employees e on e.id=t.employee_id and e.workspace_id=t.workspace_id where t.workspace_id=w),'[]'::jsonb),
   'employees',coalesce((select jsonb_agg(jsonb_build_object('id',e.id,'profile',e.profile,'propertyIds',to_jsonb(e.property_ids),'status',e.status) order by coalesce(e.profile->>'name_ar',e.profile->>'name_en',e.id::text)) from private.aqari_hr_employees e where e.workspace_id=w and e.status<>'inactive'),'[]'::jsonb),
   'templateScopes',coalesce((select jsonb_agg(jsonb_build_object('id',s.id,'templateId',s.template_id,'kind',s.kind,'scopeKind',s.scope_kind,'propertyId',s.property_id,'propertyType',s.property_type,'active',s.is_active,'revision',s.revision) order by s.kind,s.id) from private.aqari_property_template_scopes s where s.workspace_id=w),'[]'::jsonb),
   'templates',coalesce((select jsonb_agg(private.aqari_rental_template_snapshot(v) order by v.kind,v.version desc) from private.aqari_rental_template_versions v where v.workspace_id=w),'[]'::jsonb),
   'documents',coalesce((select jsonb_agg(jsonb_build_object('id',x.id,'entityRef',x.entity_ref,'title',x.title,'documentNo',x.document_no,'status',x.status,'category',coalesce(x.metadata->>'category',x.metadata->>'document_category','')) order by x.created_at desc,x.id desc) from public.aqari_documents x where x.workspace_id=w and x.entity_type='property' and x.status='uploaded'),'[]'::jsonb)
  );
 end if;
 if not manager then raise insufficient_privilege using message='PROPERTY_CONTROLS_MANAGER_ONLY';end if;
 perform private.aqari_require_sensitive_aal2(w);
 select coalesce(nullif(display_name,''),auth.uid()::text) into actor from public.aqari_profiles where user_id=auth.uid();actor:=coalesce(actor,auth.uid()::text);
 why:=btrim(coalesce(d->>'reason',''));
 if length(why) not between 3 and 1000 then raise invalid_parameter_value using message='CONTROL_REASON_REQUIRED';end if;

 if p_action='save_field' then
  ident:=coalesce(nullif(d->>'id','')::uuid,gen_random_uuid());expected:=coalesce((d->>'revision')::bigint,0);
  field_key_value:=lower(btrim(coalesce(d->>'key','')));label_ar_value:=btrim(coalesce(d->>'labelAr',''));label_en_value:=btrim(coalesce(d->>'labelEn',''));ftype:=d->>'type';visibility_value:=d->>'visibility';active_value:=coalesce((d->>'active')::boolean,true);
  if field_key_value !~ '^[a-z][a-z0-9_.-]{0,49}$' or length(label_ar_value) not between 1 and 200 or length(label_en_value)>200 or ftype not in('boolean','percentage','money','text','document') or visibility_value not in('internal','owner','both') or jsonb_typeof(d->'propertyIds') is distinct from 'array' or jsonb_array_length(d->'propertyIds') not between 1 and 100 then raise invalid_parameter_value using message='INVALID_OWNER_FIELD';end if;
  select coalesce(array_agg(distinct x::uuid order by x::uuid),'{}'::uuid[]) into props from jsonb_array_elements_text(d->'propertyIds') q(x);
  if cardinality(props)<>jsonb_array_length(d->'propertyIds') or exists(select 1 from unnest(props) p where not exists(select 1 from public.aqari_properties x where x.workspace_id=w and x.id=p)) then raise insufficient_privilege using message='INVALID_OWNER_FIELD_SCOPE';end if;
  select to_jsonb(f) into before_row from private.aqari_property_custom_fields f where f.workspace_id=w and f.id=ident for update;
  if before_row is null then if expected<>0 then raise serialization_failure using message='OWNER_FIELD_REVISION_CONFLICT';end if;next_rev:=1;
   insert into private.aqari_property_custom_fields(id,workspace_id,field_key,label_ar,label_en,field_type,visibility,property_ids,is_active,revision,created_by,updated_by) values(ident,w,field_key_value,label_ar_value,label_en_value,ftype,visibility_value,props,active_value,next_rev,auth.uid(),auth.uid());
  else if (before_row->>'revision')::bigint<>expected then raise serialization_failure using message='OWNER_FIELD_REVISION_CONFLICT';end if;next_rev:=expected+1;
   update private.aqari_property_custom_fields set field_key=field_key_value,label_ar=label_ar_value,label_en=label_en_value,field_type=ftype,visibility=visibility_value,property_ids=props,is_active=active_value,revision=next_rev,updated_by=auth.uid(),updated_at=now() where workspace_id=w and id=ident;
  end if;
  select to_jsonb(f) into after_row from private.aqari_property_custom_fields f where f.workspace_id=w and f.id=ident;
  insert into private.aqari_property_control_audit(workspace_id,entity,entity_id,action,actor_id,actor_name,reason,before_value,after_value) values(w,'owner_field_definition',ident::text,'save',auth.uid(),actor,why,before_row,after_row);
  return jsonb_build_object('workspace_id',w,'user_id',auth.uid(),'record',after_row);
 end if;

 if p_action='save_value' then
  prop:=(d->>'propertyId')::uuid;ident:=(d->>'fieldId')::uuid;expected:=coalesce((d->>'revision')::bigint,0);val:=d->'value';
  select f.field_type into ftype from private.aqari_property_custom_fields f where f.workspace_id=w and f.id=ident and f.is_active and prop=any(f.property_ids);
  if ftype is null or not exists(select 1 from public.aqari_properties p where p.workspace_id=w and p.id=prop) then raise insufficient_privilege using message='OWNER_FIELD_NOT_AVAILABLE';end if;
  if ftype='boolean' and jsonb_typeof(val)<>'boolean' then raise invalid_parameter_value using message='INVALID_OWNER_FIELD_VALUE';
  elsif ftype='percentage' and (jsonb_typeof(val) not in('number','string') or (val#>>'{}') !~ '^\d{1,3}(\.\d{1,3})?$' or (val#>>'{}')::numeric<0 or (val#>>'{}')::numeric>100) then raise invalid_parameter_value using message='INVALID_OWNER_FIELD_VALUE';
  elsif ftype='money' and (jsonb_typeof(val) not in('number','string') or (val#>>'{}') !~ '^\d{1,12}(\.\d{1,3})?$' or (val#>>'{}')::numeric<0) then raise invalid_parameter_value using message='INVALID_OWNER_FIELD_VALUE';
  elsif ftype='text' and (jsonb_typeof(val)<>'string' or length(val#>>'{}')>5000) then raise invalid_parameter_value using message='INVALID_OWNER_FIELD_VALUE';
  elsif ftype='document' then
   if jsonb_typeof(val)<>'string' or (val#>>'{}') !~ '^[0-9a-f-]{36}$' or not exists(select 1 from public.aqari_documents doc join public.aqari_properties p on p.workspace_id=doc.workspace_id and p.external_ref=doc.entity_ref where doc.workspace_id=w and doc.id=(val#>>'{}')::uuid and doc.entity_type='property' and doc.status='uploaded' and p.id=prop) then raise invalid_parameter_value using message='INVALID_OWNER_FIELD_DOCUMENT';end if;
  end if;
  select to_jsonb(v) into before_row from private.aqari_property_custom_values v where v.workspace_id=w and v.property_id=prop and v.field_id=ident for update;
  if before_row is null then if expected<>0 then raise serialization_failure using message='OWNER_VALUE_REVISION_CONFLICT';end if;next_rev:=1;insert into private.aqari_property_custom_values(workspace_id,property_id,field_id,value,revision,updated_by) values(w,prop,ident,val,next_rev,auth.uid());
  else if (before_row->>'revision')::bigint<>expected then raise serialization_failure using message='OWNER_VALUE_REVISION_CONFLICT';end if;next_rev:=expected+1;update private.aqari_property_custom_values set value=val,revision=next_rev,updated_by=auth.uid(),updated_at=now() where workspace_id=w and property_id=prop and field_id=ident;end if;
  select to_jsonb(v) into after_row from private.aqari_property_custom_values v where v.workspace_id=w and v.property_id=prop and v.field_id=ident;
  insert into private.aqari_property_control_audit(workspace_id,property_id,entity,entity_id,action,actor_id,actor_name,reason,before_value,after_value) values(w,prop,'owner_field_value',ident::text,'save',auth.uid(),actor,why,before_row,after_row);
  return jsonb_build_object('workspace_id',w,'user_id',auth.uid(),'record',after_row);
 end if;

 if p_action='save_features' then
  prop:=(d->>'propertyId')::uuid;expected:=coalesce((d->>'revision')::bigint,0);settings:=coalesce(d->'settings','{}'::jsonb);
  if not exists(select 1 from public.aqari_properties p where p.workspace_id=w and p.id=prop) or jsonb_typeof(settings)<>'object' or (select count(*) from jsonb_object_keys(settings))>50 or exists(select 1 from jsonb_each(settings) e where e.key !~ '^[a-z][a-z0-9_.-]{0,49}$' or jsonb_typeof(e.value)<>'boolean') then raise invalid_parameter_value using message='INVALID_PROPERTY_FEATURE_SETTINGS';end if;
  select to_jsonb(s) into before_row from private.aqari_property_feature_settings s where s.workspace_id=w and s.property_id=prop for update;
  if before_row is null then if expected<>0 then raise serialization_failure using message='PROPERTY_FEATURE_REVISION_CONFLICT';end if;next_rev:=1;insert into private.aqari_property_feature_settings(workspace_id,property_id,settings,revision,updated_by) values(w,prop,settings,next_rev,auth.uid());
  else if (before_row->>'revision')::bigint<>expected then raise serialization_failure using message='PROPERTY_FEATURE_REVISION_CONFLICT';end if;next_rev:=expected+1;update private.aqari_property_feature_settings set settings=settings,revision=next_rev,updated_by=auth.uid(),updated_at=now() where workspace_id=w and property_id=prop;end if;
  select to_jsonb(s) into after_row from private.aqari_property_feature_settings s where s.workspace_id=w and s.property_id=prop;
  insert into private.aqari_property_control_audit(workspace_id,property_id,entity,entity_id,action,actor_id,actor_name,reason,before_value,after_value) values(w,prop,'property_features',prop::text,'save',auth.uid(),actor,why,before_row,after_row);
  return jsonb_build_object('workspace_id',w,'user_id',auth.uid(),'record',after_row);
 end if;

 if p_action='copy_features' then
  prop:=(d->>'sourcePropertyId')::uuid;
  select s.settings into settings from private.aqari_property_feature_settings s where s.workspace_id=w and s.property_id=prop;
  settings:=coalesce(settings,'{}'::jsonb);
  if jsonb_typeof(d->'targetPropertyIds') is distinct from 'array' or jsonb_array_length(d->'targetPropertyIds') not between 1 and 100 then raise invalid_parameter_value using message='COPY_TARGET_REQUIRED';end if;
  for row_record in select (x#>>'{}')::uuid target_id from jsonb_array_elements(d->'targetPropertyIds') x loop
   if row_record.target_id=prop or not exists(select 1 from public.aqari_properties p where p.workspace_id=w and p.id=row_record.target_id) then raise invalid_parameter_value using message='INVALID_COPY_TARGET';end if;
   select to_jsonb(s) into before_row from private.aqari_property_feature_settings s where s.workspace_id=w and s.property_id=row_record.target_id for update;
   if before_row is null then next_rev:=1;insert into private.aqari_property_feature_settings(workspace_id,property_id,settings,revision,updated_by) values(w,row_record.target_id,settings,next_rev,auth.uid());
   else next_rev:=(before_row->>'revision')::bigint+1;update private.aqari_property_feature_settings s set settings=settings,revision=next_rev,updated_by=auth.uid(),updated_at=now() where s.workspace_id=w and s.property_id=row_record.target_id;end if;
   select to_jsonb(s) into after_row from private.aqari_property_feature_settings s where s.workspace_id=w and s.property_id=row_record.target_id;
   insert into private.aqari_property_control_audit(workspace_id,property_id,entity,entity_id,action,actor_id,actor_name,reason,before_value,after_value) values(w,row_record.target_id,'property_features',row_record.target_id::text,'copy',auth.uid(),actor,why,before_row,after_row);
  end loop;
  return jsonb_build_object('workspace_id',w,'user_id',auth.uid(),'copied',jsonb_array_length(d->'targetPropertyIds'));
 end if;

 if p_action='save_technician' then
  prop:=(d->>'propertyId')::uuid;employee:=(d->>'employeeId')::uuid;expected:=coalesce((d->>'revision')::bigint,0);active_value:=coalesce((d->>'active')::boolean,true);
  if not exists(select 1 from private.aqari_hr_employees e where e.workspace_id=w and e.id=employee and e.status<>'inactive' and prop=any(e.property_ids)) then raise invalid_parameter_value using message='TECHNICIAN_NOT_ASSIGNED_TO_PROPERTY';end if;
  field_key_value:=regexp_replace(coalesce(d->>'phone',''),'[ ()-]','','g');label_ar_value:=regexp_replace(coalesce(d->>'whatsapp',''),'[ ()-]','','g');
  if field_key_value<>'' and field_key_value !~ '^\+?[0-9]{8,15}$' or label_ar_value<>'' and label_ar_value !~ '^\+?[0-9]{8,15}$' then raise invalid_parameter_value using message='INVALID_TECHNICIAN_CONTACT';end if;
  if coalesce((d->>'publicToTenant')::boolean,false) and field_key_value='' and label_ar_value='' then select regexp_replace(coalesce(e.profile->>'phone',''),'[ ()-]','','g') into field_key_value from private.aqari_hr_employees e where e.id=employee;label_ar_value:=field_key_value;end if;
  if coalesce((d->>'publicToTenant')::boolean,false) and field_key_value='' and label_ar_value='' then raise invalid_parameter_value using message='PUBLIC_TECHNICIAN_CONTACT_REQUIRED';end if;
  select to_jsonb(t) into before_row from private.aqari_property_technicians t where t.workspace_id=w and t.property_id=prop and t.employee_id=employee for update;
  if before_row is null then if expected<>0 then raise serialization_failure using message='TECHNICIAN_REVISION_CONFLICT';end if;next_rev:=1;insert into private.aqari_property_technicians(workspace_id,property_id,employee_id,public_to_tenant,phone,whatsapp,is_active,revision,updated_by) values(w,prop,employee,coalesce((d->>'publicToTenant')::boolean,false),field_key_value,label_ar_value,active_value,next_rev,auth.uid());
  else if (before_row->>'revision')::bigint<>expected then raise serialization_failure using message='TECHNICIAN_REVISION_CONFLICT';end if;next_rev:=expected+1;update private.aqari_property_technicians set public_to_tenant=coalesce((d->>'publicToTenant')::boolean,false),phone=field_key_value,whatsapp=label_ar_value,is_active=active_value,revision=next_rev,updated_by=auth.uid(),updated_at=now() where workspace_id=w and property_id=prop and employee_id=employee;end if;
  select to_jsonb(t) into after_row from private.aqari_property_technicians t where t.workspace_id=w and t.property_id=prop and t.employee_id=employee;
  insert into private.aqari_property_control_audit(workspace_id,property_id,entity,entity_id,action,actor_id,actor_name,reason,before_value,after_value) values(w,prop,'property_technician',employee::text,'save',auth.uid(),actor,why,before_row,after_row);
  return jsonb_build_object('workspace_id',w,'user_id',auth.uid(),'record',after_row);
 end if;

 if p_action='save_template_scope' then
  ident:=coalesce(nullif(d->>'id','')::uuid,gen_random_uuid());template:=(d->>'templateId')::uuid;scope_kind:=d->>'scopeKind';prop:=nullif(d->>'propertyId','')::uuid;property_type_value:=nullif(btrim(coalesce(d->>'propertyType','')),'');expected:=coalesce((d->>'revision')::bigint,0);active_value:=coalesce((d->>'active')::boolean,true);
  select v.kind into ftype from private.aqari_rental_template_versions v where v.workspace_id=w and v.id=template;
  if ftype is null or scope_kind not in('property','property_type') or (scope_kind='property' and (prop is null or property_type_value is not null or not exists(select 1 from public.aqari_properties p where p.workspace_id=w and p.id=prop))) or (scope_kind='property_type' and (prop is not null or property_type_value is null or length(property_type_value)>200)) then raise invalid_parameter_value using message='INVALID_TEMPLATE_SCOPE';end if;
  select to_jsonb(s) into before_row from private.aqari_property_template_scopes s where s.workspace_id=w and s.id=ident for update;
  if before_row is null then if expected<>0 then raise serialization_failure using message='TEMPLATE_SCOPE_REVISION_CONFLICT';end if;next_rev:=1;insert into private.aqari_property_template_scopes(id,workspace_id,template_id,kind,scope_kind,property_id,property_type,is_active,revision,updated_by) values(ident,w,template,ftype,scope_kind,prop,property_type_value,active_value,next_rev,auth.uid());
  else
   if (before_row->>'revision')::bigint<>expected then raise serialization_failure using message='TEMPLATE_SCOPE_REVISION_CONFLICT';end if;
   if (before_row->>'template_id')::uuid<>template or before_row->>'scope_kind'<>scope_kind or coalesce(before_row->>'property_id','')<>coalesce(prop::text,'') or coalesce(before_row->>'property_type','')<>coalesce(property_type_value,'') then raise check_violation using message='TEMPLATE_SCOPE_IDENTITY_IMMUTABLE';end if;
   next_rev:=expected+1;update private.aqari_property_template_scopes set is_active=active_value,revision=next_rev,updated_by=auth.uid(),updated_at=now() where workspace_id=w and id=ident;
  end if;
  select to_jsonb(s) into after_row from private.aqari_property_template_scopes s where s.workspace_id=w and s.id=ident;
  insert into private.aqari_property_control_audit(workspace_id,property_id,entity,entity_id,action,actor_id,actor_name,reason,before_value,after_value) values(w,prop,'template_scope',ident::text,'save',auth.uid(),actor,why,before_row,after_row);
  return jsonb_build_object('workspace_id',w,'user_id',auth.uid(),'record',after_row);
 end if;
 raise invalid_parameter_value using message='INVALID_PROPERTY_CONTROL_ACTION';
end $function$

CREATE OR REPLACE FUNCTION public.aqari_property_cost_allocation(p_workspace_id uuid, p_action text, p_data jsonb DEFAULT '{}'::jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare w uuid:=p_workspace_id;kind text;ident uuid;source jsonb;expected bigint;next_rev bigint;why text;actor text;rows jsonb;normalized jsonb;weights jsonb;sum_amount numeric;property_ids uuid[];head private.aqari_property_cost_allocation_heads%rowtype;method text;frequency text;basis jsonb;total numeric;
begin
 if auth.uid() is null or not private.aqari_can(w,'finance','read') then raise insufficient_privilege using message='ACCESS_DENIED';end if;
 if p_action='list' then
  if jsonb_typeof(p_data) is distinct from 'object' or exists(select 1 from jsonb_object_keys(p_data)k where k not in('from','to')) then raise invalid_parameter_value using message='INVALID_ALLOCATION_QUERY';end if;
  return jsonb_build_object('workspace_id',w,'user_id',auth.uid(),'manager',private.aqari_manager(w),
   'properties',coalesce((select jsonb_agg(jsonb_build_object('id',p.id,'name',p.name,'unitCount',coalesce(q.units,0),'areaSqm',coalesce(q.area,0),'areaComplete',coalesce(q.units,0)>0 and q.units=q.with_area) order by p.name,p.id)
     from public.aqari_properties p left join lateral(select count(u.id)::int units,count(m.area_sqm)::int with_area,coalesce(sum(m.area_sqm),0) area from public.aqari_units u left join private.aqari_unit_master m on m.workspace_id=u.workspace_id and m.unit_id=u.id where u.workspace_id=p.workspace_id and u.property_id=p.id)q on true where p.workspace_id=w),'[]'::jsonb),
   'sources',(select coalesce(jsonb_agg(x order by x->>'date' desc,x->>'label'),'[]'::jsonb) from(
    select private.aqari_cost_source(w,'financial_expense',e.id)||jsonb_build_object('revision',coalesce(h.current_revision,0),'method',coalesce(h.allocation_method,'amount'),'frequency',coalesce(h.analysis_frequency,'one_time'),'basis',coalesce(h.basis_snapshot,'{}'::jsonb),'allocations',coalesce(a.rows,'[]'::jsonb)) x
     from private.aqari_financial_expenses e left join private.aqari_property_cost_allocation_heads h on h.workspace_id=e.workspace_id and h.source_kind='financial_expense' and h.source_id=e.id left join lateral(select jsonb_agg(jsonb_build_object('propertyId',q.property_id,'amount',q.amount,'weight',q.weight,'shareBps',q.share_bps) order by q.property_id) rows from private.aqari_property_cost_allocations q where q.workspace_id=e.workspace_id and q.source_kind='financial_expense' and q.source_id=e.id and q.revision=h.current_revision)a on true where e.workspace_id=w and e.state='approved'
    union all
    select private.aqari_cost_source(w,'payroll',pay.id)||jsonb_build_object('revision',coalesce(h.current_revision,0),'method',coalesce(h.allocation_method,'amount'),'frequency',coalesce(h.analysis_frequency,'monthly'),'basis',coalesce(h.basis_snapshot,'{}'::jsonb),'allocations',coalesce(a.rows,'[]'::jsonb)) x
     from private.aqari_hr_payroll pay left join private.aqari_property_cost_allocation_heads h on h.workspace_id=pay.workspace_id and h.source_kind='payroll' and h.source_id=pay.id left join lateral(select jsonb_agg(jsonb_build_object('propertyId',q.property_id,'amount',q.amount,'weight',q.weight,'shareBps',q.share_bps) order by q.property_id) rows from private.aqari_property_cost_allocations q where q.workspace_id=pay.workspace_id and q.source_kind='payroll' and q.source_id=pay.id and q.revision=h.current_revision)a on true where pay.workspace_id=w and pay.state='paid'
    union all
    select private.aqari_cost_source(w,'utility',u.id)||jsonb_build_object('revision',coalesce(h.current_revision,0),'method',coalesce(h.allocation_method,'amount'),'frequency',coalesce(h.analysis_frequency,'invoice'),'basis',coalesce(h.basis_snapshot,'{}'::jsonb),'allocations',coalesce(a.rows,'[]'::jsonb)) x
     from public.aqari_utility_entries u left join private.aqari_property_cost_allocation_heads h on h.workspace_id=u.workspace_id and h.source_kind='utility' and h.source_id=u.id left join lateral(select jsonb_agg(jsonb_build_object('propertyId',q.property_id,'amount',q.amount,'weight',q.weight,'shareBps',q.share_bps) order by q.property_id) rows from private.aqari_property_cost_allocations q where q.workspace_id=u.workspace_id and q.source_kind='utility' and q.source_id=u.id and q.revision=h.current_revision)a on true where u.workspace_id=w and u.entry_type='bill' and u.amount_paid>0 and u.payment_date is not null and u.payment_document_id is not null
   )s));
 end if;
 if p_action<>'save' or jsonb_typeof(p_data) is distinct from 'object' or exists(select 1 from jsonb_object_keys(p_data)k where k not in('sourceKind','sourceId','revision','allocations','reason','method','frequency')) then raise invalid_parameter_value using message='INVALID_ALLOCATION_REQUEST';end if;
 if not private.aqari_manager(w) or not private.aqari_can(w,'finance','write') then raise insufficient_privilege using message='ACCESS_DENIED';end if;perform private.aqari_require_sensitive_aal2(w);
 kind:=p_data->>'sourceKind';ident:=nullif(p_data->>'sourceId','')::uuid;expected:=coalesce((p_data->>'revision')::bigint,-1);why:=btrim(coalesce(p_data->>'reason',''));rows:=p_data->'allocations';method:=coalesce(nullif(p_data->>'method',''),'amount');frequency:=coalesce(nullif(p_data->>'frequency',''),case kind when 'payroll' then 'monthly' when 'utility' then 'invoice' else 'one_time' end);
 if kind not in('financial_expense','payroll','utility') or ident is null or expected<0 or method not in('amount','percentage','unit_count','area','custom') or frequency not in('one_time','monthly','annual','invoice') or jsonb_typeof(rows) is distinct from 'array' or jsonb_array_length(rows)<1 or octet_length(rows::text)>200000 or length(why) not between 3 and 1000 then raise invalid_parameter_value using message='ALLOCATION_FIELDS_REQUIRED';end if;
 source:=private.aqari_cost_source(w,kind,ident);total:=(source->>'total')::numeric;
 if exists(select 1 from jsonb_array_elements(rows)r where jsonb_typeof(r)<>'object' or coalesce(r->>'propertyId','')!~'^[0-9a-fA-F-]{36}$') then raise invalid_parameter_value using message='INVALID_ALLOCATION_ROW';end if;
 if (select count(*) from jsonb_array_elements(rows))<>(select count(distinct r->>'propertyId') from jsonb_array_elements(rows)r) then raise unique_violation using message='DUPLICATE_ALLOCATION_PROPERTY';end if;
 select array_agg((r->>'propertyId')::uuid order by (r->>'propertyId')::uuid) into property_ids from jsonb_array_elements(rows)r;
 if exists(select 1 from unnest(property_ids)p where not exists(select 1 from public.aqari_properties x where x.workspace_id=w and x.id=p)) then raise insufficient_privilege using message='ALLOCATION_PROPERTY_NOT_FOUND';end if;
 if kind='payroll' and exists(select 1 from unnest(property_ids)p where not exists(select 1 from jsonb_array_elements_text(coalesce(source->'propertyIds','[]'::jsonb))a(value) where a.value=p::text)) then raise insufficient_privilege using message='PAYROLL_ALLOCATION_OUTSIDE_EMPLOYEE_PROPERTIES';end if;
 if method='amount' then
  if exists(select 1 from jsonb_array_elements(rows)r where exists(select 1 from jsonb_object_keys(r)k where k not in('propertyId','amount')) or coalesce(r->>'amount','')!~'^\d{1,12}(\.\d{1,3})?$' or (r->>'amount')::numeric<=0) then raise invalid_parameter_value using message='INVALID_ALLOCATION_ROW';end if;
  select sum((r->>'amount')::numeric) into sum_amount from jsonb_array_elements(rows)r;if sum_amount is distinct from total then raise check_violation using message='ALLOCATION_TOTAL_MISMATCH';end if;
  select jsonb_agg(jsonb_build_object('propertyId',r->>'propertyId','amount',(r->>'amount')::numeric,'weight',(r->>'amount')::numeric,'shareBps',greatest(1,least(10000,round((r->>'amount')::numeric/total*10000)::int))) order by r->>'propertyId') into normalized from jsonb_array_elements(rows)r;weights:=rows;
 elsif method='percentage' then
  if exists(select 1 from jsonb_array_elements(rows)r where exists(select 1 from jsonb_object_keys(r)k where k not in('propertyId','shareBps')) or coalesce(r->>'shareBps','')!~'^\d{1,5}$' or (r->>'shareBps')::int not between 1 and 10000) or (select sum((r->>'shareBps')::int) from jsonb_array_elements(rows)r)<>10000 then raise check_violation using message='ALLOCATION_PERCENTAGE_MUST_TOTAL_100';end if;
  select jsonb_agg(jsonb_build_object('propertyId',r->>'propertyId','weight',(r->>'shareBps')::numeric) order by r->>'propertyId') into weights from jsonb_array_elements(rows)r;normalized:=private.aqari_normalize_weighted_allocation(total,weights,method);
 elsif method in('unit_count','area') then
  if exists(select 1 from jsonb_array_elements(rows)r where exists(select 1 from jsonb_object_keys(r)k where k<>'propertyId')) then raise invalid_parameter_value using message='INVALID_ALLOCATION_ROW';end if;weights:=private.aqari_allocation_weight_rows(w,method,rows);normalized:=private.aqari_normalize_weighted_allocation(total,weights,method);
 else
  if exists(select 1 from jsonb_array_elements(rows)r where exists(select 1 from jsonb_object_keys(r)k where k not in('propertyId','weight')) or coalesce(r->>'weight','')!~'^\d{1,18}(\.\d{1,6})?$' or (r->>'weight')::numeric<=0) then raise invalid_parameter_value using message='INVALID_ALLOCATION_WEIGHT';end if;weights:=rows;normalized:=private.aqari_normalize_weighted_allocation(total,weights,method);
 end if;
 basis:=jsonb_build_object('method',method,'frequency',frequency,'weights',weights,'sourcePropertyIds',coalesce(source->'propertyIds','[]'::jsonb),'sourceTotal',total);
 select * into head from private.aqari_property_cost_allocation_heads where workspace_id=w and source_kind=kind and source_id=ident for update;if coalesce(head.current_revision,0) is distinct from expected then raise serialization_failure using message='ALLOCATION_REVISION_CONFLICT';end if;
 next_rev:=expected+1;select coalesce(nullif(display_name,''),auth.uid()::text) into actor from public.aqari_profiles where user_id=auth.uid();actor:=coalesce(actor,auth.uid()::text);
 insert into private.aqari_property_cost_allocation_heads(workspace_id,source_kind,source_id,current_revision,source_total,source_date,allocation_method,analysis_frequency,basis_snapshot,updated_by,updated_at)
 values(w,kind,ident,next_rev,total,(source->>'date')::date,method,frequency,basis,auth.uid(),now()) on conflict(workspace_id,source_kind,source_id) do update set current_revision=excluded.current_revision,source_total=excluded.source_total,source_date=excluded.source_date,allocation_method=excluded.allocation_method,analysis_frequency=excluded.analysis_frequency,basis_snapshot=excluded.basis_snapshot,updated_by=excluded.updated_by,updated_at=excluded.updated_at;
 insert into private.aqari_property_cost_allocations(workspace_id,source_kind,source_id,revision,property_id,amount,reason,actor_id,actor_name,allocation_method,weight,share_bps,basis_snapshot)
 select w,kind,ident,next_rev,(r->>'propertyId')::uuid,(r->>'amount')::numeric,why,auth.uid(),actor,method,nullif(r->>'weight','')::numeric,nullif(r->>'shareBps','')::int,basis from jsonb_array_elements(normalized)r;
 return jsonb_build_object('workspace_id',w,'sourceKind',kind,'sourceId',ident,'revision',next_rev,'total',total,'method',method,'frequency',frequency,'basis',basis,'allocations',normalized,'actor',actor,'recordedAt',now());
end $function$

CREATE OR REPLACE FUNCTION public.aqari_property_custom_fields_v2(p_workspace_id uuid, p_action text, p_data jsonb DEFAULT '{}'::jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare w uuid:=p_workspace_id;d jsonb:=coalesce(p_data,'{}'::jsonb);manager boolean;ident uuid;prop uuid;expected bigint;next_rev bigint;why text;field_type_value text;visibility_value text;options_value jsonb;value_value jsonb;before_row jsonb;after_row jsonb;props uuid[];actor text;
begin
 if auth.uid() is null or jsonb_typeof(d) is distinct from 'object' then raise insufficient_privilege using message='ACCESS_DENIED';end if;manager:=private.aqari_manager(w) and private.aqari_can(w,'administration','write') and private.aqari_can(w,'properties','write');
 if p_action='context' then if not manager then raise insufficient_privilege using message='PROPERTY_CONTROLS_MANAGER_ONLY';end if;return jsonb_build_object('workspace_id',w,'user_id',auth.uid(),'manager',true,
  'properties',coalesce((select jsonb_agg(jsonb_build_object('id',p.id,'name',p.name) order by p.name,p.id) from public.aqari_properties p where p.workspace_id=w),'[]'::jsonb),
  'fields',coalesce((select jsonb_agg(jsonb_build_object('id',f.id,'key',f.field_key,'labelAr',f.label_ar,'labelEn',f.label_en,'type',f.field_type,'visibility',f.visibility,'options',f.options,'propertyIds',to_jsonb(f.property_ids),'active',f.is_active,'revision',f.revision) order by f.label_ar,f.id) from private.aqari_property_custom_fields f where f.workspace_id=w),'[]'::jsonb),
  'values',coalesce((select jsonb_agg(jsonb_build_object('propertyId',v.property_id,'fieldId',v.field_id,'value',v.value,'revision',v.revision) order by v.property_id,v.field_id) from private.aqari_property_custom_values v where v.workspace_id=w),'[]'::jsonb));end if;
 if not manager then raise insufficient_privilege using message='PROPERTY_CONTROLS_MANAGER_ONLY';end if;perform private.aqari_require_sensitive_aal2(w);why:=btrim(coalesce(d->>'reason',''));if length(why) not between 3 and 1000 then raise invalid_parameter_value using message='CONTROL_REASON_REQUIRED';end if;select coalesce(nullif(display_name,''),auth.uid()::text) into actor from public.aqari_profiles where user_id=auth.uid();actor:=coalesce(actor,auth.uid()::text);
 if p_action='save_field' then
  ident:=coalesce(nullif(d->>'id','')::uuid,gen_random_uuid());expected:=coalesce((d->>'revision')::bigint,0);field_type_value:=d->>'type';visibility_value:=d->>'visibility';options_value:=coalesce(d->'options','[]'::jsonb);
  if coalesce(d->>'key','')!~'^[a-z][a-z0-9_.-]{0,49}$' or length(btrim(coalesce(d->>'labelAr',''))) not between 1 and 200 or length(coalesce(d->>'labelEn',''))>200 or field_type_value not in('boolean','percentage','money','text','date','select','document') or visibility_value not in('internal','owner','both','tenant','owner_tenant') or jsonb_typeof(d->'propertyIds')<>'array' or jsonb_array_length(d->'propertyIds')<1 or octet_length((d->'propertyIds')::text)>200000 then raise invalid_parameter_value using message='INVALID_OWNER_FIELD';end if;
  if field_type_value='select' then if jsonb_typeof(options_value)<>'array' or jsonb_array_length(options_value) not between 1 and 100 or exists(select 1 from jsonb_array_elements(options_value)x where jsonb_typeof(x)<>'string' or length(btrim(x#>>'{}')) not between 1 and 200) or (select count(*) from jsonb_array_elements_text(options_value))<>(select count(distinct x) from jsonb_array_elements_text(options_value)x) then raise invalid_parameter_value using message='INVALID_CUSTOM_FIELD_OPTIONS';end if;else options_value:='[]'::jsonb;end if;
  select array_agg(distinct x::uuid order by x::uuid) into props from jsonb_array_elements_text(d->'propertyIds')q(x);if cardinality(props)<>jsonb_array_length(d->'propertyIds') or exists(select 1 from unnest(props)p where not exists(select 1 from public.aqari_properties q where q.workspace_id=w and q.id=p)) then raise invalid_parameter_value using message='INVALID_OWNER_FIELD_SCOPE';end if;
  select to_jsonb(f) into before_row from private.aqari_property_custom_fields f where f.workspace_id=w and f.id=ident for update;if before_row is null then if expected<>0 then raise serialization_failure using message='OWNER_FIELD_REVISION_CONFLICT';end if;next_rev:=1;insert into private.aqari_property_custom_fields(id,workspace_id,field_key,label_ar,label_en,field_type,visibility,property_ids,is_active,options,revision,created_by,updated_by) values(ident,w,lower(d->>'key'),btrim(d->>'labelAr'),btrim(coalesce(d->>'labelEn','')),field_type_value,visibility_value,props,coalesce((d->>'active')::boolean,true),options_value,next_rev,auth.uid(),auth.uid());else if (before_row->>'revision')::bigint<>expected then raise serialization_failure using message='OWNER_FIELD_REVISION_CONFLICT';end if;next_rev:=expected+1;update private.aqari_property_custom_fields set field_key=lower(d->>'key'),label_ar=btrim(d->>'labelAr'),label_en=btrim(coalesce(d->>'labelEn','')),field_type=field_type_value,visibility=visibility_value,property_ids=props,is_active=coalesce((d->>'active')::boolean,true),options=options_value,revision=next_rev,updated_by=auth.uid(),updated_at=now() where workspace_id=w and id=ident;end if;
  select to_jsonb(f) into after_row from private.aqari_property_custom_fields f where f.workspace_id=w and f.id=ident;insert into private.aqari_property_control_audit(workspace_id,entity,entity_id,action,actor_id,actor_name,reason,before_value,after_value) values(w,'custom_field_definition',ident::text,'save',auth.uid(),actor,why,before_row,after_row);return jsonb_build_object('workspace_id',w,'user_id',auth.uid(),'record',after_row);
 end if;
 if p_action='save_value' then
  prop:=(d->>'propertyId')::uuid;ident:=(d->>'fieldId')::uuid;expected:=coalesce((d->>'revision')::bigint,0);value_value:=d->'value';select f.field_type,f.options into field_type_value,options_value from private.aqari_property_custom_fields f where f.workspace_id=w and f.id=ident and f.is_active and prop=any(f.property_ids);if field_type_value is null then raise insufficient_privilege using message='CUSTOM_FIELD_NOT_AVAILABLE';end if;
  if field_type_value='boolean' and jsonb_typeof(value_value)<>'boolean' then raise invalid_parameter_value using message='INVALID_CUSTOM_FIELD_VALUE';
  elsif field_type_value='percentage' and (jsonb_typeof(value_value) not in('number','string') or (value_value#>>'{}')!~'^\d{1,3}(\.\d{1,3})?$' or (value_value#>>'{}')::numeric not between 0 and 100) then raise invalid_parameter_value using message='INVALID_CUSTOM_FIELD_VALUE';
  elsif field_type_value='money' and (jsonb_typeof(value_value) not in('number','string') or (value_value#>>'{}')!~'^\d{1,12}(\.\d{1,3})?$') then raise invalid_parameter_value using message='INVALID_CUSTOM_FIELD_VALUE';
  elsif field_type_value='text' and (jsonb_typeof(value_value)<>'string' or length(value_value#>>'{}')>5000) then raise invalid_parameter_value using message='INVALID_CUSTOM_FIELD_VALUE';
  elsif field_type_value='date' and (jsonb_typeof(value_value)<>'string' or (value_value#>>'{}')!~'^20[0-9]{2}-[0-1][0-9]-[0-3][0-9]$' or to_char((value_value#>>'{}')::date,'YYYY-MM-DD')<>value_value#>>'{}') then raise invalid_parameter_value using message='INVALID_CUSTOM_FIELD_VALUE';
  elsif field_type_value='select' and (jsonb_typeof(value_value)<>'string' or not exists(select 1 from jsonb_array_elements_text(options_value)x where x=value_value#>>'{}')) then raise invalid_parameter_value using message='INVALID_CUSTOM_FIELD_VALUE';
  elsif field_type_value='document' and (jsonb_typeof(value_value)<>'string' or (value_value#>>'{}')!~'^[0-9a-f-]{36}$') then raise invalid_parameter_value using message='INVALID_CUSTOM_FIELD_VALUE';end if;
  select to_jsonb(v) into before_row from private.aqari_property_custom_values v where v.workspace_id=w and v.property_id=prop and v.field_id=ident for update;if before_row is null then if expected<>0 then raise serialization_failure using message='CUSTOM_VALUE_REVISION_CONFLICT';end if;next_rev:=1;insert into private.aqari_property_custom_values(workspace_id,property_id,field_id,value,revision,updated_by) values(w,prop,ident,value_value,next_rev,auth.uid());else if (before_row->>'revision')::bigint<>expected then raise serialization_failure using message='CUSTOM_VALUE_REVISION_CONFLICT';end if;next_rev:=expected+1;update private.aqari_property_custom_values set value=value_value,revision=next_rev,updated_by=auth.uid(),updated_at=now() where workspace_id=w and property_id=prop and field_id=ident;end if;
  select to_jsonb(v) into after_row from private.aqari_property_custom_values v where v.workspace_id=w and v.property_id=prop and v.field_id=ident;insert into private.aqari_property_control_audit(workspace_id,property_id,entity,entity_id,action,actor_id,actor_name,reason,before_value,after_value) values(w,prop,'custom_field_value',ident::text,'save',auth.uid(),actor,why,before_row,after_row);return jsonb_build_object('workspace_id',w,'user_id',auth.uid(),'record',after_row);
 end if;
 raise invalid_parameter_value using message='INVALID_CUSTOM_FIELD_ACTION';
end $function$

CREATE OR REPLACE FUNCTION public.aqari_property_financial_summary(p_workspace_id uuid, p_property_id uuid, p_as_of date DEFAULT ((now() AT TIME ZONE 'Asia/Kuwait'::text))::date)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare w uuid:=p_workspace_id;p uuid:=p_property_id;month_start date;year_start date;income_month numeric:=0;income_year numeric:=0;expected_month numeric:=0;expected_year numeric:=0;arrears numeric:=0;expense_month numeric:=0;expense_year numeric:=0;finance_month numeric:=0;finance_year numeric:=0;payroll_month numeric:=0;payroll_year numeric:=0;utility_month numeric:=0;utility_year numeric:=0;unallocated_payroll numeric:=0;analytical_month numeric:=0;
begin
 if not private.aqari_can_property(w,p,'properties','read') then raise insufficient_privilege using message='ACCESS_DENIED';end if;
 if not private.aqari_can(w,'collections','read') or not private.aqari_can(w,'finance','read') then return jsonb_build_object('workspace_id',w,'property_id',p,'available',false,'reason','PERMISSION_DENIED');end if;
 if p_as_of<'2000-01-01' or p_as_of>(now() at time zone 'Asia/Kuwait')::date+1 then raise invalid_parameter_value using message='INVALID_SUMMARY_DATE';end if;month_start:=date_trunc('month',p_as_of)::date;year_start:=date_trunc('year',p_as_of)::date;
 select coalesce(sum(r.amount) filter(where r.paid_at between month_start and p_as_of),0),coalesce(sum(r.amount) filter(where r.paid_at between year_start and p_as_of),0) into income_month,income_year from public.aqari_rent_payments r join public.aqari_leases l on l.workspace_id=r.workspace_id and l.id=r.lease_id join public.aqari_units u on u.workspace_id=l.workspace_id and u.id=l.unit_id where r.workspace_id=w and u.property_id=p and r.status not in('cancelled','ملغى') and not exists(select 1 from private.aqari_receipt_cancellations c where c.workspace_id=r.workspace_id and c.payment_id=r.id);
 select coalesce(sum(d.due_amount) filter(where d.period between month_start and date_trunc('month',p_as_of)::date),0),coalesce(sum(d.due_amount) filter(where d.period between year_start and date_trunc('month',p_as_of)::date),0),coalesce(sum(greatest(d.balance,0)) filter(where d.period<=date_trunc('month',p_as_of)::date),0) into expected_month,expected_year,arrears from private.aqari_rent_due_periods d join public.aqari_leases l on l.workspace_id=d.workspace_id and l.id=d.lease_id join public.aqari_units u on u.workspace_id=l.workspace_id and u.id=l.unit_id where d.workspace_id=w and u.property_id=p;
 select coalesce(sum(private.aqari_cost_amount(w,'financial_expense',e.id,p,e.amount,array[e.property_id])) filter(where e.expense_date between month_start and p_as_of),0),coalesce(sum(private.aqari_cost_amount(w,'financial_expense',e.id,p,e.amount,array[e.property_id])) filter(where e.expense_date between year_start and p_as_of),0) into finance_month,finance_year from private.aqari_financial_expenses e where e.workspace_id=w and e.state='approved';
 select coalesce(sum(private.aqari_cost_amount(w,'payroll',pay.id,p,coalesce(pay.net,pay.basic+pay.allowances+pay.overtime-pay.deductions-pay.advance_repayment),coalesce((select array_agg(distinct j.value::uuid) from jsonb_array_elements_text(coalesce(pay.snapshot->'property_ids',to_jsonb(h.property_ids)))j(value)),h.property_ids))) filter(where coalesce(pay.paid_at::date,pay.month) between month_start and p_as_of),0),coalesce(sum(private.aqari_cost_amount(w,'payroll',pay.id,p,coalesce(pay.net,pay.basic+pay.allowances+pay.overtime-pay.deductions-pay.advance_repayment),coalesce((select array_agg(distinct j.value::uuid) from jsonb_array_elements_text(coalesce(pay.snapshot->'property_ids',to_jsonb(h.property_ids)))j(value)),h.property_ids))) filter(where coalesce(pay.paid_at::date,pay.month) between year_start and p_as_of),0) into payroll_month,payroll_year from private.aqari_hr_payroll pay join private.aqari_hr_employees h on h.workspace_id=pay.workspace_id and h.id=pay.employee_id where pay.workspace_id=w and pay.state='paid';
 select coalesce(sum(private.aqari_cost_amount(w,'utility',u.id,p,u.amount_paid,array[u.property_id])) filter(where u.payment_date between month_start and p_as_of),0),coalesce(sum(private.aqari_cost_amount(w,'utility',u.id,p,u.amount_paid,array[u.property_id])) filter(where u.payment_date between year_start and p_as_of),0) into utility_month,utility_year from public.aqari_utility_entries u where u.workspace_id=w and u.entry_type='bill' and u.amount_paid>0 and u.payment_date is not null and u.payment_document_id is not null;
 select coalesce(sum(coalesce(pay.net,pay.basic+pay.allowances+pay.overtime-pay.deductions-pay.advance_repayment)),0) into unallocated_payroll from private.aqari_hr_payroll pay join private.aqari_hr_employees h on h.workspace_id=pay.workspace_id and h.id=pay.employee_id where pay.workspace_id=w and pay.state='paid' and coalesce(pay.paid_at::date,pay.month) between year_start and p_as_of and p=any(h.property_ids) and cardinality(h.property_ids)>1 and not exists(select 1 from private.aqari_property_cost_allocation_heads a where a.workspace_id=w and a.source_kind='payroll' and a.source_id=pay.id and a.current_revision>0);
 expense_month:=finance_month+payroll_month+utility_month;expense_year:=finance_year+payroll_year+utility_year;analytical_month:=private.aqari_monthlyized_cost(w,p,month_start);
 return jsonb_build_object('workspace_id',w,'property_id',p,'available',true,'asOf',p_as_of,'arrears',arrears,
  'month',jsonb_build_object('income',income_month,'expectedIncome',expected_month,'expenses',expense_month,'analyticalExpenses',analytical_month,'net',income_month-expense_month,'analyticalNet',income_month-analytical_month,'collectionVariance',income_month-expected_month,'finance',finance_month,'payroll',payroll_month,'utilities',utility_month),
  'year',jsonb_build_object('income',income_year,'expectedIncome',expected_year,'expenses',expense_year,'net',income_year-expense_year,'collectionVariance',income_year-expected_year,'finance',finance_year,'payroll',payroll_year,'utilities',utility_year),
  'unallocatedSharedPayroll',unallocated_payroll,'policy','actual non-cancelled rent collections minus approved property allocations; annual costs remain one original movement and monthly analytical impact is calculated only, never duplicated');
end $function$

CREATE OR REPLACE FUNCTION public.aqari_property_master_save(p_workspace_id uuid, p_property_id uuid, p_expected_revision bigint, p_data jsonb, p_reason text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare old_row private.aqari_property_master%rowtype; new_row private.aqari_property_master%rowtype;
 old_snapshot jsonb; new_snapshot jsonb; actor text; nm text; owners jsonb; income numeric; rev bigint; location_value text; automatic_value text;
begin
 if not private.aqari_can_property(p_workspace_id,p_property_id,'properties','write') then raise insufficient_privilege using message='ACCESS_DENIED';end if;
 if jsonb_typeof(p_data) is distinct from 'object' or exists(select 1 from jsonb_object_keys(p_data) k where k not in('name','address','type','status','statedIncome','owners','email','phone','whatsapp','assets','locationUrl','propertyAutomaticRef')) then raise invalid_parameter_value using message='PROPERTY_MASTER_INVALID';end if;
 nm:=btrim(coalesce(p_data->>'name',''));if length(nm) not between 1 and 200 then raise invalid_parameter_value using message='PROPERTY_NAME_REQUIRED';end if;
 if length(btrim(coalesce(p_reason,''))) not between 3 and 1000 then raise invalid_parameter_value using message='CHANGE_REASON_REQUIRED';end if;
 owners:=private.aqari_property_owners_normalize(coalesce(p_data->'owners','[]'::jsonb));if not private.aqari_property_owners_valid(owners) then raise invalid_parameter_value using message='PROPERTY_OWNERS_INVALID_OR_NOT_100_PERCENT';end if;
 begin income:=nullif(p_data->>'statedIncome','')::numeric;exception when others then raise invalid_parameter_value using message='PROPERTY_INCOME_INVALID';end;
 if income is not null and (income<0 or round(income,3)<>income) then raise invalid_parameter_value using message='PROPERTY_INCOME_INVALID';end if;
 if length(coalesce(p_data->>'address',''))>1000 or length(coalesce(p_data->>'type',''))>120 or length(coalesce(p_data->>'status','')) not between 1 and 80 or length(coalesce(p_data->>'email',''))>320 or length(coalesce(p_data->>'phone',''))>40 or length(coalesce(p_data->>'whatsapp',''))>40 then raise invalid_parameter_value using message='PROPERTY_MASTER_FIELD_INVALID';end if;
 if coalesce(p_data->>'email','')<>'' and coalesce(p_data->>'email','') !~ '^[^[:space:]@]+@[^[:space:]@]+[.][^[:space:]@]+$' then raise invalid_parameter_value using message='PROPERTY_EMAIL_INVALID';end if;
 if jsonb_typeof(coalesce(p_data->'assets','{}'::jsonb))<>'object' or octet_length(coalesce(p_data->'assets','{}'::jsonb)::text)>200000 then raise invalid_parameter_value using message='PROPERTY_ASSETS_INVALID';end if;
 perform 1 from public.aqari_properties where workspace_id=p_workspace_id and id=p_property_id for update;if not found then raise no_data_found using message='PROPERTY_NOT_FOUND';end if;
 old_snapshot:=private.aqari_property_master_snapshot(p_workspace_id,p_property_id);
 select * into old_row from private.aqari_property_master where workspace_id=p_workspace_id and property_id=p_property_id for update;
 rev:=coalesce(old_row.revision,0);if p_expected_revision is distinct from rev then raise exception 'PROPERTY_MASTER_REVISION_CONFLICT' using errcode='40001';end if;
 location_value:=case when p_data?'locationUrl' then btrim(coalesce(p_data->>'locationUrl','')) else coalesce(old_row.location_url,'') end;
 automatic_value:=case when p_data?'propertyAutomaticRef' then btrim(coalesce(p_data->>'propertyAutomaticRef','')) else coalesce(old_row.property_automatic_ref,'') end;
 if length(location_value)>2000 or length(automatic_value)>200 then raise invalid_parameter_value using message='PROPERTY_EXTENDED_FIELD_INVALID';end if;
 if location_value<>'' and location_value !~ '^https://[^[:space:]@/?#]+([/?#][^[:space:]]*)?$' then raise invalid_parameter_value using message='PROPERTY_LOCATION_URL_INVALID';end if;
 select coalesce(nullif(display_name,''),auth.uid()::text) into actor from public.aqari_profiles where user_id=auth.uid();actor:=coalesce(actor,auth.uid()::text);
 update public.aqari_properties set name=nm where workspace_id=p_workspace_id and id=p_property_id;
 insert into private.aqari_property_master(workspace_id,property_id,address,property_type,status,stated_income,owners,contact_email,contact_phone,contact_whatsapp,assets,location_url,property_automatic_ref,revision,updated_by,updated_at)
 values(p_workspace_id,p_property_id,btrim(coalesce(p_data->>'address','')),btrim(coalesce(p_data->>'type','')),btrim(coalesce(p_data->>'status','active')),income,owners,lower(btrim(coalesce(p_data->>'email',''))),btrim(coalesce(p_data->>'phone','')),btrim(coalesce(p_data->>'whatsapp','')),coalesce(p_data->'assets','{}'::jsonb),location_value,automatic_value,rev+1,auth.uid(),now())
 on conflict(workspace_id,property_id) do update set address=excluded.address,property_type=excluded.property_type,status=excluded.status,stated_income=excluded.stated_income,owners=excluded.owners,contact_email=excluded.contact_email,contact_phone=excluded.contact_phone,contact_whatsapp=excluded.contact_whatsapp,assets=excluded.assets,location_url=excluded.location_url,property_automatic_ref=excluded.property_automatic_ref,revision=excluded.revision,updated_by=excluded.updated_by,updated_at=excluded.updated_at
 returning * into new_row;
 new_snapshot:=private.aqari_property_master_snapshot(p_workspace_id,p_property_id);
 insert into private.aqari_property_master_audit(workspace_id,property_id,entity_type,action,reason,actor_id,actor_name,before_value,after_value)
 values(p_workspace_id,p_property_id,'property','save_master',btrim(p_reason),auth.uid(),actor,old_snapshot,new_snapshot);
 return jsonb_build_object('workspace_id',p_workspace_id,'user_id',auth.uid(),'property',new_snapshot);
end $function$

CREATE OR REPLACE FUNCTION public.aqari_property_notices(p_workspace_id uuid, p_action text, p_data jsonb DEFAULT '{}'::jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare n private.aqari_property_notices%rowtype; previous jsonb; result jsonb; notice_id uuid;
 expected integer; who text; recipient public.aqari_portal_accounts%rowtype; at_time timestamptz;
 expiration timestamptz; allowed_keys text[]; why text:='';prop uuid;
begin
 if auth.uid() is null or p_workspace_id is null then raise insufficient_privilege using message='ACCESS_DENIED';end if;
 if p_action is null or p_action not in ('list','save','publish','archive','history','feed','ack') then raise exception 'عملية التعاميم غير صالحة.';end if;
 if p_data is null or jsonb_typeof(p_data)<>'object' then raise exception 'بيانات التعميم غير صالحة.';end if;
 allowed_keys:=case when p_action='save' then array['id','revision','property_id','kind','title','body','expires_at']
  when p_action='archive' then array['id','revision','reason'] when p_action in ('publish','ack') then array['id','revision']
  when p_action='history' then array['id'] else array[]::text[] end;
 if exists(select 1 from jsonb_object_keys(p_data) k where not k=any(allowed_keys)) then raise exception 'حقول التعميم غير مسموحة.';end if;

 if p_action in ('feed','ack') then
  select * into recipient from public.aqari_portal_accounts a where a.user_id=auth.uid() and a.workspace_id=p_workspace_id and a.is_active;
  if not found or not private.aqari_owns_tenant(p_workspace_id,recipient.tenant_id) then raise insufficient_privilege using message='ACCESS_DENIED';end if;
  if p_action='feed' then
   return coalesce((select jsonb_agg(q.item order by q.published_at desc,q.id) from (
    select x.id,x.published_at,jsonb_build_object('id',x.id,'property_id',x.property_id,'property_name',p.name,
     'kind',x.kind,'title',x.title,'body',x.body,'status',x.status,'revision',x.revision,
     'published_at',x.published_at,'expires_at',x.expires_at,'acknowledged_at',a.acknowledged_at) item
    from private.aqari_property_notices x join public.aqari_properties p on p.workspace_id=x.workspace_id and p.id=x.property_id
    left join private.aqari_property_notice_acknowledgements a on a.notice_id=x.id and a.notice_revision=x.revision and a.user_id=auth.uid()
    where x.workspace_id=p_workspace_id and x.status='published' and x.published_at<=now()
     and (x.expires_at is null or x.expires_at>now()) and private.aqari_can_read_property_notice(x.workspace_id,x.property_id)
    order by x.published_at desc,x.id limit 50
   ) q),'[]');
  end if;
  notice_id:=nullif(p_data->>'id','')::uuid;expected:=nullif(p_data->>'revision','')::integer;
  select * into n from private.aqari_property_notices x where x.workspace_id=p_workspace_id and x.id=notice_id for share;
  if not found or n.status<>'published' or n.published_at>now() or (n.expires_at is not null and n.expires_at<=now())
    or not private.aqari_can_read_property_notice(n.workspace_id,n.property_id) then raise insufficient_privilege using message='ACCESS_DENIED';end if;
  if expected is distinct from n.revision then raise serialization_failure using message='REVISION_CONFLICT';end if;
  select full_name into who from public.aqari_tenants where id=recipient.tenant_id and workspace_id=p_workspace_id;
  insert into private.aqari_property_notice_acknowledgements(notice_id,notice_revision,user_id,tenant_id,user_name)
   values(n.id,n.revision,auth.uid(),recipient.tenant_id,who) on conflict on constraint aqari_property_notice_acknowledgements_pkey do nothing;
  select acknowledged_at into at_time from private.aqari_property_notice_acknowledgements a where a.notice_id=n.id and a.notice_revision=n.revision and a.user_id=auth.uid();
  return jsonb_build_object('acknowledged_at',at_time);
 end if;

 if not private.aqari_manager(p_workspace_id) or not private.aqari_can(p_workspace_id,'notifications',case when p_action in ('list','history') then 'read' else 'write' end)
 then raise insufficient_privilege using message='ACCESS_DENIED';end if;
 if p_action='list' then
  return jsonb_build_object('manager',true,
   'properties',(select coalesce(jsonb_agg(jsonb_build_object('id',p.id,'name',p.name) order by p.name),'[]') from public.aqari_properties p where p.workspace_id=p_workspace_id),
   'notices',(select coalesce(jsonb_agg(q.item order by q.updated_at desc,q.id),'[]') from (
    select x.id,x.updated_at,to_jsonb(x)||jsonb_build_object('ack_count',(select count(*) from private.aqari_property_notice_acknowledgements a where a.notice_id=x.id)) item
    from private.aqari_property_notices x where x.workspace_id=p_workspace_id order by x.updated_at desc,x.id limit 100
   ) q));
 end if;
 notice_id:=nullif(p_data->>'id','')::uuid;
 if notice_id is null then raise exception 'رقم التعميم مطلوب.';end if;
 select * into n from private.aqari_property_notices x where x.workspace_id=p_workspace_id and x.id=notice_id for update;
 if p_action='history' then
  if n.id is null then raise exception 'التعميم غير موجود.';end if;
  return jsonb_build_object('versions',(select coalesce(jsonb_agg(to_jsonb(v) order by v.revision desc),'[]') from private.aqari_property_notice_versions v where v.notice_id=n.id),
   'acknowledgements',(select coalesce(jsonb_agg(jsonb_build_object('notice_revision',a.notice_revision,'user_name',a.user_name,'acknowledged_at',a.acknowledged_at) order by a.acknowledged_at desc),'[]') from private.aqari_property_notice_acknowledgements a where a.notice_id=n.id));
 end if;
 expected:=nullif(p_data->>'revision','')::integer;
 if expected is distinct from coalesce(n.revision,0) then raise serialization_failure using message='REVISION_CONFLICT';end if;
 previous:=case when n.id is null then null else to_jsonb(n) end;
 select display_name into who from public.aqari_profiles where user_id=auth.uid();who:=coalesce(nullif(who,''),auth.uid()::text);
 if p_action='save' then
  if n.id is not null and n.status<>'draft' then raise exception 'لا يمكن تعديل النسخة المنشورة؛ أنشئ مسودة جديدة واحفظ الأصل.';end if;
  if jsonb_typeof(p_data->'title') is distinct from 'string' or jsonb_typeof(p_data->'body') is distinct from 'string'
    or length(btrim(p_data->>'title')) not between 1 and 200 or length(btrim(p_data->>'body')) not between 1 and 10000
    or coalesce(p_data->>'kind','') not in ('notice','guidance','circular') then raise exception 'أكمل عنوان التعميم ونصه ونوعه.';end if;
  prop:=nullif(p_data->>'property_id','')::uuid;
  if not exists(select 1 from public.aqari_properties where id=prop and workspace_id=p_workspace_id) then raise insufficient_privilege using message='ACCESS_DENIED';end if;
  expiration:=nullif(p_data->>'expires_at','')::timestamptz;
  if n.id is null then
   insert into private.aqari_property_notices(id,workspace_id,property_id,kind,title,body,expires_at,created_by)
   values(notice_id,p_workspace_id,prop,p_data->>'kind',btrim(p_data->>'title'),btrim(p_data->>'body'),expiration,auth.uid()) returning * into n;
  else
   update private.aqari_property_notices set property_id=prop,kind=p_data->>'kind',title=btrim(p_data->>'title'),body=btrim(p_data->>'body'),expires_at=expiration,revision=revision+1,updated_at=now() where id=n.id returning * into n;
  end if;
 elsif p_action='publish' then
  if n.id is null or n.status<>'draft' then raise exception 'النشر متاح للمسودة المحفوظة فقط.';end if;
  if n.expires_at is not null and n.expires_at<=now() then raise exception 'راجع موعد انتهاء عرض التعميم قبل نشره.';end if;
  update private.aqari_property_notices set status='published',published_at=now(),revision=revision+1,updated_at=now() where id=n.id returning * into n;
 else
  if n.id is null or n.status='archived' then raise exception 'التعميم غير موجود أو مؤرشف.';end if;
  why:=btrim(coalesce(p_data->>'reason',''));
  if length(why) not between 3 and 500 then raise exception 'سبب الأرشفة مطلوب لحفظ السجل.';end if;
  update private.aqari_property_notices set status='archived',revision=revision+1,updated_at=now() where id=n.id returning * into n;
 end if;
 insert into private.aqari_property_notice_versions(notice_id,revision,action,actor_id,actor_name,reason,before_snapshot,after_snapshot)
 values(n.id,n.revision,p_action,auth.uid(),who,why,previous,to_jsonb(n));
 return to_jsonb(n);
end $function$

CREATE OR REPLACE FUNCTION public.aqari_property_owner_statement(p_workspace_id uuid, p_property_id uuid, p_as_of date DEFAULT ((now() AT TIME ZONE 'Asia/Kuwait'::text))::date)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare p jsonb;owners jsonb;f jsonb;result jsonb;
begin
 if not private.aqari_can_property(p_workspace_id,p_property_id,'properties','read') or not private.aqari_can(p_workspace_id,'finance','read') then raise insufficient_privilege using message='ACCESS_DENIED';end if;
 p:=private.aqari_property_master_snapshot(p_workspace_id,p_property_id);if p is null then raise no_data_found using message='PROPERTY_NOT_FOUND';end if;owners:=coalesce(p->'owners','[]'::jsonb);if jsonb_array_length(owners)>0 then perform private.aqari_validate_partner_owners(owners);end if;f:=public.aqari_property_financial_summary(p_workspace_id,p_property_id,p_as_of);
 select coalesce(jsonb_agg(jsonb_build_object('id',o->>'id','name',o->>'name','role',o->>'role','bps',(o->>'bps')::int,
  'month',jsonb_build_object('incomeFils',private.aqari_owner_share_fils((f#>>'{month,income}')::numeric,owners,o->>'id')::text,'expenseFils',private.aqari_owner_share_fils((f#>>'{month,expenses}')::numeric,owners,o->>'id')::text,'netFils',private.aqari_owner_share_fils((f#>>'{month,net}')::numeric,owners,o->>'id')::text),
  'year',jsonb_build_object('incomeFils',private.aqari_owner_share_fils((f#>>'{year,income}')::numeric,owners,o->>'id')::text,'expenseFils',private.aqari_owner_share_fils((f#>>'{year,expenses}')::numeric,owners,o->>'id')::text,'netFils',private.aqari_owner_share_fils((f#>>'{year,net}')::numeric,owners,o->>'id')::text)) order by o->>'name'),'[]'::jsonb) into result from jsonb_array_elements(owners)o;
 return jsonb_build_object('workspace_id',p_workspace_id,'property_id',p_property_id,'asOf',p_as_of,'owners',result,'totals',f,'distributionStatus','calculated_only','autoPayment',false,'note','الحصص محسوبة للعرض فقط. اعتماد وصرف الأرباح عملية منفصلة ولا ينشأ عنها تحويل مالي تلقائي.');
end $function$

CREATE OR REPLACE FUNCTION public.aqari_property_public_technicians(p_workspace_id uuid, p_property_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare allowed boolean:=false;
begin
 if auth.uid() is null then raise insufficient_privilege using message='ACCESS_DENIED';end if;
 allowed:=private.aqari_can_property(p_workspace_id,p_property_id,'maintenance','read');
 if not allowed then
  allowed:=exists(select 1 from public.aqari_portal_accounts a join public.aqari_leases l on l.workspace_id=a.workspace_id and l.tenant_id=a.tenant_id join public.aqari_units u on u.workspace_id=l.workspace_id and u.id=l.unit_id where a.user_id=auth.uid() and a.workspace_id=p_workspace_id and a.is_active and l.status not in('cancelled','expired') and u.property_id=p_property_id);
 end if;
 if not allowed then raise insufficient_privilege using message='ACCESS_DENIED';end if;
 return jsonb_build_object('workspace_id',p_workspace_id,'property_id',p_property_id,'items',coalesce((select jsonb_agg(jsonb_build_object('employeeId',t.employee_id,'nameAr',coalesce(e.profile->>'name_ar',''),'nameEn',coalesce(e.profile->>'name_en',''),'jobAr',coalesce(e.profile->>'job_ar',''),'phone',t.phone,'whatsapp',t.whatsapp) order by coalesce(e.profile->>'name_ar',e.profile->>'name_en',e.id::text)) from private.aqari_property_technicians t join private.aqari_hr_employees e on e.id=t.employee_id and e.workspace_id=t.workspace_id where t.workspace_id=p_workspace_id and t.property_id=p_property_id and t.is_active and t.public_to_tenant and e.status<>'inactive'),'[]'::jsonb));
end $function$

CREATE OR REPLACE FUNCTION public.aqari_property_responsible(p_workspace_id uuid, p_property_id uuid, p_action text DEFAULT 'context'::text, p_data jsonb DEFAULT '{}'::jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare current_row private.aqari_property_responsibles%rowtype;before_json jsonb;after_json jsonb;expected bigint;why text;nm text;ttl text;
begin
 if not private.aqari_can_property(p_workspace_id,p_property_id,'properties',case when p_action='save' then 'write' else 'read' end) then raise insufficient_privilege using message='ACCESS_DENIED';end if;
 if p_action='context' then return jsonb_build_object('workspace_id',p_workspace_id,'user_id',auth.uid(),'record',private.aqari_property_responsible_json(p_workspace_id,p_property_id));end if;
 if p_action<>'save' or jsonb_typeof(p_data) is distinct from 'object' or exists(select 1 from jsonb_object_keys(p_data) k where k not in('name','title','revision','reason')) then raise invalid_parameter_value using message='PROPERTY_RESPONSIBLE_INVALID';end if;
 nm:=btrim(coalesce(p_data->>'name',''));ttl:=btrim(coalesce(p_data->>'title',''));why:=btrim(coalesce(p_data->>'reason',''));expected:=coalesce((p_data->>'revision')::bigint,0);
 if length(nm)>200 or length(ttl)>120 or length(why) not between 3 and 1000 then raise invalid_parameter_value using message='PROPERTY_RESPONSIBLE_INVALID';end if;
 perform 1 from public.aqari_properties where workspace_id=p_workspace_id and id=p_property_id for update;if not found then raise no_data_found using message='PROPERTY_NOT_FOUND';end if;
 before_json:=private.aqari_property_responsible_json(p_workspace_id,p_property_id);
 select * into current_row from private.aqari_property_responsibles where workspace_id=p_workspace_id and property_id=p_property_id for update;
 if coalesce(current_row.revision,0)<>expected then raise serialization_failure using message='PROPERTY_RESPONSIBLE_REVISION_CONFLICT';end if;
 insert into private.aqari_property_responsibles(workspace_id,property_id,responsible_name,responsible_title,revision,updated_by,updated_at)
 values(p_workspace_id,p_property_id,nm,ttl,expected+1,auth.uid(),now())
 on conflict(workspace_id,property_id) do update set responsible_name=excluded.responsible_name,responsible_title=excluded.responsible_title,revision=excluded.revision,updated_by=excluded.updated_by,updated_at=excluded.updated_at;
 after_json:=private.aqari_property_responsible_json(p_workspace_id,p_property_id);
 insert into private.aqari_portfolio_addition_audit(workspace_id,property_id,entity_type,reason,actor_id,before_value,after_value) values(p_workspace_id,p_property_id,'property_responsible',why,auth.uid(),before_json,after_json);
 return jsonb_build_object('workspace_id',p_workspace_id,'user_id',auth.uid(),'record',after_json);
end $function$

CREATE OR REPLACE FUNCTION public.aqari_property_tenant_custom_fields(p_workspace_id uuid, p_property_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare allowed boolean:=false;
begin
 if auth.uid() is null then raise insufficient_privilege using message='ACCESS_DENIED';end if;
 allowed:=exists(select 1 from public.aqari_portal_accounts a join public.aqari_leases l on l.workspace_id=a.workspace_id and l.tenant_id=a.tenant_id join public.aqari_units u on u.workspace_id=l.workspace_id and u.id=l.unit_id where a.user_id=auth.uid() and a.workspace_id=p_workspace_id and a.is_active and l.status not in('cancelled','expired') and u.property_id=p_property_id);
 if not allowed then raise insufficient_privilege using message='ACCESS_DENIED';end if;
 return jsonb_build_object('workspace_id',p_workspace_id,'property_id',p_property_id,'user_id',auth.uid(),'items',coalesce((select jsonb_agg(jsonb_build_object('key',f.field_key,'labelAr',f.label_ar,'labelEn',f.label_en,'type',f.field_type,'value',v.value) order by f.label_ar,f.id) from private.aqari_property_custom_fields f left join private.aqari_property_custom_values v on v.workspace_id=f.workspace_id and v.property_id=p_property_id and v.field_id=f.id where f.workspace_id=p_workspace_id and f.is_active and p_property_id=any(f.property_ids) and f.visibility in('tenant','owner_tenant') and v.value is not null),'[]'::jsonb));
end $function$

CREATE OR REPLACE FUNCTION public.aqari_read_state_v267(p_workspace_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare saved public.aqari_app_state%rowtype;d jsonb;filtered jsonb:='{}';k text;rows jsonb;
begin
 if private.aqari_manager(p_workspace_id) then return private.aqari_read_state_v267_unscoped(p_workspace_id);end if;
 if auth.uid() is null or not private.aqari_can(p_workspace_id,'home','read') then raise insufficient_privilege using message='ACCESS_DENIED';end if;
 select * into saved from public.aqari_app_state where workspace_id=p_workspace_id;if not found then return null;end if;d:=private.aqari_unwrap(saved.payload);
 for k in select jsonb_object_keys(d) loop
  if not private.aqari_staff_state_key(k) or not private.aqari_can(p_workspace_id,private.aqari_state_section(k),'read') or jsonb_typeof(d->k)<>'array' then continue;end if;
  select coalesce(jsonb_agg(v order by n),'[]') into rows from jsonb_array_elements(d->k) with ordinality q(v,n) where private.aqari_staff_row_allowed(p_workspace_id,k,v,'read');
  filtered:=jsonb_set(filtered,array[k],rows,true);
 end loop;
 return jsonb_build_object('workspace_id',saved.workspace_id,'payload',filtered,'revision',saved.revision,'updated_by',saved.updated_by,'updated_at',saved.updated_at);
end $function$

CREATE OR REPLACE FUNCTION public.aqari_rent_due_schedule(p_workspace_id uuid, p_lease_id uuid DEFAULT NULL::uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare w uuid:=p_workspace_id;
begin
  if auth.uid() is null then raise insufficient_privilege using message='ACCESS_DENIED'; end if;
  if p_lease_id is not null and not private.aqari_can_lease(w,p_lease_id,'collections','read') then raise insufficient_privilege using message='ACCESS_DENIED'; end if;
  if p_lease_id is null and not private.aqari_can(w,'collections','read') then raise insufficient_privilege using message='ACCESS_DENIED'; end if;
  return jsonb_build_object(
    'periods',coalesce((
      select jsonb_agg(jsonb_build_object(
        'lease_id',d.lease_id,'contract_no',l.contract_no,'period',d.period,
        'due_amount',d.due_amount,'paid_amount',d.paid_amount,'credit_amount',d.credit_amount,
        'balance',d.balance,'status',d.status,'source_hash',d.source_hash
      ) order by d.period,d.lease_id)
      from private.aqari_rent_due_periods d
      join public.aqari_leases l on l.workspace_id=d.workspace_id and l.id=d.lease_id
      where d.workspace_id=w and (p_lease_id is null or d.lease_id=p_lease_id)
        and private.aqari_can_lease(w,d.lease_id,'collections','read')
    ),'[]'::jsonb),
    'generated_from','signed lease terms + non-cancelled payments + allocated tenant credit'
  );
end $function$

CREATE OR REPLACE FUNCTION public.aqari_rent_receipt_pdf_auto_commit(p_workspace_id uuid, p_payment_id uuid, p_snapshot_sha256 text, p_pdf_base64 text, p_pdf_sha256 text, p_renderer_version text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare source jsonb;bytes bytea;existing private.aqari_rent_receipt_pdf_artifacts%rowtype;receipt_value text;
begin
 if current_setting('role',true) is distinct from 'service_role' then raise insufficient_privilege using message='SERVER_ONLY';end if;
 if p_snapshot_sha256!~'^[a-f0-9]{64}$' or p_pdf_sha256!~'^[a-f0-9]{64}$' or length(coalesce(p_pdf_base64,''))>2796204 or length(coalesce(p_renderer_version,'')) not between 1 and 100 then raise check_violation using message='INVALID_PDF_ARCHIVE';end if;
 perform 1 from public.aqari_rent_payments where workspace_id=p_workspace_id and id=p_payment_id for update;if not found then raise no_data_found using message='RECEIPT_NOT_FOUND';end if;
 source:=private.aqari_rent_receipt_pdf_system_source(p_workspace_id,p_payment_id);receipt_value:=source->>'receiptNo';
 if source->>'snapshotSha256'<>p_snapshot_sha256 then raise check_violation using message='RECEIPT_SOURCE_CHANGED';end if;
 bytes:=decode(p_pdf_base64,'base64');
 if octet_length(bytes) not between 8 and 2097152 or substring(bytes from 1 for 5)<>convert_to('%PDF-','UTF8') or encode(sha256(bytes),'hex')<>p_pdf_sha256 then raise check_violation using message='INVALID_PDF_ARCHIVE';end if;
 select * into existing from private.aqari_rent_receipt_pdf_artifacts a where a.workspace_id=p_workspace_id and a.receipt_no=receipt_value;
 if found then
  if existing.payment_id<>p_payment_id or existing.snapshot_sha256<>p_snapshot_sha256 or existing.pdf_sha256<>p_pdf_sha256 then raise unique_violation using message='PDF_ARCHIVE_CONFLICT';end if;
  return jsonb_build_object('archived',true,'replayed',true,'receiptNo',receipt_value,'pdfSha256',existing.pdf_sha256,'snapshotSha256',existing.snapshot_sha256);
 end if;
 insert into private.aqari_rent_receipt_pdf_artifacts(workspace_id,receipt_no,payment_id,snapshot_sha256,pdf_bytes,pdf_sha256,renderer_version,archived_by,archive_actor_kind)
 values(p_workspace_id,receipt_value,p_payment_id,p_snapshot_sha256,bytes,p_pdf_sha256,p_renderer_version,null,'system');
 insert into private.aqari_rent_receipt_pdf_automation_events(workspace_id,payment_id,receipt_no,snapshot_sha256,pdf_sha256,action)
 values(p_workspace_id,p_payment_id,receipt_value,p_snapshot_sha256,p_pdf_sha256,'system_auto_archive');
 return jsonb_build_object('archived',true,'replayed',false,'receiptNo',receipt_value,'pdfSha256',p_pdf_sha256,'snapshotSha256',p_snapshot_sha256);
end $function$

CREATE OR REPLACE FUNCTION public.aqari_rent_receipt_pdf_commit(p_workspace_id uuid, p_receipt_no text, p_actor_id uuid, p_pdf_base64 text, p_pdf_sha256 text, p_renderer_version text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
 old_sub text:=current_setting('request.jwt.claim.sub',true); old_claims text:=current_setting('request.jwt.claims',true);
 source jsonb; bytes bytea; existing private.aqari_rent_receipt_pdf_artifacts%rowtype; payment_uuid uuid;
begin
 if current_setting('role',true) is distinct from 'service_role' or p_actor_id is null then
  raise insufficient_privilege using message='TRUSTED_RENDERER_REQUIRED';
 end if;
 if p_pdf_base64 is null or length(p_pdf_base64)>2796204 or p_pdf_sha256 is null or p_pdf_sha256!~'^[a-f0-9]{64}$'
  or p_renderer_version is null or length(p_renderer_version) not between 1 and 100 then
  raise exception 'INVALID_PDF_ARCHIVE' using errcode='23514';
 end if;
 perform 1 from public.aqari_rent_payments where workspace_id=p_workspace_id and reference=p_receipt_no for update;
 if not found then raise exception 'RECEIPT_NOT_FOUND' using errcode='P0002';end if;
 perform set_config('request.jwt.claim.sub',p_actor_id::text,true);
 perform set_config('request.jwt.claims',jsonb_build_object('sub',p_actor_id,'role','authenticated')::text,true);
 source:=private.aqari_rent_receipt_pdf_source(p_workspace_id,p_receipt_no);
 perform set_config('request.jwt.claim.sub',coalesce(old_sub,''),true);
 perform set_config('request.jwt.claims',coalesce(old_claims,''),true);
 payment_uuid:=(source->>'payment_id')::uuid;
 bytes:=decode(p_pdf_base64,'base64');
 if octet_length(bytes) not between 8 and 2097152 or substring(bytes from 1 for 5)<>convert_to('%PDF-','UTF8')
  or encode(sha256(bytes),'hex')<>p_pdf_sha256 then raise exception 'INVALID_PDF_ARCHIVE' using errcode='23514';end if;
 select * into existing from private.aqari_rent_receipt_pdf_artifacts where workspace_id=p_workspace_id and receipt_no=p_receipt_no;
 if found then
  if existing.payment_id<>payment_uuid or existing.snapshot_sha256<>source->>'snapshot_sha256' or existing.pdf_sha256<>p_pdf_sha256 then
   raise exception 'PDF_ARCHIVE_CONFLICT' using errcode='23505';
  end if;
  return jsonb_build_object('archived',true,'replayed',true,'pdf_sha256',existing.pdf_sha256,'snapshot_sha256',existing.snapshot_sha256);
 end if;
 insert into private.aqari_rent_receipt_pdf_artifacts(workspace_id,receipt_no,payment_id,snapshot_sha256,pdf_bytes,pdf_sha256,renderer_version,archived_by)
 values(p_workspace_id,p_receipt_no,payment_uuid,source->>'snapshot_sha256',bytes,p_pdf_sha256,p_renderer_version,p_actor_id);
 insert into private.aqari_financial_audit(workspace_id,entity_id,action,actor_id,actor_name,reason,after_value)
 values(p_workspace_id,p_receipt_no,'rent_receipt_pdf_archived',p_actor_id,p_actor_id::text,'حفظ النسخة الأصلية من وصل الإيجار PDF',jsonb_build_object('receipt_no',p_receipt_no,'payment_id',payment_uuid,'snapshot_sha256',source->>'snapshot_sha256','pdf_sha256',p_pdf_sha256,'renderer',p_renderer_version));
 return jsonb_build_object('archived',true,'replayed',false,'pdf_sha256',p_pdf_sha256,'snapshot_sha256',source->>'snapshot_sha256');
end $function$

CREATE OR REPLACE FUNCTION public.aqari_rent_receipt_pdf_get(p_workspace_id uuid, p_receipt_no text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare source jsonb; artifact private.aqari_rent_receipt_pdf_artifacts%rowtype;
begin
 source:=private.aqari_rent_receipt_pdf_source(p_workspace_id,p_receipt_no);
 select * into artifact from private.aqari_rent_receipt_pdf_artifacts
 where workspace_id=p_workspace_id and receipt_no=p_receipt_no;
 if not found then return '{}'::jsonb;end if;
 if artifact.payment_id::text is distinct from source->>'payment_id' or artifact.snapshot_sha256 is distinct from source->>'snapshot_sha256' then
  raise exception 'RECEIPT_ARCHIVE_SOURCE_CHANGED' using errcode='23514';
 end if;
 return (to_jsonb(artifact)-'pdf_bytes')||jsonb_build_object(
  'pdf_base64',replace(encode(artifact.pdf_bytes,'base64'),E'\n',''),
  'payment_status',source->>'payment_status'
 );
end $function$

CREATE OR REPLACE FUNCTION public.aqari_rental_document_issue(p_workspace_id uuid, p_actor_id uuid, p_actor_claims jsonb, p_request_id uuid, p_template_id uuid, p_lease_id uuid, p_receipt_id uuid, p_source_sha256 text, p_snapshot jsonb, p_pdf_base64 text, p_pdf_sha256 text, p_renderer_version text, p_approved boolean, p_reason text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare oldsub text:=current_setting('request.jwt.claim.sub',true);oldclaims text:=current_setting('request.jwt.claims',true);
 src jsonb;bytes bytea;h text;actor text;a private.aqari_rental_document_archive;result jsonb;
begin
 if current_setting('role',true) is distinct from 'service_role' or p_actor_id is null then raise insufficient_privilege using message='TRUSTED_RENDERER_REQUIRED';end if;
 if p_request_id is null or p_approved is distinct from true or coalesce(length(btrim(p_reason)),0) not between 6 and 500 or jsonb_typeof(p_actor_claims) is distinct from 'object'
  or jsonb_typeof(p_snapshot) is distinct from 'object' or octet_length(p_snapshot::text)>500000 or coalesce(p_source_sha256,'')!~'^[a-f0-9]{64}$'
  or p_pdf_base64 is null or length(p_pdf_base64)>2796204 or coalesce(p_pdf_sha256,'')!~'^[a-f0-9]{64}$' or coalesce(length(p_renderer_version),0) not between 1 and 100 then raise invalid_parameter_value using message='INVALID_DOCUMENT_ISSUE';end if;
 perform set_config('request.jwt.claim.sub',p_actor_id::text,true);
 perform set_config('request.jwt.claims',(p_actor_claims||jsonb_build_object('sub',p_actor_id,'role','authenticated'))::text,true);
 if not private.aqari_manager(p_workspace_id) or not private.aqari_can(p_workspace_id,'administration','write') or not private.aqari_can(p_workspace_id,'contracts','write') then raise insufficient_privilege using message='OWNER_APPROVAL_REQUIRED';end if;
 perform private.aqari_require_sensitive_aal2(p_workspace_id);
 -- Common state lock serializes with current contract/template mutations. Master
 -- rows are locked too so issuance cannot straddle an owner/unit edit.
 perform 1 from public.aqari_app_state where workspace_id=p_workspace_id for update;
 lock table private.aqari_property_template_scopes in share mode;
 perform 1 from public.aqari_leases where workspace_id=p_workspace_id and id=p_lease_id for share;
 perform 1 from public.aqari_units where workspace_id=p_workspace_id and id=(select unit_id from public.aqari_leases where workspace_id=p_workspace_id and id=p_lease_id) for share;
 perform 1 from public.aqari_properties where workspace_id=p_workspace_id and id=(select u.property_id from public.aqari_units u join public.aqari_leases l on l.unit_id=u.id and l.workspace_id=u.workspace_id where l.workspace_id=p_workspace_id and l.id=p_lease_id) for share;
 perform 1 from private.aqari_property_master where workspace_id=p_workspace_id and property_id=(select u.property_id from public.aqari_units u join public.aqari_leases l on l.unit_id=u.id and l.workspace_id=u.workspace_id where l.workspace_id=p_workspace_id and l.id=p_lease_id) for share;
 perform 1 from private.aqari_unit_master where workspace_id=p_workspace_id and unit_id=(select unit_id from public.aqari_leases where workspace_id=p_workspace_id and id=p_lease_id) for share;
 perform 1 from public.aqari_tenants where workspace_id=p_workspace_id and id=(select tenant_id from public.aqari_leases where workspace_id=p_workspace_id and id=p_lease_id) for share;
 if p_receipt_id is not null then perform 1 from public.aqari_rent_payments where workspace_id=p_workspace_id and id=p_receipt_id for share;end if;
 bytes:=decode(p_pdf_base64,'base64');h:=encode(sha256(convert_to(p_snapshot::text,'UTF8')),'hex');
 if octet_length(bytes) not between 8 and 2097152 or substring(bytes from 1 for 5)<>convert_to('%PDF-','UTF8') or encode(sha256(bytes),'hex')<>p_pdf_sha256 then raise check_violation using message='INVALID_PDF_ARCHIVE';end if;
 select * into a from private.aqari_rental_document_archive where id=p_request_id;
 if found then
  if a.workspace_id<>p_workspace_id or a.issued_by<>p_actor_id or a.template_id<>p_template_id or a.lease_id<>p_lease_id or a.receipt_id is distinct from p_receipt_id or a.source_sha256<>p_source_sha256 or a.snapshot_sha256<>h or a.pdf_sha256<>p_pdf_sha256 or a.renderer_version<>p_renderer_version or a.reason<>btrim(p_reason) then raise unique_violation using message='DOCUMENT_REQUEST_REUSED';end if;
  if not private.aqari_can_property(p_workspace_id,a.property_id,'properties','read') or not private.aqari_can_lease(p_workspace_id,a.lease_id,'contracts','read') then raise insufficient_privilege using message='ACCESS_DENIED';end if;
  result:=jsonb_build_object('workspace_id',p_workspace_id,'user_id',p_actor_id,'archived',true,'replayed',true,'record',to_jsonb(a)-'pdf_bytes'-'snapshot');
 else
  src:=private.aqari_rental_document_source(p_workspace_id,p_template_id,p_lease_id,p_receipt_id);
  if src->>'source_sha256'<>p_source_sha256 or p_snapshot->'source' is distinct from src->'source' then raise serialization_failure using message='DOCUMENT_SOURCE_CHANGED_REVIEW_AGAIN';end if;
  select display_name into actor from public.aqari_profiles where user_id=p_actor_id;
  insert into private.aqari_rental_document_archive(id,workspace_id,template_id,template_family_id,template_version,kind,title,property_id,unit_id,tenant_id,lease_id,receipt_id,source_sha256,snapshot,snapshot_sha256,pdf_bytes,pdf_sha256,renderer_version,issued_by,issued_by_name,reason)
  values(p_request_id,p_workspace_id,p_template_id,nullif(src#>>'{source,template,family_id}','')::uuid,(src#>>'{source,template,version}')::int,src#>>'{source,template,kind}',src#>>'{source,template,title}',(src#>>'{source,property,id}')::uuid,(src#>>'{source,unit,id}')::uuid,(src#>>'{source,tenant,id}')::uuid,p_lease_id,p_receipt_id,p_source_sha256,p_snapshot,h,bytes,p_pdf_sha256,p_renderer_version,p_actor_id,coalesce(actor,p_actor_id::text),btrim(p_reason)) returning * into a;
  result:=jsonb_build_object('workspace_id',p_workspace_id,'user_id',p_actor_id,'archived',true,'replayed',false,'record',to_jsonb(a)-'pdf_bytes'-'snapshot');
 end if;
 perform set_config('request.jwt.claim.sub',coalesce(oldsub,''),true);perform set_config('request.jwt.claims',coalesce(oldclaims,''),true);
 return result;
end $function$

CREATE OR REPLACE FUNCTION public.aqari_report_filters(p_workspace_id uuid, p_report_key text, p_action text, p_filters jsonb DEFAULT '{}'::jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare payload jsonb;property uuid;
begin
 if auth.uid() is null or not exists(select 1 from public.aqari_memberships m where m.workspace_id=p_workspace_id and m.user_id=auth.uid() and m.is_active) then raise insufficient_privilege using message='ACCESS_DENIED';end if;
 if p_report_key is null or p_report_key not in ('property_statements','owner_report','hr_monthly','hr_annual') then raise exception 'INVALID_REPORT_FILTERS';end if;
 if p_action='get' then
  return coalesce((select filters from public.aqari_saved_report_filters where workspace_id=p_workspace_id and user_id=auth.uid() and report_key=p_report_key),'{}'::jsonb);
 elsif p_action='clear' then
  delete from public.aqari_saved_report_filters where workspace_id=p_workspace_id and user_id=auth.uid() and report_key=p_report_key;return '{}'::jsonb;
 elsif p_action is distinct from 'save' then raise exception 'INVALID_REPORT_FILTERS';end if;
 if p_filters is null or jsonb_typeof(p_filters)<>'object' or octet_length(p_filters::text)>1024 then raise exception 'INVALID_REPORT_FILTERS';end if;
 if p_report_key='owner_report' then
  if p_filters-array['from','to']<>'{}'::jsonb or jsonb_typeof(p_filters->'from') is distinct from 'string' or jsonb_typeof(p_filters->'to') is distinct from 'string'
   or p_filters->>'from' !~ '^[0-9]{4}-[0-9]{2}-[0-9]{2}$' or p_filters->>'to' !~ '^[0-9]{4}-[0-9]{2}-[0-9]{2}$' then raise exception 'INVALID_REPORT_FILTERS';end if;
  begin
   if (p_filters->>'from')::date>(p_filters->>'to')::date then raise exception 'INVALID_REPORT_FILTERS';end if;
  exception when invalid_datetime_format or datetime_field_overflow then raise exception 'INVALID_REPORT_FILTERS';end;
 else
  if jsonb_typeof(p_filters->'property_id') is distinct from 'string' then raise exception 'INVALID_REPORT_FILTERS';end if;
  if p_report_key='hr_annual' then
   if p_filters-array['property_id','year']<>'{}'::jsonb or jsonb_typeof(p_filters->'year') is distinct from 'string' or p_filters->>'year' !~ '^[1-9][0-9]{3}$' then raise exception 'INVALID_REPORT_FILTERS';end if;
  else
   if p_filters-array['property_id','month']<>'{}'::jsonb or jsonb_typeof(p_filters->'month') is distinct from 'string' or p_filters->>'month' !~ '^[1-9][0-9]{3}-(0[1-9]|1[0-2])$' then raise exception 'INVALID_REPORT_FILTERS';end if;
  end if;
  if p_filters->>'property_id'='' and p_report_key<>'hr_annual' then raise exception 'INVALID_REPORT_FILTERS';end if;
  begin property:=nullif(p_filters->>'property_id','')::uuid;exception when invalid_text_representation then raise exception 'INVALID_REPORT_FILTERS';end;
  if property is not null and not exists(select 1 from public.aqari_properties q where q.id=property and q.workspace_id=p_workspace_id) then raise exception 'INVALID_REPORT_FILTERS';end if;
 end if;
 insert into public.aqari_saved_report_filters(workspace_id,user_id,report_key,filters)
 values(p_workspace_id,auth.uid(),p_report_key,p_filters)
 on conflict(workspace_id,user_id,report_key) do update set filters=excluded.filters,updated_at=now()
 returning filters into payload;
 return payload;
end $function$

CREATE OR REPLACE FUNCTION public.aqari_reserve_document(p_workspace_id uuid, p_document_type text, p_entity_type text, p_entity_ref text, p_title text, p_original_filename text, p_mime_type text DEFAULT NULL::text, p_metadata jsonb DEFAULT '{}'::jsonb)
 RETURNS TABLE(document_id uuid, document_no text, storage_bucket text, storage_path text)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare new_id uuid:=gen_random_uuid();new_no text;new_path text;ext text;entity text:=p_entity_type;category text:=nullif(btrim(p_metadata->>'document_category'),'');
begin
 if not private.aqari_can(p_workspace_id,'documents','write') then raise exception 'ACCESS_DENIED' using errcode='42501';end if;
 if entity='other' and p_document_type='tenant_attachment' then entity:='tenant';end if;
 if not private.aqari_document_entity(p_workspace_id,entity,p_entity_ref,'write') then raise exception 'DOCUMENT_ENTITY_NOT_FOUND' using errcode='42501';end if;
 if p_mime_type is null or p_mime_type not in ('application/pdf','image/jpeg','image/png','image/webp','image/heic','image/heif','application/vnd.openxmlformats-officedocument.wordprocessingml.document')
  or p_title is null or length(btrim(p_title)) not between 1 and 180 or p_original_filename is null or length(p_original_filename) not between 1 and 250
  or p_document_type not in ('tenant_attachment','signed_contract','property_document','mobile_scan')
  or (p_document_type='tenant_attachment' and entity<>'tenant') or (p_document_type='signed_contract' and entity<>'lease')
  or p_metadata is null or jsonb_typeof(p_metadata)<>'object' or octet_length(p_metadata::text)>4096
  or (category is not null and not private.aqari_document_category_allowed(entity,category))
  or (p_document_type='signed_contract' and category is not null and category<>'lease_contract')
 then raise exception 'INVALID_DOCUMENT';end if;
 ext:=case p_mime_type when 'application/pdf' then 'pdf' when 'image/jpeg' then 'jpg' when 'image/png' then 'png' when 'image/webp' then 'webp' when 'image/heic' then 'heic' when 'image/heif' then 'heif' else 'docx' end;
 new_no:='DOC-'||new_id::text;new_path:=p_workspace_id::text||'/'||new_id::text||'.'||ext;
 insert into public.aqari_documents(id,workspace_id,document_no,document_type,entity_type,entity_ref,title,original_filename,mime_type,metadata,storage_path,created_by)
 values(new_id,p_workspace_id,new_no,p_document_type,entity,p_entity_ref,btrim(p_title),p_original_filename,p_mime_type,p_metadata,new_path,auth.uid());
 return query select new_id,new_no,'aqari-documents'::text,new_path;
end $function$

CREATE OR REPLACE FUNCTION public.aqari_save_controls(p_workspace_id uuid, p_settings jsonb, p_expected_revision bigint, p_reason text)
 RETURNS bigint
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare old_row public.aqari_workspace_controls%rowtype;item record;subject record;section record;action record;lang record;label record;new_rev bigint;
begin
 if not private.aqari_manager(p_workspace_id) then raise exception 'ACCESS_DENIED' using errcode='42501';end if;
 if p_reason is null or length(btrim(p_reason)) not between 3 and 500 or p_settings is null or jsonb_typeof(p_settings)<>'object' or octet_length(p_settings::text)>65536 then raise exception 'INVALID_CONTROLS';end if;
 if not(p_settings ?& array['sections','permissions','labels']) then raise exception 'INVALID_CONTROLS';end if;
 for item in select * from jsonb_each(p_settings) loop if item.key not in ('sections','permissions','labels') or jsonb_typeof(item.value)<>'object' then raise exception 'INVALID_CONTROLS';end if;end loop;
 for item in select * from jsonb_each(p_settings->'sections') loop
  if not(item.key=any(private.aqari_section_keys())) or jsonb_typeof(item.value)<>'boolean' then raise exception 'INVALID_SECTION';end if;
 end loop;
 for subject in select * from jsonb_each(p_settings->'permissions') loop
  if subject.key not in ('role:property_manager','role:accountant','role:viewer') and not exists(select 1 from public.aqari_memberships where workspace_id=p_workspace_id and 'user:'||user_id::text=subject.key and role<>'general_manager' and is_active) then raise exception 'INVALID_SUBJECT';end if;
  if jsonb_typeof(subject.value)<>'object' then raise exception 'INVALID_PERMISSIONS';end if;
  for section in select * from jsonb_each(subject.value) loop
   if not(section.key=any(private.aqari_section_keys())) or jsonb_typeof(section.value)<>'object' then raise exception 'INVALID_PERMISSIONS';end if;
   for action in select * from jsonb_each(section.value) loop
    if action.key not in ('read','write') or jsonb_typeof(action.value)<>'boolean' then raise exception 'INVALID_PERMISSIONS';end if;
   end loop;
   if section.value->>'write'='true' and section.value->>'read'='false' then raise exception 'WRITE_REQUIRES_READ';end if;
  end loop;
 end loop;
 for lang in select * from jsonb_each(p_settings->'labels') loop
  if lang.key not in ('ar','en','hi','ur','ml') or jsonb_typeof(lang.value)<>'object' then raise exception 'INVALID_LANGUAGE';end if;
  for label in select * from jsonb_each(lang.value) loop
   if not(label.key=any(private.aqari_section_keys()||array['more','control_center','scan_document'])) or jsonb_typeof(label.value)<>'string' or length(btrim(label.value#>>'{}')) not between 1 and 80 or (label.value#>>'{}') ~ '[<>[:cntrl:]]' then raise exception 'INVALID_LABEL';end if;
  end loop;
 end loop;
 -- Lock workspace even before the first settings row: concurrent initial saves cannot overwrite.
 perform 1 from public.aqari_workspaces where id=p_workspace_id for update;
 select * into old_row from public.aqari_workspace_controls where workspace_id=p_workspace_id;
 if coalesce(old_row.revision,0) is distinct from p_expected_revision then raise exception 'REVISION_CONFLICT' using errcode='40001';end if;
 new_rev:=coalesce(old_row.revision,0)+1;
 insert into public.aqari_workspace_controls(workspace_id,settings,revision,updated_by) values(p_workspace_id,p_settings,new_rev,auth.uid())
 on conflict(workspace_id) do update set settings=excluded.settings,revision=excluded.revision,updated_by=excluded.updated_by,updated_at=now();
 insert into public.aqari_control_audit(workspace_id,actor_id,action,entity_ref,reason,before_value,after_value) values(p_workspace_id,auth.uid(),'controls.update',p_workspace_id::text,btrim(p_reason),old_row.settings,p_settings);
 return new_rev;
end $function$

CREATE OR REPLACE FUNCTION public.aqari_save_state_v267(p_workspace_id uuid, p_payload jsonb, p_expected_revision bigint)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare saved public.aqari_app_state%rowtype;old_data jsonb;incoming jsonb;merged jsonb;k text;v jsonb;prior jsonb;combined jsonb;ident text;duplicates boolean;
begin
 if auth.uid() is null or not private.aqari_staff(p_workspace_id) then raise insufficient_privilege using message='ACCESS_DENIED';end if;
 select * into saved from public.aqari_app_state where workspace_id=p_workspace_id for update;
 if not found or saved.revision is distinct from p_expected_revision then raise serialization_failure using message='REVISION_CONFLICT';end if;
 incoming:=private.aqari_unwrap(p_payload);old_data:=private.aqari_unwrap(saved.payload);merged:=old_data;
 if incoming is null or jsonb_typeof(incoming)<>'object' then raise exception 'INVALID_STATE';end if;
 for k in select jsonb_object_keys(incoming) loop
  if private.aqari_manager(p_workspace_id) then
   if incoming->k is distinct from old_data->k then
    if not private.aqari_can(p_workspace_id,private.aqari_state_section(k),'write') then raise insufficient_privilege using message='SECTION_WRITE_DENIED';end if;
    merged:=jsonb_set(merged,array[k],incoming->k,true);
   end if;continue;
  end if;
  if k='audit' then continue;end if;
  if not private.aqari_staff_state_key(k) or jsonb_typeof(incoming->k) is distinct from 'array' then raise insufficient_privilege using message='STAFF_STATE_KEY_DENIED';end if;
  if jsonb_typeof(coalesce(old_data->k,'[]'))<>'array' then raise insufficient_privilege using message='STAFF_STATE_KEY_DENIED';end if;
  select exists(select 1 from jsonb_array_elements(incoming->k)x group by private.aqari_staff_row_id(k,x) having count(*)>1) into duplicates;
  if duplicates then raise exception 'STAFF_DUPLICATE_ROW';end if;
  combined:=coalesce(old_data->k,'[]');
  for v in select value from jsonb_array_elements(incoming->k) loop
   ident:=private.aqari_staff_row_id(k,v);
   if ident is null or not private.aqari_staff_row_allowed(p_workspace_id,k,v,'read') then raise insufficient_privilege using message='STAFF_PROPERTY_DENIED';end if;
   select x into prior from jsonb_array_elements(coalesce(old_data->k,'[]'))x where private.aqari_staff_row_id(k,x)=ident;
   if prior=v then continue;end if;
   if not private.aqari_staff_row_allowed(p_workspace_id,k,v,'write') or (prior is not null and not private.aqari_staff_row_allowed(p_workspace_id,k,prior,'write')) then raise insufficient_privilege using message='STAFF_PROPERTY_DENIED';end if;
   if k='contractsV202' and (v->>'source' is distinct from 'v267-cloud' or v->>'detailsVersion' is distinct from '2' or v->>'rentalTermsVersion' is distinct from '1') then
    raise insufficient_privilege using message='STAFF_CURRENT_CONTRACT_REQUIRED';
   end if;
   if prior is not null then
    select coalesce(jsonb_agg(case when private.aqari_staff_row_id(k,x)=ident then v else x end order by n),'[]') into combined from jsonb_array_elements(combined)with ordinality q(x,n);
   else combined:=combined||jsonb_build_array(v);end if;
  end loop;
  merged:=jsonb_set(merged,array[k],combined,true);
 end loop;
 if not private.aqari_manager(p_workspace_id) and not private.aqari_can(p_workspace_id,'home','read') then raise insufficient_privilege using message='ACCESS_DENIED';end if;
 update public.aqari_app_state set payload=merged where workspace_id=p_workspace_id;
 return public.aqari_read_state_v267(p_workspace_id);
end $function$

CREATE OR REPLACE FUNCTION public.aqari_set_collector_alias(p_workspace_id uuid, p_source_name text, p_user_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare n text:=private.aqari_normalize_collector_name(p_source_name); uname text;
begin
 if auth.uid() is null or not private.aqari_manager(p_workspace_id) then raise insufficient_privilege using message='ACCESS_DENIED'; end if;
 perform private.aqari_require_sensitive_aal2(p_workspace_id);
 if length(n) not between 2 and 160 then raise exception 'COLLECTOR_ALIAS_INVALID' using errcode='22023'; end if;
 if not exists(select 1 from public.aqari_memberships m where m.workspace_id=p_workspace_id and m.user_id=p_user_id and m.is_active) then
   raise exception 'COLLECTOR_USER_NOT_ACTIVE' using errcode='23514';
 end if;
 select coalesce(nullif(p.display_name,''),p_user_id::text) into uname from public.aqari_profiles p where p.user_id=p_user_id;
 uname:=coalesce(uname,p_user_id::text);
 insert into private.aqari_collector_aliases(workspace_id,normalized_name,source_name,user_id,user_name_snapshot,created_by)
 values(p_workspace_id,n,btrim(p_source_name),p_user_id,uname,auth.uid())
 on conflict(workspace_id,normalized_name) do update set source_name=excluded.source_name,user_id=excluded.user_id,user_name_snapshot=excluded.user_name_snapshot,created_by=excluded.created_by,created_at=now();
 return jsonb_build_object('normalized_name',n,'user_id',p_user_id,'user_name',uname);
end $function$

CREATE OR REPLACE FUNCTION public.aqari_staff_access(p_workspace_id uuid, p_action text, p_data jsonb DEFAULT '{}'::jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare uid uuid;props uuid[];base text;effective text;enabled boolean;expected bigint;why text;who text;old_row private.aqari_staff_assignments%rowtype;saved private.aqari_staff_assignments%rowtype;
begin
 if auth.uid() is null or not private.aqari_manager(p_workspace_id) then raise insufficient_privilege using message='ACCESS_DENIED';end if;
 if p_action='list' then
  return jsonb_build_object('manager',true,
   'properties',coalesce((select jsonb_agg(jsonb_build_object('id',p.id,'name',p.name) order by p.name) from public.aqari_properties p where p.workspace_id=p_workspace_id),'[]'),
   'members',coalesce((select jsonb_agg(jsonb_build_object('user_id',m.user_id,'display_name',q.display_name,'role',m.role,'is_active',m.is_active) order by q.display_name) from public.aqari_memberships m join public.aqari_profiles q on q.user_id=m.user_id where m.workspace_id=p_workspace_id and m.role<>'general_manager'),'[]'),
   'assignments',coalesce((select jsonb_agg(to_jsonb(g)-'updated_by' order by g.updated_at desc) from private.aqari_staff_assignments g where g.workspace_id=p_workspace_id),'[]'),
   'audit',coalesce((select jsonb_agg(to_jsonb(q) order by q.id desc) from(select actor_name,recorded_at,reason,before_snapshot,after_snapshot,id from private.aqari_staff_assignment_audit where workspace_id=p_workspace_id order by id desc limit 100)q),'[]'));
 end if;
 if p_action is distinct from 'save' or jsonb_typeof(p_data) is distinct from 'object'
  or exists(select 1 from jsonb_object_keys(p_data) k where k not in('user_id','operational_role','property_ids','is_active','revision','reason')) then raise exception 'بيانات صلاحية الموظف غير صالحة.';end if;
 uid:=(p_data->>'user_id')::uuid;effective:=p_data->>'operational_role';expected:=(p_data->>'revision')::bigint;why:=btrim(p_data->>'reason');
 if jsonb_typeof(p_data->'is_active') is distinct from 'boolean' or jsonb_typeof(p_data->'property_ids') is distinct from 'array'
  or expected is null or expected<0 or why is null or length(why) not between 3 and 500 then raise exception 'أكمل الحساب والعقارات وسبب التعديل ورقم المراجعة.';end if;
 enabled:=(p_data->>'is_active')::boolean;
 perform 1 from public.aqari_workspaces where id=p_workspace_id for update;
 select role::text into base from public.aqari_memberships where workspace_id=p_workspace_id and user_id=uid and is_active for update;
 if base is null or base='general_manager' then raise insufficient_privilege using message='اختر عضوية موظف نشطة؛ صلاحية المدير العام لا تتغير هنا.';end if;
 if not coalesce((base='accountant' and effective in('collector','accountant','viewer')) or (base='property_manager' and effective in('collector','maintenance','property_manager','viewer')) or (base='viewer' and effective='viewer'),false) then raise insufficient_privilege using message='الدور التشغيلي يتجاوز حدود عضوية الحساب الحالية.';end if;
 if exists(select 1 from private.aqari_partner_access where workspace_id=p_workspace_id and user_id=uid) then raise insufficient_privilege using message='PARTNER_STAFF_CONFLICT';end if;
 select coalesce(array_agg(distinct x::uuid order by x::uuid),'{}') into props from jsonb_array_elements_text(p_data->'property_ids')x;
 if (enabled and cardinality(props)=0) or array_position(props,null) is not null then raise invalid_parameter_value using message='حدد عقاراً محفوظاً واحداً على الأقل للحساب النشط.';end if;
 if exists(select 1 from unnest(props)p where not exists(select 1 from public.aqari_properties where workspace_id=p_workspace_id and id=p)) then raise insufficient_privilege using message='ACCESS_DENIED';end if;
 select * into old_row from private.aqari_staff_assignments where workspace_id=p_workspace_id and user_id=uid for update;
 if coalesce(old_row.revision,0) is distinct from expected then raise serialization_failure using message='REVISION_CONFLICT';end if;
 insert into private.aqari_staff_assignments(workspace_id,user_id,operational_role,property_ids,is_active,revision,updated_by)
 values(p_workspace_id,uid,effective,props,enabled,expected+1,auth.uid())
 on conflict(workspace_id,user_id) do update set operational_role=excluded.operational_role,property_ids=excluded.property_ids,is_active=excluded.is_active,revision=excluded.revision,updated_by=excluded.updated_by,updated_at=now() returning * into saved;
 select display_name into who from public.aqari_profiles where user_id=auth.uid();
 insert into private.aqari_staff_assignment_audit(workspace_id,user_id,actor_id,actor_name,reason,before_snapshot,after_snapshot)
 values(p_workspace_id,uid,auth.uid(),coalesce(who,auth.uid()::text),why,case when old_row.user_id is null then null else to_jsonb(old_row) end,to_jsonb(saved));
 return to_jsonb(saved)-'updated_by';
end $function$

CREATE OR REPLACE FUNCTION public.aqari_startup_snapshot_v266(p_workspace_id uuid DEFAULT NULL::uuid, p_expected_role text DEFAULT NULL::text, p_include_payload boolean DEFAULT true)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE
 SET search_path TO ''
AS $function$
declare
  v_uid uuid := auth.uid();
  v_member record;
  v_workspace record;
  v_profile record;
  v_app jsonb := null;
begin
  if v_uid is null then
    raise exception 'AQARI_ACCESS_DENIED' using errcode = '42501';
  end if;
  select m.workspace_id, m.user_id, m.role, m.is_active, m.created_at
    into v_member from public.aqari_memberships m
    where m.user_id = v_uid and m.is_active is true
      and (p_workspace_id is null or m.workspace_id = p_workspace_id)
      and (p_expected_role is null or m.role::text = p_expected_role)
    order by m.created_at, m.workspace_id limit 1;
  if not found then
    raise exception 'AQARI_ACCESS_DENIED' using errcode = '42501';
  end if;
  select w.id, w.name, w.slug, w.created_at into v_workspace
    from public.aqari_workspaces w where w.id = v_member.workspace_id;
  if not found then
    raise exception 'AQARI_ACCESS_DENIED' using errcode = '42501';
  end if;
  select p.user_id, p.display_name, p.created_at, p.updated_at into v_profile
    from public.aqari_profiles p where p.user_id = v_uid;
  if not found then
    raise exception 'AQARI_ACCESS_DENIED' using errcode = '42501';
  end if;
  if p_include_payload then
    v_app := public.aqari_read_state_v267(v_member.workspace_id);
  end if;
  return jsonb_build_object('user_id',v_uid,'membership',to_jsonb(v_member),
    'workspace',to_jsonb(v_workspace),'profile',to_jsonb(v_profile),'app_state',v_app);
end;
$function$

CREATE OR REPLACE FUNCTION public.aqari_tenant_complete_file(p_workspace_id uuid, p_property_id uuid, p_tenant_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare tenant_row public.aqari_tenants%rowtype;family jsonb;leases jsonb;documents jsonb;receipts jsonb;
begin
 if not private.aqari_can_property(p_workspace_id,p_property_id,'properties','read') or not private.aqari_can(p_workspace_id,'tenants','read') or not private.aqari_can(p_workspace_id,'contracts','read') then raise insufficient_privilege using message='ACCESS_DENIED';end if;
 if not exists(select 1 from public.aqari_leases l join public.aqari_units u on u.workspace_id=l.workspace_id and u.id=l.unit_id where l.workspace_id=p_workspace_id and l.tenant_id=p_tenant_id and u.property_id=p_property_id) then raise insufficient_privilege using message='TENANT_PROPERTY_SCOPE_MISMATCH';end if;
 select * into strict tenant_row from public.aqari_tenants where workspace_id=p_workspace_id and id=p_tenant_id;
 select jsonb_build_object('civilIdExpiresOn',f.civil_id_expires_on,'husbandName',coalesce(f.husband_name,''),'wifeName',coalesce(f.wife_name,''),'revision',coalesce(f.revision,0),'updatedAt',f.updated_at) into family from (select 1) seed left join private.aqari_tenant_family_details f on f.workspace_id=p_workspace_id and f.tenant_id=p_tenant_id;
 select coalesce(jsonb_agg(jsonb_build_object('id',l.id,'externalRef',l.external_ref,'contractNo',l.contract_no,'unitId',l.unit_id,'unitNo',u.unit_no,'status',l.status,'startDate',l.start_date,'endDate',l.end_date,'monthlyRent',l.monthly_rent) order by l.start_date desc,l.contract_no),'[]') into leases from public.aqari_leases l join public.aqari_units u on u.workspace_id=l.workspace_id and u.id=l.unit_id where l.workspace_id=p_workspace_id and l.tenant_id=p_tenant_id and u.property_id=p_property_id;
 if private.aqari_can(p_workspace_id,'collections','read') then
  select coalesce(jsonb_agg(jsonb_build_object('id',pay.id,'leaseId',pay.lease_id,'reference',pay.reference,'amount',pay.amount,'period',pay.period,'paidAt',pay.paid_at,'status',pay.status,'paymentMethod',pay.payment_method,'createdAt',pay.created_at) order by pay.paid_at desc,pay.created_at desc),'[]') into receipts
  from public.aqari_rent_payments pay join public.aqari_leases l on l.workspace_id=pay.workspace_id and l.id=pay.lease_id join public.aqari_units u on u.workspace_id=l.workspace_id and u.id=l.unit_id
  where pay.workspace_id=p_workspace_id and l.tenant_id=p_tenant_id and u.property_id=p_property_id;
 else receipts:=null;end if;
 if private.aqari_can(p_workspace_id,'documents','read') then
  select coalesce(jsonb_agg(jsonb_build_object('id',d.id,'documentNo',d.document_no,'entityType',d.entity_type,'entityRef',d.entity_ref,'documentType',d.document_type,'title',d.title,'mimeType',d.mime_type,'status',d.status,'metadata',d.metadata,'createdAt',d.created_at) order by d.created_at desc) filter(where d.id is not null),'[]') into documents from public.aqari_documents d where d.workspace_id=p_workspace_id and d.status<>'cancelled' and ((d.entity_type='tenant' and d.entity_ref in(p_tenant_id::text,tenant_row.external_ref)) or (d.entity_type='lease' and d.entity_ref in(select x->>'id' from jsonb_array_elements(leases)x union select x->>'externalRef' from jsonb_array_elements(leases)x)));
 else documents:=null;end if;
 return jsonb_build_object('workspace_id',p_workspace_id,'user_id',auth.uid(),'propertyId',p_property_id,'tenant',jsonb_build_object('id',tenant_row.id,'externalRef',tenant_row.external_ref,'name',tenant_row.full_name,'civilId',tenant_row.civil_id,'phone',tenant_row.phone,'email',tenant_row.email,'profile',tenant_row.profile),'family',family,'leases',leases,'receipts',receipts,'documents',documents);
end $function$

CREATE OR REPLACE FUNCTION public.aqari_tenant_family_save(p_workspace_id uuid, p_property_id uuid, p_tenant_id uuid, p_expected_revision bigint, p_data jsonb, p_reason text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare current_row private.aqari_tenant_family_details%rowtype;before_json jsonb;after_json jsonb;expiry date;husband text;wife text;
begin
 if not private.aqari_can_property(p_workspace_id,p_property_id,'properties','read') or not private.aqari_can(p_workspace_id,'tenants','write') then raise insufficient_privilege using message='ACCESS_DENIED';end if;
 if not exists(select 1 from public.aqari_leases l join public.aqari_units u on u.workspace_id=l.workspace_id and u.id=l.unit_id where l.workspace_id=p_workspace_id and l.tenant_id=p_tenant_id and u.property_id=p_property_id) then raise insufficient_privilege using message='TENANT_PROPERTY_SCOPE_MISMATCH';end if;
 if jsonb_typeof(p_data) is distinct from 'object' or exists(select 1 from jsonb_object_keys(p_data) k where k not in('civilIdExpiresOn','husbandName','wifeName')) then raise invalid_parameter_value using message='TENANT_FAMILY_INVALID';end if;
 begin expiry:=nullif(p_data->>'civilIdExpiresOn','')::date;exception when others then raise invalid_parameter_value using message='TENANT_CIVIL_EXPIRY_INVALID';end;
 husband:=btrim(coalesce(p_data->>'husbandName',''));wife:=btrim(coalesce(p_data->>'wifeName',''));
 if length(husband)>200 or length(wife)>200 or length(btrim(coalesce(p_reason,''))) not between 3 and 1000 then raise invalid_parameter_value using message='TENANT_FAMILY_INVALID';end if;
 select * into current_row from private.aqari_tenant_family_details where workspace_id=p_workspace_id and tenant_id=p_tenant_id for update;
 if coalesce(current_row.revision,0)<>coalesce(p_expected_revision,0) then raise serialization_failure using message='TENANT_FAMILY_REVISION_CONFLICT';end if;
 before_json:=case when found then to_jsonb(current_row) else null end;
 insert into private.aqari_tenant_family_details(workspace_id,tenant_id,civil_id_expires_on,husband_name,wife_name,revision,updated_by,updated_at)
 values(p_workspace_id,p_tenant_id,expiry,husband,wife,coalesce(p_expected_revision,0)+1,auth.uid(),now())
 on conflict(workspace_id,tenant_id) do update set civil_id_expires_on=excluded.civil_id_expires_on,husband_name=excluded.husband_name,wife_name=excluded.wife_name,revision=excluded.revision,updated_by=excluded.updated_by,updated_at=excluded.updated_at;
 select to_jsonb(f) into after_json from private.aqari_tenant_family_details f where f.workspace_id=p_workspace_id and f.tenant_id=p_tenant_id;
 insert into private.aqari_portfolio_addition_audit(workspace_id,property_id,tenant_id,entity_type,reason,actor_id,before_value,after_value) values(p_workspace_id,p_property_id,p_tenant_id,'tenant_family',btrim(p_reason),auth.uid(),before_json,after_json);
 return public.aqari_tenant_complete_file(p_workspace_id,p_property_id,p_tenant_id);
end $function$

CREATE OR REPLACE FUNCTION public.aqari_tenant_portal_snapshot()
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE
 SET search_path TO ''
AS $function$
declare a public.aqari_portal_accounts%rowtype;
begin
 select * into a from public.aqari_portal_accounts where user_id=auth.uid() and is_active;
 if not found or not private.aqari_owns_tenant(a.workspace_id,a.tenant_id) then raise exception 'TENANT_ACCESS_DENIED' using errcode='42501';end if;
 return jsonb_build_object(
  'account',to_jsonb(a),
  'tenant',(select to_jsonb(t) from public.aqari_tenants t where t.id=a.tenant_id),
  'leases',(select coalesce(jsonb_agg(to_jsonb(l)),'[]') from public.aqari_leases l where l.tenant_id=a.tenant_id),
  'payments',(select coalesce(jsonb_agg(to_jsonb(p)),'[]') from public.aqari_rent_payments p join public.aqari_leases l on l.id=p.lease_id where l.tenant_id=a.tenant_id),
  'maintenance',(select coalesce(jsonb_agg(to_jsonb(m) order by m.created_at desc),'[]') from public.aqari_maintenance_requests m where m.tenant_id=a.tenant_id),
  'maintenance_attachments',(select coalesce(jsonb_agg(jsonb_build_object('id',x.id,'request_id',x.request_id,'storage_bucket',x.storage_bucket,'storage_path',x.storage_path,'original_filename',x.original_filename,'mime_type',x.mime_type,'size_bytes',x.size_bytes,'checksum_sha256',x.checksum_sha256,'status',x.status,'created_at',x.created_at) order by x.created_at,x.id),'[]') from public.aqari_maintenance_attachments x join public.aqari_maintenance_requests m on m.id=x.request_id and m.workspace_id=x.workspace_id where m.tenant_id=a.tenant_id and x.status='uploaded')
 );
end $function$

CREATE OR REPLACE FUNCTION public.aqari_tenant_portfolio_context(p_workspace_id uuid, p_tenant_ref text)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare tenant_row public.aqari_tenants%rowtype;properties jsonb;
begin
 if auth.uid() is null or not private.aqari_can(p_workspace_id,'tenants','read') or not private.aqari_can(p_workspace_id,'contracts','read') then
  raise insufficient_privilege using message='ACCESS_DENIED';
 end if;
 select * into tenant_row from public.aqari_tenants
  where workspace_id=p_workspace_id and external_ref=p_tenant_ref;
 if not found then raise no_data_found using message='TENANT_NOT_FOUND';end if;
 select coalesce(jsonb_agg(jsonb_build_object(
   'id',scope.id,'name',scope.name,
   'leaseCount',(select count(*) from public.aqari_leases l join public.aqari_units u on u.workspace_id=l.workspace_id and u.id=l.unit_id where l.workspace_id=p_workspace_id and l.tenant_id=tenant_row.id and u.property_id=scope.id),
   'receiptCount',(select count(*) from public.aqari_rent_payments pay join public.aqari_leases l on l.workspace_id=pay.workspace_id and l.id=pay.lease_id join public.aqari_units u on u.workspace_id=l.workspace_id and u.id=l.unit_id where pay.workspace_id=p_workspace_id and l.tenant_id=tenant_row.id and u.property_id=scope.id)
  ) order by scope.name),'[]'::jsonb) into properties
 from (
  select distinct p.id,p.name from public.aqari_leases l
  join public.aqari_units u on u.workspace_id=l.workspace_id and u.id=l.unit_id
  join public.aqari_properties p on p.workspace_id=u.workspace_id and p.id=u.property_id
  where l.workspace_id=p_workspace_id and l.tenant_id=tenant_row.id
   and private.aqari_can_property(p_workspace_id,p.id,'properties','read')
 ) scope;
 return jsonb_build_object('workspace_id',p_workspace_id,'user_id',auth.uid(),'tenantId',tenant_row.id,'tenantRef',tenant_row.external_ref,'properties',properties);
end $function$

CREATE OR REPLACE FUNCTION public.aqari_tenant_property_support()
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare account public.aqari_portal_accounts%rowtype;
begin
 if auth.uid() is null then raise insufficient_privilege using message='TENANT_ACCESS_DENIED';end if;
 select * into account from public.aqari_portal_accounts a where a.user_id=auth.uid() and a.is_active;
 if not found or not private.aqari_owns_tenant(account.workspace_id,account.tenant_id) then raise insufficient_privilege using message='TENANT_ACCESS_DENIED';end if;
 return jsonb_build_object('workspaceId',account.workspace_id,'tenantId',account.tenant_id,'properties',coalesce((
  select jsonb_agg(jsonb_build_object('propertyId',scope.property_id,'propertyName',scope.property_name,'techniciansEnabled',scope.technicians_enabled,'maintenanceEnabled',scope.maintenance_enabled,'technicians',case when scope.technicians_enabled then coalesce((select jsonb_agg(jsonb_build_object('employeeId',assignment.employee_id,'nameAr',coalesce(employee.profile->>'name_ar',''),'nameEn',coalesce(employee.profile->>'name_en',''),'jobAr',coalesce(employee.profile->>'job_ar',''),'phone',assignment.phone,'whatsapp',assignment.whatsapp) order by coalesce(nullif(employee.profile->>'name_ar',''),nullif(employee.profile->>'name_en',''),employee.id::text)) from private.aqari_property_technicians assignment join private.aqari_hr_employees employee on employee.workspace_id=assignment.workspace_id and employee.id=assignment.employee_id where assignment.workspace_id=account.workspace_id and assignment.property_id=scope.property_id and assignment.is_active and assignment.public_to_tenant and employee.status<>'inactive'),'[]'::jsonb) else '[]'::jsonb end) order by scope.property_name,scope.property_id)
  from(select distinct property.id property_id,property.name property_name,case when jsonb_typeof(feature.settings->'technicians')='boolean' then (feature.settings->>'technicians')::boolean else true end technicians_enabled,case when jsonb_typeof(feature.settings->'maintenance')='boolean' then (feature.settings->>'maintenance')::boolean else true end maintenance_enabled from public.aqari_leases lease join public.aqari_units unit on unit.workspace_id=lease.workspace_id and unit.id=lease.unit_id join public.aqari_properties property on property.workspace_id=unit.workspace_id and property.id=unit.property_id left join private.aqari_property_feature_settings feature on feature.workspace_id=property.workspace_id and feature.property_id=property.id where lease.workspace_id=account.workspace_id and lease.tenant_id=account.tenant_id and lease.status='signed' and current_date between lease.start_date and lease.end_date)scope
 ),'[]'::jsonb));
end $function$

CREATE OR REPLACE FUNCTION public.aqari_ui_presentation_settings(p_workspace_id uuid, p_action text, p_data jsonb DEFAULT '{}'::jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare w uuid:=p_workspace_id;d jsonb:=coalesce(p_data,'{}'::jsonb);surface_value text;key_value text;expected bigint;label_ar_value text;label_en_value text;icon_value text;order_value integer;visible_value boolean;why text;before_row jsonb;after_row jsonb;manager boolean;actor text;
begin
 if auth.uid() is null or jsonb_typeof(d) is distinct from 'object' or not private.aqari_can(w,'properties','read') then raise insufficient_privilege using message='ACCESS_DENIED';end if;
 surface_value:=coalesce(nullif(d->>'surface',''),'property_hub');if surface_value<>'property_hub' then raise invalid_parameter_value using message='INVALID_PRESENTATION_SURFACE';end if;
 manager:=private.aqari_manager(w) and private.aqari_can(w,'administration','write');
 if p_action='context' then
  return jsonb_build_object('workspace_id',w,'user_id',auth.uid(),'manager',manager,'surface',surface_value,
   'items',(select jsonb_agg(jsonb_build_object('key',x->>'key','labelAr',coalesce(nullif(p.label_ar,''),x->>'labelAr'),'labelEn',coalesce(nullif(p.label_en,''),x->>'labelEn'),'icon',coalesce(nullif(p.icon,''),x->>'icon'),'sortOrder',coalesce(p.sort_order,(x->>'sortOrder')::int),'visible',coalesce(p.is_visible,(x->>'visible')::boolean),'revision',coalesce(p.revision,0)) order by coalesce(p.sort_order,(x->>'sortOrder')::int),x->>'key') from jsonb_array_elements(private.aqari_property_hub_defaults())x left join private.aqari_ui_presentations p on p.workspace_id=w and p.surface=surface_value and p.item_key=x->>'key'));
 end if;
 if p_action<>'save' or not manager then raise insufficient_privilege using message='PRESENTATION_MANAGER_ONLY';end if;perform private.aqari_require_sensitive_aal2(w);
 if exists(select 1 from jsonb_object_keys(d)k where k not in('surface','key','revision','labelAr','labelEn','icon','sortOrder','visible','reason')) then raise invalid_parameter_value using message='INVALID_PRESENTATION_FIELD';end if;
 key_value:=d->>'key';if not exists(select 1 from jsonb_array_elements(private.aqari_property_hub_defaults())x where x->>'key'=key_value) then raise invalid_parameter_value using message='INVALID_PRESENTATION_KEY';end if;
 expected:=coalesce((d->>'revision')::bigint,0);label_ar_value:=btrim(coalesce(d->>'labelAr',''));label_en_value:=btrim(coalesce(d->>'labelEn',''));icon_value:=btrim(coalesce(d->>'icon',''));order_value:=coalesce((d->>'sortOrder')::int,100);visible_value:=coalesce((d->>'visible')::boolean,true);why:=btrim(coalesce(d->>'reason',''));
 if length(label_ar_value)>100 or length(label_en_value)>100 or length(icon_value)>16 or icon_value~'[<>&]' or order_value not between 0 and 10000 or length(why) not between 3 and 1000 then raise invalid_parameter_value using message='INVALID_PRESENTATION_VALUE';end if;
 select to_jsonb(p) into before_row from private.aqari_ui_presentations p where p.workspace_id=w and p.surface=surface_value and p.item_key=key_value for update;
 if before_row is null then if expected<>0 then raise serialization_failure using message='PRESENTATION_REVISION_CONFLICT';end if;insert into private.aqari_ui_presentations(workspace_id,surface,item_key,label_ar,label_en,icon,sort_order,is_visible,revision,updated_by) values(w,surface_value,key_value,label_ar_value,label_en_value,icon_value,order_value,visible_value,1,auth.uid());
 else if (before_row->>'revision')::bigint<>expected then raise serialization_failure using message='PRESENTATION_REVISION_CONFLICT';end if;update private.aqari_ui_presentations set label_ar=label_ar_value,label_en=label_en_value,icon=icon_value,sort_order=order_value,is_visible=visible_value,revision=expected+1,updated_by=auth.uid(),updated_at=now() where workspace_id=w and surface=surface_value and item_key=key_value;end if;
 select to_jsonb(p) into after_row from private.aqari_ui_presentations p where p.workspace_id=w and p.surface=surface_value and p.item_key=key_value;select coalesce(nullif(display_name,''),auth.uid()::text) into actor from public.aqari_profiles where user_id=auth.uid();actor:=coalesce(actor,auth.uid()::text);
 insert into private.aqari_property_control_audit(workspace_id,entity,entity_id,action,actor_id,actor_name,reason,before_value,after_value) values(w,'ui_presentation',surface_value||':'||key_value,'save',auth.uid(),actor,why,before_row,after_row);
 return jsonb_build_object('workspace_id',w,'user_id',auth.uid(),'record',after_row);
end $function$

CREATE OR REPLACE FUNCTION public.aqari_unit_handover_pdf_commit(p_workspace_id uuid, p_inspection_id uuid, p_actor_id uuid, p_source jsonb, p_snapshot_sha256 text, p_pdf_base64 text, p_pdf_sha256 text, p_renderer_version text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
 old_sub text:=current_setting('request.jwt.claim.sub',true);old_claims text:=current_setting('request.jwt.claims',true);
 current_source jsonb;bytes bytea;revision integer;lease_id uuid;unit_id uuid;
 existing private.aqari_unit_handover_pdf_artifacts;
begin
 if current_setting('role',true) is distinct from 'service_role' or p_actor_id is null then
  raise insufficient_privilege using message='TRUSTED_RENDERER_REQUIRED';
 end if;
 if p_source is null or jsonb_typeof(p_source)<>'object' or octet_length(p_source::text)>131072
  or p_snapshot_sha256 is null or p_snapshot_sha256!~'^[a-f0-9]{64}$'
  or p_pdf_sha256 is null or p_pdf_sha256!~'^[a-f0-9]{64}$'
  or p_pdf_base64 is null or length(p_pdf_base64)>11184812
  or p_renderer_version is null or length(p_renderer_version) not between 1 and 100 then
  raise exception 'INVALID_UNIT_HANDOVER_PDF_ARCHIVE' using errcode='23514';
 end if;
 perform 1 from private.aqari_unit_inspections i where i.workspace_id=p_workspace_id and i.id=p_inspection_id for update;
 if not found then raise insufficient_privilege using message='ACCESS_DENIED';end if;
 perform set_config('request.jwt.claim.sub',p_actor_id::text,true);
 perform set_config('request.jwt.claims',jsonb_build_object('sub',p_actor_id,'role','authenticated')::text,true);
 current_source:=public.aqari_unit_handover_pdf_source(p_workspace_id,p_inspection_id);
 perform set_config('request.jwt.claim.sub',coalesce(old_sub,''),true);
 perform set_config('request.jwt.claims',coalesce(old_claims,''),true);
 if current_source is distinct from p_source then raise exception 'UNIT_HANDOVER_SOURCE_CHANGED' using errcode='40001';end if;
 revision:=(current_source#>>'{bundle,source,inspection_revision}')::integer;
 lease_id:=(current_source#>>'{bundle,source,lease_id}')::uuid;
 unit_id:=(current_source#>>'{bundle,source,unit_id}')::uuid;
 bytes:=decode(p_pdf_base64,'base64');
 if octet_length(bytes) not between 8 and 8388608 or substring(bytes from 1 for 5)<>convert_to('%PDF-','UTF8')
  or encode(sha256(bytes),'hex')<>p_pdf_sha256 then raise exception 'INVALID_UNIT_HANDOVER_PDF_ARCHIVE' using errcode='23514';end if;
 select * into existing from private.aqari_unit_handover_pdf_artifacts a
  where a.workspace_id=p_workspace_id and a.inspection_id=p_inspection_id and a.inspection_revision=revision;
 if found then
  if existing.pdf_sha256<>p_pdf_sha256 or existing.snapshot_sha256<>p_snapshot_sha256 then raise exception 'UNIT_HANDOVER_PDF_ARCHIVE_CONFLICT' using errcode='23505';end if;
  return jsonb_build_object('archived',true,'replayed',true,'pdf_sha256',existing.pdf_sha256,'snapshot_sha256',existing.snapshot_sha256);
 end if;
 insert into private.aqari_unit_handover_pdf_artifacts(workspace_id,inspection_id,inspection_revision,lease_id,unit_id,snapshot_sha256,pdf_bytes,pdf_sha256,renderer_version,archived_by)
 values(p_workspace_id,p_inspection_id,revision,lease_id,unit_id,p_snapshot_sha256,bytes,p_pdf_sha256,p_renderer_version,p_actor_id);
 insert into private.aqari_operations_audit(workspace_id,domain,entity_id,action,actor_id,actor_name,reason,after_value)
 values(p_workspace_id,'inspections',p_inspection_id,'handover_pdf_export',p_actor_id,p_actor_id::text,'حفظ محضر تسليم واستلام PDF من فحص خروج موقع',jsonb_build_object('revision',revision,'pdf_sha256',p_pdf_sha256,'snapshot_sha256',p_snapshot_sha256,'renderer',p_renderer_version));
 return jsonb_build_object('archived',true,'replayed',false,'pdf_sha256',p_pdf_sha256,'snapshot_sha256',p_snapshot_sha256);
end $function$

CREATE OR REPLACE FUNCTION public.aqari_unit_handover_pdf_get(p_workspace_id uuid, p_inspection_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare source jsonb;revision integer;artifact private.aqari_unit_handover_pdf_artifacts;
begin
 source:=public.aqari_unit_handover_pdf_source(p_workspace_id,p_inspection_id);
 revision:=(source#>>'{bundle,source,inspection_revision}')::integer;
 select * into artifact from private.aqari_unit_handover_pdf_artifacts a
  where a.workspace_id=p_workspace_id and a.inspection_id=p_inspection_id and a.inspection_revision=revision;
 if not found then return '{}'::jsonb;end if;
 return (to_jsonb(artifact)-'pdf_bytes')||jsonb_build_object('pdf_base64',replace(encode(artifact.pdf_bytes,'base64'),E'\n',''));
end $function$

CREATE OR REPLACE FUNCTION public.aqari_unit_handover_pdf_source(p_workspace_id uuid, p_inspection_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
 w uuid:=p_workspace_id;i private.aqari_unit_inspections;l public.aqari_leases;u public.aqari_units;
 p public.aqari_properties;t public.aqari_tenants;attachments jsonb;evidence jsonb;
 expected_count integer;actual_count integer;bundle jsonb;summary_text text;
begin
 if auth.uid() is null then raise insufficient_privilege using message='ACCESS_DENIED';end if;
 select * into i from private.aqari_unit_inspections x
  where x.workspace_id=w and x.id=p_inspection_id and x.kind='move_out' and x.status='signed';
 if not found or i.signed_at is null or i.tenant_signature_document_id is null or i.inspector_signature_document_id is null
  or jsonb_typeof(i.checklist)<>'array' or jsonb_array_length(i.checklist)=0
  or jsonb_typeof(i.photo_document_ids)<>'array' or jsonb_array_length(i.photo_document_ids)=0 then
  raise exception 'UNIT_HANDOVER_SIGNED_MOVE_OUT_REQUIRED' using errcode='23514';
 end if;
 select * into l from public.aqari_leases x where x.workspace_id=w and x.id=i.lease_id;
 select * into u from public.aqari_units x where x.workspace_id=w and x.id=i.unit_id and x.id=l.unit_id;
 select * into p from public.aqari_properties x where x.workspace_id=w and x.id=u.property_id;
 select * into t from public.aqari_tenants x where x.workspace_id=w and x.id=l.tenant_id;
 if l.id is null or u.id is null or p.id is null or t.id is null
  or not private.aqari_can_property(w,p.id,'maintenance','read')
  or not private.aqari_can(w,'documents','read') then raise insufficient_privilege using message='ACCESS_DENIED';end if;
 expected_count:=jsonb_array_length(i.photo_document_ids)+2;
 with roles as(
  select x.value::uuid as id,'PHOTO_'||x.ordinality::text as role,x.ordinality::integer as ord
   from jsonb_array_elements_text(i.photo_document_ids) with ordinality x(value,ordinality)
  union all select i.tenant_signature_document_id,'TENANT_SIGNATURE',1000001
  union all select i.inspector_signature_document_id,'INSPECTOR_SIGNATURE',1000002
 ),verified as(
  select r.id,r.role,r.ord,d.checksum_sha256,d.size_bytes,d.mime_type,d.storage_bucket,d.storage_path
   from roles r join public.aqari_documents d on d.workspace_id=w and d.id=r.id
   join storage.objects o on o.bucket_id=d.storage_bucket and o.name=d.storage_path
   where d.status='uploaded' and d.checksum_sha256~'^[a-f0-9]{64}$' and d.size_bytes between 1 and 26214400
    and d.mime_type in('image/jpeg','image/png','application/pdf')
    and (r.role not like 'PHOTO_%' or d.mime_type in('image/jpeg','image/png'))
    and (o.metadata->>'size')::bigint=d.size_bytes and o.metadata->>'mimetype'=d.mime_type
    and private.aqari_operations_document(w,p.id,d.id)
 )
 select count(*)::integer,
  coalesce(jsonb_agg(jsonb_build_object('id',id,'role',role,'checksum_sha256',checksum_sha256,'size_bytes',size_bytes,'mime_type',mime_type) order by ord),'[]'::jsonb),
  coalesce(jsonb_agg(jsonb_build_object('id',id,'role',role,'checksum_sha256',checksum_sha256,'size_bytes',size_bytes,'mime_type',mime_type,'storage_bucket',storage_bucket,'storage_path',storage_path) order by ord),'[]'::jsonb)
 into actual_count,attachments,evidence from verified;
 if actual_count<>expected_count or (select count(distinct x->>'id') from jsonb_array_elements(attachments)x)<>expected_count
  or (select count(distinct x->>'role') from jsonb_array_elements(attachments)x)<>expected_count then
  raise exception 'UNIT_HANDOVER_EVIDENCE_UNVERIFIED' using errcode='23514';
 end if;
 summary_text:='محضر تسليم واستلام الوحدة '||u.unit_no||' في '||p.name||' للعقد '||l.contract_no||' والمستأجر '||t.full_name||'. الفحص المحفوظ '||i.id::text||' يتضمن '||jsonb_array_length(i.checklist)::text||' بنداً و'||jsonb_array_length(i.photo_document_ids)::text||' صورة وتوقيعَي الطرفين.';
 bundle:=jsonb_build_object(
  'kind','unit_handover','title','محضر تسليم واستلام وحدة','summary',summary_text,
  'source',jsonb_build_object('inspection_id',i.id,'lease_id',i.lease_id,'unit_id',i.unit_id,'inspection_revision',i.revision,'inspected_at',i.inspected_at,'signed_at',i.signed_at),
  'parties',jsonb_build_object('tenant_name',t.full_name,'contract_no',l.contract_no,'property_name',p.name,'unit_no',u.unit_no),
  'checklist',i.checklist,'attachments',attachments);
 return jsonb_build_object('bundle',bundle,'evidence',evidence);
end $function$

CREATE OR REPLACE FUNCTION public.aqari_unit_master_save(p_workspace_id uuid, p_property_id uuid, p_unit_id uuid, p_expected_revision bigint, p_data jsonb, p_reason text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare old_row private.aqari_unit_master%rowtype; old_snapshot jsonb; new_snapshot jsonb; actor text; n text; rent numeric; rev bigint; actual_property uuid;
begin
 if not private.aqari_can_property(p_workspace_id,p_property_id,'properties','write') then raise insufficient_privilege using message='ACCESS_DENIED';end if;
 if jsonb_typeof(p_data) is distinct from 'object' or exists(select 1 from jsonb_object_keys(p_data) k where k not in('unitNo','floor','type','status','statedRent','automaticRef')) then raise invalid_parameter_value using message='UNIT_MASTER_INVALID';end if;
 n:=btrim(coalesce(p_data->>'unitNo',''));if length(n) not between 1 and 120 then raise invalid_parameter_value using message='UNIT_NUMBER_REQUIRED';end if;
 if length(btrim(coalesce(p_reason,''))) not between 3 and 1000 then raise invalid_parameter_value using message='CHANGE_REASON_REQUIRED';end if;
 begin rent:=nullif(p_data->>'statedRent','')::numeric;exception when others then raise invalid_parameter_value using message='UNIT_RENT_INVALID';end;
 if rent is not null and (rent<0 or round(rent,3)<>rent) then raise invalid_parameter_value using message='UNIT_RENT_INVALID';end if;
 if length(coalesce(p_data->>'floor',''))>100 or length(coalesce(p_data->>'type',''))>120 or length(coalesce(p_data->>'status','')) not between 1 and 80 or length(coalesce(p_data->>'automaticRef',''))>200 then raise invalid_parameter_value using message='UNIT_MASTER_FIELD_INVALID';end if;
 select property_id into actual_property from public.aqari_units where workspace_id=p_workspace_id and id=p_unit_id for update;
 if actual_property is null or actual_property<>p_property_id then raise exception 'UNIT_PROPERTY_BINDING_MISMATCH' using errcode='23514';end if;
 if exists(select 1 from public.aqari_units where workspace_id=p_workspace_id and property_id=p_property_id and id<>p_unit_id and lower(btrim(unit_no))=lower(n)) then raise unique_violation using message='UNIT_NUMBER_ALREADY_EXISTS';end if;
 old_snapshot:=private.aqari_unit_master_snapshot(p_workspace_id,p_unit_id);
 select * into old_row from private.aqari_unit_master where workspace_id=p_workspace_id and unit_id=p_unit_id for update;
 rev:=coalesce(old_row.revision,0);if p_expected_revision is distinct from rev then raise exception 'UNIT_MASTER_REVISION_CONFLICT' using errcode='40001';end if;
 select coalesce(nullif(display_name,''),auth.uid()::text) into actor from public.aqari_profiles where user_id=auth.uid();actor:=coalesce(actor,auth.uid()::text);
 update public.aqari_units set unit_no=n where workspace_id=p_workspace_id and id=p_unit_id;
 insert into private.aqari_unit_master(workspace_id,unit_id,property_id,floor,unit_type,status,stated_rent,automatic_ref,revision,updated_by,updated_at)
 values(p_workspace_id,p_unit_id,p_property_id,btrim(coalesce(p_data->>'floor','')),btrim(coalesce(p_data->>'type','')),btrim(coalesce(p_data->>'status','available')),rent,btrim(coalesce(p_data->>'automaticRef','')),rev+1,auth.uid(),now())
 on conflict(workspace_id,unit_id) do update set property_id=excluded.property_id,floor=excluded.floor,unit_type=excluded.unit_type,status=excluded.status,stated_rent=excluded.stated_rent,automatic_ref=excluded.automatic_ref,revision=excluded.revision,updated_by=excluded.updated_by,updated_at=excluded.updated_at
 returning * into old_row;
 new_snapshot:=private.aqari_unit_master_snapshot(p_workspace_id,p_unit_id);
 insert into private.aqari_property_master_audit(workspace_id,property_id,unit_id,entity_type,action,reason,actor_id,actor_name,before_value,after_value)
 values(p_workspace_id,p_property_id,p_unit_id,'unit','save_master',btrim(p_reason),auth.uid(),actor,old_snapshot,new_snapshot);
 return jsonb_build_object('workspace_id',p_workspace_id,'user_id',auth.uid(),'unit',new_snapshot);
end $function$

CREATE OR REPLACE FUNCTION public.aqari_unit_readiness_register(p_workspace_id uuid, p_action text, p_data jsonb DEFAULT '{}'::jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare w uuid:=p_workspace_id;d jsonb:=p_data;p uuid;u public.aqari_units;
 saved private.aqari_unit_readiness;ident uuid;expected bigint;version bigint;number text;observed date;
begin
 if auth.uid() is null or not private.aqari_can(w,'properties','read') then raise insufficient_privilege using message='ACCESS_DENIED';end if;
 if p_action is null or p_action not in ('list','record') or d is null or jsonb_typeof(d)<>'object' or octet_length(d::text)>8192 then raise invalid_parameter_value using message='INVALID_READINESS_REQUEST';end if;
 if p_action='list' then
  return jsonb_build_object(
   'properties',coalesce((select jsonb_agg(jsonb_build_object('id',x.id,'name',x.name,'can_create',private.aqari_can_property(w,x.id,'properties','write'),'can_write',private.aqari_can_property(w,x.id,'properties','write') or private.aqari_can_property(w,x.id,'maintenance','write')) order by x.name,x.id) from public.aqari_properties x where x.workspace_id=w and private.aqari_can_property(w,x.id,'properties','read')),'[]'),
   'units',coalesce((select jsonb_agg(jsonb_build_object('id',x.id,'property_id',x.property_id,'unit_no',x.unit_no,'revision',coalesce(r.revision,0),'state',coalesce(r.state,'review_required'),'inspected_on',r.inspected_on,'source_ref',r.source_ref,'reason',r.reason) order by x.unit_no,x.id)
    from public.aqari_units x left join lateral(select y.* from private.aqari_unit_readiness y where y.workspace_id=w and y.unit_id=x.id order by y.revision desc limit 1)r on true where x.workspace_id=w and private.aqari_can_property(w,x.property_id,'properties','read')),'[]'),
   'history',coalesce((select jsonb_agg(to_jsonb(r) order by r.recorded_at desc,r.revision desc) from private.aqari_unit_readiness r join public.aqari_units x on x.workspace_id=r.workspace_id and x.id=r.unit_id where r.workspace_id=w and private.aqari_can_property(w,x.property_id,'properties','read')),'[]'));
 end if;
 ident:=(d->>'id')::uuid;p:=(d->>'property_id')::uuid;
 if ident is null or p is null or not (private.aqari_can_property(w,p,'properties','write') or private.aqari_can_property(w,p,'maintenance','write')) then raise insufficient_privilege using message='ACCESS_DENIED';end if;
 perform private.aqari_require_sensitive_aal2(w);
 number:=translate(btrim(coalesce(d->>'unit_no','')),'٠١٢٣٤٥٦٧٨٩','0123456789');
 if length(number) not between 1 and 80 or number~'[[:cntrl:]<>]' or coalesce(d->>'state','') not in ('ready','not_ready','review_required') or coalesce(d->>'expected_revision','')!~'^[0-9]{1,15}$' or coalesce(d->>'inspected_on','')!~'^[0-9]{4}-[0-9]{2}-[0-9]{2}$' or length(btrim(coalesce(d->>'source_ref',''))) not between 3 and 500 or length(btrim(coalesce(d->>'reason',''))) not between 3 and 500 then raise check_violation using message='INVALID_READINESS_RECORD';end if;
 expected:=(d->>'expected_revision')::bigint;observed:=(d->>'inspected_on')::date;
 if observed>(now() at time zone 'Asia/Kuwait')::date then raise check_violation using message='INVALID_READINESS_DATE';end if;
 select * into u from public.aqari_units where workspace_id=w and property_id=p and unit_no=number for update;
 if u.id is null then
  if not private.aqari_can_property(w,p,'properties','write') then raise insufficient_privilege using message='ACCESS_DENIED';end if;
  insert into public.aqari_units(id,workspace_id,property_id,unit_no) values(md5(p::text||':unit:'||number)::uuid,w,p,number) on conflict(workspace_id,property_id,unit_no) do nothing;
  select * into u from public.aqari_units where workspace_id=w and property_id=p and unit_no=number for update;
 end if;
 select * into saved from private.aqari_unit_readiness where id=ident;
 if found then
  if saved.workspace_id<>w or saved.unit_id<>u.id or saved.revision<>expected+1 or saved.state<>d->>'state' or saved.inspected_on<>observed or saved.source_ref<>btrim(d->>'source_ref') or saved.reason<>btrim(d->>'reason') then raise unique_violation using message='READINESS_IDEMPOTENCY_CONFLICT';end if;
  return to_jsonb(saved);
 end if;
 select coalesce(max(revision),0) into version from private.aqari_unit_readiness where workspace_id=w and unit_id=u.id;
 if version<>expected then raise serialization_failure using message='REVISION_CONFLICT';end if;
 insert into private.aqari_unit_readiness(id,workspace_id,unit_id,revision,state,inspected_on,source_ref,reason,recorded_by)
 values(ident,w,u.id,version+1,d->>'state',observed,btrim(d->>'source_ref'),btrim(d->>'reason'),auth.uid()) returning * into saved;
 return to_jsonb(saved);
end$function$

CREATE OR REPLACE FUNCTION public.aqari_vacating_release(p_workspace_id uuid, p_lease_id uuid, p_revision bigint)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
 w uuid:=p_workspace_id;lid uuid:=p_lease_id;expected bigint:=p_revision;
 s private.aqari_vacating_settlements;l public.aqari_leases;app public.aqari_app_state;
 actor text;balances jsonb;clearance_balances jsonb;data jsonb;contract jsonb;updated_contract jsonb;ref text;release_payload jsonb;
 deposit_json jsonb;handover_docs jsonb;open_maintenance bigint;open_utilities bigint;future_payments bigint;uncertain_payments bigint;
begin
 if auth.uid() is null or not private.aqari_manager(w)
  or not private.aqari_can_lease(w,lid,'contracts','write')
  or not private.aqari_can_lease(w,lid,'collections','read')
  or not private.aqari_can(w,'documents','read') then
  raise insufficient_privilege using message='ACCESS_DENIED';
 end if;
 if expected is null or expected<1 then raise exception 'VACATING_INVALID_RELEASE' using errcode='22023';end if;

 -- Same lock order as financial/vacating writes.
 select * into app from public.aqari_app_state where workspace_id=w for update;
 if not found then raise exception 'VACATING_WORKSPACE_UNAVAILABLE' using errcode='22023';end if;
 select * into l from public.aqari_leases where workspace_id=w and id=lid for update;
 if not found then raise exception 'VACATING_LEASE_NOT_FOUND' using errcode='22023';end if;
 select * into s from private.aqari_vacating_settlements where workspace_id=w and lease_id=lid for update;
 if not found then raise exception 'VACATING_DRAFT_REQUIRED' using errcode='22023';end if;

 -- Lost-response recovery: completed release is returned only when canonical lease still matches it.
 if s.status='released' then
  if l.status<>'expired' or l.vacated_on is distinct from s.vacate_date then
   raise exception 'VACATING_RELEASE_INCONSISTENT' using errcode='40001';
  end if;
  return jsonb_build_object('settlement',private.aqari_vacating_json(w,lid),
   'lease',jsonb_build_object('id',l.id,'status',l.status,'vacated_on',l.vacated_on,'contract_end_date',l.end_date));
 end if;
 if s.status<>'cleared' or s.clearance_no is null or s.clearance_snapshot is null then
  raise exception 'VACATING_CLEARANCE_REQUIRED' using errcode='22023';
 end if;
 if s.revision<>expected then raise exception 'VACATING_REVISION_CONFLICT' using errcode='40001';end if;
 if l.status not in('signed','expired') then raise exception 'VACATING_ACTIVE_CONTRACT_REQUIRED' using errcode='22023';end if;
 if l.vacated_on is not null and l.vacated_on<>s.vacate_date then raise exception 'VACATING_RELEASE_INCONSISTENT' using errcode='40001';end if;

 -- Clearance is not enough if financial facts changed afterwards.
 balances:=private.aqari_vacating_balances(w,lid,s.vacate_date);
 clearance_balances:=s.clearance_snapshot->'clearance_balances';
 if not coalesce(private.aqari_clearance_balances_compatible(w,lid,clearance_balances,balances),false) then
  raise exception 'VACATING_RELEASE_BALANCE_CHANGED' using errcode='40001';
 end if;
 perform private.aqari_financial_open(w,s.vacate_date);

 -- PR #71 reconciliation: real handover evidence must be an uploaded immutable file with checksum.
 select coalesce(jsonb_agg(jsonb_build_object('id',d.id,'document_no',d.document_no,'sha256',d.checksum_sha256,'category',d.metadata->>'document_category','purpose',d.metadata->>'purpose') order by d.created_at),'[]'::jsonb)
 into handover_docs from public.aqari_documents d
 where d.workspace_id=w and d.entity_type='lease' and d.entity_ref in(l.external_ref,l.id::text)
  and d.status='uploaded' and d.checksum_sha256 is not null and coalesce(d.size_bytes,0)>0
  and ((d.metadata->>'document_category')='vacating_inspection' or (d.metadata->>'purpose')='vacating_handover');
 if jsonb_array_length(handover_docs)=0 then raise exception 'VACATING_HANDOVER_REQUIRED' using errcode='22023';end if;

 select count(*) into open_maintenance from public.aqari_maintenance_requests m
  where m.workspace_id=w and m.lease_id=lid and m.status not in('completed','cancelled','canceled');
 if open_maintenance>0 then raise exception 'VACATING_OPEN_MAINTENANCE' using errcode='22023';end if;

 -- Conservative utility rule from PR #71: unresolved property bills are not silently assigned away.
 select count(*) into open_utilities from public.aqari_utility_entries e
  join public.aqari_units u on u.workspace_id=w and u.id=l.unit_id
  where e.workspace_id=w and e.property_id=u.property_id and e.entry_type='bill'
   and (e.amount_due is null or e.amount_paid is null or e.amount_due>e.amount_paid or e.payment_status<>'paid');
 if open_utilities>0 then raise exception 'VACATING_OPEN_UTILITIES' using errcode='22023';end if;

 select count(*) into future_payments from public.aqari_rent_payments p
  where p.workspace_id=w and p.lease_id=lid and p.period>date_trunc('month',s.vacate_date)::date
   and p.status in('مدفوع','جزئي','paid','partial');
 if future_payments>0 then raise exception 'VACATING_FUTURE_PAYMENT_REVIEW_REQUIRED' using errcode='22023';end if;
 select count(*) into uncertain_payments from public.aqari_rent_payments p
  where p.workspace_id=w and p.lease_id=lid
   and p.status not in('مدفوع','جزئي','paid','partial','cancelled','canceled','voided','ملغي','ملغى');
 if uncertain_payments>0 then raise exception 'VACATING_UNCERTAIN_PAYMENT' using errcode='22023';end if;

 deposit_json:=private.aqari_deposit_lease_json(w,lid);
 if nullif(l.snapshot->>'depositReceivedOn','') is not null and coalesce((deposit_json->>'received')::numeric,0)=0 then
  raise exception 'VACATING_DEPOSIT_HISTORY_REQUIRED' using errcode='22023';
 end if;
 if l.import_source is not null and not exists(
  select 1 from public.aqari_source_lease_reviews r where r.workspace_id=w and r.lease_id=lid and r.action='sign') then
  raise exception 'VACATING_SOURCE_REVIEW_REQUIRED' using errcode='22023';
 end if;

 select coalesce(nullif(p.display_name,''),auth.uid()::text) into actor from public.aqari_profiles p where p.user_id=auth.uid();
 release_payload:=jsonb_build_object(
  'lease_id',l.id,'contract_no',l.contract_no,'unit_id',l.unit_id,'original_contract_end_date',l.end_date,
  'effective_occupancy_end',s.vacate_date,'clearance_no',s.clearance_no,'clearance_snapshot',s.clearance_snapshot,
  'handover_documents',handover_docs,'open_maintenance',open_maintenance,'open_utilities',open_utilities,
  'future_confirmed_payments',future_payments,'uncertain_payments',uncertain_payments,
  'released_by',coalesce(actor,auth.uid()::text),'released_at',now());

 -- Canonical lease projection: preserve end_date, terminate occupancy and release the unit for the following day.
 update public.aqari_leases set status='expired',vacated_on=s.vacate_date where workspace_id=w and id=lid;

 -- Keep the legacy app-state projection consistent when the original contract is present there.
 data:=private.aqari_unwrap(app.payload);ref:=l.external_ref;
 select x into contract from jsonb_array_elements(coalesce(data->'contractsV202','[]'::jsonb)) x where x->>'id'=ref limit 1;
 if contract is not null then
  updated_contract:=contract||jsonb_build_object('status','expired','vacatedOn',s.vacate_date,'changeReason','vacating-clearance-release');
  data:=jsonb_set(data,'{contractsV202}',coalesce((select jsonb_agg(case when x->>'id'=ref then updated_contract else x end order by n)
   from jsonb_array_elements(coalesce(data->'contractsV202','[]'::jsonb)) with ordinality a(x,n)),'[]'::jsonb));
  update public.aqari_app_state set payload=case
   when app.payload->>'format'='aqari-cloud-state-v1' then jsonb_set(app.payload,'{snapshot,values,aqari_v30}',data)
   when app.payload->>'schema'='aqari-local-snapshot-v1' then jsonb_set(app.payload,'{values,aqari_v30}',data)
   else data end,
   revision=app.revision+1,updated_by=auth.uid(),updated_at=now() where workspace_id=w;
 end if;

 update private.aqari_vacating_settlements set status='released',revision=revision+1,
  released_by=auth.uid(),released_by_name=coalesce(actor,auth.uid()::text),released_at=now(),release_snapshot=release_payload,
  updated_by=auth.uid(),updated_at=now() where workspace_id=w and lease_id=lid;
 update public.aqari_notification_outbox set status='cancelled'
  where workspace_id=w and lease_id=lid and status in('awaiting_configuration','queued') and kind='rent_reminder';

 select * into l from public.aqari_leases where workspace_id=w and id=lid;
 return jsonb_build_object('settlement',private.aqari_vacating_json(w,lid),
  'lease',jsonb_build_object('id',l.id,'status',l.status,'vacated_on',l.vacated_on,'contract_end_date',l.end_date),
  'handover_documents',handover_docs);
end $function$

CREATE OR REPLACE FUNCTION public.aqari_vacating_review(p_workspace_id uuid, p_action text, p_data jsonb DEFAULT '{}'::jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare w uuid:=p_workspace_id;d jsonb:=p_data;a text:=p_action;k text;allowed text[];lid uuid;ident uuid;
 current_review private.aqari_vacating_reviews;old_review private.aqari_vacating_reviews;latest_revision integer;
 evidence jsonb;normalized jsonb;v_date date;value numeric;actor text;rows jsonb;
begin
 if auth.uid() is null or not private.aqari_manager(w) or not private.aqari_can(w,'contracts','read') or not private.aqari_can(w,'collections','read') then
  raise insufficient_privilege using message='ACCESS_DENIED';end if;
 if d is null or jsonb_typeof(d)<>'object' or octet_length(d::text)>20000 then raise exception 'VACATING_INVALID_DATA' using errcode='22023';end if;
 allowed:=case a when 'list' then array[]::text[] when 'read' then array['lease_id'] when 'get' then array['id']
  when 'save' then array['id','lease_id','revision','evidence_token','vacate_date','keys_returned','inspection_complete','utilities_verified','rent_due','utilities_due','damage_due','other_due','reason'] else null end;
 if allowed is null then raise exception 'VACATING_ACTION_UNAVAILABLE' using errcode='22023';end if;
 for k in select jsonb_object_keys(d) loop if not(k=any(allowed)) then raise exception 'VACATING_UNKNOWN_FIELD' using errcode='22023';end if;end loop;
 if a='list' then
  if (select count(*) from public.aqari_leases where workspace_id=w)>2000 then raise exception 'VACATING_LIST_LIMIT' using errcode='22023';end if;
  select coalesce(jsonb_agg(private.aqari_deposit_lease_json(w,l.id) order by l.contract_no,l.id),'[]') into rows
   from public.aqari_leases l where l.workspace_id=w and private.aqari_can_lease(w,l.id,'contracts','read') and private.aqari_can_lease(w,l.id,'collections','read');
  return jsonb_build_object('leases',rows);
 end if;
 if a in ('get','save') then
  if jsonb_typeof(d->'id') is distinct from 'string' then raise exception 'VACATING_INVALID_ID' using errcode='22023';end if;
  ident:=(d->>'id')::uuid;
 end if;
 if a='get' then
  select * into old_review from private.aqari_vacating_reviews where workspace_id=w and id=ident;
  if not found then return jsonb_build_object('review',null);end if;
  lid:=old_review.lease_id;
 else
  if jsonb_typeof(d->'lease_id') is distinct from 'string' then raise exception 'VACATING_INVALID_LEASE' using errcode='22023';end if;
  lid:=(d->>'lease_id')::uuid;
 end if;
 if not private.aqari_can_lease(w,lid,'contracts','read') or not private.aqari_can_lease(w,lid,'collections','read') then raise insufficient_privilege using message='ACCESS_DENIED';end if;
 if a='get' then return jsonb_build_object('review',to_jsonb(old_review));end if;
 -- Match workspace/lease lock ordering of deposits and application-state writes.
 -- Read evidence under the same lock used for saves, then compare again at save.
 perform 1 from public.aqari_app_state where workspace_id=w for update;
 if not found then raise exception 'VACATING_WORKSPACE_UNAVAILABLE' using errcode='22023';end if;
 perform 1 from public.aqari_leases where workspace_id=w and id=lid for update;
 if not found then raise insufficient_privilege using message='ACCESS_DENIED';end if;
 if (select count(*) from public.aqari_rent_payments where workspace_id=w and lease_id=lid)>2000 or
    (select count(*) from private.aqari_deposit_entries where workspace_id=w and lease_id=lid)>2000 then raise exception 'VACATING_EVIDENCE_LIMIT' using errcode='22023';end if;
 evidence:=private.aqari_vacating_evidence(w,lid);
 select * into current_review from private.aqari_vacating_reviews where workspace_id=w and lease_id=lid order by revision desc limit 1;
 latest_revision:=coalesce(current_review.revision,0);
 if a='read' then
  return jsonb_build_object('review',case when latest_revision=0 then null else to_jsonb(current_review) end,
   'can_edit',private.aqari_can_lease(w,lid,'contracts','write'),'revision',latest_revision,'evidence',evidence,'evidence_token',md5(evidence::text),
   'stale',latest_revision>0 and current_review.evidence<>evidence,'can_finalize',false,
   'blockers',jsonb_build_array('OBLIGATIONS_RECONCILIATION_REQUIRED','REVIEW_ONLY'));
 end if;
 if not private.aqari_can_lease(w,lid,'contracts','write') then raise insufficient_privilege using message='ACCESS_DENIED';end if;
 if jsonb_typeof(d->'revision') is distinct from 'number' or d->>'revision' !~ '^[0-9]{1,8}$' then raise exception 'VACATING_INVALID_REVISION' using errcode='22023';end if;
 if jsonb_typeof(d->'evidence_token') is distinct from 'string' or d->>'evidence_token' !~ '^[a-f0-9]{32}$' then raise exception 'VACATING_INVALID_EVIDENCE' using errcode='22023';end if;
 if jsonb_typeof(d->'vacate_date') is distinct from 'string' or d->>'vacate_date' !~ '^\d{4}-\d{2}-\d{2}$' then raise exception 'VACATING_INVALID_DATE' using errcode='22023';end if;
 v_date:=(d->>'vacate_date')::date;
 if evidence#>>'{contract,start_date}' is null or v_date<(evidence#>>'{contract,start_date}')::date then raise exception 'VACATING_BEFORE_CONTRACT' using errcode='22023';end if;
 foreach k in array array['keys_returned','inspection_complete','utilities_verified'] loop
  if jsonb_typeof(d->k) is distinct from 'boolean' then raise exception 'VACATING_INVALID_CHECKLIST' using errcode='22023';end if;
 end loop;
 if jsonb_typeof(d->'reason') is distinct from 'string' or length(btrim(d->>'reason')) not between 3 and 2000 then raise exception 'VACATING_REASON_REQUIRED' using errcode='22023';end if;
 normalized:=d||jsonb_build_object('id',ident,'lease_id',lid,'vacate_date',v_date,'reason',btrim(d->>'reason'));
 foreach k in array array['rent_due','utilities_due','damage_due','other_due'] loop
  if not(d ? k) then raise exception 'VACATING_INVALID_AMOUNT' using errcode='22023';end if;
  if d->k='null'::jsonb then continue;end if;
  if jsonb_typeof(d->k) is distinct from 'string' or d->>k !~ '^[0-9]{1,12}(\.[0-9]{1,3})?$' then raise exception 'VACATING_INVALID_AMOUNT' using errcode='22023';end if;
  value:=(d->>k)::numeric;
  normalized:=normalized||jsonb_build_object(k,value::numeric(15,3)::text);
 end loop;
 select * into old_review from private.aqari_vacating_reviews where workspace_id=w and id=ident;
 if found then
  if old_review.actor_id<>auth.uid() or old_review.request_data<>normalized then raise exception 'VACATING_REQUEST_CONFLICT' using errcode='22023';end if;
  return jsonb_build_object('review',to_jsonb(old_review));
 end if;
 if latest_revision<>(d->>'revision')::integer then raise exception 'VACATING_REVISION_CONFLICT' using errcode='22023';end if;
 if md5(evidence::text)<>d->>'evidence_token' then raise exception 'VACATING_EVIDENCE_CHANGED' using errcode='22023';end if;
 if evidence#>>'{contract,status}' not in ('signed','expired') then raise exception 'VACATING_SIGNED_CONTRACT_REQUIRED' using errcode='22023';end if;
 select coalesce(nullif(display_name,''),auth.uid()::text) into actor from public.aqari_profiles where user_id=auth.uid();
 insert into private.aqari_vacating_reviews(id,workspace_id,lease_id,revision,actor_id,actor_name,request_data,evidence)
 values(ident,w,lid,latest_revision+1,auth.uid(),coalesce(actor,auth.uid()::text),normalized,evidence) returning * into current_review;
 return jsonb_build_object('review',to_jsonb(current_review));
end $function$

CREATE OR REPLACE FUNCTION public.aqari_vacating_settlement(p_workspace_id uuid, p_action text, p_data jsonb DEFAULT '{}'::jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare w uuid:=p_workspace_id;d jsonb:=coalesce(p_data,'{}');action text:=p_action;k text;allowed text[];lid uuid;s private.aqari_vacating_settlements;lease_record public.aqari_leases;
 vdate date;damage numeric;why text;ref text;revision_value bigint;balances jsonb;actor text;snapshot jsonb;rows jsonb;leases jsonb;seq text;
begin
 if auth.uid() is null or not private.aqari_can(w,'contracts','read') then raise insufficient_privilege using message='ACCESS_DENIED';end if;
 if jsonb_typeof(d)<>'object' or octet_length(d::text)>12000 then raise exception 'VACATING_INVALID_DATA' using errcode='22023';end if;
 allowed:=case action when 'list' then array[]::text[] when 'get' then array['lease_id']
  when 'save' then array['lease_id','vacate_date','keys_returned','inspection_completed','meters_recorded','damage_amount','damage_notes','charges_resolved','charges_reference','revision']
  when 'finalize' then array['lease_id','revision'] when 'clearance' then array['lease_id','revision','exception_reason'] else null end;
 if allowed is null then raise exception 'VACATING_UNKNOWN_ACTION' using errcode='22023';end if;
 for k in select jsonb_object_keys(d) loop if not(k=any(allowed)) then raise exception 'VACATING_UNKNOWN_FIELD' using errcode='22023';end if;end loop;
 if action='list' then
  select coalesce(jsonb_agg(jsonb_build_object('id',l.id,'contract_no',l.contract_no,'tenant_name',t.full_name,'property_name',p.name,'unit_no',u.unit_no,'status',l.status) order by l.contract_no),'[]') into leases
  from public.aqari_leases l join public.aqari_tenants t on t.workspace_id=w and t.id=l.tenant_id join public.aqari_units u on u.workspace_id=w and u.id=l.unit_id join public.aqari_properties p on p.workspace_id=w and p.id=u.property_id
  where l.workspace_id=w and private.aqari_can_lease(w,l.id,'contracts','read');
  select coalesce(jsonb_agg(private.aqari_vacating_json(w,x.lease_id) order by x.updated_at desc),'[]') into rows from private.aqari_vacating_settlements x where x.workspace_id=w and private.aqari_can_lease(w,x.lease_id,'contracts','read');
  return jsonb_build_object('manager',private.aqari_manager(w),'leases',leases,'settlements',rows);
 end if;
 if jsonb_typeof(d->'lease_id') is distinct from 'string' then raise exception 'VACATING_INVALID_LEASE' using errcode='22023';end if;
 lid:=(d->>'lease_id')::uuid;
 if not private.aqari_can_lease(w,lid,'contracts',case when action in('save','finalize','clearance') then 'write' else 'read' end) then raise insufficient_privilege using message='ACCESS_DENIED';end if;
 if action='get' then
  if not exists(select 1 from private.aqari_vacating_settlements x where x.workspace_id=w and x.lease_id=lid) then return jsonb_build_object('settlement',null,'balances',null);end if;
  return jsonb_build_object('settlement',private.aqari_vacating_json(w,lid));
 end if;
 if action='save' then
  if not private.aqari_can(w,'contracts','write') then raise insufficient_privilege using message='ACCESS_DENIED';end if;
  if jsonb_typeof(d->'vacate_date') is distinct from 'string' or d->>'vacate_date' !~ '^\d{4}-\d{2}-\d{2}$' then raise exception 'VACATING_INVALID_DATE' using errcode='22023';end if;
  vdate:=(d->>'vacate_date')::date;
  select * into lease_record from public.aqari_leases where workspace_id=w and id=lid for update;
  if not found or lease_record.status<>'signed' or lease_record.start_date is null or vdate<lease_record.start_date or vdate>(now() at time zone 'Asia/Kuwait')::date then raise exception 'VACATING_INVALID_DATE' using errcode='22023';end if;
  if jsonb_typeof(d->'keys_returned') is distinct from 'boolean' or jsonb_typeof(d->'inspection_completed') is distinct from 'boolean' or jsonb_typeof(d->'meters_recorded') is distinct from 'boolean' or jsonb_typeof(d->'charges_resolved') is distinct from 'boolean' then raise exception 'VACATING_INVALID_CHECKLIST' using errcode='22023';end if;
  if jsonb_typeof(d->'damage_amount') is distinct from 'string' or d->>'damage_amount' !~ '^[0-9]{1,12}(\.[0-9]{1,3})?$' then raise exception 'VACATING_INVALID_DAMAGE' using errcode='22023';end if;
  damage:=(d->>'damage_amount')::numeric;why:=btrim(coalesce(d->>'damage_notes',''));ref:=btrim(coalesce(d->>'charges_reference',''));
  if length(why)>1000 or (damage>0 and length(why)<3) or length(ref)>160 or ((d->>'charges_resolved')::boolean and damage>0 and length(ref)<3) then raise exception 'VACATING_INVALID_DAMAGE' using errcode='22023';end if;
  revision_value:=coalesce((d->>'revision')::bigint,0);
  insert into private.aqari_vacating_settlements(workspace_id,lease_id,vacate_date,keys_returned,inspection_completed,meters_recorded,damage_amount,damage_notes,charges_resolved,charges_reference,created_by,updated_by)
  values(w,lid,vdate,(d->>'keys_returned')::boolean,(d->>'inspection_completed')::boolean,(d->>'meters_recorded')::boolean,damage,why,(d->>'charges_resolved')::boolean,ref,auth.uid(),auth.uid())
  on conflict(workspace_id,lease_id) do update set vacate_date=excluded.vacate_date,keys_returned=excluded.keys_returned,inspection_completed=excluded.inspection_completed,meters_recorded=excluded.meters_recorded,
   damage_amount=excluded.damage_amount,damage_notes=excluded.damage_notes,charges_resolved=excluded.charges_resolved,charges_reference=excluded.charges_reference,updated_by=auth.uid(),updated_at=now(),revision=private.aqari_vacating_settlements.revision+1
   where private.aqari_vacating_settlements.status='draft' and private.aqari_vacating_settlements.revision=revision_value;
  if not found then raise exception 'VACATING_REVISION_CONFLICT' using errcode='22023';end if;
  return jsonb_build_object('settlement',private.aqari_vacating_json(w,lid));
 end if;
 if not private.aqari_manager(w) then raise insufficient_privilege using message='ACCESS_DENIED';end if;
 perform 1 from public.aqari_app_state where workspace_id=w for update;
 select * into s from private.aqari_vacating_settlements where workspace_id=w and lease_id=lid for update;
 if not found then raise exception 'VACATING_DRAFT_REQUIRED' using errcode='22023';end if;
 revision_value:=coalesce((d->>'revision')::bigint,0);if s.revision<>revision_value then raise exception 'VACATING_REVISION_CONFLICT' using errcode='22023';end if;
 if action='finalize' then
  if s.status<>'draft' then return jsonb_build_object('settlement',private.aqari_vacating_json(w,lid));end if;
  if not s.keys_returned or not s.inspection_completed or not s.meters_recorded then raise exception 'VACATING_CHECKLIST_OPEN' using errcode='22023';end if;
  if s.damage_amount>0 and not s.charges_resolved then raise exception 'VACATING_DAMAGE_OPEN' using errcode='22023';end if;
  balances:=private.aqari_vacating_balances(w,lid,s.vacate_date);
  select coalesce(nullif(p.display_name,''),auth.uid()::text) into actor from public.aqari_profiles p where p.user_id=auth.uid();
  seq:=nextval('private.aqari_vacating_settlement_seq')::text;
  snapshot:=private.aqari_vacating_json(w,lid)||jsonb_build_object('final_balances',balances,'finalized_by',coalesce(actor,auth.uid()::text));
  update private.aqari_vacating_settlements set status='finalized',revision=revision+1,updated_by=auth.uid(),updated_at=now(),finalized_by=auth.uid(),finalized_by_name=coalesce(actor,auth.uid()::text),finalized_at=now(),
   settlement_no='VS-'||to_char(s.vacate_date,'YYYYMMDD')||'-'||lpad(seq,8,'0'),settlement_snapshot=snapshot where workspace_id=w and lease_id=lid;
  return jsonb_build_object('settlement',private.aqari_vacating_json(w,lid));
 end if;
 if s.status='cleared' then return jsonb_build_object('settlement',private.aqari_vacating_json(w,lid));end if;
 if s.status<>'finalized' then raise exception 'VACATING_FINALIZE_REQUIRED' using errcode='22023';end if;
 why:=btrim(coalesce(d->>'exception_reason',''));if length(why)>1000 then raise exception 'VACATING_INVALID_EXCEPTION' using errcode='22023';end if;
 balances:=private.aqari_vacating_balances(w,lid,s.vacate_date);
 if ((balances->>'rent_balance')::numeric>0 or (balances->>'tenant_credit')::numeric>0 or (balances->>'deposit_balance')::numeric>0 or (s.damage_amount>0 and not s.charges_resolved)) and length(why)<10 then raise exception 'VACATING_OUTSTANDING_BALANCE' using errcode='22023';end if;
 select coalesce(nullif(p.display_name,''),auth.uid()::text) into actor from public.aqari_profiles p where p.user_id=auth.uid();
 seq:=nextval('private.aqari_clearance_seq')::text;
 snapshot:=coalesce(s.settlement_snapshot,'{}')||jsonb_build_object('clearance_balances',balances,'exception_reason',why,'clearance_by',coalesce(actor,auth.uid()::text),'issued_at',now());
 update private.aqari_vacating_settlements set status='cleared',revision=revision+1,updated_by=auth.uid(),updated_at=now(),clearance_by=auth.uid(),clearance_by_name=coalesce(actor,auth.uid()::text),clearance_at=now(),
  clearance_no='CL-'||to_char((now() at time zone 'Asia/Kuwait')::date,'YYYYMMDD')||'-'||lpad(seq,8,'0'),clearance_snapshot=snapshot,exception_reason=why where workspace_id=w and lease_id=lid;
 return jsonb_build_object('settlement',private.aqari_vacating_json(w,lid));
end $function$

CREATE OR REPLACE FUNCTION private.aqari_allocation_weight_rows(w uuid, method text, rows jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare result jsonb;
begin
 if method='unit_count' then
  select coalesce(jsonb_agg(jsonb_build_object('propertyId',p.id,'weight',q.cnt) order by p.id),'[]'::jsonb) into result
  from (select distinct (r->>'propertyId')::uuid id from jsonb_array_elements(rows)r)p
  join lateral(select count(*)::numeric cnt from public.aqari_units u where u.workspace_id=w and u.property_id=p.id)q on true
  where q.cnt>0;
  if jsonb_array_length(result)<>jsonb_array_length(rows) then raise check_violation using message='ALLOCATION_UNIT_COUNT_REQUIRED';end if;
  return result;
 elsif method='area' then
  select coalesce(jsonb_agg(jsonb_build_object('propertyId',p.id,'weight',q.area) order by p.id),'[]'::jsonb) into result
  from (select distinct (r->>'propertyId')::uuid id from jsonb_array_elements(rows)r)p
  join lateral(select count(*) total,count(m.area_sqm) with_area,coalesce(sum(m.area_sqm),0)::numeric area
    from public.aqari_units u left join private.aqari_unit_master m on m.workspace_id=u.workspace_id and m.unit_id=u.id
    where u.workspace_id=w and u.property_id=p.id)q on true
  where q.total>0 and q.total=q.with_area and q.area>0;
  if jsonb_array_length(result)<>jsonb_array_length(rows) then raise check_violation using message='ALLOCATION_COMPLETE_AREA_REQUIRED';end if;
  return result;
 elsif method='custom' then
  return rows;
 end if;
 return rows;
end $function$

CREATE OR REPLACE FUNCTION private.aqari_audit_contract_versions()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare c jsonb;previous jsonb;actor text;d jsonb:=private.aqari_unwrap(new.payload);old_d jsonb:=private.aqari_unwrap(old.payload);
begin
 select display_name into actor from public.aqari_profiles where user_id=auth.uid();
 for c in select value from jsonb_array_elements(coalesce(d->'contractsV202','[]')) loop
  select x into previous from jsonb_array_elements(coalesce(old_d->'contractsV202','[]')) x where x->>'id'=c->>'id';
  if c=previous or c->>'source' is distinct from 'v267-cloud' then continue;end if;
  insert into private.aqari_contract_versions(workspace_id,contract_ref,actor_id,actor_name,reason,before_snapshot,after_snapshot) values(new.workspace_id,c->>'id',auth.uid(),coalesce(actor,auth.uid()::text),coalesce(nullif(c->>'changeReason',''),'إنشاء أو انتقال حالة عقد'),previous,c);
 end loop;return new;
end $function$

CREATE OR REPLACE FUNCTION private.aqari_can(w uuid, s text, a text)
 RETURNS boolean
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare b text;r text;cfg jsonb;v jsonb;allowed boolean;
begin
 if auth.uid() is null or a not in('read','write') then return false;end if;
 select role::text into b from public.aqari_memberships where workspace_id=w and user_id=auth.uid() and is_active;
 if b is null then return false;end if;
 if s='administration' then return b='general_manager';end if;
 if not(s=any(private.aqari_section_keys())) then return false;end if;
 select settings into cfg from public.aqari_workspace_controls where workspace_id=w;
 if b='general_manager' and a='read' then return true;end if;
 if coalesce((cfg#>>array['sections',s])::boolean,true)=false then return false;end if;
 if b='general_manager' then return true;end if;
 select operational_role into r from private.aqari_staff_assignments where workspace_id=w and user_id=auth.uid() and is_active and cardinality(property_ids)>0;
 if r is null or not private.aqari_staff_ceiling(r,s,a) then return false;end if;
 if a='write' and (b='viewer' or (b='accountant' and s in('properties','tenants','contracts','partners'))) then return false;end if;
 if a='read' and s='contracts' and (not private.aqari_can(w,'tenants','read') or not private.aqari_can(w,'properties','read')) then return false;end if;
 if a='read' and s='collections' and not private.aqari_can(w,'contracts','read') then return false;end if;
 allowed:=true;
 v:=cfg#>array['permissions','role:'||b,s,a];if v is not null then allowed:=(v#>>'{}')::boolean;end if;
 v:=cfg#>array['permissions','role:'||r,s,a];if v is not null then allowed:=(v#>>'{}')::boolean;end if;
 v:=cfg#>array['permissions','user:'||auth.uid()::text,s,a];if v is not null then allowed:=(v#>>'{}')::boolean;end if;
 return allowed and (a='read' or private.aqari_can(w,s,'read'));
end $function$

CREATE OR REPLACE FUNCTION private.aqari_capture_collection_attribution()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare actor uuid:=auth.uid(); actor_name text; source_value text;
begin
 source_value:=coalesce(nullif(btrim(new.record->>'collectorName'),''),nullif(btrim(new.record->>'collector'),''),nullif(btrim(new.record->>'accountant'),''),nullif(btrim(new.receipt->>'accountant'),''));
 if actor is not null and exists(select 1 from public.aqari_memberships m where m.workspace_id=new.workspace_id and m.user_id=actor and m.is_active) then
   select coalesce(nullif(p.display_name,''),actor::text) into actor_name from public.aqari_profiles p where p.user_id=actor;
   actor_name:=coalesce(actor_name,actor::text);
   insert into private.aqari_collection_attribution(payment_id,workspace_id,collector_user_id,collector_name_snapshot,source_name,source_kind)
   values(new.id,new.workspace_id,actor,actor_name,source_value,'authenticated') on conflict(payment_id) do nothing;
 elsif source_value is not null then
   insert into private.aqari_collection_attribution(payment_id,workspace_id,collector_name_snapshot,source_name,source_kind)
   values(new.id,new.workspace_id,source_value,source_value,'legacy_name') on conflict(payment_id) do nothing;
 else
   insert into private.aqari_collection_attribution(payment_id,workspace_id,source_kind)
   values(new.id,new.workspace_id,'system_unassigned') on conflict(payment_id) do nothing;
 end if;
 return new;
end $function$

CREATE OR REPLACE FUNCTION private.aqari_capture_partner_period()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare p record;income numeric:=0;expenses numeric:=0;icount bigint:=0;ecount bigint:=0;v jsonb;payments jsonb;exclusions jsonb;costs jsonb;reserves jsonb;commercial jsonb;matches boolean;
begin
 if new.snapshot->>'scope' is distinct from 'posted_rent_payments_and_approved_expenses_only' then return new;end if;
 perform 1 from public.aqari_app_state where workspace_id=new.workspace_id for update;
 select coalesce(sum(r.amount),0),count(*) into income,icount from public.aqari_rent_payments r
 where r.workspace_id=new.workspace_id and r.paid_at>=new.month and r.paid_at<(new.month+interval '1 month')::date
 and r.status in('paid','partial','مدفوع','جزئي') and not exists(select 1 from private.aqari_receipt_cancellations c where c.workspace_id=r.workspace_id and c.payment_id=r.id);
 select coalesce(sum(e.amount),0),count(*) into expenses,ecount from private.aqari_financial_expenses e where e.workspace_id=new.workspace_id and e.expense_date>=new.month and e.expense_date<(new.month+interval '1 month')::date and e.state='approved';
 matches:=coalesce((new.snapshot->>'rent_payments')::numeric=income and (new.snapshot->>'approved_expenses')::numeric=expenses
 and (new.snapshot->>'rent_payment_count')::bigint=icount and (new.snapshot->>'approved_expense_count')::bigint=ecount,false);
 for p in select * from public.aqari_properties where workspace_id=new.workspace_id order by id loop
  select coalesce(jsonb_agg(to_jsonb(r) order by r.id)filter(where r.status in('paid','partial','مدفوع','جزئي') and c.id is null),'[]'),
   coalesce(jsonb_agg(jsonb_build_object('payment',to_jsonb(r),'cancellation',to_jsonb(c))order by r.id)filter(where r.status not in('paid','partial','مدفوع','جزئي') or c.id is not null),'[]') into payments,exclusions
  from public.aqari_rent_payments r join public.aqari_leases l on l.workspace_id=r.workspace_id and l.id=r.lease_id
  join public.aqari_units u on u.workspace_id=l.workspace_id and u.id=l.unit_id
  left join private.aqari_receipt_cancellations c on c.workspace_id=r.workspace_id and c.payment_id=r.id
  where r.workspace_id=new.workspace_id and u.property_id=p.id and r.paid_at>=new.month and r.paid_at<(new.month+interval '1 month')::date;
  select coalesce(jsonb_agg(to_jsonb(e)order by e.id),'[]') into costs from private.aqari_financial_expenses e
   where e.workspace_id=new.workspace_id and e.property_id=p.id and e.expense_date>=new.month and e.expense_date<(new.month+interval '1 month')::date and e.state='approved';
  select coalesce(jsonb_agg(to_jsonb(r)order by r.id),'[]') into reserves from private.aqari_reserve_entries r
   where r.workspace_id=new.workspace_id and r.property_id=p.id and (r.created_at at time zone 'Asia/Kuwait')::date>=new.month and (r.created_at at time zone 'Asia/Kuwait')::date<(new.month+interval '1 month')::date;
  commercial:=private.aqari_partner_commercial_evidence(new.workspace_id,payments);
  v:=jsonb_build_object('version',1,'source_scope','posted_confirmed_rent_and_approved_expenses_and_reserve_movements_only','workspace_id',new.workspace_id,'property_id',p.id,'property_name',p.name,'month',new.month,
   'period_hash',private.aqari_partner_hash(new.snapshot),'workspace_period_matches',matches,'period_matches',matches and jsonb_array_length(commercial)=0,'commercial_allocations',commercial,'review_reason',case when jsonb_array_length(commercial)>0 then 'PARTNER_COMMERCIAL_ALLOCATION_REVIEW_REQUIRED' when not matches then 'PARTNER_CLOSE_TOTAL_MISMATCH' else null end,'payments',payments,'excluded_payments',exclusions,'expenses',costs,'reserves',reserves,
   'reserve_policy','period_hold_minus_release_once','income_fils',(select (coalesce(sum((x->>'amount')::numeric),0)*1000)::bigint::text from jsonb_array_elements(payments)x),
   'expense_fils',(select (coalesce(sum((x->>'amount')::numeric),0)*1000)::bigint::text from jsonb_array_elements(costs)x),
   'reserve_fils',(select (coalesce(sum((x->>'amount')::numeric*case when x->>'direction'='hold' then 1 else -1 end),0)*1000)::bigint::text from jsonb_array_elements(reserves)x));
  insert into private.aqari_partner_period_sources(workspace_id,property_id,month,source,source_hash,period_matches) values(new.workspace_id,p.id,new.month,v,private.aqari_partner_hash(v),matches and jsonb_array_length(commercial)=0);
 end loop;
 -- Independently check the property partition matches the authoritative totals.
 if (select coalesce(sum((s.source->>'income_fils')::numeric),0) from private.aqari_partner_period_sources s where s.workspace_id=new.workspace_id and s.month=new.month)<>income*1000
 or (select coalesce(sum((s.source->>'expense_fils')::numeric),0) from private.aqari_partner_period_sources s where s.workspace_id=new.workspace_id and s.month=new.month)<>expenses*1000 then
  raise exception 'PARTNER_CLOSE_PROPERTY_TOTAL_MISMATCH' using errcode='23514';
 end if;
 return new;
end$function$

CREATE OR REPLACE FUNCTION private.aqari_clearance_balances_compatible(w uuid, lid uuid, expected jsonb, actual jsonb)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare old_keys text[]:=array['rent_due_total','rent_paid_total','rent_balance','tenant_credit','deposit_balance'];
 allowed_keys text[]:=array['rent_due_total','rent_paid_total','rent_balance','tenant_credit','deposit_balance','rent_payment_total','commercial_allocated_from_payments','commercial_sales_due_total','commercial_sales_paid_total','commercial_sales_balance','unified_due_balance','commercial_collection_mode'];
begin
 if expected is null or actual is null or jsonb_typeof(expected)<>'object' or jsonb_typeof(actual)<>'object' then return false;end if;
 perform private.aqari_require_commercial_clearance(w,lid);
 if expected=actual then return true;end if;
 if (select count(*) from jsonb_object_keys(expected))<>5 or exists(select 1 from jsonb_object_keys(expected)k where not(k=any(old_keys)))
  or exists(select 1 from jsonb_object_keys(actual)k where not(k=any(allowed_keys))) then return false;end if;
 if exists(select 1 from unnest(old_keys)k where expected->k is distinct from actual->k) then return false;end if;
 if actual->>'commercial_collection_mode' is not null and actual->>'commercial_collection_mode'<>'independent_collection' then return false;end if;
 return actual->>'commercial_allocated_from_payments'='0.000'
  and actual->>'commercial_sales_due_total'='0.000' and actual->>'commercial_sales_paid_total'='0.000' and actual->>'commercial_sales_balance'='0.000'
  and actual->'rent_payment_total'=actual->'rent_paid_total'
  and actual->'unified_due_balance'=actual->'rent_balance';
end $function$

CREATE OR REPLACE FUNCTION private.aqari_collection_account_manage(w uuid, action text, d jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare a private.aqari_collection_accounts;event private.aqari_collection_account_audit;ident uuid;op uuid;request jsonb;before_row jsonb;actor text;reason text;expected integer;
begin
 if auth.uid() is null or not private.aqari_manager(w) then raise insufficient_privilege using message='ACCESS_DENIED';end if;
 if d is null or jsonb_typeof(d)<>'object' or octet_length(d::text)>6000 then raise invalid_parameter_value using message='INVALID_ACCOUNT_REQUEST';end if;
 if action not in('list','read','edit','archive') then raise invalid_parameter_value using message='INVALID_ACCOUNT_ACTION';end if;
 if action='list' then return jsonb_build_object('accounts',(select coalesce(jsonb_agg(to_jsonb(x)-'created_by' order by x.name,x.id),'[]') from private.aqari_collection_accounts x where x.workspace_id=w),
  'properties',(select coalesce(jsonb_agg(jsonb_build_object('id',x.id,'name',x.name) order by x.name),'[]')from public.aqari_properties x where x.workspace_id=w),
  'posting_accounts',(select coalesce(jsonb_agg(jsonb_build_object('posting_id',x.posting_id,'snapshot',x.snapshot,'captured_on_post',x.captured_on_post)),'[]')from private.aqari_collection_posting_accounts x where x.workspace_id=w));end if;
 ident:=nullif(d->>'id','')::uuid;op:=nullif(d->>'operation_id','')::uuid;
 if action in('edit','archive') then
  perform private.aqari_require_sensitive_aal2(w);
  perform 1 from public.aqari_app_state where workspace_id=w for update;
  if not found then raise insufficient_privilege using message='ACCESS_DENIED';end if;
 end if;
 if action='read' then select * into a from private.aqari_collection_accounts x where x.workspace_id=w and x.id=ident;
 else select * into a from private.aqari_collection_accounts x where x.workspace_id=w and x.id=ident for update;end if;
 if not found then raise insufficient_privilege using message='ACCESS_DENIED';end if;
 if action='read' then
  return jsonb_build_object('account',to_jsonb(a)-'created_by','events',(select coalesce(jsonb_agg(to_jsonb(x) order by x.recorded_at desc,x.operation_id),'[]')from(select * from private.aqari_collection_account_audit x where x.workspace_id=w and x.account_id=ident and (op is null or x.operation_id=op) order by x.recorded_at desc,x.operation_id limit 25)x));
 end if;
 reason:=btrim(coalesce(d->>'reason',''));expected:=(d->>'revision')::integer;
 if op is null or expected is null or expected<1 or length(reason) not between 3 and 1000 then raise check_violation using message='ACCOUNT_REVISION_AND_REASON_REQUIRED';end if;
 if exists(select 1 from jsonb_object_keys(d)k where k not in('id','operation_id','revision','reason','name','masked_reference')) then raise check_violation using message='ACCOUNT_IDENTITY_IMMUTABLE';end if;
 request:=jsonb_build_object('id',ident,'operation_id',op,'revision',expected,'reason',reason,'action',action);
 if action='edit' then
  if length(btrim(coalesce(d->>'name',''))) not between 2 and 160 or length(btrim(coalesce(d->>'masked_reference',''))) not between 1 and 80
   or length(regexp_replace(translate(d->>'masked_reference','٠١٢٣٤٥٦٧٨٩۰۱۲۳۴۵۶۷۸۹','01234567890123456789'),'[^0-9]','','g'))>4 then raise check_violation using message='ACCOUNT_NAME_OR_MASKED_REFERENCE_REQUIRED';end if;
  request:=request||jsonb_build_object('name',btrim(d->>'name'),'masked_reference',btrim(d->>'masked_reference'));
 elsif d?'name' or d?'masked_reference' then raise check_violation using message='ARCHIVE_CANNOT_EDIT_ACCOUNT';end if;
 select * into event from private.aqari_collection_account_audit x where x.workspace_id=w and x.operation_id=op;
 if found then
  if event.request is distinct from request or event.actor_id is distinct from auth.uid() then raise unique_violation using message='ACCOUNT_OPERATION_CONFLICT';end if;
  return jsonb_build_object('account',to_jsonb(a)-'created_by','operation_id',event.operation_id,'replayed',true);
 end if;
 if a.revision is distinct from expected then raise serialization_failure using message='REVISION_CONFLICT';end if;
 if a.status<>'active' then raise check_violation using message='ACCOUNT_ARCHIVED';end if;
 before_row:=to_jsonb(a);select coalesce(nullif(display_name,''),auth.uid()::text)into actor from public.aqari_profiles where user_id=auth.uid();actor:=coalesce(actor,auth.uid()::text);
 if action='edit' then
  if a.name=request->>'name' and a.masked_reference=request->>'masked_reference' then raise check_violation using message='ACCOUNT_UNCHANGED';end if;
  update private.aqari_collection_accounts x set name=request->>'name',masked_reference=request->>'masked_reference',revision=x.revision+1,updated_by=auth.uid(),updated_at=now() where x.id=ident and x.workspace_id=w returning * into a;
 else
  update private.aqari_collection_accounts x set status='archived',revision=x.revision+1,updated_by=auth.uid(),updated_at=now() where x.id=ident and x.workspace_id=w returning * into a;
 end if;
 insert into private.aqari_collection_account_audit(operation_id,workspace_id,account_id,action,request,actor_id,actor_name,reason,before_value,after_value)
 values(op,w,ident,action,request,auth.uid(),actor,reason,before_row,to_jsonb(a));
 return jsonb_build_object('account',to_jsonb(a)-'created_by','operation_id',op,'replayed',false);
end $function$

CREATE OR REPLACE FUNCTION private.aqari_collection_account_posting_guard()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare a private.aqari_collection_accounts;
begin
 -- Same workspace row lock as final-gap post_payment / financial_open, before account rows.
 perform 1 from public.aqari_app_state where workspace_id=new.workspace_id for update;
 if not found then raise insufficient_privilege using message='ACCESS_DENIED';end if;
 select * into a from private.aqari_collection_accounts where workspace_id=new.workspace_id and id=new.account_id for update;
 if not found or a.status<>'active' then raise exception 'ACCOUNT_ARCHIVED_OR_UNAVAILABLE' using errcode='23514';end if;
 insert into private.aqari_collection_posting_accounts(posting_id,workspace_id,account_id,snapshot,captured_on_post)
 values(new.id,new.workspace_id,new.account_id,jsonb_build_object('id',a.id,'property_id',a.property_id,'kind',a.kind,'name',a.name,'masked_reference',a.masked_reference,'currency',a.currency,'revision',a.revision),true);
 return new;
end $function$

CREATE OR REPLACE FUNCTION private.aqari_commercial_balance(w uuid, lid uuid, as_of date)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare charges numeric:=0;charge_reversals numeric:=0;receipts numeric:=0;receipt_reversals numeric:=0;rows jsonb;
begin
 if auth.uid() is null or not private.aqari_can(w,'finance','read') or not private.aqari_can_lease(w,lid,'finance','read') then raise insufficient_privilege using message='ACCESS_DENIED';end if;
 if as_of is null or as_of>(now() at time zone 'Asia/Kuwait')::date then raise invalid_parameter_value using message='INVALID_COMMERCIAL_AS_OF';end if;
 -- Keep the totals and event lines on one serialized financial history even
 -- when this helper is called independently by another statement/report RPC.
 perform 1 from public.aqari_app_state where workspace_id=w for share;
 if not found then raise insufficient_privilege using message='ACCESS_DENIED';end if;
 perform private.aqari_assert_commercial_collections(w,lid);
 select coalesce(sum(s.amount),0) into charges from private.aqari_commercial_sales s where s.workspace_id=w and s.lease_id=lid and s.period_end<=as_of;
 select coalesce(sum(s.amount),0) into charge_reversals from private.aqari_commercial_sales_reversals r join private.aqari_commercial_sales s on s.workspace_id=r.workspace_id and s.id=r.sale_id where r.workspace_id=w and s.lease_id=lid and r.occurred_on<=as_of;
 select coalesce(sum(c.amount),0) into receipts from private.aqari_commercial_collections c where c.workspace_id=w and c.lease_id=lid and c.occurred_on<=as_of;
 select coalesce(sum(r.amount),0) into receipt_reversals from private.aqari_commercial_collection_reversals r join private.aqari_commercial_collections c on c.workspace_id=r.workspace_id and c.id=r.collection_id where r.workspace_id=w and c.lease_id=lid and r.occurred_on<=as_of;
 select coalesce(jsonb_agg(jsonb_build_object('id',x.id,'source_type',x.source_type,'occurred_on',x.occurred_on,'amount',to_char(x.amount,'FM999999999999990.000'),'direction',x.direction,'sale_id',x.sale_id,'collection_id',x.collection_id,'reference',x.reference) order by x.occurred_on,x.source_type,x.id),'[]') into rows from (
  select s.id,'commercial_sales'::text source_type,s.period_end occurred_on,s.amount,'debit'::text direction,s.id sale_id,null::uuid collection_id,s.source_reference reference from private.aqari_commercial_sales s where s.workspace_id=w and s.lease_id=lid and s.period_end<=as_of
  union all select r.id,'commercial_sales_reversal',r.occurred_on,s.amount,'credit',s.id,null,r.reason from private.aqari_commercial_sales_reversals r join private.aqari_commercial_sales s on s.workspace_id=r.workspace_id and s.id=r.sale_id where r.workspace_id=w and s.lease_id=lid and r.occurred_on<=as_of
  union all select c.id,'commercial_collection',c.occurred_on,c.amount,'credit',null,c.id,c.reference from private.aqari_commercial_collections c where c.workspace_id=w and c.lease_id=lid and c.occurred_on<=as_of
  union all select r.id,'commercial_collection_reversal',r.occurred_on,r.amount,'debit',null,c.id,r.reason from private.aqari_commercial_collection_reversals r join private.aqari_commercial_collections c on c.workspace_id=r.workspace_id and c.id=r.collection_id where r.workspace_id=w and c.lease_id=lid and r.occurred_on<=as_of
 )x;
 return jsonb_build_object('lease_id',lid,'as_of',as_of,'charge_total',to_char(charges,'FM999999999999990.000'),'reversed_charge_total',to_char(charge_reversals,'FM999999999999990.000'),'collected_total',to_char(receipts,'FM999999999999990.000'),'collection_reversed_total',to_char(receipt_reversals,'FM999999999999990.000'),'balance',to_char(charges-charge_reversals-receipts+receipt_reversals,'FM999999999999990.000'),'lines',rows);
end $function$

CREATE OR REPLACE FUNCTION private.aqari_commercial_collection_write_guard()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare lid uuid;begin
 perform 1 from public.aqari_app_state where workspace_id=new.workspace_id for update;
 if tg_table_name='aqari_commercial_collections' then lid:=new.lease_id;
 else select c.lease_id into strict lid from private.aqari_commercial_collections c where c.workspace_id=new.workspace_id and c.id=new.collection_id;end if;
 perform private.aqari_financial_open(new.workspace_id,new.occurred_on);
 if private.aqari_commercial_legacy_history(new.workspace_id,lid) then raise check_violation using message='COMMERCIAL_COLLECTION_LEGACY_MODE_REQUIRED';end if;
 if exists(select 1 from public.aqari_leases l where l.workspace_id=new.workspace_id and l.id=lid and l.vacated_on is not null)
  or exists(select 1 from private.aqari_vacating_settlements s where s.workspace_id=new.workspace_id and s.lease_id=lid and s.status in('cleared','released')) then raise check_violation using message='COMMERCIAL_COLLECTION_AFTER_CLEARANCE';end if;
 return new;
end $function$

CREATE OR REPLACE FUNCTION private.aqari_commercial_collections_register(w uuid, action text, d jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare actor uuid:=auth.uid();lid uuid;ident uuid;account_ident uuid;posted date;as_of date;today date:=(now() at time zone 'Asia/Kuwait')::date;
 l public.aqari_leases;p public.aqari_properties;account private.aqari_collection_accounts;doc public.aqari_documents;
 c private.aqari_commercial_collections;r private.aqari_commercial_collection_reversals;s private.aqari_commercial_sales;
 item jsonb;request jsonb;allocations jsonb;amount_value numeric(15,3);allocated numeric(15,3);paid numeric;total numeric:=0;result jsonb;
begin
 if actor is null or not private.aqari_can(w,'finance','read') then raise insufficient_privilege using message='ACCESS_DENIED';end if;
 if jsonb_typeof(d) is distinct from 'object' or octet_length(d::text)>24000 or action is null or action not in('list','get','record','reverse') then raise invalid_parameter_value using message='INVALID_COMMERCIAL_COLLECTION_ACTION';end if;
 if action='list' then
  if exists(select 1 from jsonb_object_keys(d)k where k not in('lease_id','as_of')) then raise invalid_parameter_value using message='INVALID_COMMERCIAL_COLLECTION_REQUEST';end if;
  perform 1 from public.aqari_app_state where workspace_id=w for share;
  if not found then raise insufficient_privilege using message='ACCESS_DENIED';end if;
  as_of:=coalesce(nullif(d->>'as_of','')::date,today);lid:=nullif(d->>'lease_id','')::uuid;
  if as_of>today then raise invalid_parameter_value using message='INVALID_COMMERCIAL_AS_OF';end if;
  if lid is not null then
   if not private.aqari_can_lease(w,lid,'finance','read') then raise insufficient_privilege using message='ACCESS_DENIED';end if;
   select q.* into strict l from public.aqari_leases q where q.workspace_id=w and q.id=lid;
   select z.* into strict p from public.aqari_properties z join public.aqari_units u on u.workspace_id=z.workspace_id and u.property_id=z.id where u.workspace_id=w and u.id=l.unit_id;
  end if;
  if lid is not null and private.aqari_commercial_legacy_history(w,lid) then
   return jsonb_build_object('as_of',as_of,'mode','legacy_payment_allocation','unavailable_reason','COMMERCIAL_COLLECTION_LEGACY_MODE_REQUIRED','can_manage',false,
    'leases',(select coalesce(jsonb_agg(jsonb_build_object('id',q.id,'contract_no',q.contract_no,'external_ref',q.external_ref,'property_id',z.id,'property_ref',z.external_ref,'property_name',z.name,'collection_mode',case when private.aqari_commercial_legacy_history(w,q.id) then 'legacy_payment_allocation' else 'independent_collection' end) order by q.contract_no,q.id),'[]')
     from public.aqari_leases q join public.aqari_units u on u.workspace_id=q.workspace_id and u.id=q.unit_id join public.aqari_properties z on z.workspace_id=u.workspace_id and z.id=u.property_id
     where q.workspace_id=w and private.aqari_can_lease(w,q.id,'finance','read') and exists(select 1 from private.aqari_commercial_sales ss where ss.workspace_id=w and ss.lease_id=q.id)),
    'accounts','[]'::jsonb,'documents','[]'::jsonb,'statement',null,'sales','[]'::jsonb,'collections','[]'::jsonb);
  end if;
  return jsonb_build_object('as_of',as_of,'mode','independent_collection','unavailable_reason',null,'can_manage',private.aqari_manager(w) and private.aqari_can(w,'finance','write') and (lid is null or private.aqari_can_lease(w,lid,'finance','write')),'leases',(select coalesce(jsonb_agg(jsonb_build_object('id',q.id,'contract_no',q.contract_no,'external_ref',q.external_ref,'property_id',z.id,'property_ref',z.external_ref,'property_name',z.name,'collection_mode',case when private.aqari_commercial_legacy_history(w,q.id) then 'legacy_payment_allocation' else 'independent_collection' end) order by q.contract_no,q.id),'[]')
   from public.aqari_leases q join public.aqari_units u on u.workspace_id=q.workspace_id and u.id=q.unit_id join public.aqari_properties z on z.workspace_id=u.workspace_id and z.id=u.property_id
   where q.workspace_id=w and private.aqari_can_lease(w,q.id,'finance','read') and exists(select 1 from private.aqari_commercial_sales ss where ss.workspace_id=w and ss.lease_id=q.id)),
   'accounts',(select coalesce(jsonb_agg(to_jsonb(a)-'created_by' order by a.name,a.id),'[]') from private.aqari_collection_accounts a where a.workspace_id=w and a.property_id=p.id and a.status='active'),
   'documents',(select coalesce(jsonb_agg(to_jsonb(x) order by x.created_at desc,x.id),'[]') from (
    select dd.id,dd.title,dd.entity_type,dd.entity_ref,dd.created_at from public.aqari_documents dd join storage.objects o on o.bucket_id=dd.storage_bucket and o.name=dd.storage_path
    where dd.workspace_id=w and dd.status='uploaded' and ((dd.entity_type='lease' and dd.entity_ref=l.external_ref) or(dd.entity_type='property' and dd.entity_ref=p.external_ref))
     and dd.size_bytes>0 and dd.checksum_sha256~'^[a-f0-9]{64}$' and (o.metadata->>'size')::bigint=dd.size_bytes and o.metadata->>'mimetype'=dd.mime_type
     and private.aqari_can(w,'documents','read') and private.aqari_document_entity(w,dd.entity_type,dd.entity_ref,'read') limit 200)x),
   'statement',case when lid is null then null else private.aqari_commercial_balance(w,lid,as_of) end,
   'sales',(select coalesce(jsonb_agg(jsonb_build_object('id',ss.id,'month',ss.month,'amount',to_char(ss.amount,'FM999999999999990.000'),'period_end',ss.period_end,'reference',ss.source_reference,'reversed',exists(select 1 from private.aqari_commercial_sales_reversals sr where sr.workspace_id=w and sr.sale_id=ss.id and sr.occurred_on<=as_of),
     'outstanding',to_char(case when exists(select 1 from private.aqari_commercial_sales_reversals sr where sr.workspace_id=w and sr.sale_id=ss.id and sr.occurred_on<=as_of) then 0 else ss.amount-(select coalesce(sum(a.amount),0) from private.aqari_commercial_collection_allocations a join private.aqari_commercial_collections cc on cc.workspace_id=a.workspace_id and cc.id=a.collection_id where a.workspace_id=w and a.sale_id=ss.id and cc.occurred_on<=as_of and not exists(select 1 from private.aqari_commercial_collection_reversals rr where rr.workspace_id=w and rr.collection_id=a.collection_id and rr.occurred_on<=as_of)) end,'FM999999999999990.000')) order by ss.month,ss.id),'[]') from private.aqari_commercial_sales ss where ss.workspace_id=w and ss.lease_id=lid and ss.period_end<=as_of),
   'collections',(select coalesce(jsonb_agg(case when (proof#>>'{reversal,occurred_on}')::date>as_of then proof||'{"reversal":null}'::jsonb else proof end order by cc.occurred_on desc,cc.id),'[]') from private.aqari_commercial_collections cc cross join lateral(select private.aqari_commercial_collection_json(w,cc.id) proof)x where cc.workspace_id=w and cc.lease_id=lid and cc.occurred_on<=as_of));
 end if;
 ident:=nullif(d->>'id','')::uuid;if ident is null then raise invalid_parameter_value using message='COMMERCIAL_COLLECTION_ID_REQUIRED';end if;
 if action='get' then
  if exists(select 1 from jsonb_object_keys(d)k where k<>'id') then raise invalid_parameter_value using message='INVALID_COMMERCIAL_COLLECTION_REQUEST';end if;
  select * into c from private.aqari_commercial_collections x where x.workspace_id=w and x.id=ident;
  if not found then return jsonb_build_object('collection',null,'allocations','[]'::jsonb,'reversal',null);end if;
  if not private.aqari_can_lease(w,c.lease_id,'finance','read') then raise insufficient_privilege using message='ACCESS_DENIED';end if;
  return private.aqari_commercial_collection_json(w,ident);
 end if;
 if not private.aqari_manager(w) or not private.aqari_can(w,'finance','write') then raise insufficient_privilege using message='ACCESS_DENIED';end if;
 perform private.aqari_require_sensitive_aal2(w);
 perform 1 from public.aqari_app_state where workspace_id=w for update;
 if not found then raise insufficient_privilege using message='ACCESS_DENIED';end if;
 if coalesce(d->>'occurred_on','') !~ '^20[0-9]{2}-(0[1-9]|1[0-2])-[0-9]{2}$' then raise invalid_parameter_value using message='INVALID_COMMERCIAL_COLLECTION_DATE';end if;
 posted:=(d->>'occurred_on')::date;if posted>today then raise check_violation using message='INVALID_COMMERCIAL_COLLECTION_DATE';end if;
 if action='record' then
  if exists(select 1 from jsonb_object_keys(d)k where k not in('id','lease_id','account_id','account_revision','method','occurred_on','reference','source_document_id','amount','allocations'))
   or coalesce(d->>'amount','') !~ '^[0-9]{1,12}(\.[0-9]{1,3})?$' or (d->>'amount')::numeric<=0
   or d->>'method' not in('cash','bank_transfer') or nullif(d->>'method','') is null
   or coalesce(d->>'account_revision','') !~ '^[1-9][0-9]{0,8}$'
   or length(btrim(coalesce(d->>'reference',''))) not between 3 and 160
   or jsonb_typeof(d->'allocations') is distinct from 'array' then raise invalid_parameter_value using message='INVALID_COMMERCIAL_COLLECTION_REQUEST';end if;
  if jsonb_array_length(d->'allocations') not between 1 and 60 then raise invalid_parameter_value using message='INVALID_COMMERCIAL_ALLOCATIONS';end if;
  amount_value:=(d->>'amount')::numeric;allocations:='[]';
  for item in select value from jsonb_array_elements(d->'allocations') loop
   if jsonb_typeof(item) is distinct from 'object' or exists(select 1 from jsonb_object_keys(item)k where k not in('sale_id','amount')) or coalesce(item->>'amount','') !~ '^[0-9]{1,12}(\.[0-9]{1,3})?$' or (item->>'amount')::numeric<=0 or nullif(item->>'sale_id','') is null then raise invalid_parameter_value using message='INVALID_COMMERCIAL_ALLOCATIONS';end if;
   allocations:=allocations||jsonb_build_array(jsonb_build_object('sale_id',(item->>'sale_id')::uuid,'amount',to_char((item->>'amount')::numeric,'FM999999999999990.000')));total:=total+(item->>'amount')::numeric;
  end loop;
  if total<>amount_value or (select count(distinct x->>'sale_id') from jsonb_array_elements(allocations)x)<>jsonb_array_length(allocations) then raise check_violation using message='COMMERCIAL_ALLOCATION_TOTAL_MISMATCH';end if;
  select jsonb_agg(x order by x->>'sale_id') into allocations from jsonb_array_elements(allocations)x;
  request:=d||jsonb_build_object('amount',to_char(amount_value,'FM999999999999990.000'),'reference',btrim(d->>'reference'),'allocations',allocations);
  select * into c from private.aqari_commercial_collections x where x.id=ident;
  if found then
   if c.workspace_id<>w or c.request_data is distinct from request or c.recorded_by<>actor then raise unique_violation using message='COMMERCIAL_COLLECTION_RETRY_CONFLICT';end if;
   if not private.aqari_can_lease(w,c.lease_id,'finance','read') then raise insufficient_privilege using message='ACCESS_DENIED';end if;
   return private.aqari_commercial_collection_json(w,ident);
  end if;
  lid:=nullif(d->>'lease_id','')::uuid;account_ident:=nullif(d->>'account_id','')::uuid;
 else
  if exists(select 1 from jsonb_object_keys(d)k where k not in('id','collection_id','occurred_on','reason')) or length(btrim(coalesce(d->>'reason',''))) not between 5 and 500 then raise invalid_parameter_value using message='INVALID_COMMERCIAL_COLLECTION_REVERSAL';end if;
  request:=d||jsonb_build_object('reason',btrim(d->>'reason'));
  select * into r from private.aqari_commercial_collection_reversals x where x.id=ident;
  if found then
   if r.workspace_id<>w or r.request_data is distinct from request or r.recorded_by<>actor then raise unique_violation using message='COMMERCIAL_COLLECTION_RETRY_CONFLICT';end if;
   select * into c from private.aqari_commercial_collections x where x.workspace_id=w and x.id=r.collection_id;
   if not private.aqari_can_lease(w,c.lease_id,'finance','read') then raise insufficient_privilege using message='ACCESS_DENIED';end if;
   return private.aqari_commercial_collection_json(w,c.id);
  end if;
  select * into c from private.aqari_commercial_collections x where x.workspace_id=w and x.id=nullif(d->>'collection_id','')::uuid;
  if not found then raise insufficient_privilege using message='ACCESS_DENIED';end if;
  lid:=c.lease_id;account_ident:=c.account_id;
 end if;
 if not private.aqari_can_lease(w,lid,'finance','write') then raise insufficient_privilege using message='ACCESS_DENIED';end if;
 select * into l from public.aqari_leases q where q.workspace_id=w and q.id=lid for update;
 if not found then raise insufficient_privilege using message='ACCESS_DENIED';end if;
 if private.aqari_commercial_legacy_history(w,lid) then raise check_violation using message='COMMERCIAL_COLLECTION_LEGACY_MODE_REQUIRED';end if;
 select z.* into strict p from public.aqari_properties z join public.aqari_units u on u.workspace_id=z.workspace_id and u.property_id=z.id where u.workspace_id=w and u.id=l.unit_id;
 perform private.aqari_financial_open(w,posted);
 if action='record' then
  if l.status not in('signed','expired') then raise check_violation using message='COMMERCIAL_COLLECTION_CONTRACT_REQUIRED';end if;
  select * into account from private.aqari_collection_accounts a where a.workspace_id=w and a.id=account_ident for update;
  if not found or account.property_id<>p.id or account.status<>'active' or account.currency<>'KWD' or account.kind<>(case d->>'method' when 'cash' then 'cashbox' else 'bank' end) then raise check_violation using message='COMMERCIAL_COLLECTION_ACCOUNT_MISMATCH';end if;
  if account.revision<>(d->>'account_revision')::integer then raise serialization_failure using message='COMMERCIAL_COLLECTION_ACCOUNT_CHANGED';end if;
  select dd.* into doc from public.aqari_documents dd join storage.objects o on o.bucket_id=dd.storage_bucket and o.name=dd.storage_path
   where dd.workspace_id=w and dd.id=nullif(d->>'source_document_id','')::uuid and dd.status='uploaded'
    and ((dd.entity_type='lease' and dd.entity_ref=l.external_ref) or(dd.entity_type='property' and dd.entity_ref=p.external_ref))
    and dd.size_bytes>0 and dd.checksum_sha256~'^[a-f0-9]{64}$' and (o.metadata->>'size')::bigint=dd.size_bytes and o.metadata->>'mimetype'=dd.mime_type
    and private.aqari_can(w,'documents','read') and private.aqari_document_entity(w,dd.entity_type,dd.entity_ref,'read');
  if not found then raise check_violation using message='COMMERCIAL_COLLECTION_DOCUMENT_UNVERIFIED';end if;
  perform private.aqari_assert_commercial_collections(w,lid);
  for item in select value from jsonb_array_elements(allocations) loop
   select * into s from private.aqari_commercial_sales x where x.workspace_id=w and x.lease_id=lid and x.id=(item->>'sale_id')::uuid for share;
   if not found or s.amount<=0 or exists(select 1 from private.aqari_commercial_sales_reversals rr where rr.workspace_id=w and rr.sale_id=s.id) then raise check_violation using message='COMMERCIAL_ALLOCATION_SOURCE_INVALID';end if;
   if posted<s.period_end then raise check_violation using message='COMMERCIAL_COLLECTION_BEFORE_CHARGE';end if;
   select coalesce(sum(a.amount),0) into paid from private.aqari_commercial_collection_allocations a where a.workspace_id=w and a.sale_id=s.id and not exists(select 1 from private.aqari_commercial_collection_reversals rr where rr.workspace_id=w and rr.collection_id=a.collection_id);
   if paid+(item->>'amount')::numeric>s.amount then raise check_violation using message='COMMERCIAL_ALLOCATION_EXCEEDS_BALANCE';end if;
  end loop;
  insert into private.aqari_commercial_collections(id,workspace_id,lease_id,account_id,account_snapshot,method,occurred_on,amount,reference,source_document_id,source_checksum,request_data,recorded_by)
   values(ident,w,lid,account.id,jsonb_build_object('id',account.id,'property_id',account.property_id,'kind',account.kind,'name',account.name,'masked_reference',account.masked_reference,'currency',account.currency,'revision',account.revision),d->>'method',posted,amount_value,btrim(d->>'reference'),doc.id,doc.checksum_sha256,request,actor);
  insert into private.aqari_commercial_collection_allocations(workspace_id,collection_id,sale_id,amount) select w,ident,(x->>'sale_id')::uuid,(x->>'amount')::numeric from jsonb_array_elements(allocations)x;
  result:=private.aqari_commercial_collection_json(w,ident);
 else
  if posted<c.occurred_on then raise check_violation using message='INVALID_COMMERCIAL_COLLECTION_DATE';end if;
  if exists(select 1 from private.aqari_commercial_collection_reversals rr where rr.workspace_id=w and rr.collection_id=c.id) then raise unique_violation using message='COMMERCIAL_COLLECTION_ALREADY_REVERSED';end if;
  insert into private.aqari_commercial_collection_reversals(id,workspace_id,collection_id,amount,occurred_on,reason,request_data,recorded_by) values(ident,w,c.id,c.amount,posted,btrim(d->>'reason'),request,actor);
  result:=private.aqari_commercial_collection_json(w,c.id);
 end if;
 perform private.aqari_assert_commercial_collections(w,lid);
 insert into private.aqari_operations_audit(workspace_id,domain,entity_id,action,actor_id,actor_name,reason,after_value)
  values(w,'commercial_collections',ident,action,actor,coalesce(auth.jwt()->>'email',actor::text),coalesce(request->>'reference',request->>'reason'),result);
 return result;
end $function$

CREATE OR REPLACE FUNCTION private.aqari_commercial_lease_release_guard()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
begin
 if new.vacated_on is not null and new.vacated_on is distinct from old.vacated_on then
  perform 1 from public.aqari_app_state where workspace_id=new.workspace_id for update;
  perform private.aqari_require_commercial_clearance(new.workspace_id,new.id);
 end if;
 return new;
end $function$

CREATE OR REPLACE FUNCTION private.aqari_commercial_post_clearance_guard()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
begin
 perform 1 from public.aqari_app_state where workspace_id=new.workspace_id for update;
 if exists(select 1 from private.aqari_vacating_settlements v where v.workspace_id=new.workspace_id and v.lease_id=new.lease_id and v.status in ('cleared','released'))
  or exists(select 1 from public.aqari_leases l where l.workspace_id=new.workspace_id and l.id=new.lease_id and l.vacated_on is not null) then
  raise check_violation using message='لا يمكن إضافة استحقاق مبيعات بعد براءة الذمة أو إنهاء العقد. يلزم مسار مراجعة تسوية معتمد يحافظ على البراءة السابقة.',detail='SALES_AFTER_CLEARANCE_REVIEW_REQUIRED';
 end if;
 return new;
end $function$

CREATE OR REPLACE FUNCTION private.aqari_commercial_sales_register(w uuid, action text, d jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
 actor uuid:=auth.uid(); ident uuid; lid uuid; mon date; first_day date; last_day date; posted_on date;
 today date:=(now() at time zone 'Asia/Kuwait')::date;
 l public.aqari_leases; prop public.aqari_properties; terms private.aqari_commercial_terms;
 saved private.aqari_commercial_sales; reversed private.aqari_commercial_sales_reversals;
 document_row public.aqari_documents; amount numeric(15,3); sales numeric(15,3); request jsonb; result jsonb;
begin
 if actor is null or not private.aqari_manager(w) or not private.aqari_can(w,'finance','read') then
  raise insufficient_privilege using message='ACCESS_DENIED';
 end if;
 if jsonb_typeof(d) is distinct from 'object' or action is null or action not in ('list','record','reverse') then
  raise exception 'INVALID_COMMERCIAL_SALES_ACTION' using errcode='22023';
 end if;
 if coalesce(d->>'month','') !~ '^20[0-9]{2}-(0[1-9]|1[0-2])$' then
  raise exception 'INVALID_SALES_MONTH' using errcode='22023';
 end if;
 mon:=(d->>'month'||'-01')::date;
 if action='list' then
  return jsonb_build_object('month',to_char(mon,'YYYY-MM'),
   'leases',(select coalesce(jsonb_agg(jsonb_build_object('id',q.id,'external_ref',q.external_ref,'contract_no',q.contract_no,'property_ref',p.external_ref,'property_id',p.id,'property_name',p.name,'sales_percentage',t.sales_percentage,'terms_revision',t.revision) order by q.contract_no),'[]')
    from public.aqari_leases q join public.aqari_units u on u.workspace_id=q.workspace_id and u.id=q.unit_id
    join public.aqari_properties p on p.workspace_id=u.workspace_id and p.id=u.property_id
    join private.aqari_commercial_terms t on t.workspace_id=q.workspace_id and t.lease_id=q.id
    where q.workspace_id=w and t.sales_percentage>0 and q.status in ('signed','expired') and private.aqari_can_property(w,p.id,'finance','read')),
   'documents',(select coalesce(jsonb_agg(to_jsonb(z)),'[]') from (
    select doc.id,doc.title,doc.entity_type,doc.entity_ref from public.aqari_documents doc
    join storage.objects o on o.bucket_id=doc.storage_bucket and o.name=doc.storage_path
    where doc.workspace_id=w and doc.entity_type in ('property','lease') and doc.status='uploaded'
     and doc.checksum_sha256~'^[a-f0-9]{64}$' and doc.size_bytes>0 and (o.metadata->>'size')::bigint=doc.size_bytes and o.metadata->>'mimetype'=doc.mime_type
     and private.aqari_can(w,'documents','read') and private.aqari_document_entity(w,doc.entity_type,doc.entity_ref,'read')
    order by doc.created_at desc,doc.id limit 200)z),
   'entries',(select coalesce(jsonb_agg(to_jsonb(s)||jsonb_build_object('reversal',(select to_jsonb(r) from private.aqari_commercial_sales_reversals r where r.workspace_id=w and r.sale_id=s.id)) order by s.recorded_at desc,s.id),'[]')
    from private.aqari_commercial_sales s join public.aqari_leases q on q.workspace_id=s.workspace_id and q.id=s.lease_id
    join public.aqari_units u on u.workspace_id=q.workspace_id and u.id=q.unit_id
    where s.workspace_id=w and s.month=mon and private.aqari_can_property(w,u.property_id,'finance','read')));
 end if;
 perform private.aqari_require_sensitive_aal2(w);
 if not private.aqari_can(w,'finance','write') then raise insufficient_privilege using message='ACCESS_DENIED';end if;
 ident:=nullif(d->>'id','')::uuid;
 if ident is null then raise exception 'SALES_ID_REQUIRED' using errcode='22023';end if;
 -- Same lock order as financial closing: workspace first, then lease/terms.
 perform 1 from public.aqari_app_state where workspace_id=w for update;
 if not found then raise insufficient_privilege using message='ACCESS_DENIED';end if;

 if action='record' then
  if exists(select 1 from jsonb_object_keys(d)k where k not in ('id','lease_id','month','gross_sales','terms_revision','source_document_id','source_reference','calculation_basis'))
   or coalesce(d->>'gross_sales','') !~ '^[0-9]{1,9}(\.[0-9]{1,3})?$'
   or coalesce(d->>'terms_revision','') !~ '^[1-9][0-9]{0,8}$'
   or d->>'calculation_basis' is distinct from 'additional_to_base_rent'
   or length(btrim(coalesce(d->>'source_reference',''))) not between 3 and 200 then
   raise exception 'INVALID_COMMERCIAL_SALES' using errcode='22023';
  end if;
  lid:=nullif(d->>'lease_id','')::uuid;sales:=(d->>'gross_sales')::numeric;
  request:=d||jsonb_build_object('gross_sales',to_char(sales,'FM999999999990.000'),'source_reference',btrim(d->>'source_reference'));
  select * into saved from private.aqari_commercial_sales where id=ident;
  if found then
   if saved.workspace_id<>w or saved.request_data is distinct from request then raise exception 'SALES_RETRY_CONFLICT' using errcode='23505';end if;
   return to_jsonb(saved);
  end if;
  select * into l from public.aqari_leases where workspace_id=w and id=lid for share;
  if not found then raise insufficient_privilege using message='ACCESS_DENIED';end if;
  select p.* into prop from public.aqari_properties p join public.aqari_units u on u.workspace_id=p.workspace_id and u.property_id=p.id where u.workspace_id=w and u.id=l.unit_id;
  if not private.aqari_can_property(w,prop.id,'finance','write') or not private.aqari_can_property(w,prop.id,'contracts','read') then raise insufficient_privilege using message='ACCESS_DENIED';end if;
  first_day:=greatest(mon,l.start_date);last_day:=least((mon+interval '1 month - 1 day')::date,l.end_date,coalesce(l.vacated_on,l.end_date));
  if l.status not in ('signed','expired') or l.start_date is null or l.end_date is null or first_day>last_day or first_day<mon or first_day>=(mon+interval '1 month')::date or last_day>today then
   raise exception 'SALES_PERIOD_OUTSIDE_COMPLETED_LEASE_MONTH' using errcode='23514';
  end if;
  perform private.aqari_financial_open(w,last_day);
  select * into terms from private.aqari_commercial_terms where workspace_id=w and lease_id=lid for share;
  if not found or terms.sales_percentage<=0 or terms.compliance_reviewed_at is null then raise exception 'APPROVED_SALES_TERMS_REQUIRED' using errcode='23514';end if;
  if terms.revision<>(d->>'terms_revision')::integer then raise serialization_failure using message='SALES_TERMS_REVISION_CONFLICT';end if;
  if exists(select 1 from private.aqari_commercial_sales s where s.workspace_id=w and s.lease_id=lid and s.month=mon
   and not exists(select 1 from private.aqari_commercial_sales_reversals r where r.workspace_id=w and r.sale_id=s.id)) then
   raise exception 'SALES_MONTH_ALREADY_POSTED' using errcode='23505';
  end if;
  select doc.* into document_row from public.aqari_documents doc join storage.objects o on o.bucket_id=doc.storage_bucket and o.name=doc.storage_path
   where doc.workspace_id=w and doc.id=nullif(d->>'source_document_id','')::uuid and doc.status='uploaded'
    and ((doc.entity_type='property' and doc.entity_ref=prop.external_ref) or (doc.entity_type='lease' and doc.entity_ref=l.external_ref))
    and doc.checksum_sha256~'^[a-f0-9]{64}$' and doc.size_bytes>0 and (o.metadata->>'size')::bigint=doc.size_bytes and o.metadata->>'mimetype'=doc.mime_type
    and private.aqari_can(w,'documents','read') and private.aqari_document_entity(w,doc.entity_type,doc.entity_ref,'read');
  if not found then raise exception 'SALES_SOURCE_DOCUMENT_UNVERIFIED' using errcode='23514';end if;
  amount:=round(sales*terms.sales_percentage/100,3);
  insert into private.aqari_commercial_sales(id,workspace_id,lease_id,month,period_start,period_end,gross_sales,sales_percentage,amount,terms_revision,calculation_basis,source_document_id,source_checksum,source_reference,request_data,recorded_by)
   values(ident,w,lid,mon,first_day,last_day,sales,terms.sales_percentage,amount,terms.revision,'additional_to_base_rent',document_row.id,document_row.checksum_sha256,btrim(d->>'source_reference'),request,actor) returning to_jsonb(aqari_commercial_sales) into result;
  if amount>0 then
   insert into private.aqari_tenant_adjustments(id,workspace_id,lease_id,kind,direction,amount,occurred_on,source_type,source_id,reason,actor_id)
    values(gen_random_uuid(),w,lid,'commercial_sales','debit',amount,last_day,'commercial_sales',ident,'استحقاق نسبة مبيعات '||to_char(mon,'YYYY-MM')||' — '||btrim(d->>'source_reference'),actor);
  end if;
 else
  if exists(select 1 from jsonb_object_keys(d)k where k not in ('id','sale_id','month','occurred_on','reason'))
   or length(btrim(coalesce(d->>'reason',''))) not between 5 and 500
   or coalesce(d->>'occurred_on','') !~ '^20[0-9]{2}-(0[1-9]|1[0-2])-[0-9]{2}$' then raise exception 'INVALID_SALES_REVERSAL' using errcode='22023';end if;
  posted_on:=(d->>'occurred_on')::date;request:=d||jsonb_build_object('reason',btrim(d->>'reason'));
  select * into reversed from private.aqari_commercial_sales_reversals where id=ident;
  if found then
   if reversed.workspace_id<>w or reversed.request_data is distinct from request then raise exception 'SALES_RETRY_CONFLICT' using errcode='23505';end if;
   return to_jsonb(reversed);
  end if;
  select * into saved from private.aqari_commercial_sales where workspace_id=w and id=nullif(d->>'sale_id','')::uuid and month=mon for share;
  if not found then raise insufficient_privilege using message='ACCESS_DENIED';end if;
  select p.* into prop from public.aqari_properties p join public.aqari_units u on u.workspace_id=p.workspace_id and u.property_id=p.id join public.aqari_leases q on q.workspace_id=u.workspace_id and q.unit_id=u.id where q.workspace_id=w and q.id=saved.lease_id;
  if not private.aqari_can_property(w,prop.id,'finance','write') then raise insufficient_privilege using message='ACCESS_DENIED';end if;
  if posted_on<saved.period_end or posted_on>today then raise exception 'INVALID_SALES_REVERSAL_DATE' using errcode='23514';end if;
  perform private.aqari_financial_open(w,posted_on);
  if exists(select 1 from private.aqari_commercial_sales_reversals where workspace_id=w and sale_id=saved.id) then raise exception 'SALES_ALREADY_REVERSED' using errcode='23505';end if;
  insert into private.aqari_commercial_sales_reversals(id,workspace_id,sale_id,occurred_on,reason,request_data,recorded_by)
   values(ident,w,saved.id,posted_on,btrim(d->>'reason'),request,actor) returning to_jsonb(aqari_commercial_sales_reversals) into result;
  if saved.amount>0 then
   insert into private.aqari_tenant_adjustments(id,workspace_id,lease_id,kind,direction,amount,occurred_on,source_type,source_id,reason,actor_id)
    values(gen_random_uuid(),w,saved.lease_id,'commercial_sales','credit',saved.amount,posted_on,'commercial_sales_reversal',ident,btrim(d->>'reason'),actor);
  end if;
 end if;
 insert into private.aqari_operations_audit(workspace_id,domain,entity_id,action,actor_id,actor_name,reason,after_value)
  values(w,'commercial_sales',ident,action,actor,coalesce(auth.jwt()->>'email',actor::text),coalesce(result->>'source_reference',result->>'reason'),result);
 return result;
end $function$

CREATE OR REPLACE FUNCTION private.aqari_contract_administration(w uuid, act text, d jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare manager boolean; ident uuid; doc public.aqari_documents; lease public.aqari_leases;
 tenant public.aqari_tenants; unit public.aqari_units; archive_row private.aqari_contract_archives;
 req private.aqari_contract_change_requests; sig private.aqari_contract_signature_reviews;
 result jsonb; required jsonb; signed jsonb; fingerprint text;
begin
 if auth.uid() is null or not private.aqari_can(w,'contracts','read') then raise insufficient_privilege using message='ACCESS_DENIED';end if;
 if jsonb_typeof(d) is distinct from 'object' then raise invalid_parameter_value using message='INVALID_REQUEST';end if;
 manager:=private.aqari_manager(w);
 if act in('archive','review_signatures','decide_request') and not private.aqari_can(w,'contracts','write') then raise insufficient_privilege using message='ACCESS_DENIED';end if;
 if act in('archives','archive','review_signatures') and not manager then raise insufficient_privilege using message='MANAGER_REQUIRED';end if;
 if act='archives' then
  select coalesce(jsonb_agg(x order by x.created_at desc),'[]'::jsonb) into result from (
   select a.*,t.full_name tenant_name,p.name property_name,u.unit_no,archive_doc.original_filename,archive_doc.storage_path,archive_doc.status document_status,
    coalesce((select s.status from private.aqari_contract_signature_reviews s where s.workspace_id=w and s.document_id=a.document_id order by s.reviewed_at desc,s.id desc limit 1),'unverified') signature_status
   from private.aqari_contract_archives a join public.aqari_tenants t on t.workspace_id=w and t.id=a.tenant_id
   join public.aqari_properties p on p.workspace_id=w and p.id=a.property_id join public.aqari_units u on u.workspace_id=w and u.id=a.unit_id
   join public.aqari_documents archive_doc on archive_doc.workspace_id=w and archive_doc.id=a.document_id
   where a.workspace_id=w and (nullif(d->>'tenant_id','') is null or a.tenant_id=(d->>'tenant_id')::uuid)
    and (nullif(d->>'property_id','') is null or a.property_id=(d->>'property_id')::uuid)
  )x;
 elsif act='archive' then
  perform private.aqari_require_sensitive_aal2(w);
  if not private.aqari_can(w,'documents','write') then raise insufficient_privilege using message='ACCESS_DENIED';end if;
  ident:=(d->>'id')::uuid;
  if coalesce(d->>'original_date','') !~ '^[0-9]{4}-[0-9]{2}-[0-9]{2}$' then raise invalid_parameter_value using message='ARCHIVE_ORIGINAL_DATE_REQUIRED';end if;
  perform (d->>'original_date')::date;
  if ident is null or coalesce(length(btrim(d->>'reference')),0) not between 1 and 200 then raise invalid_parameter_value using message='ARCHIVE_REFERENCE_REQUIRED';end if;
  select * into tenant from public.aqari_tenants where workspace_id=w and id=(d->>'tenant_id')::uuid;
  select * into unit from public.aqari_units where workspace_id=w and id=(d->>'unit_id')::uuid and property_id=(d->>'property_id')::uuid;
  select * into doc from public.aqari_documents where workspace_id=w and id=(d->>'document_id')::uuid;
  if tenant.id is null or unit.id is null or doc.id is null or doc.status is distinct from 'uploaded'
   or doc.entity_type is distinct from 'tenant' or doc.entity_ref is distinct from tenant.external_ref
   or doc.metadata->>'category' is distinct from 'archived_contract' or doc.checksum_sha256 is null
  then raise invalid_parameter_value using message='ARCHIVE_BINDING_INVALID';end if;
  insert into private.aqari_contract_archives(id,workspace_id,tenant_id,property_id,unit_id,document_id,reference,original_date,created_by)
   values(ident,w,tenant.id,unit.property_id,unit.id,doc.id,btrim(d->>'reference'),(d->>'original_date')::date,auth.uid()) on conflict(id) do nothing;
  select * into archive_row from private.aqari_contract_archives where id=ident;
  if archive_row.workspace_id is distinct from w or archive_row.tenant_id is distinct from tenant.id or archive_row.unit_id is distinct from unit.id
   or archive_row.property_id is distinct from unit.property_id or archive_row.document_id is distinct from doc.id or archive_row.reference is distinct from btrim(d->>'reference')
   or archive_row.original_date is distinct from (d->>'original_date')::date
   or archive_row.created_by is distinct from auth.uid() then raise invalid_parameter_value using message='ARCHIVE_REQUEST_CONFLICT';end if;
  result:=to_jsonb(archive_row);
 elsif act='signature_status' then
  select * into doc from public.aqari_documents where workspace_id=w and id=(d->>'document_id')::uuid;
  if doc.id is null or not (manager or doc.entity_type='lease' and exists(select 1 from public.aqari_leases l where l.workspace_id=w and l.external_ref=doc.entity_ref and private.aqari_can_lease(w,l.id,'contracts','read'))) then raise insufficient_privilege using message='ACCESS_DENIED';end if;
  select to_jsonb(s) into result from private.aqari_contract_signature_reviews s where workspace_id=w and document_id=doc.id order by reviewed_at desc,id desc limit 1;
  if doc.entity_type='lease' and result is not null then
   select encode(sha256(convert_to((l.snapshot-array['status','changeReason','updatedAt'])::text,'UTF8')),'hex') into fingerprint from public.aqari_leases l where l.workspace_id=w and l.external_ref=doc.entity_ref;
   if result->>'contract_sha256' is distinct from fingerprint then result:=result||jsonb_build_object('status','outdated_copy');end if;
  end if;
  result:=coalesce(result,jsonb_build_object('status','unverified'))||jsonb_build_object('document_status',doc.status);
 elsif act='review_signatures' then
  perform private.aqari_require_sensitive_aal2(w);
  ident:=(d->>'id')::uuid;required:=d->'required_signers';signed:=d->'signed_by';
  if ident is null or jsonb_typeof(required) is distinct from 'array' or jsonb_typeof(signed) is distinct from 'array' then raise invalid_parameter_value using message='SIGNERS_REQUIRED';end if;
  if jsonb_array_length(required) not between 2 and 20 or jsonb_array_length(signed)>20
   or not required @> '["tenant","landlord"]'::jsonb or not required @> signed
   or exists(select 1 from jsonb_array_elements(required||signed)x where jsonb_typeof(x)<>'string' or length(btrim(x#>>'{}')) not between 1 and 100)
   or (select count(distinct value) from jsonb_array_elements(required))<>jsonb_array_length(required)
   or (select count(distinct value) from jsonb_array_elements(signed))<>jsonb_array_length(signed)
  then raise invalid_parameter_value using message='SIGNERS_INVALID';end if;
  select * into doc from public.aqari_documents where workspace_id=w and id=(d->>'document_id')::uuid for update;
  if doc.id is null or doc.status is distinct from 'uploaded' or doc.checksum_sha256 is null or not (
   doc.entity_type='lease' and doc.document_type='signed_contract' or
   exists(select 1 from private.aqari_contract_archives where workspace_id=w and document_id=doc.id))
  then raise invalid_parameter_value using message='SIGNED_COPY_REQUIRED';end if;
  if doc.entity_type='lease' then
   select encode(sha256(convert_to((l.snapshot-array['status','changeReason','updatedAt'])::text,'UTF8')),'hex') into fingerprint from public.aqari_leases l where l.workspace_id=w and l.external_ref=doc.entity_ref;
   if fingerprint is null then raise invalid_parameter_value using message='CONTRACT_NOT_FOUND';end if;
   if exists(select 1 from private.aqari_contract_signature_reviews s where s.workspace_id=w and s.document_id=doc.id and s.contract_sha256 is distinct from fingerprint) then raise invalid_parameter_value using message='SIGNED_COPY_OUTDATED';end if;
  end if;
  -- The required signer set cannot shrink after a review; incomplete copies stay incomplete.
  if exists(select 1 from private.aqari_contract_signature_reviews s where s.workspace_id=w and s.document_id=doc.id and not required @> s.required_signers)
  then raise invalid_parameter_value using message='REQUIRED_SIGNERS_CANNOT_BE_REMOVED';end if;
  insert into private.aqari_contract_signature_reviews(id,workspace_id,document_id,required_signers,signed_by,reviewed_by,status,contract_sha256)
   values(ident,w,doc.id,required,signed,auth.uid(),case when signed @> required then 'complete' else 'missing_signature' end,fingerprint) on conflict(id) do nothing;
  select * into sig from private.aqari_contract_signature_reviews where id=ident;
  if sig.workspace_id is distinct from w or sig.document_id is distinct from doc.id or sig.required_signers is distinct from required or sig.signed_by is distinct from signed or sig.reviewed_by is distinct from auth.uid()
  then raise invalid_parameter_value using message='SIGNATURE_REQUEST_CONFLICT';end if;
  result:=to_jsonb(sig);
 elsif act='requests' then
  select coalesce(jsonb_agg(to_jsonb(r) order by r.created_at desc),'[]'::jsonb) into result from private.aqari_contract_change_requests r
   where r.workspace_id=w and (manager or r.created_by=auth.uid()) and private.aqari_can_lease(w,r.lease_id,'contracts','read');
 elsif act='request_change' then
  select * into lease from public.aqari_leases where workspace_id=w and external_ref=d->>'contract_ref';
  if lease.id is null or not private.aqari_can_lease(w,lease.id,'contracts','read') then raise insufficient_privilege using message='ACCESS_DENIED';end if;
  ident:=(d->>'id')::uuid;
  if ident is null or coalesce(length(btrim(d->>'proposed_change')),0) not between 3 and 4000 then raise invalid_parameter_value using message='CHANGE_REASON_REQUIRED';end if;
  insert into private.aqari_contract_change_requests(id,workspace_id,lease_id,proposed_change,created_by)
   values(ident,w,lease.id,btrim(d->>'proposed_change'),auth.uid()) on conflict(id) do nothing;
  select * into req from private.aqari_contract_change_requests where id=ident;
  if req.workspace_id is distinct from w or req.lease_id is distinct from lease.id or req.created_by is distinct from auth.uid() or req.proposed_change is distinct from btrim(d->>'proposed_change')
  then raise invalid_parameter_value using message='CHANGE_REQUEST_CONFLICT';end if;
  result:=to_jsonb(req);
 elsif act='decide_request' then
  if not manager then raise insufficient_privilege using message='MANAGER_REQUIRED';end if;
  perform private.aqari_require_sensitive_aal2(w);
  if coalesce(d->>'status','') not in('approved','rejected') or coalesce(length(btrim(d->>'reason')),0) not between 3 and 500 then raise invalid_parameter_value using message='DECISION_REQUIRED';end if;
  select * into req from private.aqari_contract_change_requests where workspace_id=w and id=(d->>'id')::uuid for update;
  if req.id is null then raise invalid_parameter_value using message='REQUEST_NOT_FOUND';end if;
  if req.status<>'pending' then
   if req.status is distinct from d->>'status' or req.decision_reason is distinct from btrim(d->>'reason') then raise serialization_failure using message='REQUEST_ALREADY_DECIDED';end if;
  else
   update private.aqari_contract_change_requests set status=d->>'status',decided_by=auth.uid(),decided_at=now(),decision_reason=btrim(d->>'reason') where id=req.id returning * into req;
  end if;
  -- Approval never silently rewrites contract terms or triggers a financial event.
  result:=to_jsonb(req);
 else raise invalid_parameter_value using message='UNKNOWN_ACTION';
 end if;
 return jsonb_build_object('workspace_id',w,'user_id',auth.uid(),'result',result);
end $function$

CREATE OR REPLACE FUNCTION private.aqari_contract_due(c jsonb, period text)
 RETURNS numeric
 LANGUAGE plpgsql
 IMMUTABLE
 SET search_path TO ''
AS $function$
declare a jsonb;amount numeric:=(c->>'rent')::numeric;
begin
 if c->>'rentalTermsVersion'='1' then
  if c->>'freeMonthApproved'='true' and c->>'freeMonthPeriod'=period then return 0;end if;
  for a in select value from jsonb_array_elements(coalesce(c->'rentAdjustments','[]')) loop
   if a->>'effectiveMonth'<=period then amount:=(a->>'rent')::numeric;end if;
  end loop;
 end if;return amount;
end $function$

CREATE OR REPLACE FUNCTION private.aqari_cost_amount(w uuid, k text, i uuid, p uuid, total numeric, defaults uuid[])
 RETURNS numeric
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare rev bigint;allocated numeric;
begin
 select current_revision into rev from private.aqari_property_cost_allocation_heads where workspace_id=w and source_kind=k and source_id=i;
 if coalesce(rev,0)>0 then
  select coalesce(sum(a.amount),0) into allocated from private.aqari_property_cost_allocations a where a.workspace_id=w and a.source_kind=k and a.source_id=i and a.revision=rev and a.property_id=p;
  return coalesce(allocated,0);
 end if;
 if cardinality(defaults)=1 and defaults[1]=p then return total;end if;
 return 0;
end $function$

CREATE OR REPLACE FUNCTION private.aqari_cost_source(w uuid, k text, i uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare total numeric;source_date date;props uuid[];label text;
begin
 if k='financial_expense' then
  select e.amount,e.expense_date,array[e.property_id],coalesce(nullif(e.category,''),'مصروف')||' — '||coalesce(nullif(e.payee,''),e.id::text)
   into total,source_date,props,label from private.aqari_financial_expenses e where e.workspace_id=w and e.id=i and e.state='approved';
 elsif k='payroll' then
  select coalesce(p.net,p.basic+p.allowances+p.overtime-p.deductions-p.advance_repayment),coalesce(p.paid_at::date,p.month),
   coalesce((select array_agg(distinct j.value::uuid order by j.value::uuid) from jsonb_array_elements_text(coalesce(p.snapshot->'property_ids',to_jsonb(h.property_ids))) as j(value)),h.property_ids),
   'راتب — '||coalesce(nullif(h.profile->>'name_ar',''),nullif(h.profile->>'name_en',''),h.id::text)||' — '||to_char(p.month,'YYYY-MM')
   into total,source_date,props,label from private.aqari_hr_payroll p join private.aqari_hr_employees h on h.workspace_id=p.workspace_id and h.id=p.employee_id
   where p.workspace_id=w and p.id=i and p.state='paid';
 elsif k='utility' then
  select u.amount_paid,u.payment_date,array[u.property_id],coalesce(nullif(u.invoice_no,''),nullif(u.source_ref,''),u.id::text)
   into total,source_date,props,label from public.aqari_utility_entries u where u.workspace_id=w and u.id=i and u.entry_type='bill' and u.amount_paid>0 and u.payment_date is not null and u.payment_document_id is not null;
 else raise invalid_parameter_value using message='INVALID_COST_SOURCE_KIND';end if;
 if total is null or source_date is null or total<=0 or props is null or cardinality(props)=0 then raise no_data_found using message='COST_SOURCE_NOT_FINALIZED';end if;
 if total<>round(total,3) then raise check_violation using message='COST_SOURCE_PRECISION_INVALID';end if;
 return jsonb_build_object('kind',k,'id',i,'total',total,'date',source_date,'propertyIds',to_jsonb(props),'label',label);
end $function$

CREATE OR REPLACE FUNCTION private.aqari_document_cancellation_guard()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
begin
  if old.status is distinct from 'cancelled' and new.status='cancelled' then
    if auth.uid() is null or not exists(
      select 1 from private.aqari_cancellation_audit a
      where a.workspace_id=new.workspace_id and a.entity_type='document' and a.entity_id=new.id::text
        and a.action='cancel' and a.actor_id=auth.uid()
    ) then raise exception 'DOCUMENT_CANCELLATION_REASON_REQUIRED' using errcode='23514'; end if;
  end if;
  if old.status='cancelled' and to_jsonb(new) is distinct from to_jsonb(old) then
    raise exception 'CANCELLED_DOCUMENT_IMMUTABLE' using errcode='23514';
  end if;
  return new;
end $function$

CREATE OR REPLACE FUNCTION private.aqari_document_entity(w uuid, t text, r text, a text)
 RETURNS boolean
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
begin
 if t='property' then return exists(select 1 from public.aqari_properties p where p.workspace_id=w and p.external_ref=r and private.aqari_can_property(w,p.id,'properties',a));
 elsif t='lease' then return exists(select 1 from public.aqari_leases l where l.workspace_id=w and l.external_ref=r and private.aqari_can_lease(w,l.id,'contracts',a));
 elsif t='tenant' then
  return exists(select 1 from public.aqari_tenants q where q.workspace_id=w and q.external_ref=r and private.aqari_can(w,'tenants',a)
   and (private.aqari_manager(w) or (exists(select 1 from public.aqari_leases l where l.workspace_id=w and l.tenant_id=q.id)
    and not exists(select 1 from public.aqari_leases l where l.workspace_id=w and l.tenant_id=q.id and not private.aqari_can_lease(w,l.id,'tenants',a)))));
 end if;return false;
end $function$

CREATE OR REPLACE FUNCTION private.aqari_document_guard()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare saved storage.objects%rowtype;
begin
 if not private.aqari_can(new.workspace_id,'documents','write') or not private.aqari_document_entity(new.workspace_id,new.entity_type,new.entity_ref,'write') then raise exception 'DOCUMENT_ENTITY_NOT_FOUND' using errcode='42501';end if;
 if new.created_by is distinct from auth.uid() then raise exception 'ACCESS_DENIED' using errcode='42501';end if;
 if tg_op='INSERT' then
  if new.status<>'draft' or new.size_bytes is not null or new.uploaded_at is not null then raise exception 'INVALID_DOCUMENT';end if;
  if new.storage_path not like new.workspace_id::text||'/'||new.id::text||'.%' then raise exception 'INVALID_DOCUMENT_PATH';end if;
  new.created_at:=now();
 else
  if old.status<>'draft' or old.created_by is distinct from auth.uid() then raise exception 'DOCUMENT_IMMUTABLE' using errcode='42501';end if;
  if (to_jsonb(new)-array['status','size_bytes','checksum_sha256','uploaded_at']) is distinct from (to_jsonb(old)-array['status','size_bytes','checksum_sha256','uploaded_at']) then raise exception 'DOCUMENT_IMMUTABLE';end if;
  if new.status not in ('uploaded','cancelled') then raise exception 'INVALID_DOCUMENT';end if;
  if new.status='uploaded' then
   select * into saved from storage.objects where bucket_id=new.storage_bucket and name=new.storage_path;
   if not found or coalesce((saved.metadata->>'size')::bigint,0)<>new.size_bytes or new.size_bytes not between 1 and 26214400 or saved.metadata->>'mimetype' is distinct from new.mime_type then raise exception 'STORED_FILE_NOT_CONFIRMED';end if;
   new.uploaded_at:=now();
  end if;
 end if;
 return new;
end $function$

CREATE OR REPLACE FUNCTION private.aqari_document_handover_register(p_workspace_id uuid, p_document_id uuid, p_action text, p_data jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare doc public.aqari_documents;proof public.aqari_documents;entry private.aqari_document_handovers;cancelled private.aqari_document_handover_voids;
 actor uuid:=auth.uid();actor_name text;entry_id uuid;proof_id uuid;handover_id uuid;canonical jsonb;handed_at timestamptz;copies int;page int;reason text;result jsonb;
begin
 if actor is null or not exists(select 1 from public.aqari_memberships m where m.workspace_id=p_workspace_id and m.user_id=actor and m.is_active)
  or not coalesce(private.aqari_can(p_workspace_id,'documents','read'),false) then raise exception 'ACCESS_DENIED' using errcode='42501';end if;
 select * into doc from public.aqari_documents where workspace_id=p_workspace_id and id=p_document_id;
 if not found or not coalesce(private.aqari_document_entity(p_workspace_id,doc.entity_type,doc.entity_ref,'read'),false) then raise exception 'ACCESS_DENIED' using errcode='42501';end if;
 if p_data is null or jsonb_typeof(p_data)<>'object' or octet_length(p_data::text)>4096 then raise exception 'INVALID_HANDOVER';end if;
 if p_action='list' then
  if p_data-array['page']<>'{}'::jsonb or coalesce(p_data->>'page','0')!~'^[0-9]{1,5}$' then raise exception 'INVALID_HANDOVER';end if;
  page:=coalesce(p_data->>'page','0')::int;if page>10000 then raise exception 'INVALID_HANDOVER';end if;
  select coalesce(jsonb_agg(to_jsonb(r)),'[]') into result from (
   select h.*,to_jsonb(v) as cancellation from private.aqari_document_handovers h left join private.aqari_document_handover_voids v on v.handover_id=h.id
   where h.workspace_id=p_workspace_id and h.document_id=p_document_id order by h.recorded_at desc,h.id desc limit 50 offset page*50
  ) r;
  return jsonb_build_object('entries',result,'can_write',coalesce(private.aqari_can(p_workspace_id,'documents','write') and private.aqari_document_entity(p_workspace_id,doc.entity_type,doc.entity_ref,'write'),false),
   'evidence',(select coalesce(jsonb_agg(to_jsonb(x)),'[]') from (select d.id,d.title,d.document_no from public.aqari_documents d
    where d.workspace_id=p_workspace_id and d.entity_type=doc.entity_type and d.entity_ref=doc.entity_ref and d.id<>doc.id and d.status='uploaded' and d.checksum_sha256 is not null
    order by d.created_at desc,d.id desc limit 50) x));
 end if;
 if not coalesce(private.aqari_can(p_workspace_id,'documents','write') and private.aqari_document_entity(p_workspace_id,doc.entity_type,doc.entity_ref,'write'),false) then raise exception 'ACCESS_DENIED' using errcode='42501';end if;
 if p_action not in ('record','void') or p_action is null then raise exception 'INVALID_HANDOVER';end if;
 begin entry_id:=(p_data->>'id')::uuid;exception when invalid_text_representation then raise exception 'INVALID_HANDOVER';end;
 if entry_id is null then raise exception 'INVALID_HANDOVER';end if;
 select coalesce(nullif(btrim(display_name),''),actor::text) into actor_name from public.aqari_profiles where user_id=actor;
 actor_name:=coalesce(actor_name,actor::text);
 -- Serialize same-document retries and cancellation; unrelated documents are independent.
 perform pg_advisory_xact_lock(hashtextextended('aqari-handover:'||p_document_id::text,0));
 if p_action='void' then
  if p_data-array['id','handover_id','reason']<>'{}'::jsonb then raise exception 'INVALID_HANDOVER';end if;
  begin handover_id:=(p_data->>'handover_id')::uuid;exception when invalid_text_representation then raise exception 'INVALID_HANDOVER';end;
  reason:=btrim(p_data->>'reason');if reason is null or length(reason) not between 5 and 500 then raise exception 'INVALID_HANDOVER';end if;
  select * into entry from private.aqari_document_handovers where id=handover_id and workspace_id=p_workspace_id and document_id=p_document_id;
  if not found then raise exception 'HANDOVER_NOT_FOUND';end if;
  select v.* into cancelled from private.aqari_document_handover_voids v where v.handover_id=entry.id;
  if found then
   if cancelled.id=entry_id and cancelled.actor_id=actor and cancelled.reason=reason then return to_jsonb(cancelled);end if;
   raise exception 'HANDOVER_ALREADY_VOID';
  end if;
  insert into private.aqari_document_handover_voids(id,handover_id,actor_id,actor_name,reason) values(entry_id,entry.id,actor,actor_name,reason) returning * into cancelled;
  return to_jsonb(cancelled);
 end if;
 if p_data-array['id','evidence_document_id','sender_name','recipient_name','handed_at','copy_kind','copies','method','note']<>'{}'::jsonb then raise exception 'INVALID_HANDOVER';end if;
 if doc.status<>'uploaded' or doc.checksum_sha256 is null then raise exception 'HANDOVER_VERIFIED_DOCUMENT_REQUIRED';end if;
 if coalesce(p_data->>'copies','')!~'^[0-9]{1,2}$' or coalesce(p_data->>'handed_at','')!~'(Z|[+-][0-9]{2}:[0-9]{2})$' then raise exception 'INVALID_HANDOVER';end if;
 begin proof_id:=(p_data->>'evidence_document_id')::uuid;handed_at:=(p_data->>'handed_at')::timestamptz;copies:=(p_data->>'copies')::int;
 exception when invalid_text_representation or invalid_datetime_format or datetime_field_overflow then raise exception 'INVALID_HANDOVER';end;
 if proof_id is null or proof_id=doc.id or not isfinite(handed_at) or handed_at>now()+interval '5 minutes' or copies not between 1 and 99
  or coalesce(p_data->>'copy_kind','') not in ('original','copy') or coalesce(p_data->>'method','') not in ('hand','courier','electronic')
  or length(coalesce(btrim(p_data->>'sender_name'),'')) not between 2 and 180 or length(coalesce(btrim(p_data->>'recipient_name'),'')) not between 2 and 180
  or length(coalesce(p_data->>'note',''))>500 then raise exception 'INVALID_HANDOVER';end if;
 select * into proof from public.aqari_documents where id=proof_id and workspace_id=p_workspace_id and status='uploaded' and checksum_sha256 is not null
  and entity_type=doc.entity_type and entity_ref=doc.entity_ref;
 if not found then raise exception 'HANDOVER_VERIFIED_EVIDENCE_REQUIRED';end if;
 canonical:=jsonb_build_object('sender_name',btrim(p_data->>'sender_name'),'recipient_name',btrim(p_data->>'recipient_name'),'handed_at',handed_at,
  'copy_kind',p_data->>'copy_kind','copies',copies,'method',p_data->>'method','note',btrim(coalesce(p_data->>'note','')));
 select * into entry from private.aqari_document_handovers where id=entry_id;
 if found then
  if entry.workspace_id=p_workspace_id and entry.document_id=doc.id and entry.evidence_document_id=proof_id and entry.actor_id=actor and entry.details=canonical then return to_jsonb(entry);end if;
  raise exception 'HANDOVER_IDEMPOTENCY_CONFLICT';
 end if;
 insert into private.aqari_document_handovers(id,workspace_id,document_id,evidence_document_id,actor_id,actor_name,details,source_snapshot,evidence_snapshot)
 values(entry_id,p_workspace_id,doc.id,proof.id,actor,actor_name,canonical,
  jsonb_build_object('id',doc.id,'document_no',doc.document_no,'title',doc.title,'checksum_sha256',doc.checksum_sha256,'uploaded_at',doc.uploaded_at),
  jsonb_build_object('id',proof.id,'document_no',proof.document_no,'title',proof.title,'checksum_sha256',proof.checksum_sha256,'uploaded_at',proof.uploaded_at)) returning * into entry;
 return to_jsonb(entry);
end $function$

CREATE OR REPLACE FUNCTION private.aqari_editor_source_boundary(s text, off integer)
 RETURNS boolean
 LANGUAGE plpgsql
 IMMUTABLE
 SET search_path TO ''
AS $function$
declare lo integer:=0;hi integer;mid integer;n integer;matched text[];token text;cursor_at integer:=1;at_char integer;start16 integer;end16 integer;
begin
 if s is null or off is null or off<0 or off>private.aqari_editor_utf16_length(s) then return false;end if;
 -- Binary search raw source codepoints for the exact UTF-16 boundary. A
 -- position between the two UTF-16 units of an astral character never matches.
 hi:=length(s);
 while lo<=hi loop
  mid:=(lo+hi)/2;n:=private.aqari_editor_utf16_length(left(s,mid));
  if n=off then exit;elsif n<off then lo:=mid+1;else hi:=mid-1;end if;
 end loop;
 if lo>hi then return false;end if;
 -- Same complete and malformed placeholder forms as the browser tokenizer.
 for matched in select regexp_matches(s,'(\{\{[^{}\r\n]*\}\}|\{\([^{}\r\n]*\}\}|\{\{[a-zA-Z0-9_ \t-]*(?:\}|(?=[^a-zA-Z0-9_ \t-]|$))|\{[a-zA-Z0-9_]+\}\})','g') loop
  token:=matched[1];at_char:=strpos(substr(s,cursor_at),token)+cursor_at-1;
  start16:=private.aqari_editor_utf16_length(left(s,at_char-1));end16:=start16+private.aqari_editor_utf16_length(token);
  if off>start16 and off<end16 then return false;end if;
  cursor_at:=at_char+length(token);
 end loop;
 return true;
end $function$

CREATE OR REPLACE FUNCTION private.aqari_editor_style_valid(v jsonb, in_range boolean DEFAULT false)
 RETURNS boolean
 LANGUAGE plpgsql
 IMMUTABLE
 SET search_path TO ''
AS $function$
declare k text;allowed text[];begin
 allowed:=case when in_range then array['font_family','font_pt','bold','underline'] else array['font_family','bold','underline','direction','paragraph_gap_mm','clause_before_mm','clause_after_mm','numbering'] end;
 if not private.aqari_editor_keys(v,allowed) or (in_range and v='{}'::jsonb) then return false;end if;
 for k in select jsonb_object_keys(v) loop
  if k='font_family' then if coalesce(v->>k,'') not in('sans','mono') then return false;end if;
  elsif k='font_pt' then if not private.aqari_editor_number(v->k,8,36) then return false;end if;
  elsif k in('bold','underline') then if jsonb_typeof(v->k) is distinct from 'boolean' then return false;end if;
  elsif k='direction' then if coalesce(v->>k,'') not in('auto','rtl','ltr') then return false;end if;
  elsif k='numbering' then if coalesce(v->>k,'') not in('none','decimal') then return false;end if;
  elsif not private.aqari_editor_number(v->k,0,case when k='paragraph_gap_mm' then 12 else 20 end) then return false;
  end if;
 end loop;return true;
end $function$

CREATE OR REPLACE FUNCTION private.aqari_financial_legacy_guard()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare b jsonb:=private.aqari_unwrap(old.payload); n jsonb:=private.aqari_unwrap(new.payload); k text;
begin
 if coalesce(b->'expenses','[]') is distinct from coalesce(n->'expenses','[]') then
  raise exception 'استخدم سجل المصروفات المعتمدة؛ محفوظات المصروفات السابقة لا تُعدّل.';
 end if;
 if exists(select 1 from private.aqari_financial_periods p where p.workspace_id=new.workspace_id) then
  foreach k in array array['journalEntries','openingBalancesV267','depositReceiptsV267','depositRefundsV267','partnerDistributionsV267','partnerAdjustmentsV267','partnerReservesV267','payroll','bank','cashbox','deposits','advances','invoices'] loop
   if b->k is distinct from n->k then raise exception 'توجد فترة مقفلة؛ لا يمكن تغيير دفتر قديم غير مرتبط بتاريخ قيد معتمد.';end if;
  end loop;
 end if;
 return new;
end $function$

CREATE OR REPLACE FUNCTION private.aqari_financial_open(w uuid, d date)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
begin
 if d is null then raise exception 'تاريخ العملية المالية مطلوب.';end if;
 perform 1 from public.aqari_app_state where workspace_id=w for update;
 if not found then raise exception 'مساحة العمل غير متاحة.';end if;
 if exists(select 1 from private.aqari_financial_periods p where p.workspace_id=w and p.month=date_trunc('month',d)::date) then
  raise exception 'الفترة المالية مقفلة؛ لا يمكن تسجيل أو تغيير عملية فيها.';
 end if;
end $function$

CREATE OR REPLACE FUNCTION private.aqari_financial_row_guard()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare n jsonb; b jsonb; w uuid; d date;
begin
 if tg_op='UPDATE' and to_jsonb(new)=to_jsonb(old) then return new;end if;
 n:=case when tg_op='DELETE' then to_jsonb(old) else to_jsonb(new) end;
 w:=(n->>'workspace_id')::uuid;
 if tg_op in ('UPDATE','DELETE') then b:=to_jsonb(old);end if;
 if tg_op='UPDATE' and n->>'workspace_id' is distinct from b->>'workspace_id' then raise exception 'لا يمكن نقل السجل المالي إلى مساحة عمل أخرى.';end if;
 if tg_table_name='aqari_hr_events' then
  if n->>'kind'='advance' then perform private.aqari_financial_open(w,(n->>'on_date')::date);end if;
  if b->>'kind'='advance' then perform private.aqari_financial_open(w,(b->>'on_date')::date);end if;
  return case when tg_op='DELETE' then old else new end;
 end if;
 if tg_table_name='aqari_rent_payments' then d:=(n->>'paid_at')::date;
 elsif tg_table_name='aqari_hr_payroll' then d:=(n->>'month')::date;
 else d:=(n->>'expense_date')::date;end if;
 perform private.aqari_financial_open(w,d);
 if tg_op in ('UPDATE','DELETE') then
  if tg_table_name='aqari_rent_payments' then perform private.aqari_financial_open(w,(b->>'paid_at')::date);
  elsif tg_table_name='aqari_hr_payroll' then perform private.aqari_financial_open(w,(b->>'month')::date);
  else perform private.aqari_financial_open(w,(b->>'expense_date')::date);end if;
 end if;
 if tg_table_name='aqari_hr_payroll' then
  if n->>'paid_at' is not null then perform private.aqari_financial_open(w,((n->>'paid_at')::timestamptz at time zone 'Asia/Kuwait')::date);end if;
  if b->>'paid_at' is not null then perform private.aqari_financial_open(w,((b->>'paid_at')::timestamptz at time zone 'Asia/Kuwait')::date);end if;
 end if;
 if tg_table_name='aqari_financial_expenses' and tg_op<>'INSERT' then
  if tg_op='DELETE' or old.state='cancelled' then raise exception 'المصروف محفوظ في الأرشيف ولا يقبل الحذف أو التعديل.';end if;
  if old.state='approved' and (new.state<>'cancelled' or
   (to_jsonb(new)-array['state','revision','updated_at','cancelled_by','cancelled_by_name','cancelled_at','cancel_reason']) is distinct from
   (to_jsonb(old)-array['state','revision','updated_at','cancelled_by','cancelled_by_name','cancelled_at','cancel_reason'])) then
   raise exception 'المصروف المعتمد ثابت؛ التصحيح بإلغاء موثق ثم سجل جديد.';
  end if;
 end if;
 return case when tg_op='DELETE' then old else new end;
end $function$

CREATE OR REPLACE FUNCTION private.aqari_guard_cancelled_renewal_commitment()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare lid uuid;
begin
 if tg_table_name='aqari_documents' then
  if new.entity_type<>'lease' or new.document_type<>'signed_contract' or new.status<>'uploaded' then return new;end if;
  select id into lid from public.aqari_leases where workspace_id=new.workspace_id and external_ref=new.entity_ref;
 elsif tg_table_name='aqari_document_handovers' then
  select l.id into lid from public.aqari_documents d join public.aqari_leases l on l.workspace_id=d.workspace_id and l.external_ref=d.entity_ref
   where d.workspace_id=new.workspace_id and d.id=new.document_id and d.entity_type='lease';
 else
  if tg_table_name='aqari_unit_inspections' then
   if new.status<>'signed' then return new;end if;
  end if;
  lid:=new.lease_id;
 end if;
 if lid is null then return new;end if;
 perform 1 from public.aqari_app_state where workspace_id=new.workspace_id for update;
 if exists(select 1 from private.aqari_lease_renewals r join public.aqari_leases l on l.workspace_id=r.workspace_id and l.id=r.successor_lease_id
  where r.workspace_id=new.workspace_id and l.id=lid and l.status='cancelled') then raise exception 'التجديد ملغى؛ لا يمكن إنشاء التزام أو توقيع جديد عليه.';end if;
 return new;
end $function$

CREATE OR REPLACE FUNCTION private.aqari_guard_section_write()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare old_data jsonb;new_data jsonb;k text;
begin
 new_data:=private.aqari_unwrap(new.payload);old_data:=case when tg_op='INSERT' then '{}'::jsonb else private.aqari_unwrap(old.payload) end;
 for k in select jsonb_object_keys(coalesce(old_data,'{}')||coalesce(new_data,'{}')) loop
  if old_data->k is distinct from new_data->k and not private.aqari_can(new.workspace_id,private.aqari_state_section(k),'write') then raise exception 'SECTION_WRITE_DENIED:%',k using errcode='42501';end if;
 end loop;
 return new;
end $function$

CREATE OR REPLACE FUNCTION private.aqari_handle_new_user()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare allowed private.aqari_allowed_users%rowtype;w uuid;t public.aqari_tenants%rowtype;partner_name text;
begin
 select a.display_name into partner_name from private.aqari_partner_access a where a.email=lower(btrim(coalesce(new.email,''))) and a.is_active order by a.updated_at desc limit 1;
 if partner_name is not null then
  if exists(select 1 from private.aqari_allowed_users where email=lower(new.email) and is_active) then raise exception 'PARTNER_STAFF_CONFLICT';end if;
  insert into public.aqari_profiles(user_id,display_name) values(new.id,partner_name);
  update private.aqari_partner_access set user_id=new.id where email=lower(new.email);
  return new;
 end if;
 select * into allowed from private.aqari_allowed_users where email=lower(btrim(coalesce(new.email,''))) and is_active;
 if found then
  select id into w from public.aqari_workspaces where slug=allowed.workspace_slug;
  if w is null then raise exception 'WORKSPACE_NOT_CONFIGURED';end if;
  insert into public.aqari_profiles(user_id,display_name) values(new.id,allowed.display_name);
  insert into public.aqari_memberships(workspace_id,user_id,role,is_active) values(w,new.id,allowed.role,true);
 else
  if (select count(*) from public.aqari_tenants where lower(email)=lower(new.email) and is_active)<>1 then raise exception 'EMAIL_NOT_AUTHORIZED' using errcode='28000';end if;
  select * into t from public.aqari_tenants where lower(email)=lower(new.email) and is_active;
  insert into public.aqari_profiles(user_id,display_name) values(new.id,t.full_name);
  insert into public.aqari_portal_accounts(user_id,workspace_id,tenant_id) values(new.id,t.workspace_id,t.id);
 end if;
 return new;
end $function$

CREATE OR REPLACE FUNCTION private.aqari_hr_cost_split(p_workspace uuid, p_employee uuid, p_net numeric)
 RETURNS TABLE(property_id uuid, share numeric, allocated_net numeric)
 LANGUAGE plpgsql
 STABLE
 SET search_path TO ''
AS $function$
declare props uuid[]; allocations integer; total numeric;
begin
 select e.property_ids into props from private.aqari_hr_employees e where e.id=p_employee and e.workspace_id=p_workspace;
 if coalesce(cardinality(props),0)=0 then raise exception 'HR_COST_ALLOCATION_REQUIRED';end if;
 if p_net is null or p_net::text in ('NaN','Infinity','-Infinity') or p_net<0 or p_net<>round(p_net,3) then raise exception 'INVALID_AMOUNT';end if;
 select count(*),sum(a.share) into allocations,total from private.aqari_hr_cost_allocations a where a.employee_id=p_employee and a.active;
 if (allocations=0 and cardinality(props)<>1) or (allocations>0 and (total<>100 or exists(
  select 1 from private.aqari_hr_cost_allocations a where a.employee_id=p_employee and a.active
   and (a.workspace_id<>p_workspace or not a.property_id=any(props))
  ))) then raise exception 'HR_COST_ALLOCATION_REQUIRED';end if;
 return query
 with portions as (
  select q.id,coalesce(a.share,case when allocations=0 then 100.00 else 0.00 end) as pct
  from unnest(props) q(id) left join private.aqari_hr_cost_allocations a on a.employee_id=p_employee and a.property_id=q.id and a.active
 ), raw as (
  select id,pct,p_net*1000*pct/100 as fils from portions
 ), ranked as (
  select id,pct,floor(fils) as base,row_number() over(order by fils-floor(fils) desc,id) as position,
   p_net*1000-sum(floor(fils)) over() as remainder from raw
 ) select id,pct,(base+case when position<=remainder then 1 else 0 end)/1000 from ranked order by id;
end $function$

CREATE OR REPLACE FUNCTION private.aqari_hr_cycle_audit()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v jsonb:=case when tg_op='DELETE' then to_jsonb(old) else to_jsonb(new) end;
        b jsonb:=case when tg_op='UPDATE' then to_jsonb(old) end; actor text;
begin
 if tg_op='DELETE' then raise exception 'HR_RECORDS_ARE_IMMUTABLE'; end if;
 select display_name into actor from public.aqari_profiles where user_id=auth.uid();
 insert into private.aqari_hr_audit(workspace_id,employee_id,entity,entity_id,actor_id,actor_name,operation,before_value,after_value)
 values((v->>'workspace_id')::uuid,nullif(v->>'employee_id','')::uuid,tg_table_name,
        coalesce(v->>'id',v->>'document_id',v->>'employee_id',v->>'property_id',v->>'month'),auth.uid(),
        coalesce(actor,auth.uid()::text,'system'),tg_op,b,case when tg_op='DELETE' then null else v end);
 return new;
end $function$

CREATE OR REPLACE FUNCTION private.aqari_hr_log()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v jsonb:=to_jsonb(new); b jsonb; actor text;
begin
 if tg_op='UPDATE' then b:=to_jsonb(old);end if;
 if auth.uid() is null then actor:='النظام — تجهيز الرواتب';else select display_name into actor from public.aqari_profiles where user_id=auth.uid();end if;
 insert into private.aqari_hr_audit(workspace_id,employee_id,entity,entity_id,actor_id,actor_name,operation,before_value,after_value)
 values((v->>'workspace_id')::uuid,case when tg_table_name='aqari_hr_employees' then (v->>'id')::uuid else (v->>'employee_id')::uuid end,
 tg_table_name,coalesce(v->>'id',v->>'user_id'),auth.uid(),coalesce(actor,auth.uid()::text),tg_op,b,v);
 return new;
end $function$

CREATE OR REPLACE FUNCTION private.aqari_hr_month_transition_guard()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
begin
 if tg_op='INSERT' and new.state<>'reviewed' then raise exception 'MONTH_REVIEW_REQUIRED';end if;
 if tg_op='UPDATE' and not ((old.state='reviewed' and new.state='approved') or (old.state='approved' and new.state='closed')) then raise exception 'INVALID_MONTH_TRANSITION';end if;
 return new;
end $function$

CREATE OR REPLACE FUNCTION private.aqari_hr_prepare(w uuid, period date, employee uuid DEFAULT NULL::uuid)
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare n integer;
begin
 if period<>date_trunc('month',period)::date then raise exception 'شهر غير صالح.';end if;
 perform 1 from public.aqari_app_state where workspace_id=w for update;
 insert into private.aqari_hr_payroll(workspace_id,employee_id,month,snapshot,basic,allowances)
 select w,e.id,period,e.profile||jsonb_build_object('hired_on',e.hired_on,'property_ids',e.property_ids,'properties',(select jsonb_agg(p.name order by p.name) from public.aqari_properties p where p.workspace_id=w and p.id=any(e.property_ids))),e.basic,e.allowances
 from private.aqari_hr_employees e where e.workspace_id=w and e.status in ('active','leave') and e.hired_on<(period+interval '1 month')::date and (employee is null or e.id=employee)
 on conflict(employee_id,month) do nothing;
 get diagnostics n=row_count;return n;
end $function$

CREATE OR REPLACE FUNCTION private.aqari_hr_salary_snapshot_guard()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare a numeric;d numeric;n numeric;
begin
 if jsonb_typeof(new.snapshot)<>'object' or new.snapshot->>'employee_id'<>new.employee_id::text or new.snapshot->>'id'<>new.payroll_id::text or coalesce(new.snapshot->>'month','') !~ '^\d{4}-\d{2}-01' then raise exception 'INVALID_SALARY_SNAPSHOT_SCOPE';end if;
 if new.replaces_id is not null then
  if not exists(select 1 from private.aqari_hr_salary_registry x where x.id=new.replaces_id and x.payroll_id=new.payroll_id and x.employee_id=new.employee_id and x.status='void') then raise exception 'VOID_SALARY_REQUIRED';end if;
  begin
   a:=coalesce((new.snapshot->>'basic')::numeric,0)+coalesce((new.snapshot->>'allowances')::numeric,0)+coalesce((new.snapshot->>'overtime')::numeric,0)+coalesce((new.snapshot->>'reward')::numeric,0)+coalesce((new.snapshot->>'loan_payment')::numeric,0)+coalesce((new.snapshot->>'housing')::numeric,0)+coalesce((new.snapshot->>'indemnity')::numeric,0)+coalesce((new.snapshot->>'holidays')::numeric,0);
   d:=coalesce((new.snapshot->>'late')::numeric,0)+coalesce((new.snapshot->>'absence')::numeric,0)+coalesce((new.snapshot->>'deductions')::numeric,0)+coalesce((new.snapshot->>'advance_repayment')::numeric,0);n:=(new.snapshot->>'net')::numeric;
  exception when others then raise exception 'INVALID_SALARY_SNAPSHOT_AMOUNTS';end;
  if least(a,d,n)<0 or round(a-d,3)<>round(n,3) then raise exception 'INVALID_SALARY_SNAPSHOT_TOTAL';end if;
 end if;
 return new;
end $function$

CREATE OR REPLACE FUNCTION private.aqari_hr_slip_details(v jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 IMMUTABLE
 SET search_path TO ''
AS $function$
declare k text;
begin
 if jsonb_typeof(v) is distinct from 'object' or coalesce(v->>'template','') not in ('standard','dhahawi-v1') or exists(select 1 from jsonb_object_keys(v) x where x not in ('template','payer_ar','payer_en')) then raise exception 'نموذج سند غير صالح.';end if;
 foreach k in array array['payer_ar','payer_en'] loop
  if v ? k and (jsonb_typeof(v->k) is distinct from 'string' or length(v->>k)>200 or (v->>k) ~ '[<>[:cntrl:]]') then raise exception 'اسم مسؤول صرف غير صالح.';end if;
 end loop;
 return v;
end $function$

CREATE OR REPLACE FUNCTION private.aqari_imported_tenant_read(w uuid, ref text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare tenant public.aqari_tenants; revision bigint; history jsonb;
begin
 if auth.uid() is null or not private.aqari_manager(w) or not private.aqari_can(w,'tenants','read') then raise exception 'غير مصرح بعرض الملف.' using errcode='42501';end if;
 select * into tenant from public.aqari_tenants where workspace_id=w and external_ref=ref and import_source is not null;
 if not found then raise exception 'الملف المستورد غير موجود.';end if;
 select s.revision into revision from public.aqari_app_state s where s.workspace_id=w;
 select coalesce(jsonb_agg(row_to_json(h) order by h.id desc),'[]'::jsonb) into history from
 (select id,reason,created_at,before_profile,after_profile from private.aqari_imported_tenant_edits where workspace_id=w and tenant_id=tenant.id order by id desc limit 10) h;
 return jsonb_build_object('profile',tenant.profile,'revision',revision,'history',history);
end $function$

CREATE OR REPLACE FUNCTION private.aqari_imported_tenant_save(w uuid, ref text, patch jsonb, expected bigint, reason text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare tenant public.aqari_tenants; state public.aqari_app_state; d jsonb; next_profile jsonb; f text; val text; display_name text;
begin
 if auth.uid() is null or not private.aqari_manager(w) or not private.aqari_can(w,'tenants','write') then raise exception 'غير مصرح بتعديل الملف.' using errcode='42501';end if;
 if expected is null or reason is null or length(btrim(reason)) not between 3 and 500 or jsonb_typeof(patch) is distinct from 'object' then raise exception 'أدخل سبب التعديل وراجع البيانات.';end if;
 if exists(select 1 from jsonb_object_keys(patch) k where k not in ('nameAr','nameEn','civilId','passportNo','phone','email','nationality','address')) then raise exception 'لا يمكن تغيير بيانات المصدر أو الربط.';end if;
 select * into state from public.aqari_app_state where workspace_id=w for update;
 if not found or state.revision<>expected then raise exception 'تغيّرت البيانات؛ حدّث الملف قبل الحفظ.' using errcode='40001';end if;
 select * into tenant from public.aqari_tenants where workspace_id=w and external_ref=ref and import_source is not null for update;
 if not found then raise exception 'الملف المستورد غير موجود.';end if;
 d:=private.aqari_unwrap(state.payload);
 if not exists(select 1 from jsonb_array_elements(coalesce(d->'tenantProfilesV267','[]')) x where x->>'id'=ref and x=tenant.profile) then raise exception 'تعارض بين الملف والسجل المحفوظ؛ يلزم المراجعة.';end if;
 next_profile:=tenant.profile;
 for f,val in select key,value from jsonb_each_text(patch) loop
  if jsonb_typeof(patch->f) is distinct from 'string' or length(val)>300 then raise exception 'راجع نوع البيانات وطولها.';end if;
  val:=btrim(val);
  if f in ('civilId','phone') then val:=translate(val,'٠١٢٣٤٥٦٧٨٩۰۱۲۳۴۵۶۷۸۹','01234567890123456789');end if;
  if f='phone' then val:=regexp_replace(val,'[ ()-]','','g');end if;
  next_profile:=jsonb_set(next_profile,array[f],to_jsonb(val));
 end loop;
 display_name:=coalesce(nullif(next_profile->>'nameAr',''),nullif(next_profile->>'nameEn',''));
 if display_name is null then raise exception 'أدخل اسم المستأجر بالعربية أو الإنجليزية.';end if;
 if coalesce(next_profile->>'civilId','')<>'' and next_profile->>'civilId' !~ '^[0-9]{12}$' then raise exception 'الرقم المدني يجب أن يكون ١٢ رقماً أو يُترك فارغاً.';end if;
 if coalesce(next_profile->>'phone','')<>'' and next_profile->>'phone' !~ '^[+]?[0-9]{8,15}$' then raise exception 'راجع رقم الهاتف أو اتركه فارغاً.';end if;
 if coalesce(next_profile->>'email','')<>'' and next_profile->>'email' !~ '^[^[:space:]@]+@[^[:space:]@]+[.][^[:space:]@]+$' then raise exception 'راجع البريد الإلكتروني.';end if;
 if coalesce(next_profile->>'civilId','')<>'' and exists(select 1 from public.aqari_tenants t where t.workspace_id=w and t.id<>tenant.id and t.civil_id=next_profile->>'civilId') then raise exception 'الرقم المدني مرتبط بمستأجر آخر.';end if;
 -- Email is the portal identity; do not silently transfer an existing account.
 if coalesce(tenant.profile->>'email','') is distinct from coalesce(next_profile->>'email','') then
  if exists(select 1 from auth.users u where lower(u.email)=lower(tenant.profile->>'email') or lower(u.email)=lower(next_profile->>'email')) then raise exception 'البريد مرتبط بحساب؛ يلزم إجراء مستقل للتحقق من هوية صاحب الحساب.';end if;
 end if;
 update public.aqari_tenants set full_name=display_name,civil_id=nullif(next_profile->>'civilId',''),phone=nullif(next_profile->>'phone',''),email=nullif(lower(next_profile->>'email'),''),profile=next_profile where id=tenant.id and workspace_id=w;
 d:=jsonb_set(d,'{tenantProfilesV267}',(select jsonb_agg(case when x->>'id'=ref then next_profile else x end order by n) from jsonb_array_elements(d->'tenantProfilesV267') with ordinality a(x,n)));
 d:=jsonb_set(d,'{tenants}',coalesce((select jsonb_agg(case when x->>4=ref or exists(select 1 from jsonb_array_elements(x) v where v->>'aqariTenantProfileV267'=ref) then jsonb_set(x,'{0}',to_jsonb(display_name)) else x end order by n) from jsonb_array_elements(coalesce(d->'tenants','[]')) with ordinality a(x,n)),'[]'));
 d:=jsonb_set(d,'{tenantDirectoryV202}',coalesce((select jsonb_agg(case when x->>'tenantProfileId'=ref then x||jsonb_build_object('tenant',display_name,'nameAr',next_profile->>'nameAr','nameEn',next_profile->>'nameEn','passportNo',next_profile->>'passportNo','phone',next_profile->>'phone','email',next_profile->>'email','civilId',next_profile->>'civilId','nationality',next_profile->>'nationality') else x end order by n) from jsonb_array_elements(coalesce(d->'tenantDirectoryV202','[]')) with ordinality a(x,n)),'[]'));
 d:=jsonb_set(d,'{tenantPreparationDraftsV267}',coalesce((select jsonb_agg(x) from jsonb_array_elements(coalesce(d->'tenantPreparationDraftsV267','[]')) x where x->>'id'<>ref),'[]'));
 -- Contract snapshots, original source statements, receipts and payment records stay historical.
 insert into private.aqari_imported_tenant_edits(workspace_id,tenant_id,actor_id,reason,before_profile,after_profile) values(w,tenant.id,auth.uid(),btrim(reason),tenant.profile,next_profile);
 update public.aqari_app_state set payload=case when state.payload->>'format'='aqari-cloud-state-v1' then jsonb_set(state.payload,'{snapshot,values,aqari_v30}',d) when state.payload->>'schema'='aqari-local-snapshot-v1' then jsonb_set(state.payload,'{values,aqari_v30}',d) else d end,revision=state.revision+1,updated_by=auth.uid(),updated_at=now() where workspace_id=w;
 return private.aqari_imported_tenant_read(w,ref);
end $function$

CREATE OR REPLACE FUNCTION private.aqari_independent_commercial_clearance(w uuid, lid uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
begin
 -- Reject incomplete or unrelated financial source links instead of allowing a
 -- generic credit or a rent payment to erase a separately evidenced obligation.
 if exists(
  select 1 from private.aqari_commercial_sales s
  left join private.aqari_commercial_sales_reversals r on r.workspace_id=s.workspace_id and r.sale_id=s.id
  where s.workspace_id=w and s.lease_id=lid and s.amount>0 and (
   not exists(select 1 from private.aqari_tenant_adjustments a where a.workspace_id=w and a.lease_id=lid
    and a.kind='commercial_sales' and a.source_type='commercial_sales' and a.source_id=s.id and a.direction='debit' and a.amount=s.amount)
   or (r.id is not null and not exists(select 1 from private.aqari_tenant_adjustments a where a.workspace_id=w and a.lease_id=lid
    and a.kind='commercial_sales' and a.source_type='commercial_sales_reversal' and a.source_id=r.id and a.direction='credit' and a.amount=s.amount))
  )
 ) or exists(
  select 1 from private.aqari_tenant_adjustments a where a.workspace_id=w and a.lease_id=lid and a.kind='commercial_sales' and not (
   (a.direction='debit' and a.source_type='commercial_sales' and exists(select 1 from private.aqari_commercial_sales s where s.workspace_id=w and s.lease_id=lid and s.id=a.source_id and s.amount=a.amount))
   or (a.direction='credit' and a.source_type='commercial_sales_reversal' and exists(select 1 from private.aqari_commercial_sales_reversals r join private.aqari_commercial_sales s on s.workspace_id=r.workspace_id and s.id=r.sale_id where r.workspace_id=w and s.lease_id=lid and r.id=a.source_id and s.amount=a.amount))
  )
 ) then
  raise check_violation using message='قيود نسبة المبيعات تحتاج مطابقة مصادرها قبل اعتماد التسوية أو براءة الذمة أو إنهاء العقد.',detail='COMMERCIAL_SALES_LEDGER_REVIEW_REQUIRED';
 end if;
 if to_regprocedure('private.aqari_commercial_balance(uuid,uuid,date)') is not null then
  if (private.aqari_commercial_balance(w,lid,(now() at time zone 'Asia/Kuwait')::date)->>'balance')::numeric<>0 then
   raise check_violation using message='توجد مستحقات نسبة مبيعات غير محسومة. راجع تسجيل التحصيل الموثق وتخصيصه قبل اعتماد التسوية أو براءة الذمة أو إنهاء العقد.',detail='VACATING_COMMERCIAL_BALANCE_REVIEW_REQUIRED';
  end if;
  if exists(select 1 from private.aqari_vacating_settlements v where v.workspace_id=w and v.lease_id=lid and (private.aqari_commercial_balance(w,lid,v.vacate_date)->>'balance')::numeric<>0) then
   raise check_violation using message='COMMERCIAL_COLLECTION_CUTOFF_REVIEW_REQUIRED';
  end if;
  return;
 end if;
 if exists(select 1 from private.aqari_commercial_sales s where s.workspace_id=w and s.lease_id=lid and s.amount>0
  and not exists(select 1 from private.aqari_commercial_sales_reversals r where r.workspace_id=w and r.sale_id=s.id)) then
  raise check_violation using message='توجد مستحقات نسبة مبيعات غير محسومة. راجعها قبل اعتماد التسوية أو براءة الذمة أو إنهاء العقد؛ دفعة الإيجار وحدها لا تسدد هذا الاستحقاق.',detail='VACATING_COMMERCIAL_BALANCE_REVIEW_REQUIRED';
 end if;
end $function$

CREATE OR REPLACE FUNCTION private.aqari_integration_public_metadata_safe(p_value jsonb)
 RETURNS boolean
 LANGUAGE plpgsql
 IMMUTABLE STRICT
 SET search_path TO ''
AS $function$
declare stack jsonb[]:=array[p_value];current_value jsonb;child_value jsonb;key_name text;normalized_key text;last_index integer;visited integer:=0;
begin
 if pg_catalog.jsonb_typeof(p_value)<>'object' then return false;end if;
 while coalesce(pg_catalog.array_length(stack,1),0)>0 loop
  last_index:=pg_catalog.array_upper(stack,1);current_value:=stack[last_index];if last_index=1 then stack:='{}'::jsonb[];else stack:=stack[1:last_index-1];end if;visited:=visited+1;if visited>4096 then return false;end if;
  if pg_catalog.jsonb_typeof(current_value)='object' then
   for key_name,child_value in select key,value from pg_catalog.jsonb_each(current_value) loop
    normalized_key:=pg_catalog.regexp_replace(pg_catalog.lower(key_name),'[_[:space:]-]','','g');
    if normalized_key=any(array['password','secret','token','apikey','civilid','accesstoken','refreshtoken','authorization','servicerolekey']) then return false;end if;
    if pg_catalog.jsonb_typeof(child_value) in('object','array') then if coalesce(pg_catalog.array_length(stack,1),0)>=4096 then return false;end if;stack:=pg_catalog.array_append(stack,child_value);end if;
   end loop;
  elsif pg_catalog.jsonb_typeof(current_value)='array' then
   for child_value in select value from pg_catalog.jsonb_array_elements(current_value) loop if pg_catalog.jsonb_typeof(child_value) in('object','array') then if coalesce(pg_catalog.array_length(stack,1),0)>=4096 then return false;end if;stack:=pg_catalog.array_append(stack,child_value);end if;end loop;
  end if;
 end loop;return true;
end $function$

CREATE OR REPLACE FUNCTION private.aqari_lease_cancellation_guard()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare why text; actor text;
begin
  if old.status='cancelled' and to_jsonb(new) is distinct from to_jsonb(old) then
    raise exception 'CANCELLED_LEASE_IMMUTABLE' using errcode='23514';
  end if;
  if old.status is distinct from 'cancelled' and new.status='cancelled' then
    why:=btrim(coalesce(new.snapshot->>'changeReason',''));
    if length(why) not between 3 and 500 then raise exception 'CANCELLATION_REASON_REQUIRED' using errcode='23514'; end if;
    if auth.uid() is null then raise insufficient_privilege using message='CANCELLATION_ACTOR_REQUIRED'; end if;
    select coalesce(nullif(p.display_name,''),auth.uid()::text) into actor from public.aqari_profiles p where p.user_id=auth.uid();
    actor:=coalesce(actor,auth.uid()::text);
    insert into private.aqari_cancellation_audit(workspace_id,entity_type,entity_id,action,reason,actor_id,actor_name,before_value,after_value)
    values(new.workspace_id,'lease',new.id::text,'cancel',why,auth.uid(),actor,to_jsonb(old),to_jsonb(new));
  end if;
  return new;
end $function$

CREATE OR REPLACE FUNCTION private.aqari_lease_renewal_context(w uuid, ref text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare l public.aqari_leases; reason text; source_value jsonb;
begin
 if auth.uid() is null or not private.aqari_can(w,'contracts','read') then raise insufficient_privilege using message='ACCESS_DENIED';end if;
 perform 1 from public.aqari_app_state where workspace_id=w for share;
 select * into l from public.aqari_leases where workspace_id=w and external_ref=ref;
 if not found or not private.aqari_can_lease(w,l.id,'contracts','read') then raise insufficient_privilege using message='ACCESS_DENIED';end if;
 source_value:=private.aqari_renewal_source(w,l.id);
 if not private.aqari_can_lease(w,l.id,'contracts','write') then reason:='صلاحية إنشاء عقد مطلوبة لإعداد التجديد.';
 elsif l.status not in('approved','signed','expired') or l.start_date is null or l.end_date is null or l.vacated_on is not null then reason:='التجديد يحتاج عقدًا معتمدًا أو موقّعًا أو منتهي المدة بتواريخ مكتملة، دون إخلاء مسجّل.';
 elsif exists(select 1 from private.aqari_cheques c join public.aqari_leases prior on prior.workspace_id=c.workspace_id and prior.id=c.lease_id where c.workspace_id=w and c.renewal_frozen and prior.tenant_id=l.tenant_id and prior.unit_id=l.unit_id) then reason:='تجميد التجديد ما زال قائمًا في سجل الشيكات لهذا المستأجر والوحدة.';
 elsif exists(select 1 from private.aqari_lease_renewals r join public.aqari_leases next_lease on next_lease.workspace_id=r.workspace_id and next_lease.id=r.successor_lease_id where r.workspace_id=w and r.predecessor_lease_id=l.id and next_lease.status<>'cancelled') then reason:='يوجد عقد تجديد محفوظ لهذا الأصل. افتحه لاستكماله بدل إنشاء نسخة أخرى.';
 end if;
 return jsonb_build_object('workspace_id',w,'user_id',auth.uid(),'can_prepare',reason is null,'reason',reason,
  'source',source_value,'suggestedStart',case when l.end_date is not null then to_char(l.end_date+1,'YYYY-MM-DD') end);
end $function$

CREATE OR REPLACE FUNCTION private.aqari_maintenance_attachments(w uuid, r uuid, action text, d jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare doc private.aqari_maintenance_attachments;ident uuid;can_write boolean;reason text;
begin
 if auth.uid() is null or not private.aqari_maintenance_attachment_access(w,r,false) then raise insufficient_privilege using message='ACCESS_DENIED';end if;
 can_write:=private.aqari_maintenance_attachment_access(w,r,true);
 if action='list' then return jsonb_build_object(
  'can_upload',can_write,
  'attachments',coalesce((select jsonb_agg(to_jsonb(a) order by a.created_at,a.id) from private.aqari_maintenance_attachments a where a.workspace_id=w and a.request_id=r and a.status='uploaded'),'[]'::jsonb),
  'pending_reservations',case when can_write then coalesce((select jsonb_agg(to_jsonb(a) order by a.created_at,a.id) from private.aqari_maintenance_attachments a where a.workspace_id=w and a.request_id=r and a.status='reserved' and a.created_by=auth.uid()),'[]'::jsonb) else '[]'::jsonb end
 );end if;
 if coalesce(action,'') not in('reserve','finalize','cancel') then raise insufficient_privilege using message='ACCESS_DENIED';end if;
 if d is null or jsonb_typeof(d)<>'object' then raise invalid_parameter_value using message='INVALID_ATTACHMENT';end if;
 ident:=nullif(d->>'id','')::uuid;if ident is null then raise invalid_parameter_value using message='INVALID_ATTACHMENT';end if;
 perform 1 from public.aqari_maintenance_requests where workspace_id=w and id=r for update;
 select * into doc from private.aqari_maintenance_attachments where id=ident for update;
 if doc.id is not null and (doc.workspace_id<>w or doc.request_id<>r or doc.created_by<>auth.uid()) then raise insufficient_privilege using message='ACCESS_DENIED';end if;
 if not can_write and not(action='finalize' and coalesce(doc.status='uploaded',false)) then raise insufficient_privilege using message='ACCESS_DENIED';end if;
 if action='cancel' then
  if doc.id is null then raise invalid_parameter_value using message='ATTACHMENT_NOT_CONFIRMED';end if;
  if doc.status='uploaded' then raise invalid_parameter_value using message='ATTACHMENT_ALREADY_FINALIZED';end if;
  if doc.status='cancelled' then return to_jsonb(doc)||jsonb_build_object('cancellation_reused',true);end if;
  reason:=btrim(coalesce(nullif(d->>'reason',''),'user_cancelled_incomplete_upload'));
  if length(reason) not between 6 and 240 then raise invalid_parameter_value using message='INVALID_CANCEL_REASON';end if;
  if exists(select 1 from storage.objects o where o.bucket_id=doc.storage_bucket and o.name=doc.storage_path) then raise invalid_parameter_value using message='ATTACHMENT_OBJECT_PRESENT';end if;
  update private.aqari_maintenance_attachments
   set status='cancelled',cancelled_at=now(),cancelled_by=auth.uid(),cancel_reason=reason
   where id=ident and status='reserved' returning * into doc;
  if doc.id is null then raise invalid_parameter_value using message='ATTACHMENT_NOT_CONFIRMED';end if;
  return to_jsonb(doc)||jsonb_build_object('cancellation_reused',false);
 end if;
 if action='reserve' then
  if coalesce(d->>'mime_type','') not in ('image/jpeg','image/png','image/webp','application/pdf')
   or coalesce(d->>'size_bytes','')!~'^[0-9]{1,8}$' or (d->>'size_bytes')::integer not between 1 and 10485760
   or length(btrim(coalesce(d->>'filename',''))) not between 1 and 180
   or d->>'filename' ~ '[[:cntrl:]/\\]' or coalesce(d->>'checksum_sha256','')!~'^[a-f0-9]{64}$' then raise invalid_parameter_value using message='INVALID_ATTACHMENT';end if;
  if doc.id is not null then
   if doc.status='cancelled' then raise invalid_parameter_value using message='ATTACHMENT_RESERVATION_CANCELLED';end if;
   if doc.filename<>d->>'filename' or doc.mime_type<>d->>'mime_type' or doc.size_bytes<>(d->>'size_bytes')::integer or doc.checksum_sha256<>d->>'checksum_sha256' then raise invalid_parameter_value using message='ATTACHMENT_RESERVATION_CONFLICT';end if;
   return to_jsonb(doc)||jsonb_build_object('reservation_reused',true);
  end if;
  select * into doc from private.aqari_maintenance_attachments a
   where a.workspace_id=w and a.request_id=r and a.created_by=auth.uid() and a.status in('reserved','uploaded')
    and a.filename=d->>'filename' and a.mime_type=d->>'mime_type'
    and a.size_bytes=(d->>'size_bytes')::integer and a.checksum_sha256=d->>'checksum_sha256'
   order by a.created_at,a.id limit 1 for update;
  if doc.id is not null then return to_jsonb(doc)||jsonb_build_object('reservation_reused',true);end if;
  if (select count(*) from private.aqari_maintenance_attachments where workspace_id=w and request_id=r and status in('reserved','uploaded'))>=8 then raise invalid_parameter_value using message='ATTACHMENT_LIMIT_REACHED';end if;
  insert into private.aqari_maintenance_attachments(id,workspace_id,request_id,filename,mime_type,size_bytes,checksum_sha256,storage_path,created_by)
   values(ident,w,r,d->>'filename',d->>'mime_type',(d->>'size_bytes')::integer,d->>'checksum_sha256',w::text||'/'||r::text||'/'||ident::text,auth.uid()) returning * into doc;
  return to_jsonb(doc)||jsonb_build_object('reservation_reused',false);
 end if;
 if doc.id is null or doc.status='cancelled' or doc.checksum_sha256 is distinct from d->>'checksum_sha256' then raise invalid_parameter_value using message='ATTACHMENT_NOT_CONFIRMED';end if;
 if not exists(select 1 from storage.objects o where o.bucket_id=doc.storage_bucket and o.name=doc.storage_path
  and o.metadata->>'size'=doc.size_bytes::text and o.metadata->>'mimetype'=doc.mime_type) then raise invalid_parameter_value using message='STORED_FILE_NOT_CONFIRMED';end if;
 if doc.status='reserved' then update private.aqari_maintenance_attachments set status='uploaded',uploaded_at=now() where id=ident returning * into doc;end if;
 return to_jsonb(doc);
end $function$

CREATE OR REPLACE FUNCTION private.aqari_maintenance_evidence_status_guard()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
begin
 if new.status is distinct from old.status then
  if new.status='in_progress' and new.evidence_policy_version>=1
   and not exists(select 1 from private.aqari_maintenance_evidence e where e.workspace_id=new.workspace_id and e.task_id=new.id and e.stage='before')
  then raise check_violation using message='MAINTENANCE_BEFORE_EVIDENCE_REQUIRED';end if;
  if new.status='completed' then
   if not exists(select 1 from private.aqari_maintenance_evidence e where e.workspace_id=new.workspace_id and e.task_id=new.id and e.stage='after')
   then raise check_violation using message='MAINTENANCE_AFTER_EVIDENCE_REQUIRED';end if;
   if new.evidence_policy_version>=1
    and not exists(select 1 from private.aqari_maintenance_evidence e where e.workspace_id=new.workspace_id and e.task_id=new.id and e.stage='before')
   then raise check_violation using message='MAINTENANCE_BEFORE_EVIDENCE_REQUIRED';end if;
  end if;
 end if;
 return new;
end $function$

CREATE OR REPLACE FUNCTION private.aqari_maintenance_report_payload(p_action text)
 RETURNS jsonb
 LANGUAGE plpgsql
 IMMUTABLE
 SET search_path TO ''
AS $function$
declare payload jsonb;
begin
 if p_action is null or left(ltrim(p_action),1)<>'{' then return null;end if;
 begin payload:=p_action::jsonb;
 exception when invalid_text_representation then return null;end;
 if jsonb_typeof(payload)<>'object' or payload->>'operation' is distinct from 'maintenance_update' then return null;end if;
 return payload;
end $function$

CREATE OR REPLACE FUNCTION private.aqari_maintenance_workflow(p_workspace_id uuid, p_action text, p_data jsonb DEFAULT '{}'::jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare w uuid:=p_workspace_id;d jsonb:=p_data;ident uuid;expected integer;plan private.aqari_maintenance_plans;task private.aqari_property_maintenance_tasks;before_row jsonb;after_row jsonb;prop uuid;doc uuid;actor text;why text;as_of_date date;next_date date;vendor_id uuid;contract private.aqari_vendor_contracts;photo jsonb;
begin
 if auth.uid() is null or not private.aqari_can(w,'maintenance','read') then raise insufficient_privilege using message='ACCESS_DENIED';end if;
 if d is null or jsonb_typeof(d)<>'object' or octet_length(d::text)>16000 then raise exception 'INVALID_MAINTENANCE_PLAN_DATA' using errcode='22023';end if;
 if p_action='list' then
  return jsonb_build_object(
   'workflow_version',2,'can_complete',private.aqari_can(w,'maintenance','write') and private.aqari_can(w,'documents','read'),'manager',private.aqari_manager(w),'can_write',private.aqari_can(w,'maintenance','write'),
   'properties',(select coalesce(jsonb_agg(jsonb_build_object('id',p.id,'name',p.name) order by p.name),'[]') from public.aqari_properties p where p.workspace_id=w and private.aqari_can_property(w,p.id,'maintenance','read')),
   'vendors',(select coalesce(jsonb_agg(jsonb_build_object('id',v.id,'name',v.name) order by v.name),'[]') from private.aqari_vendors v where v.workspace_id=w and v.status='active'),
   'contracts',(select coalesce(jsonb_agg(jsonb_build_object('id',c.id,'contract_no',c.contract_no,'property_id',c.property_id,'vendor_id',c.vendor_id,'starts_on',c.starts_on,'ends_on',c.ends_on,'service_kind',c.service_kind) order by c.ends_on),'[]') from private.aqari_vendor_contracts c join private.aqari_vendors v on v.workspace_id=c.workspace_id and v.id=c.vendor_id where c.workspace_id=w and c.status in('approved','active') and v.status='active' and (c.property_id is null or private.aqari_can_property(w,c.property_id,'maintenance','read'))),
   'documents',(select coalesce(jsonb_agg(jsonb_build_object('id',doc.id,'title',doc.title,'document_no',doc.document_no,'property_id',p.id,'mime_type',doc.mime_type) order by doc.created_at desc),'[]') from public.aqari_documents doc join public.aqari_properties p on p.workspace_id=doc.workspace_id and p.external_ref=doc.entity_ref where doc.workspace_id=w and doc.entity_type='property' and doc.status='uploaded' and private.aqari_can(w,'documents','read') and private.aqari_document_entity(w,doc.entity_type,doc.entity_ref,'read') and private.aqari_can_property(w,p.id,'maintenance','read')),
   'plans',(select coalesce(jsonb_agg(to_jsonb(p) order by p.next_due_on,p.id),'[]') from private.aqari_maintenance_plans p where p.workspace_id=w and private.aqari_can_property(w,p.property_id,'maintenance','read')),
   'tasks',(select coalesce(jsonb_agg(to_jsonb(t) order by t.due_on desc,t.id),'[]') from private.aqari_property_maintenance_tasks t where t.workspace_id=w and private.aqari_can_property(w,t.property_id,'maintenance','read')),
   'alerts',(select coalesce(jsonb_agg(to_jsonb(n) order by n.scheduled_for desc,n.id),'[]') from (select * from private.aqari_notification_deliveries n where n.workspace_id=w and n.kind in('maintenance_due','lease_expiry','vendor_contract_expiry') and (private.aqari_manager(w) or (n.kind='maintenance_due' and exists(select 1 from private.aqari_maintenance_plans p where p.workspace_id=w and p.id::text=n.aggregate_id and private.aqari_can_property(w,p.property_id,'maintenance','read')))) order by n.scheduled_for desc limit 100)n),
   'runs',(select coalesce(jsonb_agg(to_jsonb(r) order by r.as_of desc),'[]') from (select * from private.aqari_alert_preparation_runs r where r.workspace_id=w and private.aqari_manager(w) order by r.as_of desc limit 30)r)
  );
 end if;
 if not private.aqari_can(w,'maintenance','write') then raise insufficient_privilege using message='ACCESS_DENIED';end if;
 perform private.aqari_require_sensitive_aal2(w);
 select coalesce(nullif(display_name,''),auth.uid()::text) into actor from public.aqari_profiles where user_id=auth.uid();actor:=coalesce(actor,auth.uid()::text);
 if p_action='prepare_alerts' then
  if not private.aqari_manager(w) then raise insufficient_privilege using message='ACCESS_DENIED';end if;
  as_of_date:=coalesce(nullif(d->>'as_of','')::date,(now() at time zone 'Asia/Kuwait')::date);
  return private.aqari_prepare_operational_alerts(w,as_of_date);
 end if;
 ident:=nullif(d->>'id','')::uuid;if ident is null then raise exception 'PLAN_OR_TASK_ID_REQUIRED' using errcode='22023';end if;
 if p_action='save' then
  prop:=nullif(d->>'property_id','')::uuid;if not private.aqari_can_property(w,prop,'maintenance','write') then raise insufficient_privilege using message='ACCESS_DENIED';end if;
  select * into plan from private.aqari_maintenance_plans p where p.workspace_id=w and p.id=ident for update;
  if plan.id is not null and not private.aqari_can_property(w,plan.property_id,'maintenance','write') then raise insufficient_privilege using message='ACCESS_DENIED';end if;
  if plan.id is not null and prop is distinct from plan.property_id then raise exception 'PLAN_PROPERTY_IMMUTABLE' using errcode='23514';end if;
  expected:=coalesce((d->>'revision')::integer,0);if coalesce(plan.revision,0) is distinct from expected then raise serialization_failure using message='REVISION_CONFLICT';end if;
  if d->>'asset_kind' not in('elevator','air_conditioning','fire_system','water_tank','generator','plumbing','electrical','other') or length(btrim(coalesce(d->>'title',''))) not between 3 and 200 or (d->>'frequency_days')::integer not between 1 and 730 then raise exception 'INVALID_MAINTENANCE_PLAN' using errcode='22023';end if;
  if plan.id is not null and exists(select 1 from private.aqari_property_maintenance_tasks t where t.workspace_id=w and t.plan_id=plan.id and t.status not in('completed','cancelled'))
   and (plan.next_due_on is distinct from (d->>'next_due_on')::date or plan.frequency_days is distinct from (d->>'frequency_days')::integer or plan.vendor_contract_id is distinct from nullif(d->>'vendor_contract_id','')::uuid or plan.asset_kind is distinct from d->>'asset_kind') then raise exception 'OPEN_TASK_SCHEDULE_LOCKED' using errcode='23514';end if;
  if coalesce((d->>'is_active')::boolean,true) and nullif(d->>'vendor_contract_id','') is not null then
   select * into contract from private.aqari_vendor_contracts c where c.workspace_id=w and c.id=(d->>'vendor_contract_id')::uuid;
   if not found or contract.property_id is not null and contract.property_id<>prop or contract.status not in('approved','active') or (d->>'next_due_on')::date not between contract.starts_on and contract.ends_on
    or not exists(select 1 from private.aqari_vendors v where v.workspace_id=w and v.id=contract.vendor_id and v.status='active') then raise exception 'VENDOR_CONTRACT_NOT_VALID_FOR_PLAN' using errcode='23514';end if;
  end if;
  before_row:=case when plan.id is null then null else to_jsonb(plan) end;
  if plan.id is null then insert into private.aqari_maintenance_plans(id,workspace_id,property_id,vendor_contract_id,asset_kind,title,frequency_days,next_due_on,warning_days,is_active,created_by)
   values(ident,w,prop,nullif(d->>'vendor_contract_id','')::uuid,d->>'asset_kind',btrim(d->>'title'),(d->>'frequency_days')::integer,(d->>'next_due_on')::date,case when jsonb_typeof(d->'warning_days')='array' and jsonb_array_length(d->'warning_days')>0 then array(select jsonb_array_elements_text(d->'warning_days')::integer) else array[90,60,30] end,coalesce((d->>'is_active')::boolean,true),auth.uid()) returning * into plan;
  else update private.aqari_maintenance_plans p set property_id=prop,vendor_contract_id=nullif(d->>'vendor_contract_id','')::uuid,asset_kind=d->>'asset_kind',title=btrim(d->>'title'),frequency_days=(d->>'frequency_days')::integer,next_due_on=(d->>'next_due_on')::date,warning_days=case when jsonb_typeof(d->'warning_days')='array' and jsonb_array_length(d->'warning_days')>0 then array(select jsonb_array_elements_text(d->'warning_days')::integer) else p.warning_days end,is_active=coalesce((d->>'is_active')::boolean,p.is_active),revision=p.revision+1,updated_at=now() where p.id=ident returning * into plan;end if;
  after_row:=to_jsonb(plan);
 elsif p_action='generate_task' then
  select * into plan from private.aqari_maintenance_plans p where p.workspace_id=w and p.id=ident and p.is_active for update;
  if not found or not private.aqari_can_property(w,plan.property_id,'maintenance','write') then raise insufficient_privilege using message='ACCESS_DENIED';end if;
  if exists(select 1 from private.aqari_property_maintenance_tasks t where t.workspace_id=w and t.plan_id=plan.id and t.due_on=plan.next_due_on) then raise exception 'DUPLICATE_DUE_TASK' using errcode='23505';end if;
  vendor_id:=nullif(d->>'vendor_id','')::uuid;
  if plan.vendor_contract_id is not null then
   select * into contract from private.aqari_vendor_contracts c where c.workspace_id=w and c.id=plan.vendor_contract_id;
   if not found or contract.property_id is not null and contract.property_id<>plan.property_id or contract.status not in('approved','active') or plan.next_due_on not between contract.starts_on and contract.ends_on then raise exception 'VENDOR_CONTRACT_NOT_VALID_FOR_PLAN' using errcode='23514';end if;
   if vendor_id is not null and vendor_id<>contract.vendor_id then raise exception 'VENDOR_CONTRACT_MISMATCH' using errcode='23514';end if;
   vendor_id:=contract.vendor_id;
  end if;
  if vendor_id is not null and not exists(select 1 from private.aqari_vendors v where v.workspace_id=w and v.id=vendor_id and v.status='active') then raise exception 'ACTIVE_VENDOR_REQUIRED' using errcode='23514';end if;
  task.id:=nullif(d->>'task_id','')::uuid;
  if task.id is null or length(btrim(coalesce(d->>'task_no',''))) not between 3 and 80 then raise exception 'TASK_REFERENCE_REQUIRED' using errcode='22023';end if;
  insert into private.aqari_property_maintenance_tasks(id,workspace_id,plan_id,property_id,due_on,task_no,assigned_vendor_id,description,status,assigned_by,assigned_at)
   values(task.id,w,plan.id,plan.property_id,plan.next_due_on,btrim(d->>'task_no'),vendor_id,btrim(coalesce(d->>'description',plan.title)),case when vendor_id is null then 'scheduled' else 'assigned' end,case when vendor_id is not null then auth.uid() end,case when vendor_id is not null then now() end) returning * into task;
  after_row:=to_jsonb(task);
 elsif p_action in('assign_task','start_task','cancel_task') then
  select p.* into plan from private.aqari_maintenance_plans p join private.aqari_property_maintenance_tasks t on t.workspace_id=p.workspace_id and t.plan_id=p.id where t.workspace_id=w and t.id=ident for update of p;
  select * into task from private.aqari_property_maintenance_tasks t where t.workspace_id=w and t.id=ident for update;
  if not found or plan.id is null or plan.property_id is distinct from task.property_id or not private.aqari_can_property(w,task.property_id,'maintenance','write') then raise insufficient_privilege using message='ACCESS_DENIED';end if;
  if task.revision is distinct from (d->>'revision')::integer or task.status in('completed','cancelled') then raise serialization_failure using message='REVISION_CONFLICT';end if;
  before_row:=to_jsonb(task);why:=btrim(coalesce(d->>'reason',''));
  if length(why) not between 3 and 1000 then raise exception 'MAINTENANCE_REASON_REQUIRED' using errcode='22023';end if;
  if p_action='assign_task' then
   if task.status not in('scheduled','assigned') then raise exception 'TASK_ASSIGNMENT_CLOSED' using errcode='23514';end if;
   vendor_id:=nullif(d->>'vendor_id','')::uuid;
   if not exists(select 1 from private.aqari_vendors v where v.workspace_id=w and v.id=vendor_id and v.status='active') then raise exception 'ACTIVE_VENDOR_REQUIRED' using errcode='23514';end if;
   if plan.vendor_contract_id is not null then
    select * into contract from private.aqari_vendor_contracts c where c.workspace_id=w and c.id=plan.vendor_contract_id;
    if contract.property_id is not null and contract.property_id<>task.property_id or contract.vendor_id is distinct from vendor_id or contract.status not in('approved','active') or task.due_on not between contract.starts_on and contract.ends_on then raise exception 'VENDOR_CONTRACT_MISMATCH' using errcode='23514';end if;
   end if;
   update private.aqari_property_maintenance_tasks set status='assigned',assigned_vendor_id=vendor_id,assigned_by=auth.uid(),assigned_at=now(),revision=revision+1 where id=ident returning * into task;
  elsif p_action='start_task' then
   if task.status<>'assigned' or not exists(select 1 from private.aqari_vendors v where v.workspace_id=w and v.id=task.assigned_vendor_id and v.status='active') then raise exception 'TASK_ASSIGNMENT_REQUIRED' using errcode='23514';end if;
   if plan.vendor_contract_id is not null then
    select * into contract from private.aqari_vendor_contracts c where c.workspace_id=w and c.id=plan.vendor_contract_id;
    if not found or contract.property_id is not null and contract.property_id<>task.property_id or contract.vendor_id is distinct from task.assigned_vendor_id or contract.status not in('approved','active') or task.due_on not between contract.starts_on and contract.ends_on then raise exception 'VENDOR_CONTRACT_MISMATCH' using errcode='23514';end if;
   end if;
   update private.aqari_property_maintenance_tasks set status='in_progress',started_at=now(),revision=revision+1 where id=ident returning * into task;
  else
   update private.aqari_property_maintenance_tasks set status='cancelled',cancelled_at=now(),cancelled_by=auth.uid(),cancellation_reason=why,revision=revision+1 where id=ident returning * into task;
  end if;
  after_row:=to_jsonb(task);
 elsif p_action='complete_task' then
  select p.* into plan from private.aqari_maintenance_plans p join private.aqari_property_maintenance_tasks t on t.workspace_id=p.workspace_id and t.plan_id=p.id where t.workspace_id=w and t.id=ident for update of p;
  select * into task from private.aqari_property_maintenance_tasks t where t.workspace_id=w and t.id=ident for update;
  if not found or plan.id is null or plan.property_id is distinct from task.property_id or not private.aqari_can_property(w,task.property_id,'maintenance','write') then raise insufficient_privilege using message='ACCESS_DENIED';end if;
  expected:=(d->>'revision')::integer;if task.revision is distinct from expected or task.status not in('scheduled','assigned','in_progress') then raise serialization_failure using message='REVISION_CONFLICT';end if;
  if task.status<>'in_progress' then raise exception 'TASK_EXECUTION_REQUIRED' using errcode='23514';end if;
  if not private.aqari_can(w,'documents','read') then raise insufficient_privilege using message='ACCESS_DENIED';end if;
  doc:=nullif(d->>'completion_document_id','')::uuid;
  if not private.aqari_operations_document(w,task.property_id,doc) then raise exception 'COMPLETION_DOCUMENT_REQUIRED' using errcode='23514';end if;
  if jsonb_typeof(d->'photo_document_ids') is distinct from 'array' or jsonb_array_length(d->'photo_document_ids') not between 1 and 20 then raise exception 'COMPLETION_PHOTOS_REQUIRED' using errcode='23514';end if;
  for photo in select value from jsonb_array_elements(d->'photo_document_ids') loop
   if jsonb_typeof(photo)<>'string' or not exists(select 1 from public.aqari_documents x where x.workspace_id=w and x.id=(photo#>>'{}')::uuid and x.mime_type in('image/jpeg','image/png','image/webp','image/heic','image/heif') and private.aqari_document_entity(w,x.entity_type,x.entity_ref,'read')) or not private.aqari_operations_document(w,task.property_id,(photo#>>'{}')::uuid) then raise exception 'COMPLETION_PHOTO_NOT_VERIFIED' using errcode='23514';end if;
  end loop;
  before_row:=to_jsonb(task);why:=btrim(coalesce(d->>'reason',''));if length(why)<3 then raise exception 'COMPLETION_REASON_REQUIRED' using errcode='22023';end if;
  update private.aqari_property_maintenance_tasks t set status='completed',cost=private.aqari_hr_money(d->'cost'),photo_document_ids=coalesce(d->'photo_document_ids','[]'),completion_document_id=doc,completed_by=auth.uid(),completed_at=now(),revision=t.revision+1 where t.id=ident returning * into task;
  select task.due_on+p.frequency_days into next_date from private.aqari_maintenance_plans p where p.id=task.plan_id for update;
  update private.aqari_maintenance_plans p set next_due_on=next_date,revision=p.revision+1,updated_at=now() where p.id=task.plan_id;
  after_row:=to_jsonb(task)||jsonb_build_object('next_due_on',next_date);
 else raise exception 'INVALID_MAINTENANCE_PLAN_ACTION' using errcode='22023';end if;
 insert into private.aqari_operations_audit(workspace_id,domain,entity_id,action,actor_id,actor_name,reason,before_value,after_value)
 values(w,'maintenance_plans',ident,p_action,auth.uid(),actor,coalesce(why,''),before_row,after_row);
 return after_row;
end $function$

CREATE OR REPLACE FUNCTION private.aqari_manage_partner_access(w uuid, email_address text, property uuid, partner_name text, enabled boolean, expected bigint, reason text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
 target_email text:=lower(btrim(email_address));
 target_user uuid;
 old_row private.aqari_partner_access%rowtype;
 saved private.aqari_partner_access%rowtype;
begin
 if auth.uid() is null or not private.aqari_manager(w) then
  raise exception 'ACCESS_DENIED' using errcode='42501';
 end if;

 perform private.aqari_require_sensitive_aal2(w);

 if target_email is null
  or target_email !~ '^[^[:space:]@]+@[^[:space:]@]+[.][^[:space:]@]+$'
  or length(target_email)>254
  or partner_name is null
  or length(btrim(partner_name)) not between 1 and 120
  or enabled is null
  or reason is null
  or length(btrim(reason)) not between 3 and 500
  or expected is null
  or expected<0 then
  raise exception 'INVALID_PARTNER_ACCESS';
 end if;

 perform 1 from public.aqari_workspaces where id=w for update;
 if not exists(
  select 1 from public.aqari_properties p
  where p.id=property and p.workspace_id=w
 ) then
  raise exception 'ACCESS_DENIED' using errcode='42501';
 end if;

 select id into target_user
 from auth.users
 where lower(email)=target_email
 for update;

 if exists(
  select 1 from public.aqari_memberships m
  where m.user_id=target_user and m.workspace_id=w
 ) or exists(
  select 1
  from private.aqari_allowed_users a
  join public.aqari_workspaces x on x.slug=a.workspace_slug
  where a.email=target_email and x.id=w
 ) then
  raise exception 'PARTNER_STAFF_CONFLICT' using errcode='42501';
 end if;

 select * into old_row
 from private.aqari_partner_access a
 where a.workspace_id=w and a.email=target_email and a.property_id=property;

 if coalesce(old_row.revision,0) is distinct from expected then
  raise exception 'REVISION_CONFLICT' using errcode='40001';
 end if;

 insert into private.aqari_partner_access(
  workspace_id,email,property_id,user_id,display_name,is_active,revision,updated_by
 ) values(
  w,target_email,property,target_user,btrim(partner_name),enabled,
  coalesce(old_row.revision,0)+1,auth.uid()
 )
 on conflict(workspace_id,email,property_id) do update set
  user_id=excluded.user_id,
  display_name=excluded.display_name,
  is_active=excluded.is_active,
  revision=excluded.revision,
  updated_by=excluded.updated_by,
  updated_at=now()
 returning * into saved;

 insert into public.aqari_control_audit(
  workspace_id,actor_id,action,entity_ref,reason,before_value,after_value
 ) values(
  w,auth.uid(),'partner.access',property::text,btrim(reason),
  to_jsonb(old_row),to_jsonb(saved)
 );

 return to_jsonb(saved)-'updated_by';
end $function$

CREATE OR REPLACE FUNCTION private.aqari_manager_contract_guard()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare next_data jsonb:=private.aqari_unwrap(new.payload); previous_data jsonb:=private.aqari_unwrap(old.payload); c jsonb; old_c jsonb;
begin
 if auth.uid() is not null and not private.aqari_manager(new.workspace_id) then
  if coalesce(next_data->'contractsV202','[]') is distinct from coalesce(previous_data->'contractsV202','[]')
   or coalesce(next_data->'contractPreparationDraftsV267','[]') is distinct from coalesce(previous_data->'contractPreparationDraftsV267','[]')
  then raise insufficient_privilege using message='تعديل العقود وإنشاؤها واعتمادها متاح للمدير العام فقط. قدّم طلب تعديل.';end if;
 end if;
 for c in select value from jsonb_array_elements(coalesce(next_data->'contractsV202','[]')) loop
  select value into old_c from jsonb_array_elements(coalesce(previous_data->'contractsV202','[]')) where value->>'id'=c->>'id';
  if c->>'status'='signed' and old_c->>'status' is distinct from 'signed' and not exists(
   select 1 from public.aqari_documents doc
   cross join lateral (select s.status,s.contract_sha256 from private.aqari_contract_signature_reviews s where s.workspace_id=new.workspace_id and s.document_id=doc.id order by s.reviewed_at desc,s.id desc limit 1) review
   where doc.workspace_id=new.workspace_id and doc.entity_type='lease' and doc.entity_ref=c->>'id' and doc.document_type='signed_contract' and doc.status='uploaded' and review.status='complete' and review.contract_sha256=encode(sha256(convert_to((c-array['status','changeReason','updatedAt'])::text,'UTF8')),'hex')
  ) then raise exception 'ناقص توقيع: ارفع النسخة الموقعة وراجع جميع التواقيع قبل إكمال العقد.';end if;
 end loop;
 return new;
end $function$

CREATE OR REPLACE FUNCTION private.aqari_normalize_weighted_allocation(total numeric, weights jsonb, method text)
 RETURNS jsonb
 LANGUAGE plpgsql
 IMMUTABLE
 SET search_path TO ''
AS $function$
declare result jsonb;total_fils bigint;sum_weight numeric;
begin
 if total is null or total<=0 or total<>round(total,3) or jsonb_typeof(weights)<>'array' or jsonb_array_length(weights)<1 then raise invalid_parameter_value using message='INVALID_WEIGHTED_ALLOCATION';end if;
 total_fils:=round(total*1000)::bigint;
 if exists(select 1 from jsonb_array_elements(weights)r where jsonb_typeof(r)<>'object' or coalesce(r->>'propertyId','')!~'^[0-9a-fA-F-]{36}$' or coalesce(r->>'weight','')!~'^\d{1,18}(\.\d{1,6})?$' or (r->>'weight')::numeric<=0) then raise invalid_parameter_value using message='INVALID_ALLOCATION_WEIGHT';end if;
 select sum((r->>'weight')::numeric) into sum_weight from jsonb_array_elements(weights)r;if sum_weight<=0 then raise invalid_parameter_value using message='INVALID_ALLOCATION_WEIGHT';end if;
 with b as(
  select (r->>'propertyId')::uuid property_id,(r->>'weight')::numeric weight,
   floor(total_fils::numeric*(r->>'weight')::numeric/sum_weight)::bigint part,
   (total_fils::numeric*(r->>'weight')::numeric/sum_weight)-floor(total_fils::numeric*(r->>'weight')::numeric/sum_weight) frac
  from jsonb_array_elements(weights)r
 ),ranked as(
  select *,row_number() over(order by frac desc,property_id) rn,(total_fils-sum(part) over())::bigint remainder from b
 ),final as(
  select property_id,weight,part+case when rn<=remainder then 1 else 0 end fils from ranked
 )
 select jsonb_agg(jsonb_build_object('propertyId',property_id,'amount',(fils::numeric/1000)::numeric(15,3),'weight',weight,'shareBps',greatest(1,least(10000,round(weight/sum_weight*10000)::int))) order by property_id) into result from final;
 if (select sum((r->>'amount')::numeric) from jsonb_array_elements(result)r)<>total then raise check_violation using message='ALLOCATION_TOTAL_MISMATCH';end if;
 return result;
end $function$

CREATE OR REPLACE FUNCTION private.aqari_official_source_guard()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare s private.aqari_official_document_series;defaults jsonb;key text;value jsonb;v_source_key text;
begin
 select * into strict s from private.aqari_official_document_series where workspace_id=new.workspace_id and id=new.series_id;
 if new.version=1 and not exists(select 1 from private.aqari_official_number_reservations r where r.workspace_id=s.workspace_id and r.id=s.id and r.document_no=s.document_no and r.kind=s.kind and r.entity_id=s.entity_id and r.actor_id=auth.uid()) then raise exception 'DOCUMENT_RESERVED_NUMBER_REQUIRED' using errcode='23514';end if;
 perform private.aqari_official_validate(s.kind,s.document_no,new.template_version,new.title,new.body,new.payload,new.content_sha256);
 if not private.aqari_official_entity_scope(s.workspace_id,s.entity_type,s.entity_id,'write') then raise insufficient_privilege using message='DOCUMENT_ENTITY_NOT_FOUND';end if;
 -- Serialize mutable work-order state with issuance. Financial mutations also
 -- take the workspace ledger lock held by the public registration RPC.
 if s.kind='work_order' then perform 1 from private.aqari_work_orders where workspace_id=s.workspace_id and id=s.entity_id for share;end if;
 defaults:=private.aqari_official_source(s.workspace_id,s.kind,s.entity_type,s.entity_id,nullif(new.payload->>'sourceId','')::uuid,new.payload);
 for key,value in select * from jsonb_each(defaults) loop
  if new.payload->key is distinct from value then raise exception 'DOCUMENT_SOURCE_MISMATCH: %',key using errcode='23514';end if;
 end loop;
 if s.kind in ('rent_receipt','receipt_voucher','deposit_receipt','deposit_refund','payment_voucher','expense_approval','work_order') then v_source_key:=defaults->>'sourceId';
 elsif s.kind='daily_collection' then v_source_key:=s.entity_id::text||':'||(defaults->>'collectionDate');end if;
 if s.source_key is not null and s.source_key is distinct from v_source_key then raise exception 'DOCUMENT_SOURCE_CANNOT_CHANGE' using errcode='23514';end if;
 if v_source_key is not null then update private.aqari_official_document_series set source_key=v_source_key where workspace_id=s.workspace_id and id=s.id;end if;
 return new;
end $function$

CREATE OR REPLACE FUNCTION private.aqari_official_source(w uuid, k text, t text, i uuid, source_id uuid, fields jsonb DEFAULT '{}'::jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare defaults jsonb;pay public.aqari_rent_payments;dep private.aqari_deposit_entries;
 expense private.aqari_financial_expenses;work private.aqari_work_orders;settlement private.aqari_vacating_settlements;
 required_entity text;receipt_count bigint;total numeric;on_date date;starts_on date;snap jsonb;v jsonb;
begin
 required_entity:=case when k in ('payment_voucher','expense_approval','daily_collection') then 'property' when k='work_order' then 'work_order'
 when k in ('rent_receipt','deposit_receipt','deposit_refund','tenant_statement','debt_notice','renewal_notice','nonrenewal_notice','receipt_voucher','key_handover','damage_report','final_settlement','clearance') then 'lease' else null end;
 if required_entity is null or t is distinct from required_entity then raise exception 'DOCUMENT_KIND_ENTITY_MISMATCH' using errcode='22023';end if;
 if not private.aqari_official_entity_scope(w,t,i,'read') then raise insufficient_privilege using message='DOCUMENT_ENTITY_NOT_FOUND';end if;
 if t='lease' then
  select jsonb_build_object('tenantName',q.full_name,'contractNo',l.contract_no,'propertyName',p.name,'unitNo',u.unit_no)
   into defaults from public.aqari_leases l join public.aqari_tenants q on q.workspace_id=w and q.id=l.tenant_id
   join public.aqari_units u on u.workspace_id=w and u.id=l.unit_id join public.aqari_properties p on p.workspace_id=w and p.id=u.property_id
   where l.workspace_id=w and l.id=i;
 elsif t='property' then select jsonb_build_object('propertyName',name) into defaults from public.aqari_properties where workspace_id=w and id=i;
 else
  select * into strict work from private.aqari_work_orders where workspace_id=w and id=i;
  if work.status not in ('approved','assigned','in_progress','completed') then raise exception 'DOCUMENT_APPROVED_SOURCE_REQUIRED' using errcode='23514';end if;
  select jsonb_build_object('propertyName',p.name,'vendorName',v.name,'description',work.description,'approvedAmount',work.approved_amount::text,
   'approvedBy',coalesce(nullif(pr.display_name,''),work.approved_by::text),'sourceId',work.id::text)
   into defaults from public.aqari_properties p join private.aqari_vendors v on v.workspace_id=w and v.id=work.vendor_id
   left join public.aqari_profiles pr on pr.user_id=work.approved_by where p.workspace_id=w and p.id=work.property_id;
 end if;

 if k in ('rent_receipt','receipt_voucher','deposit_receipt','deposit_refund','tenant_statement','debt_notice','daily_collection','final_settlement','clearance','payment_voucher','expense_approval') then
  if not private.aqari_can(w,'collections','read') then raise insufficient_privilege using message='ACCESS_DENIED';end if;
 end if;
 if k in ('rent_receipt','receipt_voucher') then
  select * into pay from public.aqari_rent_payments p where p.workspace_id=w and p.lease_id=i and p.id=source_id
   and p.status in ('paid','partial','مدفوع','جزئي') and p.amount>0
   and not exists(select 1 from private.aqari_receipt_cancellations c where c.workspace_id=w and c.payment_id=p.id);
  if not found then raise exception 'DOCUMENT_CONFIRMED_PAYMENT_REQUIRED' using errcode='23514';end if;
  defaults:=defaults||jsonb_build_object('sourceId',pay.id::text,'amount',pay.amount::text,'period',to_char(pay.period,'YYYY-MM'),
   'paymentMethod',case pay.payment_method when 'cash' then 'نقداً' when 'knet' then 'كي نت' when 'bank' then 'تحويل بنكي' when 'cheque' then 'شيك' else pay.payment_method end,
   'paymentReference',coalesce(nullif(pay.reference,''),'نقداً دون مرجع بنكي'),'reference',coalesce(nullif(pay.reference,''),'نقداً دون مرجع بنكي'),
   'collectorName',coalesce(nullif(pay.receipt->>'collectorName',''),nullif(pay.receipt->>'collector',''),nullif(pay.receipt->>'accountant','')),
   'receivedFrom',defaults->>'tenantName','reason','إيجار الفترة '||to_char(pay.period,'YYYY-MM'));
 elsif k in ('deposit_receipt','deposit_refund') then
  select * into dep from private.aqari_deposit_entries e where e.workspace_id=w and e.lease_id=i and e.id=source_id
   and e.status='confirmed' and e.kind=case k when 'deposit_receipt' then 'receipt' else 'refund' end;
  if not found then raise exception 'DOCUMENT_CONFIRMED_DEPOSIT_REQUIRED' using errcode='23514';end if;
  defaults:=defaults||jsonb_build_object('sourceId',dep.id::text,'amount',dep.amount::text,'collectorName',dep.actor_name,'approvedBy',dep.actor_name,
   'reason',dep.reason,'paymentMethod',case dep.method when 'cash' then 'نقداً' when 'knet' then 'كي نت' when 'bank' then 'تحويل بنكي' when 'cheque' then 'شيك' else dep.method end);
 elsif k in ('payment_voucher','expense_approval') then
  select * into expense from private.aqari_financial_expenses e where e.workspace_id=w and e.property_id=i and e.id=source_id and e.state='approved';
  if not found then raise exception 'DOCUMENT_APPROVED_EXPENSE_REQUIRED' using errcode='23514';end if;
  defaults:=defaults||jsonb_build_object('sourceId',expense.id::text,'amount',expense.amount::text,'paidTo',expense.payee,
   'reason',expense.description,'expenseCategory',expense.category,'approvedBy',expense.approved_by_name,'invoiceReference',coalesce(nullif(expense.reference,''),expense.voucher_no));
 elsif k in ('renewal_notice','nonrenewal_notice') then
  select jsonb_build_object('currentEndDate',l.end_date::text) into v from public.aqari_leases l where l.workspace_id=w and l.id=i and l.status in ('signed','expired');
  if v is null then raise exception 'DOCUMENT_ACTIVE_LEASE_REQUIRED' using errcode='23514';end if;defaults:=defaults||v;
 elsif k in ('tenant_statement','debt_notice') then
  select start_date into starts_on from public.aqari_leases where workspace_id=w and id=i;
  on_date:=coalesce(nullif(fields->>case k when 'debt_notice' then 'dueDate' else 'toDate' end,'')::date,(now() at time zone 'Asia/Kuwait')::date);
  v:=private.aqari_official_statement(w,i,case k when 'debt_notice' then starts_on else coalesce(nullif(fields->>'fromDate','')::date,starts_on) end,on_date);
  if k='debt_notice' then
   if (v->>'closingBalance')::numeric<=0 then raise exception 'DOCUMENT_NO_ACTUAL_DEBT' using errcode='23514';end if;
   defaults:=defaults||jsonb_build_object('dueDate',on_date::text,'dueAmount',v->>'closingBalance');
  else defaults:=defaults||v;end if;
 elsif k='daily_collection' then
  if coalesce(fields->>'collectionDate','') !~ '^\d{4}-\d{2}-\d{2}$' then raise exception 'DOCUMENT_COLLECTION_DATE_REQUIRED' using errcode='22023';end if;
  on_date:=(fields->>'collectionDate')::date;
  select count(*),coalesce(sum(p.amount),0) into receipt_count,total from public.aqari_rent_payments p
   join public.aqari_leases l on l.workspace_id=w and l.id=p.lease_id join public.aqari_units u on u.workspace_id=w and u.id=l.unit_id
   where p.workspace_id=w and u.property_id=i and p.paid_at=on_date and p.status in ('paid','partial','مدفوع','جزئي')
    and not exists(select 1 from private.aqari_receipt_cancellations c where c.workspace_id=w and c.payment_id=p.id);
  defaults:=defaults||jsonb_build_object('collectionDate',on_date::text,'receiptCount',receipt_count::text,'totalAmount',total::numeric(18,3)::text,
   'preparedBy',(select coalesce(nullif(display_name,''),auth.uid()::text) from public.aqari_profiles where user_id=auth.uid()));
 elsif k in ('final_settlement','clearance') then
  select * into settlement from private.aqari_vacating_settlements s where s.workspace_id=w and s.lease_id=i;
  if not found or settlement.status not in ('finalized','cleared','released') or (k='clearance' and settlement.status not in ('cleared','released')) then
   raise exception 'DOCUMENT_APPROVED_SETTLEMENT_REQUIRED' using errcode='23514';end if;
  snap:=case k when 'clearance' then settlement.clearance_snapshot else settlement.settlement_snapshot end;
  if snap is null then raise exception 'DOCUMENT_APPROVED_SETTLEMENT_REQUIRED' using errcode='23514';end if;
  -- The archived clearance must match the currently verified settlement balances.
  if k='clearance' and snap->'clearance_balances' is distinct from private.aqari_vacating_balances(w,i,settlement.vacate_date) then
   raise exception 'DOCUMENT_SETTLEMENT_CHANGED' using errcode='40001';end if;
  -- Supplemental obligations are not inferred to be settled by the old rent/deposit snapshot.
  if (exists(select 1 from private.aqari_tenant_adjustments a where a.workspace_id=w and a.lease_id=i)
      or exists(select 1 from private.aqari_tenant_ledger_entries e where e.workspace_id=w and e.lease_id=i)) then
   raise exception 'DOCUMENT_SUPPLEMENTAL_SETTLEMENT_REVIEW_REQUIRED' using errcode='23514';end if;
  if k='clearance' then
   defaults:=defaults||jsonb_build_object('settlementReference',settlement.settlement_no,'approvedBy',settlement.clearance_by_name,'exceptionReason',settlement.exception_reason);
  else
   v:=snap->'final_balances';
   if v is null then raise exception 'DOCUMENT_APPROVED_SETTLEMENT_REQUIRED' using errcode='23514';end if;
   if not (snap ? 'utility_balance' and snap ? 'legal_balance') then raise exception 'DOCUMENT_SUPPLEMENTAL_SETTLEMENT_REVIEW_REQUIRED' using errcode='23514';end if;
   defaults:=defaults||jsonb_build_object('rentBalance',v->>'rent_balance','damageBalance',snap->>'damage_amount','utilityBalance',snap->>'utility_balance','legalBalance',snap->>'legal_balance',
    'depositBalance',v->>'deposit_balance','netBalance',((v->>'rent_balance')::numeric+(snap->>'utility_balance')::numeric+(snap->>'legal_balance')::numeric+coalesce((snap->>'damage_amount')::numeric,0)-(v->>'deposit_balance')::numeric)::numeric(18,3)::text,
    'approvedBy',settlement.finalized_by_name);
  end if;
 end if;
 return coalesce(defaults,'{}');
end $function$

CREATE OR REPLACE FUNCTION private.aqari_official_validate(k text, doc_no text, v integer, title text, body text, payload jsonb, hash text)
 RETURNS void
 LANGUAGE plpgsql
 IMMUTABLE
 SET search_path TO ''
AS $function$
declare spec jsonb:=private.aqari_official_template(k);fields jsonb:=$fields${"documentNo":{"label":"رقم المستند","type":"text","multiline":false,"maxLength":5000},"issuedAt":{"label":"تاريخ الإصدار","type":"date","multiline":false,"maxLength":5000},"tenantName":{"label":"اسم المستأجر","type":"text","multiline":false,"maxLength":5000},"propertyName":{"label":"اسم العقار","type":"text","multiline":false,"maxLength":5000},"unitNo":{"label":"رقم الوحدة","type":"text","multiline":false,"maxLength":5000},"contractNo":{"label":"رقم العقد","type":"text","multiline":false,"maxLength":5000},"period":{"label":"فترة الإيجار","type":"month","multiline":false,"maxLength":5000},"amount":{"label":"المبلغ (د.ك)","type":"decimal","multiline":false,"maxLength":5000},"paymentMethod":{"label":"طريقة الدفع","type":"text","multiline":false,"maxLength":5000},"paymentReference":{"label":"مرجع الدفع","type":"text","multiline":false,"maxLength":5000},"collectorName":{"label":"اسم المحصل","type":"text","multiline":false,"maxLength":5000},"reason":{"label":"سبب الحركة","type":"text","multiline":true,"maxLength":5000},"approvedBy":{"label":"اسم المعتمد","type":"text","multiline":false,"maxLength":5000},"fromDate":{"label":"من تاريخ","type":"date","multiline":false,"maxLength":5000},"toDate":{"label":"إلى تاريخ","type":"date","multiline":false,"maxLength":5000},"openingBalance":{"label":"الرصيد الافتتاحي (د.ك)","type":"decimal","multiline":false,"maxLength":5000},"charges":{"label":"المطلوب (د.ك)","type":"decimal","multiline":false,"maxLength":5000},"payments":{"label":"المدفوع (د.ك)","type":"decimal","multiline":false,"maxLength":5000},"credits":{"label":"التسويات الدائنة (د.ك)","type":"decimal","multiline":false,"maxLength":5000},"closingBalance":{"label":"الرصيد الختامي (د.ك)","type":"decimal","multiline":false,"maxLength":5000},"dueAmount":{"label":"المستحق الفعلي (د.ك)","type":"decimal","multiline":false,"maxLength":5000},"dueDate":{"label":"تاريخ الاستحقاق","type":"date","multiline":false,"maxLength":5000},"graceDeadline":{"label":"آخر مهلة للسداد","type":"date","multiline":false,"maxLength":5000},"currentEndDate":{"label":"تاريخ انتهاء العقد","type":"date","multiline":false,"maxLength":5000},"responseDeadline":{"label":"آخر موعد للرد","type":"date","multiline":false,"maxLength":5000},"vacateDate":{"label":"تاريخ الإخلاء","type":"date","multiline":false,"maxLength":5000},"receivedFrom":{"label":"استلمنا من","type":"text","multiline":false,"maxLength":5000},"reference":{"label":"المرجع","type":"text","multiline":false,"maxLength":5000},"paidTo":{"label":"المستفيد من الصرف","type":"text","multiline":false,"maxLength":5000},"expenseCategory":{"label":"بند المصروف","type":"text","multiline":false,"maxLength":5000},"vendorName":{"label":"اسم المقاول","type":"text","multiline":false,"maxLength":5000},"description":{"label":"وصف الأعمال","type":"text","multiline":true,"maxLength":5000},"approvedAmount":{"label":"المبلغ المعتمد (د.ك)","type":"decimal","multiline":false,"maxLength":5000},"invoiceReference":{"label":"مرجع الفاتورة","type":"text","multiline":false,"maxLength":5000},"keyCount":{"label":"عدد المفاتيح","type":"decimal","multiline":false,"maxLength":5000},"deliveredBy":{"label":"اسم المسلّم","type":"text","multiline":false,"maxLength":5000},"receivedBy":{"label":"اسم المستلم","type":"text","multiline":false,"maxLength":5000},"inspectionReference":{"label":"مرجع المعاينة","type":"text","multiline":false,"maxLength":5000},"damageSummary":{"label":"وصف الأضرار","type":"text","multiline":true,"maxLength":5000},"estimatedAmount":{"label":"التكلفة التقديرية (د.ك)","type":"decimal","multiline":false,"maxLength":5000},"rentBalance":{"label":"رصيد الإيجار (د.ك)","type":"decimal","multiline":false,"maxLength":5000},"damageBalance":{"label":"رصيد الأضرار (د.ك)","type":"decimal","multiline":false,"maxLength":5000},"utilityBalance":{"label":"رصيد الخدمات (د.ك)","type":"decimal","multiline":false,"maxLength":5000},"legalBalance":{"label":"رصيد القضايا (د.ك)","type":"decimal","multiline":false,"maxLength":5000},"depositBalance":{"label":"رصيد التأمين (د.ك)","type":"decimal","multiline":false,"maxLength":5000},"netBalance":{"label":"صافي التسوية (د.ك)","type":"decimal","multiline":false,"maxLength":5000},"settlementReference":{"label":"مرجع التسوية","type":"text","multiline":false,"maxLength":5000},"collectionDate":{"label":"تاريخ التحصيل","type":"date","multiline":false,"maxLength":5000},"receiptCount":{"label":"عدد الوصولات","type":"decimal","multiline":false,"maxLength":5000},"totalAmount":{"label":"إجمالي التحصيل (د.ك)","type":"decimal","multiline":false,"maxLength":5000},"preparedBy":{"label":"اسم معدّ الكشف","type":"text","multiline":false,"maxLength":5000}}$fields$::jsonb;
 key text;value text;field_type text;rendered text;snapshot jsonb;actual_hash text;test_date date;
begin
 if spec is null or v is distinct from (spec->>'version')::integer or title is distinct from spec->>'title'
  or jsonb_typeof(payload) is distinct from 'object' or payload->>'documentNo' is distinct from doc_no then
  raise exception 'INVALID_DOCUMENT_TEMPLATE' using errcode='23514';end if;
 for key in select jsonb_array_elements_text(spec->'required') loop
  if jsonb_typeof(payload->key) is distinct from 'string' then raise exception 'INVALID_DOCUMENT_FIELD: %',key using errcode='23514';end if;
  value:=payload->>key;field_type:=fields#>>array[key,'type'];
  if value is distinct from btrim(value) or length(value)=0 or length(value)>5000 then raise exception 'INVALID_DOCUMENT_FIELD: %',key using errcode='23514';end if;
  if field_type='date' then
   if value !~ '^\d{4}-\d{2}-\d{2}$' then raise exception 'INVALID_DOCUMENT_DATE' using errcode='23514';end if;
   begin test_date:=value::date;exception when datetime_field_overflow or invalid_datetime_format then raise exception 'INVALID_DOCUMENT_DATE' using errcode='23514';end;
  elsif field_type='month' and value !~ '^\d{4}-(0[1-9]|1[0-2])$' then raise exception 'INVALID_DOCUMENT_PERIOD' using errcode='23514';
  elsif field_type='decimal' then
   if key in ('keyCount','receiptCount') then
    if value !~ '^\d{1,7}$' then raise exception 'INVALID_DOCUMENT_COUNT' using errcode='23514';end if;
   elsif value !~ (case when key in ('openingBalance','closingBalance','netBalance') then '^-?\d{1,12}(\.\d{1,3})?$' else '^\d{1,12}(\.\d{1,3})?$' end) then raise exception 'INVALID_DOCUMENT_AMOUNT' using errcode='23514';end if;
  end if;
 end loop;
 if (payload->>'fromDate')::date>(payload->>'toDate')::date or (payload->>'dueDate')::date>(payload->>'graceDeadline')::date
  or (k='debt_notice' and (payload->>'dueAmount')::numeric<=0) then raise exception 'INVALID_DOCUMENT_RANGE' using errcode='23514';end if;
 rendered:=spec->>'body';for key in select jsonb_array_elements_text(spec->'required') loop rendered:=replace(rendered,'{{'||key||'}}',payload->>key);end loop;
 if body is distinct from rendered then raise exception 'DOCUMENT_BODY_MISMATCH' using errcode='23514';end if;
 snapshot:=jsonb_build_object('kind',k,'title',title,'documentNo',doc_no,'version',v,'issuedAt',payload->>'issuedAt','body',body,'payload',payload);
 actual_hash:=encode(sha256(convert_to(private.aqari_official_canonical(snapshot),'UTF8')),'hex');
 if hash is distinct from actual_hash then raise exception 'DOCUMENT_HASH_MISMATCH' using errcode='23514';end if;
end $function$

CREATE OR REPLACE FUNCTION private.aqari_opening_balance_reconciliation(p_workspace_id uuid, p_action text, p_data jsonb DEFAULT '{}'::jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
 w uuid:=p_workspace_id; d jsonb:=p_data; t uuid; cutoff date; ident uuid; ids uuid[]; expected integer;
 source_doc public.aqari_documents; saved private.aqari_opening_balance_reviews; snapshot jsonb;
 debit numeric(15,3); credit numeric(15,3); actual_debit numeric(15,3); actual_credit numeric(15,3); latest integer; actor text; previous uuid; fingerprint text; correction text;
begin
 if auth.uid() is null or not private.aqari_manager(w) or not private.aqari_can(w,'finance','read') or not private.aqari_can(w,'documents','read') then
  raise insufficient_privilege using message='ACCESS_DENIED';end if;
 if d is null or jsonb_typeof(d)<>'object' or octet_length(d::text)>100000 then raise invalid_parameter_value using message='INVALID_OPENING_REVIEW';end if;
 if p_action not in('context','get','review') or p_action is null then raise invalid_parameter_value using message='INVALID_OPENING_ACTION';end if;
 if exists(select 1 from jsonb_object_keys(d) k where not(k=any(case p_action
  when 'context' then array['tenant_id','cutoff_date'] when 'get' then array['id']
  else array['id','tenant_id','cutoff_date','cutoff_boundary','expected_revision','source_document_id','source_sha256','source_reference','source_coverage','source_debit','source_credit','entry_ids','source_attestation','bytes_verified','previous_review_id','correction_reason'] end))) then
  raise invalid_parameter_value using message='INVALID_OPENING_REVIEW';end if;
 if p_action='get' then
  select * into saved from private.aqari_opening_balance_reviews r where r.workspace_id=w and r.id=(d->>'id')::uuid;
  return jsonb_build_object('workspace_id',w,'user_id',auth.uid(),'review',case when saved.id is null then null else to_jsonb(saved) end);
 end if;
 t:=nullif(d->>'tenant_id','')::uuid;
 if t is not null and not exists(select 1 from public.aqari_tenants x where x.workspace_id=w and x.id=t) then raise insufficient_privilege using message='ACCESS_DENIED';end if;
 if nullif(d->>'cutoff_date','') is not null then
  if (d->>'cutoff_date') !~ '^\d{4}-\d{2}-\d{2}$' then raise invalid_parameter_value using message='OPENING_CUTOFF_REQUIRED';end if;
  cutoff:=(d->>'cutoff_date')::date;
 end if;
 if p_action='context' then
  return jsonb_build_object('workspace_id',w,'user_id',auth.uid(),'tenant_id',t,'cutoff_date',cutoff,'cutoff_boundary','end_of_day',
   'scope','selected_opening_lines_source_review_only',
   'tenants',(select coalesce(jsonb_agg(jsonb_build_object('id',x.id,'name',x.full_name) order by x.full_name,x.id),'[]') from public.aqari_tenants x where x.workspace_id=w),
   'documents',(select coalesce(jsonb_agg(jsonb_build_object('id',x.id,'title',x.title,'document_no',x.document_no,'entity_type',x.entity_type,'entity_ref',x.entity_ref,
    'storage_bucket',x.storage_bucket,'storage_path',x.storage_path,'checksum_sha256',x.checksum_sha256,'size_bytes',x.size_bytes,'mime_type',x.mime_type,'original_filename',x.original_filename) order by x.created_at desc,x.id),'[]')
    from public.aqari_documents x where t is not null and x.workspace_id=w and private.aqari_opening_source_valid(w,t,x.id)),
   'entries',(select coalesce(jsonb_agg(jsonb_build_object('id',e.id,'tenant_id',e.tenant_id,'lease_id',e.lease_id,'contract_no',l.contract_no,'kind',e.kind,'direction',e.direction,'amount',e.amount::text,
    'occurred_on',e.occurred_on,'reason',e.reason,'side',case when cutoff is null then 'unspecified' when e.occurred_on<=cutoff then 'through_cutoff' else 'after_cutoff' end) order by e.occurred_on,e.created_at,e.id),'[]')
    from private.aqari_tenant_ledger_entries e left join public.aqari_leases l on l.workspace_id=e.workspace_id and l.id=e.lease_id where e.workspace_id=w and e.tenant_id=t),
   'reviews',(select coalesce(jsonb_agg(to_jsonb(r) order by r.cutoff_date desc,r.revision desc),'[]') from private.aqari_opening_balance_reviews r where r.workspace_id=w and r.tenant_id=t),
   'latest_revision',(select coalesce(max(r.revision),0) from private.aqari_opening_balance_reviews r where r.workspace_id=w and r.tenant_id=t and r.cutoff_date=cutoff),
   'actual_collections',case when t is null then null else public.aqari_opening_balance_statement(w,t)#>>'{totals,actual_collections}' end);
 end if;
 if not private.aqari_can(w,'finance','write') then raise insufficient_privilege using message='ACCESS_DENIED';end if;
 perform private.aqari_require_sensitive_aal2(w);
 if t is null or cutoff is null or d->>'cutoff_boundary' is distinct from 'end_of_day' then raise check_violation using message='OPENING_CUTOFF_REQUIRED';end if;
 if d->'source_attestation' is distinct from 'true'::jsonb or d->'bytes_verified' is distinct from 'true'::jsonb then raise check_violation using message='OPENING_SOURCE_ATTESTATION_REQUIRED';end if;
 if coalesce(d->>'source_debit','') !~ '^\d{1,12}(\.\d{1,3})?$' or coalesce(d->>'source_credit','') !~ '^\d{1,12}(\.\d{1,3})?$'
  or coalesce(d->>'expected_revision','') !~ '^\d{1,9}$' or coalesce(d->>'source_sha256','') !~ '^[a-f0-9]{64}$'
  or length(btrim(coalesce(d->>'source_reference',''))) not between 3 and 500 or length(btrim(coalesce(d->>'source_coverage',''))) not between 3 and 2000
  or jsonb_typeof(d->'entry_ids') is distinct from 'array' then raise check_violation using message='INVALID_OPENING_REVIEW';end if;
 ident:=(d->>'id')::uuid;expected:=(d->>'expected_revision')::integer;debit:=(d->>'source_debit')::numeric;credit:=(d->>'source_credit')::numeric;
 if ident is null then raise check_violation using message='INVALID_OPENING_REVIEW';end if;
 select array_agg(x::uuid order by x::uuid) into ids from jsonb_array_elements_text(d->'entry_ids') x;
 if coalesce(cardinality(ids),0) not between 1 and 1000 or cardinality(ids)<>(select count(distinct x) from unnest(ids) x) then raise check_violation using message='OPENING_ENTRIES_REQUIRED';end if;
 -- Serialize tenant review revisions, including competing identifiers and source reuse.
 perform 1 from public.aqari_tenants x where x.workspace_id=w and x.id=t for update;
 select * into saved from private.aqari_opening_balance_reviews r where r.id=ident;
 if saved.id is not null then
  if saved.workspace_id<>w or saved.reviewed_by<>auth.uid() or saved.request_snapshot<>d then raise check_violation using message='OPENING_RETRY_CONFLICT';end if;
  return jsonb_build_object('workspace_id',w,'user_id',auth.uid(),'review',to_jsonb(saved));
 end if;
 select coalesce(max(r.revision),0) into latest from private.aqari_opening_balance_reviews r where r.workspace_id=w and r.tenant_id=t and r.cutoff_date=cutoff;
 if latest<>expected then raise serialization_failure using message='OPENING_REVIEW_REVISION_CONFLICT';end if;
 select r.id into previous from private.aqari_opening_balance_reviews r where r.workspace_id=w and r.tenant_id=t and r.cutoff_date=cutoff and r.revision=latest;
 correction:=nullif(btrim(d->>'correction_reason'),'');
 if (latest=0 and (nullif(d->>'previous_review_id','') is not null or correction is not null)) or
  (latest>0 and (nullif(d->>'previous_review_id','')::uuid is distinct from previous or coalesce(length(correction),0) not between 3 and 1000)) then
  raise check_violation using message='OPENING_CORRECTION_REASON_REQUIRED';end if;
 select * into source_doc from public.aqari_documents x where x.workspace_id=w and x.id=(d->>'source_document_id')::uuid for share;
 perform 1 from storage.objects o where o.bucket_id=source_doc.storage_bucket and o.name=source_doc.storage_path for share;
 if source_doc.id is null or not private.aqari_opening_source_valid(w,t,source_doc.id) or source_doc.checksum_sha256<>d->>'source_sha256' then raise check_violation using message='OPENING_SOURCE_UNVERIFIED';end if;
 fingerprint:=encode(sha256(convert_to(jsonb_build_object('tenant_id',t,'cutoff_date',cutoff,'cutoff_boundary','end_of_day',
  'source_sha256',source_doc.checksum_sha256,'source_reference',btrim(d->>'source_reference'),'source_coverage',btrim(d->>'source_coverage'),
  'source_debit',debit,'source_credit',credit,'entry_ids',ids)::text,'UTF8')),'hex');
 if exists(select 1 from private.aqari_opening_balance_reviews r where r.workspace_id=w and r.review_fingerprint=fingerprint) then
  raise unique_violation using message='OPENING_SOURCE_ALREADY_REVIEWED';end if;
 if cardinality(ids)<>(select count(*) from private.aqari_tenant_ledger_entries e where e.workspace_id=w and e.tenant_id=t and e.id=any(ids)
  and e.kind in('opening_debit','opening_credit','opening_balance') and e.occurred_on<=cutoff
  and (e.kind<>'opening_debit' or e.direction='debit') and (e.kind<>'opening_credit' or e.direction='credit')
  and (e.lease_id is null or exists(select 1 from public.aqari_leases l where l.workspace_id=w and l.id=e.lease_id and l.tenant_id=t))
  and (source_doc.entity_type='tenant'
   or exists(select 1 from public.aqari_leases l where l.workspace_id=w and l.id=e.lease_id and l.tenant_id=t and source_doc.entity_type='lease' and source_doc.entity_ref=l.external_ref)
   or exists(select 1 from public.aqari_leases l join public.aqari_units u on u.workspace_id=l.workspace_id and u.id=l.unit_id join public.aqari_properties p on p.workspace_id=u.workspace_id and p.id=u.property_id
    where l.workspace_id=w and l.id=e.lease_id and l.tenant_id=t and source_doc.entity_type='property' and source_doc.entity_ref=p.external_ref))) then raise check_violation using message='OPENING_ENTRY_SCOPE_OR_CUTOFF_CONFLICT';end if;
 select coalesce(sum(e.amount) filter(where e.direction='debit'),0),coalesce(sum(e.amount) filter(where e.direction='credit'),0),
  jsonb_agg(to_jsonb(e) order by e.id) into actual_debit,actual_credit,snapshot
  from private.aqari_tenant_ledger_entries e where e.workspace_id=w and e.tenant_id=t and e.id=any(ids);
 if actual_debit<>debit or actual_credit<>credit then raise check_violation using message='OPENING_SOURCE_TOTALS_MISMATCH';end if;
 select coalesce(nullif(p.display_name,''),auth.uid()::text) into actor from public.aqari_profiles p where p.user_id=auth.uid();
 insert into private.aqari_opening_balance_reviews(id,workspace_id,tenant_id,cutoff_date,revision,previous_review_id,correction_reason,review_fingerprint,source_document_id,source_sha256,source_reference,source_coverage,
  source_debit,source_credit,entry_ids,entries_snapshot,document_snapshot,request_snapshot,source_attestation,bytes_verified,reviewed_by,reviewed_by_name)
 values(ident,w,t,cutoff,latest+1,previous,correction,fingerprint,source_doc.id,source_doc.checksum_sha256,btrim(d->>'source_reference'),btrim(d->>'source_coverage'),
  debit,credit,ids,snapshot,to_jsonb(source_doc),d,true,true,auth.uid(),coalesce(actor,auth.uid()::text)) returning * into saved;
 return jsonb_build_object('workspace_id',w,'user_id',auth.uid(),'review',to_jsonb(saved));
end $function$

CREATE OR REPLACE FUNCTION private.aqari_operational_dispatch_payload(w uuid, nid uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$ declare n private.aqari_notification_deliveries%rowtype;recipient text;vars jsonb;purpose_value text;template_value text;manager_email text;plan private.aqari_maintenance_plans%rowtype;lease_row public.aqari_leases%rowtype;unit_row public.aqari_units%rowtype;property_row public.aqari_properties%rowtype;tenant_row public.aqari_tenants%rowtype;vendor_contract private.aqari_vendor_contracts%rowtype;vendor_row private.aqari_vendors%rowtype;cheque_row private.aqari_cheques%rowtype;escalation private.aqari_maintenance_sla_escalations%rowtype;task_row private.aqari_property_maintenance_tasks%rowtype;begin
 select * into n from private.aqari_notification_deliveries x where x.workspace_id=w and x.id=nid;if not found or n.status in('cancelled','delivered','read') or n.kind not in('maintenance_due','maintenance_sla_escalation','lease_expiry','vendor_contract_expiry','cheque_returned') then return null;end if;purpose_value:=n.kind;template_value:=n.kind;
 if n.kind='cheque_returned' then begin select * into cheque_row from private.aqari_cheques c where c.workspace_id=w and c.id=n.aggregate_id::uuid;exception when invalid_text_representation then return null;end;if cheque_row.id is null then return null;end if;select * into lease_row from public.aqari_leases l where l.workspace_id=w and l.id=cheque_row.lease_id;select * into unit_row from public.aqari_units u where u.workspace_id=w and u.id=lease_row.unit_id;select * into property_row from public.aqari_properties p where p.workspace_id=w and p.id=unit_row.property_id;select * into tenant_row from public.aqari_tenants t where t.workspace_id=w and t.id=lease_row.tenant_id;if tenant_row.id is null or tenant_row.id<>n.recipient_id or not private.aqari_contact_channel_allowed(tenant_row.profile,n.channel) then return null;end if;recipient:=case n.channel when 'email' then nullif(btrim(tenant_row.email),'') when 'whatsapp' then nullif(btrim(tenant_row.phone),'') else null end;if recipient is null then return null;end if;vars:=jsonb_build_object('tenantName',tenant_row.full_name,'propertyName',property_row.name,'unitNo',unit_row.unit_no,'contractNo',lease_row.contract_no,'chequeNo',cheque_row.cheque_no,'bankName',cheque_row.bank_name,'amount',cheque_row.amount,'dueOn',cheque_row.due_on,'state',cheque_row.state);return jsonb_build_object('channel',n.channel,'recipientReference',recipient,'template',template_value,'purpose',purpose_value,'variables',vars);end if;
 if n.channel='email' then select email into manager_email from auth.users where id=n.recipient_id;recipient:=nullif(btrim(manager_email),'');elsif n.channel='push' then recipient:=n.recipient_id::text;else return null;end if;if recipient is null then return null;end if;
 if n.kind='maintenance_due' then begin select * into plan from private.aqari_maintenance_plans x where x.workspace_id=w and x.id=n.aggregate_id::uuid;exception when invalid_text_representation then return null;end;if plan.id is null or not plan.is_active then return null;end if;select * into property_row from public.aqari_properties p where p.workspace_id=w and p.id=plan.property_id;vars:=jsonb_build_object('propertyName',property_row.name,'title',plan.title,'assetKind',plan.asset_kind,'nextDueOn',plan.next_due_on,'frequencyDays',plan.frequency_days);
 elsif n.kind='maintenance_sla_escalation' then select * into escalation from private.aqari_maintenance_sla_escalations e where e.workspace_id=w and e.notification_id=n.id order by e.prepared_at desc limit 1;if escalation.id is null then return null;end if;select * into task_row from private.aqari_property_maintenance_tasks t where t.workspace_id=w and t.id=escalation.task_id;select * into property_row from public.aqari_properties p where p.workspace_id=w and p.id=escalation.property_id;vars:=jsonb_build_object('propertyName',property_row.name,'taskNo',task_row.task_no,'stage',escalation.stage,'thresholdMinutes',escalation.threshold_minutes,'breachedAt',escalation.breached_at,'taskStatus',task_row.status);
 elsif n.kind='lease_expiry' then begin select * into lease_row from public.aqari_leases l where l.workspace_id=w and l.id=n.aggregate_id::uuid;exception when invalid_text_representation then return null;end;if lease_row.id is null or lease_row.status<>'signed' then return null;end if;select * into unit_row from public.aqari_units u where u.workspace_id=w and u.id=lease_row.unit_id;select * into property_row from public.aqari_properties p where p.workspace_id=w and p.id=unit_row.property_id;select * into tenant_row from public.aqari_tenants t where t.workspace_id=w and t.id=lease_row.tenant_id;vars:=jsonb_build_object('propertyName',property_row.name,'unitNo',unit_row.unit_no,'tenantName',tenant_row.full_name,'contractNo',lease_row.contract_no,'endsOn',lease_row.end_date,'daysRemaining',lease_row.end_date-current_date);
 elsif n.kind='vendor_contract_expiry' then begin select * into vendor_contract from private.aqari_vendor_contracts c where c.workspace_id=w and c.id=n.aggregate_id::uuid;exception when invalid_text_representation then return null;end;if vendor_contract.id is null or vendor_contract.status not in('approved','active') then return null;end if;select * into vendor_row from private.aqari_vendors v where v.workspace_id=w and v.id=vendor_contract.vendor_id;if vendor_contract.property_id is not null then select * into property_row from public.aqari_properties p where p.workspace_id=w and p.id=vendor_contract.property_id;end if;vars:=jsonb_build_object('propertyName',coalesce(property_row.name,''),'vendorName',vendor_row.name,'contractNo',vendor_contract.contract_no,'serviceKind',vendor_contract.service_kind,'endsOn',vendor_contract.ends_on,'daysRemaining',vendor_contract.ends_on-current_date);end if;return jsonb_build_object('channel',n.channel,'recipientReference',recipient,'template',template_value,'purpose',purpose_value,'variables',coalesce(vars,'{}'::jsonb));end $function$

CREATE OR REPLACE FUNCTION private.aqari_operations_expense(w uuid, p uuid, d date, category text, payee text, amount numeric, reference text, description text, document_id uuid, expense_id uuid, actor_name text)
 RETURNS private.aqari_financial_expenses
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare e private.aqari_financial_expenses;
begin
 perform private.aqari_financial_open(w,d);
 if not private.aqari_operations_document(w,p,document_id) then raise exception 'DOCUMENT_REQUIRED_AND_UNVERIFIED' using errcode='23514'; end if;
 insert into private.aqari_financial_expenses(
  id,workspace_id,property_id,expense_date,category,payee,amount,method,reference,description,document_id,
  state,revision,voucher_no,created_by,approved_by,approved_by_name,approved_at,approval_reason
 ) values(
  expense_id,w,p,d,category,payee,amount,'bank',reference,description,document_id,
  'approved',1,'EX-'||to_char(now() at time zone 'Asia/Kuwait','YYYYMMDD')||'-'||lpad(nextval('private.aqari_expense_voucher_seq')::text,8,'0'),
  auth.uid(),auth.uid(),actor_name,now(),'اعتماد آلي مرتبط بسجل تشغيلي معتمد'
 ) returning * into e;
 return e;
end $function$

CREATE OR REPLACE FUNCTION private.aqari_operations_register_core(p_workspace_id uuid, p_domain text, p_action text, p_data jsonb DEFAULT '{}'::jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
 w uuid:=p_workspace_id; d jsonb:=p_data; ident uuid; expected integer; before_row jsonb; after_row jsonb;
 actor text; why text; now_date date:=(now() at time zone 'Asia/Kuwait')::date;
 cheque private.aqari_cheques; vendor private.aqari_vendors; work_order private.aqari_work_orders;
 legal_case private.aqari_legal_cases; fund private.aqari_petty_cash_funds; entry private.aqari_petty_cash_entries;
 expense private.aqari_financial_expenses; property_id uuid; lease_id uuid; document_id uuid; expense_id uuid;
 amount_value numeric(15,3); next_state text; from_state text; event_id uuid; result jsonb;
begin
 if auth.uid() is null or not private.aqari_manager(w) then raise insufficient_privilege using message='ACCESS_DENIED'; end if;
 if p_action<>'list' then perform private.aqari_require_sensitive_aal2(w); end if;
 if d is null or jsonb_typeof(d)<>'object' or octet_length(d::text)>32000 then raise exception 'INVALID_OPERATION_DATA' using errcode='22023'; end if;
 if p_domain not in ('overview','cheques','vendors','work_orders','legal_cases','petty_cash') then raise exception 'INVALID_OPERATION_DOMAIN' using errcode='22023'; end if;
 select coalesce(nullif(display_name,''),auth.uid()::text) into actor from public.aqari_profiles where user_id=auth.uid();
 actor:=coalesce(actor,auth.uid()::text);

 if p_action='list' then
  return case p_domain
   when 'overview' then jsonb_build_object(
    'health',public.aqari_operations_health(w),
    'properties',(select coalesce(jsonb_agg(jsonb_build_object('id',p.id,'name',p.name) order by p.name),'[]') from public.aqari_properties p where p.workspace_id=w),
    'documents',(select coalesce(jsonb_agg(jsonb_build_object('id',doc.id,'name',coalesce(doc.document_no||' — ','')||doc.title,'property_id',p.id) order by doc.created_at desc),'[]') from public.aqari_documents doc join public.aqari_properties p on p.workspace_id=doc.workspace_id and p.external_ref=doc.entity_ref where doc.workspace_id=w and doc.entity_type='property' and doc.status='uploaded'),
    'leases',(select coalesce(jsonb_agg(jsonb_build_object('id',l.id,'contract_no',l.contract_no,'tenant_id',l.tenant_id,'unit_id',l.unit_id,'status',l.status) order by l.contract_no),'[]') from public.aqari_leases l where l.workspace_id=w),
    'vendors',(select coalesce(jsonb_agg(to_jsonb(v) order by v.name),'[]') from private.aqari_vendors v where v.workspace_id=w and v.status<>'archived'),
    'funds',(select coalesce(jsonb_agg(to_jsonb(f) order by f.name),'[]') from private.aqari_petty_cash_funds f where f.workspace_id=w),
    'audit',(select coalesce(jsonb_agg(to_jsonb(a) order by a.id desc),'[]') from (select * from private.aqari_operations_audit a where a.workspace_id=w order by a.id desc limit 100) a)
   )
   when 'cheques' then jsonb_build_object('items',(select coalesce(jsonb_agg(to_jsonb(c) order by c.due_on,c.id),'[]') from private.aqari_cheques c where c.workspace_id=w),
    'events',(select coalesce(jsonb_agg(to_jsonb(e) order by e.occurred_at desc,e.id),'[]') from private.aqari_cheque_events e where e.workspace_id=w))
   when 'vendors' then jsonb_build_object('items',(select coalesce(jsonb_agg(to_jsonb(v) order by v.name,v.id),'[]') from private.aqari_vendors v where v.workspace_id=w),
    'contracts',(select coalesce(jsonb_agg(to_jsonb(c) order by c.ends_on,c.id),'[]') from private.aqari_vendor_contracts c where c.workspace_id=w))
   when 'work_orders' then jsonb_build_object('items',(select coalesce(jsonb_agg(to_jsonb(o) order by o.created_at desc,o.id),'[]') from private.aqari_work_orders o where o.workspace_id=w))
   when 'legal_cases' then jsonb_build_object('items',(select coalesce(jsonb_agg(to_jsonb(c) order by c.opened_on desc,c.id),'[]') from private.aqari_legal_cases c where c.workspace_id=w),
    'events',(select coalesce(jsonb_agg(to_jsonb(e) order by e.occurs_at desc,e.id),'[]') from private.aqari_legal_case_events e where e.workspace_id=w),
    'costs',(select coalesce(jsonb_agg(to_jsonb(c) order by c.occurred_on desc,c.id),'[]') from private.aqari_legal_costs c where c.workspace_id=w))
   when 'petty_cash' then jsonb_build_object('funds',(select coalesce(jsonb_agg(to_jsonb(f) order by f.name,f.id),'[]') from private.aqari_petty_cash_funds f where f.workspace_id=w),
    'entries',(select coalesce(jsonb_agg(to_jsonb(e) order by e.created_at desc,e.id),'[]') from private.aqari_petty_cash_entries e where e.workspace_id=w))
  end;
 end if;

 ident:=nullif(d->>'id','')::uuid;
 if ident is null then raise exception 'OPERATION_ID_REQUIRED' using errcode='22023'; end if;
 why:=btrim(coalesce(d->>'reason',''));
 if p_action not in ('create','save') and length(why)<3 then raise exception 'OPERATION_REASON_REQUIRED' using errcode='22023'; end if;

 if p_domain='cheques' then
  if not private.aqari_can(w,'collections','write') then raise insufficient_privilege using message='ACCESS_DENIED'; end if;
  if p_action='create' then
   lease_id:=nullif(d->>'lease_id','')::uuid; amount_value:=private.aqari_hr_money(d->'amount');
   if not exists(select 1 from public.aqari_leases l where l.workspace_id=w and l.id=lease_id) then raise insufficient_privilege using message='ACCESS_DENIED'; end if;
   if coalesce(d->>'kind','') not in ('postdated','guarantee') or length(btrim(coalesce(d->>'cheque_no','')))<2 or length(btrim(coalesce(d->>'bank_name','')))<2 or coalesce(d->>'due_on','') !~ '^\d{4}-\d{2}-\d{2}$' or amount_value<=0 then raise exception 'INVALID_CHEQUE_DATA' using errcode='22023'; end if;
   insert into private.aqari_cheques(id,workspace_id,lease_id,cheque_no,bank_name,kind,amount,due_on,created_by)
    values(ident,w,lease_id,btrim(d->>'cheque_no'),btrim(d->>'bank_name'),d->>'kind',amount_value,(d->>'due_on')::date,auth.uid()) returning * into cheque;
   after_row:=to_jsonb(cheque);
  elsif p_action='transition' then
   expected:=(d->>'revision')::integer; event_id:=nullif(d->>'event_id','')::uuid; next_state:=d->>'state';
   select * into cheque from private.aqari_cheques c where c.workspace_id=w and c.id=ident for update;
   if not found then raise insufficient_privilege using message='ACCESS_DENIED'; end if;
   if cheque.revision is distinct from expected then raise serialization_failure using message='REVISION_CONFLICT'; end if;
   from_state:=cheque.state;
   if not ((from_state='scheduled' and next_state in ('deposited','cancelled')) or (from_state='deposited' and next_state in ('cleared','returned')) or (from_state='returned' and next_state in ('redeposited','settled','cancelled')) or (from_state='redeposited' and next_state in ('cleared','returned'))) then raise exception 'INVALID_CHEQUE_TRANSITION' using errcode='23514'; end if;
   if next_state in ('deposited','cleared','returned','redeposited') and length(btrim(coalesce(d->>'bank_reference','')))<3 then raise exception 'CHEQUE_REFERENCE_REQUIRED' using errcode='22023'; end if;
   if event_id is null then raise exception 'CHEQUE_EVENT_ID_REQUIRED' using errcode='22023'; end if;
   if exists(select 1 from private.aqari_cheque_events e where e.id=event_id) then raise exception 'DUPLICATE_OPERATION' using errcode='23505'; end if;
   before_row:=to_jsonb(cheque);
   update private.aqari_cheques c set state=next_state,renewal_frozen=case when next_state='returned' then true when next_state in ('cleared','settled') then false else c.renewal_frozen end,revision=c.revision+1,updated_at=now() where c.id=ident returning * into cheque;
   insert into private.aqari_cheque_events(id,workspace_id,cheque_id,from_state,to_state,occurred_at,bank_reference,reason,debt_adjustment,actor_id,actor_name,snapshot)
    values(event_id,w,ident,from_state,next_state,now(),btrim(coalesce(d->>'bank_reference','')),why,case when next_state='returned' then cheque.amount else 0 end,auth.uid(),actor,to_jsonb(cheque));
   if next_state='returned' then insert into private.aqari_tenant_adjustments(id,workspace_id,lease_id,kind,direction,amount,occurred_on,source_type,source_id,reason,actor_id)
     values(event_id,w,cheque.lease_id,'cheque_return','debit',cheque.amount,now_date,'cheque_event',event_id,why,auth.uid()) on conflict(workspace_id,source_type,source_id) do nothing; end if;
   after_row:=to_jsonb(cheque);
  else raise exception 'INVALID_CHEQUE_ACTION' using errcode='22023'; end if;

 elsif p_domain='vendors' then
  if not private.aqari_can(w,'maintenance','write') then raise insufficient_privilege using message='ACCESS_DENIED'; end if;
  if p_action='save' then
   select * into vendor from private.aqari_vendors v where v.workspace_id=w and v.id=ident for update;
   expected:=coalesce((d->>'revision')::integer,0); if coalesce(vendor.revision,0) is distinct from expected then raise serialization_failure using message='REVISION_CONFLICT'; end if;
   if length(btrim(coalesce(d->>'name',''))) not between 2 and 200 or coalesce(d->>'status','active') not in ('active','suspended','archived') then raise exception 'INVALID_VENDOR_DATA' using errcode='22023'; end if;
   before_row:=case when vendor.id is null then null else to_jsonb(vendor) end;
   if vendor.id is null then
    insert into private.aqari_vendors(id,workspace_id,name,civil_or_license_no,phone,email,status,rating,rating_basis,created_by)
     values(ident,w,btrim(d->>'name'),btrim(coalesce(d->>'license_no','')),btrim(coalesce(d->>'phone','')),nullif(btrim(coalesce(d->>'email','')),''),coalesce(d->>'status','active'),nullif(d->>'rating','')::numeric,btrim(coalesce(d->>'rating_basis','')),auth.uid()) returning * into vendor;
   else
    update private.aqari_vendors v set name=btrim(d->>'name'),civil_or_license_no=btrim(coalesce(d->>'license_no','')),phone=btrim(coalesce(d->>'phone','')),email=nullif(btrim(coalesce(d->>'email','')),''),status=coalesce(d->>'status','active'),rating=nullif(d->>'rating','')::numeric,rating_basis=btrim(coalesce(d->>'rating_basis','')),revision=v.revision+1,updated_at=now()
     where v.workspace_id=w and v.id=ident returning * into vendor;
   end if;
   after_row:=to_jsonb(vendor);
  elsif p_action='contract' then
   lease_id:=nullif(d->>'vendor_id','')::uuid; property_id:=nullif(d->>'property_id','')::uuid; document_id:=nullif(d->>'document_id','')::uuid;
   if not private.aqari_can_property(w,property_id,'maintenance','write') or not exists(select 1 from private.aqari_vendors v where v.workspace_id=w and v.id=lease_id and v.status='active') or not private.aqari_operations_document(w,property_id,document_id) then raise insufficient_privilege using message='ACCESS_DENIED_OR_DOCUMENT_UNVERIFIED'; end if;
   amount_value:=private.aqari_hr_money(d->'amount');
   if length(btrim(coalesce(d->>'contract_no','')))<2 or length(btrim(coalesce(d->>'service_kind','')))<2 or nullif(d->>'starts_on','')::date>nullif(d->>'ends_on','')::date or amount_value<0 then raise exception 'INVALID_VENDOR_CONTRACT' using errcode='22023'; end if;
   insert into private.aqari_vendor_contracts as vc(id,workspace_id,vendor_id,property_id,contract_no,starts_on,ends_on,service_kind,amount,status,document_id,approved_by,approved_at)
    values(ident,w,lease_id,property_id,btrim(d->>'contract_no'),(d->>'starts_on')::date,(d->>'ends_on')::date,btrim(d->>'service_kind'),amount_value,'active',document_id,auth.uid(),now()) returning to_jsonb(vc) into after_row;
  else raise exception 'INVALID_VENDOR_ACTION' using errcode='22023'; end if;

 elsif p_domain='work_orders' then
  if not private.aqari_can(w,'maintenance','write') then raise insufficient_privilege using message='ACCESS_DENIED'; end if;
  if p_action='create' then
   property_id:=nullif(d->>'property_id','')::uuid;
   if not private.aqari_can_property(w,property_id,'maintenance','write') or not exists(select 1 from private.aqari_vendors v where v.workspace_id=w and v.id=(d->>'vendor_id')::uuid and v.status='active') then raise insufficient_privilege using message='ACCESS_DENIED'; end if;
   amount_value:=private.aqari_hr_money(d->'approved_amount');
   if length(btrim(coalesce(d->>'order_no','')))<2 or length(btrim(coalesce(d->>'description',''))) not between 3 and 5000 or amount_value<0 then raise exception 'INVALID_WORK_ORDER_DATA' using errcode='22023'; end if;
   insert into private.aqari_work_orders(id,workspace_id,property_id,maintenance_request_id,vendor_id,vendor_contract_id,order_no,description,approved_amount,created_by)
    values(ident,w,property_id,nullif(d->>'maintenance_request_id','')::uuid,(d->>'vendor_id')::uuid,nullif(d->>'vendor_contract_id','')::uuid,btrim(d->>'order_no'),btrim(d->>'description'),amount_value,auth.uid()) returning * into work_order;
   after_row:=to_jsonb(work_order);
  elsif p_action='status' then
   expected:=(d->>'revision')::integer; next_state:=d->>'state'; select * into work_order from private.aqari_work_orders o where o.workspace_id=w and o.id=ident for update;
   if not found then raise insufficient_privilege using message='ACCESS_DENIED'; end if;
   if work_order.revision is distinct from expected then raise serialization_failure using message='REVISION_CONFLICT'; end if;
   if not ((work_order.status='draft' and next_state in ('approved','cancelled')) or (work_order.status='approved' and next_state in ('assigned','cancelled')) or (work_order.status='assigned' and next_state in ('in_progress','cancelled')) or (work_order.status='in_progress' and next_state in ('completed','cancelled'))) then raise exception 'INVALID_WORK_ORDER_TRANSITION' using errcode='23514'; end if;
   before_row:=to_jsonb(work_order);
   update private.aqari_work_orders o set status=next_state,approved_by=case when next_state='approved' then auth.uid() else o.approved_by end,approved_at=case when next_state='approved' then now() else o.approved_at end,completed_at=case when next_state='completed' then now() else o.completed_at end,revision=o.revision+1 where o.id=ident returning * into work_order;
   after_row:=to_jsonb(work_order);
  elsif p_action='invoice' then
   expected:=(d->>'revision')::integer; select * into work_order from private.aqari_work_orders o where o.workspace_id=w and o.id=ident for update;
   if not found or work_order.status<>'completed' then raise exception 'WORK_ORDER_NOT_COMPLETED' using errcode='23514'; end if;
   if work_order.revision is distinct from expected then raise serialization_failure using message='REVISION_CONFLICT'; end if;
   if work_order.invoice_id is not null then raise exception 'WORK_ORDER_ALREADY_INVOICED' using errcode='23505'; end if;
   amount_value:=private.aqari_hr_money(d->'amount'); document_id:=nullif(d->>'document_id','')::uuid; expense_id:=nullif(d->>'expense_id','')::uuid;
   if amount_value<=0 or amount_value>work_order.approved_amount or length(btrim(coalesce(d->>'invoice_id','')))<2 or length(btrim(coalesce(d->>'reference','')))<3 then raise exception 'INVALID_WORK_ORDER_INVOICE' using errcode='22023'; end if;
   select * into vendor from private.aqari_vendors v where v.workspace_id=w and v.id=work_order.vendor_id;
   before_row:=to_jsonb(work_order);
   expense:=private.aqari_operations_expense(w,work_order.property_id,now_date,'أمر شغل وصيانة',vendor.name,amount_value,btrim(d->>'reference'),'فاتورة أمر الشغل '||work_order.order_no,document_id,expense_id,actor);
   update private.aqari_work_orders o set invoice_id=btrim(d->>'invoice_id'),invoice_amount=amount_value,expense_key='expense:'||expense.id::text,revision=o.revision+1 where o.id=ident returning * into work_order;
   after_row:=to_jsonb(work_order)||jsonb_build_object('expense',to_jsonb(expense));
  else raise exception 'INVALID_WORK_ORDER_ACTION' using errcode='22023'; end if;

 elsif p_domain='legal_cases' then
  if not private.aqari_can(w,'legal','write') and not private.aqari_can(w,'contracts','write') then raise insufficient_privilege using message='ACCESS_DENIED'; end if;
  if p_action='create' then
   lease_id:=nullif(d->>'lease_id','')::uuid;
   if not exists(select 1 from public.aqari_leases l where l.workspace_id=w and l.id=lease_id) or length(btrim(coalesce(d->>'case_no','')))<2 or length(btrim(coalesce(d->>'court','')))<2 or length(btrim(coalesce(d->>'kind','')))<2 then raise exception 'INVALID_LEGAL_CASE_DATA' using errcode='22023'; end if;
   insert into private.aqari_legal_cases(id,workspace_id,lease_id,case_no,court,kind,opened_on,summary,created_by)
    values(ident,w,lease_id,btrim(d->>'case_no'),btrim(d->>'court'),btrim(d->>'kind'),coalesce(nullif(d->>'opened_on','')::date,now_date),btrim(coalesce(d->>'summary','')),auth.uid()) returning * into legal_case;
   after_row:=to_jsonb(legal_case);
  elsif p_action='event' then
   event_id:=nullif(d->>'event_id','')::uuid; select * into legal_case from private.aqari_legal_cases c where c.workspace_id=w and c.id=ident for update;
   if not found or d->>'kind' not in ('hearing','filing','judgment','appeal','note','status_change') or length(btrim(coalesce(d->>'title','')))<2 then raise exception 'INVALID_LEGAL_EVENT' using errcode='22023'; end if;
   insert into private.aqari_legal_case_events(id,workspace_id,case_id,kind,occurs_at,title,details,document_id,actor_id)
    values(event_id,w,ident,d->>'kind',coalesce(nullif(d->>'occurs_at','')::timestamptz,now()),btrim(d->>'title'),btrim(coalesce(d->>'details','')),nullif(d->>'document_id','')::uuid,auth.uid());
   after_row:=jsonb_build_object('id',event_id,'case_id',ident,'kind',d->>'kind');
  elsif p_action='cost' then
   event_id:=nullif(d->>'cost_id','')::uuid; expense_id:=nullif(d->>'expense_id','')::uuid; document_id:=nullif(d->>'document_id','')::uuid;
   select * into legal_case from private.aqari_legal_cases c where c.workspace_id=w and c.id=ident for update;
   if not found then raise insufficient_privilege using message='ACCESS_DENIED'; end if;
   amount_value:=private.aqari_hr_money(d->'amount');
   select u.property_id into property_id from public.aqari_leases l join public.aqari_units u on u.workspace_id=l.workspace_id and u.id=l.unit_id where l.workspace_id=w and l.id=legal_case.lease_id;
   if amount_value<=0 or d->>'kind' not in ('court_fee','lawyer_fee','expert_fee','execution_fee','other') or ((d->>'charge_to_tenant')::boolean and length(btrim(coalesce(d->>'legal_basis','')))<5) then raise exception 'INVALID_LEGAL_COST' using errcode='22023'; end if;
   expense:=private.aqari_operations_expense(w,property_id,coalesce(nullif(d->>'occurred_on','')::date,now_date),'مصاريف قضائية',btrim(coalesce(d->>'payee','جهة قضائية أو قانونية')),amount_value,btrim(d->>'reference'),'مصاريف القضية '||legal_case.case_no,document_id,expense_id,actor);
   insert into private.aqari_legal_costs(id,workspace_id,case_id,lease_id,amount,occurred_on,kind,charge_to_tenant,legal_basis,approved_by,approved_at,expense_key,document_id,actor_id)
    values(event_id,w,ident,legal_case.lease_id,amount_value,coalesce(nullif(d->>'occurred_on','')::date,now_date),d->>'kind',coalesce((d->>'charge_to_tenant')::boolean,false),btrim(coalesce(d->>'legal_basis','')),auth.uid(),now(),'expense:'||expense.id::text,document_id,auth.uid());
   if coalesce((d->>'charge_to_tenant')::boolean,false) then insert into private.aqari_tenant_adjustments(id,workspace_id,lease_id,kind,direction,amount,occurred_on,source_type,source_id,reason,actor_id)
    values(event_id,w,legal_case.lease_id,'legal_cost','debit',amount_value,coalesce(nullif(d->>'occurred_on','')::date,now_date),'legal_cost',event_id,btrim(d->>'legal_basis'),auth.uid()); end if;
   after_row:=jsonb_build_object('id',event_id,'expense',to_jsonb(expense));
  else raise exception 'INVALID_LEGAL_ACTION' using errcode='22023'; end if;

 elsif p_domain='petty_cash' then
  if not private.aqari_can(w,'finance','write') then raise insufficient_privilege using message='ACCESS_DENIED'; end if;
  if p_action='create' then
   amount_value:=private.aqari_hr_money(d->'ceiling');
   if length(btrim(coalesce(d->>'name','')))<2 or amount_value<=0 then raise exception 'INVALID_PETTY_CASH_FUND' using errcode='22023'; end if;
   insert into private.aqari_petty_cash_funds(id,workspace_id,custodian_id,name,ceiling)
    values(ident,w,nullif(d->>'custodian_id','')::uuid,btrim(d->>'name'),amount_value) returning * into fund;
   after_row:=to_jsonb(fund);
  elsif p_action='entry' then
   event_id:=nullif(d->>'entry_id','')::uuid; select * into fund from private.aqari_petty_cash_funds f where f.workspace_id=w and f.id=ident for update;
   if not found or fund.status<>'open' then raise exception 'PETTY_CASH_FUND_NOT_OPEN' using errcode='23514'; end if;
   amount_value:=private.aqari_hr_money(d->'amount'); next_state:=d->>'kind'; before_row:=to_jsonb(fund);
   if next_state not in ('fund','spend','settle') or amount_value<=0 then raise exception 'INVALID_PETTY_CASH_ENTRY' using errcode='22023'; end if;
   if next_state='fund' and fund.balance+amount_value>fund.ceiling then raise exception 'PETTY_CASH_CEILING' using errcode='23514'; end if;
   if next_state in ('spend','settle') and fund.balance<amount_value then raise exception 'PETTY_CASH_INSUFFICIENT' using errcode='23514'; end if;
   if next_state='spend' then
    property_id:=nullif(d->>'property_id','')::uuid; document_id:=nullif(d->>'document_id','')::uuid; expense_id:=nullif(d->>'expense_id','')::uuid;
    expense:=private.aqari_operations_expense(w,property_id,now_date,btrim(coalesce(d->>'category','مصروف عهدة')),actor,amount_value,btrim(d->>'reference'),'مصروف من العهدة '||fund.name,document_id,expense_id,actor);
   end if;
   update private.aqari_petty_cash_funds f set balance=case when next_state='fund' then f.balance+amount_value else f.balance-amount_value end,revision=f.revision+1 where f.id=ident returning * into fund;
   insert into private.aqari_petty_cash_entries(id,workspace_id,fund_id,kind,amount,balance_after,invoice_id,property_id,approved_by,approved_at,document_id,actor_id,snapshot)
    values(event_id,w,ident,next_state,amount_value,fund.balance,nullif(d->>'invoice_id',''),property_id,case when next_state='spend' then auth.uid() end,case when next_state='spend' then now() end,document_id,auth.uid(),jsonb_build_object('fund',to_jsonb(fund),'expense',to_jsonb(expense)));
   after_row:=to_jsonb(fund)||jsonb_build_object('entry_id',event_id,'expense',to_jsonb(expense));
  else raise exception 'INVALID_PETTY_CASH_ACTION' using errcode='22023'; end if;
 else raise exception 'OVERVIEW_READ_ONLY' using errcode='22023'; end if;

 insert into private.aqari_operations_audit(workspace_id,domain,entity_id,action,actor_id,actor_name,reason,before_value,after_value)
 values(w,p_domain,ident,p_action,auth.uid(),actor,why,before_row,after_row);
 return after_row;
end $function$

CREATE OR REPLACE FUNCTION private.aqari_partner_commercial_evidence(w uuid, payments jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE
 SET search_path TO ''
AS $function$
declare result jsonb;begin
 if to_regclass('private.aqari_commercial_active_allocations') is not null then
  execute 'select coalesce(jsonb_agg(to_jsonb(a) order by a.allocation_id),''[]''::jsonb) from private.aqari_commercial_active_allocations a where a.workspace_id=$1 and a.payment_id in(select (x->>''id'')::uuid from jsonb_array_elements($2)x)' into result using w,payments;
  return result;
 end if;
 if to_regclass('private.aqari_commercial_payment_allocations') is not null then return '[{"review_required":"COMMERCIAL_ACTIVE_VIEW_REQUIRED"}]'::jsonb;end if;
 return '[]'::jsonb;
end$function$

CREATE OR REPLACE FUNCTION private.aqari_partner_distribution_register(p_workspace_id uuid, p_action text, p_data jsonb DEFAULT '{}'::jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
#variable_conflict use_column
declare w uuid:=p_workspace_id;d jsonb:=p_data;k text;allowed text[];m date;p uuid;ident uuid;why text;app jsonb;s jsonb;owners jsonb;recipients jsonb;x jsonb;v jsonb;rh text;doc jsonb;
 src private.aqari_partner_period_sources;a private.aqari_partner_source_approvals;e private.aqari_partner_distributions;original private.aqari_partner_distributions;
begin
 if auth.uid() is null or not private.aqari_manager(w) or not private.aqari_can(w,'partners','read') or not private.aqari_can(w,'finance','read') or not private.aqari_can(w,'documents','read') then raise insufficient_privilege using message='ACCESS_DENIED';end if;
 if d is null or jsonb_typeof(d)<>'object' or octet_length(d::text)>64000 then raise exception 'INVALID_PARTNER_REQUEST' using errcode='22023';end if;
 allowed:=case p_action when 'list' then array['month'] when 'preview' then array['property_id','month','shares_key']
 when 'approve_source' then array['id','property_id','month','source_hash','shares_key','shares_version','expected_review_revision','expected_income_fils','expected_expense_fils','expected_reserve_fils','document_id','recipients','reason']
 when 'post' then array['id','source_id','review_hash','reason'] when 'reverse' then array['id','distribution_id','reason'] else null end;
 if allowed is null then raise exception 'INVALID_PARTNER_ACTION' using errcode='22023';end if;
 for k in select jsonb_object_keys(d) loop if not k=any(allowed) then raise exception 'INVALID_PARTNER_FIELD' using errcode='22023';end if;end loop;
 if p_action in('list','preview','approve_source') then
  if coalesce(d->>'month','')!~ '^(20[0-9]{2}|2100)-(0[1-9]|1[0-2])$' then raise exception 'INVALID_PARTNER_MONTH' using errcode='22023';end if;m:=((d->>'month')||'-01')::date;
 end if;
 if p_action='list' then
  select private.aqari_unwrap(payload) into app from public.aqari_app_state where workspace_id=w;
  return jsonb_build_object('workspace_id',w,'month',d->>'month',
   'properties',(select coalesce(jsonb_agg(jsonb_build_object('id',p.id,'name',p.name) order by p.name,p.id),'[]') from public.aqari_properties p where p.workspace_id=w),
   'shares',coalesce(app->'propertySharesV267','{}'),
   'sources',(select coalesce(jsonb_agg(to_jsonb(s) order by s.property_id),'[]') from private.aqari_partner_period_sources s where s.workspace_id=w and s.month=m),
   'approvals',(select coalesce(jsonb_agg(to_jsonb(a) order by a.property_id),'[]') from private.aqari_partner_source_approvals a where a.workspace_id=w and a.month=m),
   'entries',(select coalesce(jsonb_agg(to_jsonb(e) order by e.recorded_at,e.id),'[]') from private.aqari_partner_distributions e where e.workspace_id=w and e.month=m),
   'partners',(select coalesce(jsonb_agg(jsonb_build_object('user_id',a.user_id,'property_id',a.property_id,'name',a.display_name,'email',a.email) order by a.property_id,a.email),'[]') from private.aqari_partner_access a join auth.users u on u.id=a.user_id and lower(u.email)=a.email where a.workspace_id=w and a.is_active and u.email_confirmed_at is not null),
   'documents',(select coalesce(jsonb_agg(jsonb_build_object('id',doc.id,'property_id',p.id,'title',doc.title) order by doc.created_at desc,doc.id),'[]') from public.aqari_documents doc join public.aqari_properties p on p.workspace_id=doc.workspace_id and p.external_ref=doc.entity_ref where doc.workspace_id=w and doc.entity_type='property' and doc.status='uploaded'),
   'rule','largest_remainder_absolute_fils_then_owner_id_C','currency','KWD','external_payments',false);
 end if;
 if p_action<>'preview' then
  if not private.aqari_can(w,'partners','write') or not private.aqari_can(w,'finance','write') then raise insufficient_privilege using message='ACCESS_DENIED';end if;
  perform private.aqari_require_sensitive_aal2(w);
 end if;
 select private.aqari_unwrap(payload) into app from public.aqari_app_state where workspace_id=w for update;
 if not found then raise insufficient_privilege using message='ACCESS_DENIED';end if;
 if p_action<>'preview' then
  ident:=(d->>'id')::uuid;why:=btrim(d->>'reason');rh:=private.aqari_partner_hash(d);
  if ident is null or why is null or length(why) not between 5 and 500 then raise exception 'PARTNER_REASON_REQUIRED' using errcode='22023';end if;
  if p_action='approve_source' then
   select * into a from private.aqari_partner_source_approvals where id=ident;
   if found then if a.workspace_id<>w then raise insufficient_privilege using message='ACCESS_DENIED';end if;if a.approved_by<>auth.uid() then raise insufficient_privilege using message='ACCESS_DENIED';end if;if a.request_hash<>rh then raise exception 'PARTNER_RETRY_CONFLICT' using errcode='23514';end if;return to_jsonb(a);end if;
  else
   select * into e from private.aqari_partner_distributions where id=ident;
   if found then if e.workspace_id<>w then raise insufficient_privilege using message='ACCESS_DENIED';end if;if e.actor_id<>auth.uid() then raise insufficient_privilege using message='ACCESS_DENIED';end if;if e.request_hash<>rh or e.kind<>(case when p_action='post' then 'distribution' else 'reversal' end) then raise exception 'PARTNER_RETRY_CONFLICT' using errcode='23514';end if;return to_jsonb(e);end if;
  end if;
 end if;
 if p_action in('preview','approve_source') then
  p:=(d->>'property_id')::uuid;
  if p is null or not exists(select 1 from public.aqari_properties where workspace_id=w and id=p) then raise insufficient_privilege using message='ACCESS_DENIED';end if;
  select * into src from private.aqari_partner_period_sources where workspace_id=w and property_id=p and month=m;
  if found and jsonb_array_length(private.aqari_partner_commercial_evidence(w,src.source->'payments'))>0 then raise exception 'PARTNER_COMMERCIAL_ALLOCATION_REVIEW_REQUIRED' using errcode='23514';end if;
  if not found or not src.period_matches then raise exception 'PARTNER_SOURCE_REVIEW_REQUIRED' using errcode='23514';end if;
  if src.source_hash<>private.aqari_partner_hash(src.source) then raise exception 'PARTNER_SOURCE_HASH_MISMATCH' using errcode='23514';end if;
  s:=app->'propertySharesV267'->(d->>'shares_key');owners:=s->'owners';
  if s->>'enabled' is distinct from 'true' or jsonb_typeof(s->'version') is distinct from 'number' or jsonb_typeof(s->'events') is distinct from 'array' then raise exception 'PARTNER_SHARES_REVIEW_REQUIRED' using errcode='23514';end if;
  perform private.aqari_validate_partner_owners(owners);
  if exists(select 1 from jsonb_array_elements(s->'events')x where x->>'type' in('distribution','payment')) then raise exception 'PARTNER_LEGACY_FINANCE_REVIEW_REQUIRED' using errcode='23514';end if;
  v:=jsonb_build_object('workspace_id',w,'property_id',p,'month',d->>'month','source_hash',src.source_hash,'shares_key',d->>'shares_key','shares_version',s->'version','owners',owners,
   'income_fils',src.source->>'income_fils','expense_fils',src.source->>'expense_fils','reserve_fils',src.source->>'reserve_fils',
   'review_revision',(select coalesce(max(a.review_revision),0) from private.aqari_partner_source_approvals a where a.workspace_id=w and a.property_id=p and a.month=m),'net_fils',((src.source->>'income_fils')::bigint-(src.source->>'expense_fils')::bigint-(src.source->>'reserve_fils')::bigint)::text);
  if p_action='preview' then return v||jsonb_build_object('allocations',private.aqari_partner_allocate((v->>'net_fils')::bigint,owners,'{}'));end if;
  if d->>'source_hash' is distinct from src.source_hash or d->'shares_version' is distinct from s->'version' or d->'expected_review_revision' is distinct from v->'review_revision' then raise serialization_failure using message='PARTNER_REVIEW_STALE';end if;
  foreach k in array array['income','expense','reserve'] loop
   if jsonb_typeof(d->('expected_'||k||'_fils')) is distinct from 'string' or coalesce(d->>('expected_'||k||'_fils'),'')!~ '^-?(0|[1-9][0-9]{0,15})$'
    or (d->>('expected_'||k||'_fils'))::numeric<>(src.source->>(k||'_fils'))::numeric then raise exception 'PARTNER_EXPLICIT_RECONCILIATION_REQUIRED' using errcode='23514';end if;
  end loop;
  select to_jsonb(doc) into doc from public.aqari_documents doc join public.aqari_properties p on p.workspace_id=doc.workspace_id and p.external_ref=doc.entity_ref
   join storage.objects o on o.bucket_id=doc.storage_bucket and o.name=doc.storage_path where doc.id=(d->>'document_id')::uuid and doc.workspace_id=w and doc.entity_type='property' and p.id=src.property_id and doc.status='uploaded'
   and doc.checksum_sha256~'^[a-f0-9]{64}$' and doc.size_bytes>0 and (o.metadata->>'size')::bigint=doc.size_bytes and o.metadata->>'mimetype'=doc.mime_type for share of doc,o;
  if doc is null then raise exception 'PARTNER_DOCUMENT_UNVERIFIED' using errcode='23514';end if;
  recipients:=d->'recipients';
  if jsonb_typeof(recipients) is distinct from 'object' or (select count(*) from jsonb_object_keys(recipients))<>jsonb_array_length(owners) then raise exception 'PARTNER_RECIPIENT_REVIEW_REQUIRED' using errcode='23514';end if;
  for x in select value from jsonb_array_elements(owners) loop
   if not recipients?(x->>'id') then raise exception 'PARTNER_RECIPIENT_REVIEW_REQUIRED' using errcode='23514';end if;
   -- Explicit null keeps an offline owner private; it grants nobody access.
   if recipients->(x->>'id')<>'null'::jsonb and not exists(select 1 from private.aqari_partner_access a join auth.users u on u.id=a.user_id and lower(u.email)=a.email
    where a.workspace_id=w and a.property_id=p and a.is_active and u.email_confirmed_at is not null and a.user_id=(recipients->>(x->>'id'))::uuid
    and not exists(select 1 from public.aqari_memberships m where m.workspace_id=w and m.user_id=a.user_id)) then raise exception 'PARTNER_RECIPIENT_ACCESS_REQUIRED' using errcode='23514';end if;
  end loop;
  if exists(select 1 from jsonb_each_text(recipients) where value is not null group by value having count(*)>1) then raise exception 'PARTNER_RECIPIENT_DUPLICATE' using errcode='23514';end if;
  if exists(select 1 from private.aqari_partner_source_approvals a where a.workspace_id=w and ((a.property_id=p and a.shares_key<>d->>'shares_key') or (a.shares_key=d->>'shares_key' and a.property_id<>p))) then raise exception 'PARTNER_PROPERTY_SHARES_BINDING_CONFLICT' using errcode='23514';end if;
  if exists(select 1 from private.aqari_partner_distributions e where e.workspace_id=w and e.property_id=p and e.month=m) then raise exception 'PARTNER_DISTRIBUTED_SOURCE_IMMUTABLE' using errcode='23514';end if;
  insert into private.aqari_partner_source_approvals(id,workspace_id,property_id,month,shares_key,shares_version,owners,recipients,review_revision,source_hash,review_hash,document_id,document_snapshot,income_fils,expense_fils,reserve_fils,net_fils,reason,approved_by,request_hash)
   values(ident,w,p,m,d->>'shares_key',(s->>'version')::bigint,owners,recipients,(v->>'review_revision')::bigint+1,src.source_hash,private.aqari_partner_hash(v||jsonb_build_object('recipients',recipients,'document',doc)),(d->>'document_id')::uuid,doc,(v->>'income_fils')::bigint,(v->>'expense_fils')::bigint,(v->>'reserve_fils')::bigint,(v->>'net_fils')::bigint,why,auth.uid(),rh) returning * into a;
  return to_jsonb(a);
 end if;
 perform private.aqari_financial_open(w,(now() at time zone 'Asia/Kuwait')::date);
 if p_action='post' then
  select * into a from private.aqari_partner_source_approvals where workspace_id=w and id=(d->>'source_id')::uuid;
  if not found then raise insufficient_privilege using message='ACCESS_DENIED';end if;
  if a.review_hash is distinct from d->>'review_hash' or exists(select 1 from private.aqari_partner_source_approvals newer where newer.workspace_id=w and newer.property_id=a.property_id and newer.month=a.month and newer.review_revision>a.review_revision) then raise serialization_failure using message='PARTNER_REVIEW_STALE';end if;
  select * into src from private.aqari_partner_period_sources where workspace_id=w and property_id=a.property_id and month=a.month;
  if not found or not src.period_matches or src.source_hash<>a.source_hash then raise exception 'PARTNER_SOURCE_REVIEW_REQUIRED' using errcode='23514';end if;
  if jsonb_array_length(private.aqari_partner_commercial_evidence(w,src.source->'payments'))>0 then raise exception 'PARTNER_COMMERCIAL_ALLOCATION_REVIEW_REQUIRED' using errcode='23514';end if;
  s:=app->'propertySharesV267'->a.shares_key;
  if s->'owners' is distinct from a.owners or (s->>'version')::bigint is distinct from a.shares_version or s->>'enabled' is distinct from 'true' then raise serialization_failure using message='PARTNER_SHARES_CHANGED_AFTER_REVIEW';end if;
  for x in select value from jsonb_array_elements(a.owners) loop
   if a.recipients->(x->>'id')<>'null'::jsonb and not exists(select 1 from private.aqari_partner_access pa join auth.users u on u.id=pa.user_id and lower(u.email)=pa.email
    where pa.workspace_id=w and pa.property_id=a.property_id and pa.is_active and u.email_confirmed_at is not null and pa.user_id=(a.recipients->>(x->>'id'))::uuid
    and not exists(select 1 from public.aqari_memberships m where m.workspace_id=w and m.user_id=pa.user_id)) then raise exception 'PARTNER_RECIPIENT_ACCESS_REQUIRED' using errcode='23514';end if;
  end loop;
  perform 1 from public.aqari_documents doc join storage.objects o on o.bucket_id=doc.storage_bucket and o.name=doc.storage_path
   where doc.id=a.document_id and to_jsonb(doc)=a.document_snapshot and doc.status='uploaded' and (o.metadata->>'size')::bigint=doc.size_bytes and o.metadata->>'mimetype'=doc.mime_type for share of doc,o;
  if not found then raise exception 'PARTNER_DOCUMENT_UNVERIFIED' using errcode='23514';end if;
  if exists(select 1 from private.aqari_partner_distributions where workspace_id=w and property_id=a.property_id and month=a.month and kind='distribution') then raise exception 'PARTNER_PERIOD_ALREADY_DISTRIBUTED' using errcode='23514';end if;
  v:=private.aqari_partner_allocate(a.net_fils,a.owners,a.recipients);
  insert into private.aqari_partner_distributions(id,workspace_id,source_id,property_id,month,kind,occurred_on,net_fils,allocations,review_hash,reason,actor_id,request_hash)
  values(ident,w,a.id,a.property_id,a.month,'distribution',(now() at time zone 'Asia/Kuwait')::date,a.net_fils,v,a.review_hash,why,auth.uid(),rh) returning * into e;
 else
  select * into original from private.aqari_partner_distributions where workspace_id=w and id=(d->>'distribution_id')::uuid and kind='distribution';
  if not found then raise insufficient_privilege using message='ACCESS_DENIED';end if;
  if exists(select 1 from private.aqari_partner_distributions where reverses_id=original.id) then raise exception 'PARTNER_ALREADY_REVERSED' using errcode='23514';end if;
  select jsonb_agg(x||jsonb_build_object('amount_fils',(-(x->>'amount_fils')::bigint)::text) order by (x->>'owner_id')collate "C") into v from jsonb_array_elements(original.allocations)x;
  insert into private.aqari_partner_distributions(id,workspace_id,source_id,property_id,month,kind,reverses_id,occurred_on,net_fils,allocations,review_hash,reason,actor_id,request_hash)
   values(ident,w,original.source_id,original.property_id,original.month,'reversal',original.id,(now() at time zone 'Asia/Kuwait')::date,-original.net_fils,v,original.review_hash,why,auth.uid(),rh) returning * into e;
 end if;
 return to_jsonb(e);
end$function$

CREATE OR REPLACE FUNCTION private.aqari_partner_distribution_statement(p_property_id uuid, p_month date)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare w uuid;email_address text;result jsonb;begin
 if auth.uid() is null then raise insufficient_privilege using message='ACCESS_DENIED';end if;
 select lower(email) into email_address from auth.users where id=auth.uid() and email_confirmed_at is not null;
 select a.workspace_id into w from private.aqari_partner_access a where a.property_id=p_property_id and a.user_id=auth.uid() and a.email=email_address and a.is_active
 and not exists(select 1 from public.aqari_memberships m where m.workspace_id=a.workspace_id and m.user_id=auth.uid());
 if w is null then raise insufficient_privilege using message='ACCESS_DENIED';end if;
 if p_month is null or p_month<>date_trunc('month',p_month)::date or p_month not between date '2000-01-01' and date '2100-12-01' then raise exception 'INVALID_PARTNER_MONTH' using errcode='22023';end if;
 select coalesce(jsonb_agg(jsonb_build_object('id',e.id,'kind',e.kind,'reverses_id',e.reverses_id,'occurred_on',e.occurred_on,'recorded_at',e.recorded_at,'owner_id',x->>'owner_id','name',x->>'name','bps',x->'bps','amount_fils',x->>'amount_fils') order by e.recorded_at,e.id),'[]') into result
 from private.aqari_partner_distributions e cross join lateral jsonb_array_elements(e.allocations)x
 where e.workspace_id=w and e.property_id=p_property_id and e.month=p_month and x->>'recipient_user_id'=auth.uid()::text;
 return jsonb_build_object('user_id',auth.uid(),'workspace_id',w,'property_id',p_property_id,'month',p_month,'currency','KWD','entries',result,
 'balance_fils',(select coalesce(sum((x->>'amount_fils')::numeric),0)::text from jsonb_array_elements(result)x));
end$function$

CREATE OR REPLACE FUNCTION private.aqari_partner_legacy_distribution_guard()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare k text;before_state jsonb;after_state jsonb;x jsonb;n integer;
begin
 for k in select distinct a.shares_key from private.aqari_partner_source_approvals a where a.workspace_id=new.workspace_id loop
  before_state:=private.aqari_unwrap(old.payload)->'propertySharesV267'->k;
  after_state:=private.aqari_unwrap(new.payload)->'propertySharesV267'->k;
  if before_state is not distinct from after_state then continue;end if;
  n:=coalesce(jsonb_array_length(before_state->'events'),0);
  for x in select value from jsonb_array_elements(after_state->'events') with ordinality r(value,ord) where ord>n loop
   if x->>'type' in('distribution','payment') then raise exception 'PARTNER_SERVER_REGISTER_REQUIRED' using errcode='23514';end if;
  end loop;
 end loop;return new;
end$function$

CREATE OR REPLACE FUNCTION private.aqari_partner_summary(property uuid DEFAULT NULL::uuid, month_start date DEFAULT NULL::date)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare account auth.users%rowtype; result jsonb; p public.aqari_properties%rowtype; scope_id uuid;
begin
 if auth.uid() is null then raise exception 'ACCESS_DENIED' using errcode='42501';end if;
 select * into account from auth.users where id=auth.uid();
 if account.email_confirmed_at is null then raise exception 'ACCESS_DENIED' using errcode='42501';end if;
 if property is null then
  select coalesce(jsonb_agg(jsonb_build_object('id',x.id,'workspace_id',x.workspace_id,'name',x.name) order by x.name,x.id),'[]') into result
  from public.aqari_properties x where exists(select 1 from private.aqari_partner_access a where a.property_id=x.id and a.workspace_id=x.workspace_id and a.user_id=auth.uid() and a.email=lower(account.email) and a.is_active)
  and not exists(select 1 from public.aqari_memberships m where m.user_id=auth.uid() and m.workspace_id=x.workspace_id);
  return jsonb_build_object('user_id',auth.uid(),'properties',result);
 end if;
 select a.workspace_id into scope_id from private.aqari_partner_access a where a.property_id=property and a.user_id=auth.uid() and a.email=lower(account.email) and a.is_active
 and not exists(select 1 from public.aqari_memberships m where m.user_id=auth.uid() and m.workspace_id=a.workspace_id);
 if scope_id is null then raise exception 'ACCESS_DENIED' using errcode='42501';end if;
 if month_start is null or month_start<>date_trunc('month',month_start)::date or month_start not between date '2000-01-01' and date '2100-12-01' then raise exception 'INVALID_MONTH';end if;
 select * into strict p from public.aqari_properties where id=property and workspace_id=scope_id;
 return jsonb_build_object('user_id',auth.uid(),'workspace_id',scope_id,'property_id',p.id,'name',p.name,'month',month_start,
 'unit_count',(select count(*) from public.aqari_units u where u.workspace_id=scope_id and u.property_id=p.id),
 'draft_leases',(select count(*) from public.aqari_leases l join public.aqari_units u on u.id=l.unit_id and u.workspace_id=l.workspace_id where l.workspace_id=scope_id and u.property_id=p.id and l.status='draft'),
 'receipt_count',(select count(*) from public.aqari_rent_payments r join public.aqari_leases l on l.id=r.lease_id and l.workspace_id=r.workspace_id join public.aqari_units u on u.id=l.unit_id and u.workspace_id=l.workspace_id where r.workspace_id=scope_id and u.property_id=p.id and r.paid_at>=month_start and r.paid_at<(month_start+interval '1 month')::date),
 'recorded_receipts',(select coalesce(sum(r.amount),0) from public.aqari_rent_payments r join public.aqari_leases l on l.id=r.lease_id and l.workspace_id=r.workspace_id join public.aqari_units u on u.id=l.unit_id and u.workspace_id=l.workspace_id where r.workspace_id=scope_id and u.property_id=p.id and r.paid_at>=month_start and r.paid_at<(month_start+interval '1 month')::date));
end $function$

CREATE OR REPLACE FUNCTION private.aqari_payment_method_reference_guard()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare
 ref text:=new.record->>'transactionNo';
 provider text:=new.record->>'paymentProvider';
begin
 if new.payment_method is null or new.payment_method not in
  ('كي نت','KNET','knet','تحويل بنكي','bank','نقدي','cash','شيك','cheque','أخرى','other') then
  raise check_violation using message='اختر طريقة دفع صحيحة قبل إصدار الوصل.';
 end if;
 if jsonb_typeof(new.record->'transactionNo') is distinct from 'string'
  or length(btrim(ref)) not between 1 and 150 or length(ref)>150
  or ref !~ U&'[^\0020\00A0\1680\2000-\200A\2028\2029\202F\205F\3000]'
  or ref ~ '[[:cntrl:]]' or ref ~ U&'[\00AD\061C\180E\200B-\200F\2028-\202E\2060-\206F\FEFF]'
  or lower(btrim(ref)) in ('—','-','–','n/a','na','none','null','undefined','غير مسجل','لا يوجد') then
  raise check_violation using message='أدخل مرجع الحركة من 1 إلى 150 حرفاً، بما فيه سند القبض النقدي.';
 end if;
 if jsonb_typeof(new.record->'method') is distinct from 'string'
  or new.record->>'method' is distinct from new.payment_method
  or jsonb_typeof(new.receipt->'transactionNo') is distinct from 'string'
  or new.receipt->>'transactionNo' is distinct from ref
  or new.receipt#>>'{record,9}' is distinct from new.payment_method then
  raise check_violation using message='طريقة الدفع ومرجع الحركة لا يتطابقان مع الوصل المحفوظ.';
 end if;
 if new.payment_method in ('كي نت','KNET','knet') then
  if jsonb_typeof(new.record->'paymentProvider') is distinct from 'string'
   or provider is distinct from 'KNET' then
   raise check_violation using message='يجب حفظ مزود KNET باسم KNET.';
  end if;
 elsif new.payment_method in ('نقدي','cash') then
  if new.record ? 'paymentProvider' and coalesce(btrim(provider),'')<>'' then
   raise check_violation using message='الدفع النقدي لا يستخدم بنكاً أو مزود دفع.';
  end if;
 else
  if jsonb_typeof(new.record->'paymentProvider') is distinct from 'string'
   or length(btrim(provider)) not between 2 and 120 or length(provider)>120
   or provider !~ U&'[^\0020\00A0\1680\2000-\200A\2028\2029\202F\205F\3000]'
   or provider ~ '[[:cntrl:]]' or provider ~ U&'[\00AD\061C\180E\200B-\200F\2028-\202E\2060-\206F\FEFF]'
   or lower(btrim(provider)) in ('—','-','–','n/a','na','none','null','undefined','غير مسجل','لا يوجد') then
   raise check_violation using message='أدخل اسم البنك أو مزوّد الدفع من 2 إلى 120 حرفاً.';
  end if;
 end if;
 return new;
end $function$

CREATE OR REPLACE FUNCTION private.aqari_pdf_contract_bindings(w uuid, act text, d jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare p uuid; l public.aqari_leases;u public.aqari_units;prop public.aqari_properties;
 v private.aqari_pdf_template_versions;a private.aqari_pdf_template_approvals;
 doc public.aqari_documents;source public.aqari_documents;b private.aqari_pdf_contract_bindings;
 items jsonb;off int;q text;
begin
 if auth.uid() is null or jsonb_typeof(d) is distinct from 'object' then raise insufficient_privilege using message='ACCESS_DENIED';end if;
 p:=(d->>'property_id')::uuid;
 if p is null or not coalesce(private.aqari_can_property(w,p,'contracts','read'),false)
  or not coalesce(private.aqari_can_property(w,p,'documents','read'),false) then raise insufficient_privilege using message='ACCESS_DENIED';end if;
 select * into prop from public.aqari_properties where id=p and workspace_id=w;
 if prop.id is null then raise insufficient_privilege using message='ACCESS_DENIED';end if;
 if act='leases' then
  if not coalesce(private.aqari_manager(w),false) then raise insufficient_privilege using message='ACCESS_DENIED';end if;
  if d-array['property_id','offset','query']<>'{}' or coalesce(d->>'offset','0')!~'^[0-9]{1,5}$' or length(coalesce(d->>'query',''))>100 then raise exception 'INVALID_PDF_BINDING';end if;
  off:=coalesce(d->>'offset','0')::int;q:=btrim(coalesce(d->>'query',''));
  select coalesce(jsonb_agg(to_jsonb(x)),'[]') into items from(
   select lease.id,lease.external_ref,lease.contract_no,unit.unit_no,coalesce(lease.snapshot->>'tenant','') as tenant
   from public.aqari_leases lease join public.aqari_units unit on unit.id=lease.unit_id and unit.workspace_id=w and unit.property_id=p
   where lease.workspace_id=w and lease.status not in ('cancelled','void')
    and private.aqari_can_lease(w,lease.id,'contracts','read') and private.aqari_can_lease(w,lease.id,'documents','read')
    and (q='' or strpos(lower(concat_ws(' ',lease.contract_no,unit.unit_no,lease.snapshot->>'tenant')),lower(q))>0)
   order by lease.contract_no,lease.id limit 51 offset off)x;
  return jsonb_build_object('items',items,'has_more',jsonb_array_length(items)>50,'next_offset',off+50);
 end if;
 select * into l from public.aqari_leases where workspace_id=w and external_ref=d->>'contract_ref';
 select * into u from public.aqari_units where id=l.unit_id and workspace_id=w and property_id=p;
 if l.id is null or u.id is null or not coalesce(private.aqari_can_lease(w,l.id,'contracts','read'),false)
  or not coalesce(private.aqari_can_lease(w,l.id,'documents','read'),false) then raise insufficient_privilege using message='ACCESS_DENIED';end if;
 if act='list' then
  if d-array['property_id','contract_ref','offset']<>'{}' or coalesce(d->>'offset','0')!~'^[0-9]{1,5}$' then raise exception 'INVALID_PDF_BINDING';end if;
  off:=coalesce(d->>'offset','0')::int;
  select coalesce(jsonb_agg(to_jsonb(x)),'[]') into items from(
   select link.* from private.aqari_pdf_contract_bindings link where workspace_id=w and property_id=p and lease_id=l.id
   order by created_at desc,artifact_document_id limit 21 offset off)x;
  return jsonb_build_object('items',items,'has_more',jsonb_array_length(items)>20,'next_offset',off+20);
 elsif act<>'bind' then raise exception 'INVALID_PDF_BINDING';end if;
 if d-array['property_id','contract_ref','artifact_document_id','template_document_id','template_revision','confirmed']<>'{}'
  or d->'confirmed' is distinct from 'true'::jsonb or coalesce(d->>'template_revision','')!~'^[1-9][0-9]{0,8}$' then raise exception 'INVALID_PDF_BINDING';end if;
 if not coalesce(private.aqari_manager(w),false) or not coalesce(private.aqari_can_lease(w,l.id,'contracts','write'),false)
  or not coalesce(private.aqari_can_lease(w,l.id,'documents','write'),false) then raise insufficient_privilege using message='ACCESS_DENIED';end if;
 -- Serialize retries using the artifact identity; a PDF cannot be reassigned.
 perform pg_advisory_xact_lock(hashtextextended('pdf-binding:'||(d->>'artifact_document_id'),0));
 select * into b from private.aqari_pdf_contract_bindings where artifact_document_id=(d->>'artifact_document_id')::uuid;
 if b.artifact_document_id is not null then
  if b.workspace_id<>w or b.property_id<>p or b.lease_id<>l.id or b.template_document_id<>(d->>'template_document_id')::uuid or b.template_revision<>(d->>'template_revision')::int
   or b.created_by<>auth.uid() then raise exception 'PDF_BINDING_CONFLICT';end if;
  return to_jsonb(b);
 end if;
 if l.status in ('cancelled','void') then raise exception 'INVALID_PDF_BINDING';end if;
 select * into v from private.aqari_pdf_template_versions where document_id=(d->>'template_document_id')::uuid and workspace_id=w and property_id=p and revision=(d->>'template_revision')::int;
 select * into a from private.aqari_pdf_template_approvals where document_id=v.document_id and workspace_id=w and property_id=p for share;
 select * into source from public.aqari_documents where id=v.document_id and workspace_id=w for share;
 select * into doc from public.aqari_documents where id=(d->>'artifact_document_id')::uuid and workspace_id=w for share;
 if v.document_id is null or a.is_active is distinct from true or source.checksum_sha256 is distinct from a.checksum_sha256
  or source.status<>'uploaded' or doc.id is null or doc.id=source.id or doc.status<>'uploaded' or doc.mime_type<>'application/pdf'
  or doc.document_type<>'property_document' or doc.entity_type<>'property' or doc.entity_ref<>prop.external_ref or doc.created_by<>auth.uid()
  or doc.checksum_sha256!~'^[a-f0-9]{64}$' or doc.size_bytes not between 1 and 4194304
  or doc.metadata->'pdf_field_template'='true'::jsonb
  or not coalesce(doc.metadata @> jsonb_build_object('property_id',p::text,'asset_role','property_contract','category','property_other','pdf_source_document_id',v.document_id::text,'pdf_source_revision',v.revision),false)
  then raise insufficient_privilege using message='ACCESS_DENIED';end if;
 insert into private.aqari_pdf_contract_bindings(artifact_document_id,workspace_id,property_id,lease_id,template_document_id,template_revision,template_checksum,artifact_checksum,contract_snapshot,created_by)
 values(doc.id,w,p,l.id,v.document_id,v.revision,source.checksum_sha256,doc.checksum_sha256,
  jsonb_build_object('contract_ref',l.external_ref,'contract_no',l.contract_no,'tenant_id',l.tenant_id,'unit_id',u.id,'unit_no',u.unit_no,'lease_status',l.status),auth.uid()) returning * into b;
 return to_jsonb(b);
end$function$

CREATE OR REPLACE FUNCTION private.aqari_pdf_editor_drafts(p_workspace_id uuid, p_action text, p_data jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare actor uuid:=auth.uid(); prop uuid; doc uuid; draft uuid; req uuid; expected bigint; saved private.aqari_pdf_editor_drafts;
 snap jsonb; m jsonb; f jsonb; k text; val jsonb; ids text[]:='{}'; offset_n int; items jsonb; manager boolean:=coalesce(private.aqari_manager(p_workspace_id),false);
begin
 if actor is null or not coalesce(private.aqari_can(p_workspace_id,'contracts','read'),false)
  then raise exception 'ACCESS_DENIED' using errcode='42501';end if;
 if p_data is null or jsonb_typeof(p_data)<>'object' or octet_length(p_data::text)>355000 then raise exception 'INVALID_PDF_DRAFT';end if;
 prop:=(p_data->>'property_id')::uuid;
 if prop is null or not exists(select 1 from public.aqari_properties p where p.workspace_id=p_workspace_id and p.id=prop) then raise exception 'ACCESS_DENIED' using errcode='42501';end if;
 if not manager and not coalesce(private.aqari_pdf_fill_allowed(p_workspace_id,prop),false) then raise insufficient_privilege using message='ACCESS_DENIED';end if;
 if p_action='list' then
  if p_data-array['property_id','offset']<>'{}' or coalesce(p_data->>'offset','0')!~'^[0-9]{1,5}$' then raise exception 'INVALID_PDF_DRAFT';end if;
  offset_n:=coalesce(p_data->>'offset','0')::int;
  select coalesce(jsonb_agg(to_jsonb(q)),'[]') into items from (
   select d.id,d.document_id,d.revision,d.updated_at,coalesce(nullif(d.snapshot#>>'{mapping,title}',''),'مسودة دون اسم') as title
   from private.aqari_pdf_editor_drafts d where d.workspace_id=p_workspace_id and d.property_id=prop and d.created_by=actor and (manager or private.aqari_pdf_template_active(p_workspace_id,prop,d.document_id))
   order by d.updated_at desc,d.id limit 20 offset offset_n
  ) q;
  return jsonb_build_object('items',items,'next_offset',offset_n+20,'has_more',exists(select 1 from private.aqari_pdf_editor_drafts d where d.workspace_id=p_workspace_id and d.property_id=prop and d.created_by=actor and (manager or private.aqari_pdf_template_active(p_workspace_id,prop,d.document_id)) offset offset_n+20 limit 1));
 end if;
 draft:=(p_data->>'id')::uuid;
 if draft is null then raise exception 'INVALID_PDF_DRAFT';end if;
 if p_action='save' then
  if not coalesce(private.aqari_can(p_workspace_id,'contracts','write'),false) then raise exception 'ACCESS_DENIED' using errcode='42501';end if;
  if p_data-array['property_id','id','document_id','expected_revision','request_id','snapshot']<>'{}'
   or coalesce(p_data->>'expected_revision','')!~'^[0-9]{1,12}$' then raise exception 'INVALID_PDF_DRAFT';end if;
  req:=(p_data->>'request_id')::uuid;doc:=(p_data->>'document_id')::uuid;expected:=(p_data->>'expected_revision')::bigint;snap:=p_data->'snapshot';m:=snap->'mapping';
  if req is null or doc is null or snap is null or jsonb_typeof(snap)<>'object' or snap-array['mapping','values','page','selected']<>'{}'
   or octet_length(snap::text)>350000 or jsonb_typeof(m) is distinct from 'object'
   or m-array['version','title','propertyId','fields']<>'{}' or m->'version' is distinct from '1'::jsonb or m->>'propertyId' is distinct from prop::text
   or jsonb_typeof(m->'title') is distinct from 'string' or length(m->>'title')>160
   or jsonb_typeof(m->'fields') is distinct from 'array' or jsonb_array_length(m->'fields')>100
   or jsonb_typeof(snap->'page') is distinct from 'number' or jsonb_typeof(snap->'values') is distinct from 'object' or coalesce(snap->>'page','')!~'^([1-9]|[12][0-9]|30)$'
   then raise exception 'INVALID_PDF_DRAFT';end if;
  for f in select value from jsonb_array_elements(m->'fields') loop
   if jsonb_typeof(f)<>'object' or f-array['id','label','type','page','x','y','width','height','fontSize','align','color','dataKey','locked','required','options']<>'{}'
    or coalesce(f->>'id','')!~'^[A-Za-z0-9_-]{1,80}$' or f->>'id'=any(ids)
    or jsonb_typeof(f->'label') is distinct from 'string' or length(f->>'label')>100
    or coalesce(f->>'type','') not in ('text','date','number','money','civil_id','select') or coalesce(f->>'align','') not in ('left','right','center')
    or jsonb_typeof(f->'page') is distinct from 'number' or coalesce(f->>'page','')!~'^([1-9]|[12][0-9]|30)$'
    or (f ? 'color' and coalesce(f->>'color','')!~'^#[0-9A-Fa-f]{6}$') then raise exception 'INVALID_PDF_DRAFT';end if;
   if f ? 'dataKey' and (jsonb_typeof(f->'dataKey') is distinct from 'string' or coalesce(f->>'dataKey','')!~'^[A-Za-z0-9_-]{1,64}$') then raise exception 'INVALID_PDF_DRAFT';end if;
   if f ? 'locked' and jsonb_typeof(f->'locked') is distinct from 'boolean' then raise exception 'INVALID_PDF_DRAFT';end if;
   if f ? 'required' and jsonb_typeof(f->'required') is distinct from 'boolean' then raise exception 'INVALID_PDF_DRAFT';end if;
   if f->>'type'='select' then
    if jsonb_typeof(f->'options') is distinct from 'array' then raise exception 'INVALID_PDF_DRAFT';end if;
    if jsonb_array_length(f->'options') not between 1 and 50 then raise exception 'INVALID_PDF_DRAFT';end if;
    if exists(select 1 from jsonb_array_elements(f->'options') opt where jsonb_typeof(opt) is distinct from 'string'
     or length(opt#>>'{}') not between 1 and 100 or (opt#>>'{}')<>btrim(opt#>>'{}') or (opt#>>'{}')~'[[:cntrl:]]')
     or (select count(distinct opt) from jsonb_array_elements(f->'options') opt)<>jsonb_array_length(f->'options') then raise exception 'INVALID_PDF_DRAFT';end if;
   elsif f ? 'options' then raise exception 'INVALID_PDF_DRAFT';end if;
   ids:=array_append(ids,f->>'id');
   foreach k in array array['x','y','width','height','fontSize'] loop
    if jsonb_typeof(f->k) is distinct from 'number' then raise exception 'INVALID_PDF_DRAFT';end if;
   end loop;
   if (f->>'x')::numeric<0 or (f->>'y')::numeric<0 or (f->>'width')::numeric<=0 or (f->>'height')::numeric<=0
    or (f->>'x')::numeric+(f->>'width')::numeric>1.000001 or (f->>'y')::numeric+(f->>'height')::numeric>1.000001
    or (f->>'fontSize')::numeric not between 6 and 48 then raise exception 'INVALID_PDF_DRAFT';end if;
  end loop;
  for k,val in select * from jsonb_each(snap->'values') loop
   if not k=any(ids) or jsonb_typeof(val)<>'string' or length(val#>>'{}')>1000 then raise exception 'INVALID_PDF_DRAFT';end if;
  end loop;
  if exists(select 1 from jsonb_array_elements(m->'fields') a cross join jsonb_array_elements(m->'fields') b
    where a->>'dataKey'=b->>'dataKey' and (a->>'type' is distinct from b->>'type' or a->'options' is distinct from b->'options'
      or coalesce(snap->'values'->>(a->>'id'),'') is distinct from coalesce(snap->'values'->>(b->>'id'),''))) then raise exception 'INVALID_PDF_DRAFT';end if;
  if snap->>'selected' is not null and (jsonb_typeof(snap->'selected')<>'string' or not (snap->>'selected')=any(ids)) then raise exception 'INVALID_PDF_DRAFT';end if;
  -- Same draft serializes creation, CAS updates and lost-response retries.
  perform pg_advisory_xact_lock(hashtextextended('aqari-pdf-draft:'||draft::text,0));
 elsif p_action='get' then
  if p_data-array['property_id','id']<>'{}' then raise exception 'INVALID_PDF_DRAFT';end if;
 else raise exception 'INVALID_PDF_DRAFT';end if;
 select * into saved from private.aqari_pdf_editor_drafts d where d.id=draft;
 if found and (saved.workspace_id<>p_workspace_id or saved.property_id<>prop or saved.created_by<>actor) then raise exception 'ACCESS_DENIED' using errcode='42501';end if;
 if p_action='get' then
  if saved.id is null then raise exception 'PDF_DRAFT_NOT_FOUND';end if;
  doc:=saved.document_id;
 end if;
 if not exists(select 1 from public.aqari_documents d join public.aqari_properties p on p.id=prop and p.workspace_id=p_workspace_id
  where d.id=doc and d.workspace_id=p_workspace_id and d.status='uploaded' and d.mime_type='application/pdf'
   and d.entity_type='property' and d.entity_ref=p.external_ref and d.document_type='property_document'
   and d.metadata->>'category'='property_other' and d.metadata->>'asset_role'='property_contract' and d.metadata->>'property_id'=prop::text
 ) then raise exception 'ACCESS_DENIED' using errcode='42501';end if;
 if not manager then
  if not private.aqari_pdf_template_active(p_workspace_id,prop,doc) then raise insufficient_privilege using message='ACCESS_DENIED';end if;
  if (case when p_action='save' then snap else saved.snapshot end)->'mapping' is distinct from (select a.mapping from private.aqari_pdf_template_approvals a where a.document_id=doc and a.workspace_id=p_workspace_id and a.property_id=prop) then raise insufficient_privilege using message='PDF_TEMPLATE_IMMUTABLE';end if;
 end if;
 if p_action='save' then
  if saved.id is not null and saved.last_request=req then
   if saved.document_id<>doc or saved.snapshot<>snap or saved.revision<>expected+1 then raise exception 'PDF_DRAFT_RETRY_CONFLICT';end if;
  else
   if coalesce(saved.revision,0)<>expected then raise exception 'PDF_DRAFT_REVISION_CONFLICT' using errcode='40001';end if;
   if saved.id is null then
    insert into private.aqari_pdf_editor_drafts(id,workspace_id,property_id,document_id,created_by,revision,snapshot,last_request)
     values(draft,p_workspace_id,prop,doc,actor,1,snap,req) returning * into saved;
   else
    update private.aqari_pdf_editor_drafts set document_id=doc,revision=revision+1,snapshot=snap,last_request=req,updated_at=now() where id=draft returning * into saved;
   end if;
  end if;
 end if;
 return to_jsonb(saved);
end $function$

CREATE OR REPLACE FUNCTION private.aqari_pdf_templates_v400(w uuid, act text, data jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare actor uuid:=auth.uid();p uuid;doc uuid;ident uuid;manager boolean;row private.aqari_pdf_template_approvals;
 request_row private.aqari_pdf_template_requests;mapping jsonb;hash text;note text;off int;items jsonb;
begin
 if actor is null or data is null or jsonb_typeof(data)<>'object' or octet_length(data::text)>355000 then raise insufficient_privilege using message='ACCESS_DENIED';end if;
 p:=(data->>'property_id')::uuid;doc:=(data->>'document_id')::uuid;
 manager:=coalesce(private.aqari_manager(w),false) and coalesce(private.aqari_can(w,'contracts','write'),false);
 if not coalesce(private.aqari_pdf_fill_allowed(w,p),false) then raise insufficient_privilege using message='ACCESS_DENIED';end if;
 if act='context' then
  if data-array['property_id','document_id']<>'{}' then raise exception 'INVALID_PDF_TEMPLATE_REQUEST';end if;
  select * into row from private.aqari_pdf_template_approvals a where a.workspace_id=w and a.property_id=p and a.document_id=doc;
  if doc is not null and not manager and not private.aqari_pdf_template_active(w,p,doc) then raise insufficient_privilege using message='ACCESS_DENIED';end if;
  return jsonb_build_object('workspace_id',w,'user_id',actor,'can_publish',manager,'can_fill',true,'mapping',case when row.is_active then row.mapping end,'approved',coalesce(row.is_active,false));
 elsif act in('list','requests') then
  if data-array['property_id','offset']<>'{}' or coalesce(data->>'offset','0')!~'^[0-9]{1,5}$' then raise exception 'INVALID_PDF_TEMPLATE_REQUEST';end if;
  off:=coalesce(data->>'offset','0')::int;
  if act='list' then
   select coalesce(jsonb_agg(to_jsonb(q)),'[]') into items from(select a.document_id,a.mapping->>'title' as title,a.approved_at,a.is_active
    from private.aqari_pdf_template_approvals a where a.workspace_id=w and a.property_id=p and (manager or private.aqari_pdf_template_active(w,p,a.document_id))
    order by a.approved_at desc,a.document_id limit 21 offset off)q;
  else
   select coalesce(jsonb_agg(to_jsonb(q)),'[]') into items from(select r.id,r.document_id,r.reason,r.requested_at,r.response,r.responded_at
    from private.aqari_pdf_template_requests r where r.workspace_id=w and r.property_id=p and (manager or r.requested_by=actor)
    order by r.requested_at desc,r.id limit 21 offset off)q;
  end if;
  return jsonb_build_object('items',items,'next_offset',off+20,'has_more',jsonb_array_length(items)>20);
 elsif act='publish' then
  if not manager or not private.aqari_can(w,'documents','write') then raise insufficient_privilege using message='ACCESS_DENIED';end if;
  if data-array['property_id','document_id','mapping']<>'{}' then raise exception 'INVALID_PDF_TEMPLATE_REQUEST';end if;
  mapping:=data->'mapping';
  if jsonb_typeof(mapping) is distinct from 'object' or mapping->>'propertyId' is distinct from p::text or mapping->'version' is distinct from '1'::jsonb
   or jsonb_typeof(mapping->'fields') is distinct from 'array' or jsonb_array_length(mapping->'fields') not between 1 and 100
   or length(btrim(coalesce(mapping->>'title',''))) not between 1 and 160 then raise exception 'INVALID_PDF_TEMPLATE_REQUEST';end if;
  select d.checksum_sha256 into hash from public.aqari_documents d join public.aqari_properties prop on prop.id=p and prop.workspace_id=w
   where d.id=doc and d.workspace_id=w and d.status='uploaded' and d.mime_type='application/pdf' and d.entity_type='property' and d.entity_ref=prop.external_ref
   and d.document_type='property_document' and d.checksum_sha256 ~ '^[a-f0-9]{64}$'
   and d.metadata @> jsonb_build_object('category','property_other','asset_role','property_contract','property_id',p::text,'pdf_field_template',true);
  if hash is null then raise insufficient_privilege using message='ACCESS_DENIED';end if;
  perform pg_advisory_xact_lock(hashtextextended('pdf-template:'||doc::text,0));
  select * into row from private.aqari_pdf_template_approvals a where a.document_id=doc;
  if row.document_id is not null and (row.workspace_id<>w or row.property_id<>p or row.mapping<>mapping or row.checksum_sha256<>hash) then raise exception 'PDF_TEMPLATE_IMMUTABLE';end if;
  if row.document_id is null then
   insert into private.aqari_pdf_template_approvals(document_id,workspace_id,property_id,checksum_sha256,mapping,approved_by) values(doc,w,p,hash,mapping,actor);
  elsif row.is_active then return jsonb_build_object('approved',true,'document_id',doc);
  else update private.aqari_pdf_template_approvals set is_active=true where document_id=doc;end if;
  insert into private.aqari_pdf_template_events(workspace_id,document_id,actor_id,action) values(w,doc,actor,'publish');
  return jsonb_build_object('approved',true,'document_id',doc);
 elsif act='revoke' then
  if not manager then raise insufficient_privilege using message='ACCESS_DENIED';end if;
  if data-array['property_id','document_id']<>'{}' then raise exception 'INVALID_PDF_TEMPLATE_REQUEST';end if;
  update private.aqari_pdf_template_approvals set is_active=false where workspace_id=w and property_id=p and document_id=doc and is_active;
  if found then insert into private.aqari_pdf_template_events(workspace_id,document_id,actor_id,action) values(w,doc,actor,'revoke');end if;
  return jsonb_build_object('approved',false,'document_id',doc);
 elsif act='request' then
  if data-array['property_id','document_id','id','reason']<>'{}' or not private.aqari_pdf_template_active(w,p,doc) then raise insufficient_privilege using message='ACCESS_DENIED';end if;
  ident:=(data->>'id')::uuid;note:=btrim(data->>'reason');
  if ident is null or note is null or length(note) not between 3 and 1000 then raise exception 'INVALID_PDF_TEMPLATE_REQUEST';end if;
  perform pg_advisory_xact_lock(hashtextextended('pdf-change:'||ident::text,0));
  select * into request_row from private.aqari_pdf_template_requests where id=ident;
  if request_row.id is not null then
   if request_row.workspace_id<>w or request_row.property_id<>p or request_row.document_id<>doc or request_row.requested_by<>actor or request_row.reason<>note then raise exception 'PDF_TEMPLATE_RETRY_CONFLICT';end if;
  else insert into private.aqari_pdf_template_requests(id,workspace_id,property_id,document_id,requested_by,reason) values(ident,w,p,doc,actor,note);end if;
  return jsonb_build_object('id',ident,'saved',true);
 elsif act='respond' then
  if not manager then raise insufficient_privilege using message='ACCESS_DENIED';end if;
  if data-array['property_id','id','response']<>'{}' then raise exception 'INVALID_PDF_TEMPLATE_REQUEST';end if;
  ident:=(data->>'id')::uuid;note:=btrim(data->>'response');
  if ident is null or note is null or length(note) not between 3 and 1000 then raise exception 'INVALID_PDF_TEMPLATE_REQUEST';end if;
  select * into request_row from private.aqari_pdf_template_requests where id=ident and workspace_id=w and property_id=p for update;
  if request_row.id is null then raise insufficient_privilege using message='ACCESS_DENIED';end if;
  if request_row.response is not null and request_row.response<>note then raise exception 'PDF_TEMPLATE_RESPONSE_EXISTS';end if;
  update private.aqari_pdf_template_requests set response=note,responded_by=actor,responded_at=now() where id=ident and response is null;
  return jsonb_build_object('saved',true,'id',ident);
 end if;
 raise exception 'INVALID_PDF_TEMPLATE_REQUEST';
end $function$

CREATE OR REPLACE FUNCTION private.aqari_pdf_templates(w uuid, act text, data jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare ctx jsonb;p uuid;doc uuid;origin jsonb;parent uuid;family uuid;expected int;next_revision int;off int;
 result jsonb;items jsonb;v private.aqari_pdf_template_versions;head private.aqari_pdf_template_versions;
begin
 -- Always establish the live membership and property permissions first.
 ctx:=private.aqari_pdf_templates_v400(w,'context',jsonb_build_object('property_id',data->>'property_id','document_id',data->>'document_id'));
 p:=(data->>'property_id')::uuid;doc:=(data->>'document_id')::uuid;
 if act='context' then
  result:=private.aqari_pdf_templates_v400(w,act,data);
  select * into v from private.aqari_pdf_template_versions where document_id=doc and workspace_id=w and property_id=p;
  if v.document_id is not null then
   select * into head from private.aqari_pdf_template_versions where family_id=v.family_id order by revision desc limit 1;
   result:=result||jsonb_build_object('template_version',jsonb_build_object('document_id',v.document_id,'revision',v.revision,'is_latest',head.document_id=v.document_id));
  end if;
  return result;
 elsif act='history' then
  if (ctx->>'can_publish')::boolean is distinct from true then raise insufficient_privilege using message='ACCESS_DENIED';end if;
  if data-array['property_id','document_id','offset']<>'{}' or coalesce(data->>'offset','0')!~'^[0-9]{1,5}$' then raise exception 'INVALID_PDF_TEMPLATE_REQUEST';end if;
  off:=coalesce(data->>'offset','0')::int;
  select * into v from private.aqari_pdf_template_versions where document_id=doc and workspace_id=w and property_id=p;
  select coalesce(jsonb_agg(to_jsonb(q)),'[]') into items from(
   select h.document_id,h.revision,h.created_at,a.mapping->>'title' as title,a.is_active,h.base_document_id,h.copied_from_document_id,
    not exists(select 1 from private.aqari_pdf_template_versions n where n.family_id=h.family_id and n.revision>h.revision) as is_latest
   from private.aqari_pdf_template_versions h join private.aqari_pdf_template_approvals a using(document_id)
   where h.family_id=v.family_id and h.workspace_id=w and h.property_id=p order by h.revision desc limit 21 offset off)q;
  return jsonb_build_object('items',items,'next_offset',off+20,'has_more',jsonb_array_length(items)>20);
 elsif act='list' then
  if data-array['property_id','offset']<>'{}' or coalesce(data->>'offset','0')!~'^[0-9]{1,5}$' then raise exception 'INVALID_PDF_TEMPLATE_REQUEST';end if;
  off:=coalesce(data->>'offset','0')::int;
  select coalesce(jsonb_agg(to_jsonb(q)),'[]') into items from(
   select a.document_id,a.mapping->>'title' as title,a.approved_at,a.is_active,ver.revision
   from private.aqari_pdf_template_approvals a join private.aqari_pdf_template_versions ver using(document_id)
   where a.workspace_id=w and a.property_id=p
    and ((ctx->>'can_publish')::boolean or private.aqari_pdf_template_active(w,p,a.document_id))
    and not exists(select 1 from private.aqari_pdf_template_versions n where n.family_id=ver.family_id and n.revision>ver.revision)
   order by a.approved_at desc,a.document_id limit 21 offset off)q;
  return jsonb_build_object('items',items,'next_offset',off+20,'has_more',jsonb_array_length(items)>20);
 elsif act='publish' then
  if (ctx->>'can_publish')::boolean is distinct from true or not coalesce(private.aqari_can(w,'documents','write'),false) then raise insufficient_privilege using message='ACCESS_DENIED';end if;
  if data-array['property_id','document_id','mapping','origin']<>'{}' or doc is null then raise exception 'INVALID_PDF_TEMPLATE_REQUEST';end if;
  origin:=coalesce(nullif(data->'origin','null'::jsonb),'{}');
  if jsonb_typeof(origin)<>'object' then raise exception 'INVALID_PDF_TEMPLATE_ORIGIN';end if;
  perform pg_advisory_xact_lock(hashtextextended('pdf-template:'||doc::text,0));
  select * into v from private.aqari_pdf_template_versions where document_id=doc;
  if v.document_id is not null then
   -- Lost response retries reactivate only the same immutable document; no new revision.
   result:=private.aqari_pdf_templates_v400(w,act,data-'origin');
   return result||jsonb_build_object('revision',v.revision);
  end if;
  family:=doc;next_revision:=1;
  if origin->>'kind'='revision' then
   if origin-array['kind','document_id','revision']<>'{}' or coalesce(origin->>'revision','')!~'^[1-9][0-9]{0,8}$' then raise exception 'INVALID_PDF_TEMPLATE_ORIGIN';end if;
   parent:=(origin->>'document_id')::uuid;expected:=(origin->>'revision')::int;
   select * into v from private.aqari_pdf_template_versions where document_id=parent and workspace_id=w and property_id=p and revision=expected;
   if v.document_id is null then raise insufficient_privilege using message='ACCESS_DENIED';end if;
   family:=v.family_id;
   perform pg_advisory_xact_lock(hashtextextended('pdf-family:'||family::text,0));
   select * into head from private.aqari_pdf_template_versions where family_id=family order by revision desc limit 1;
   if head.document_id<>parent or head.revision<>expected then raise exception 'PDF_TEMPLATE_REVISION_CONFLICT' using errcode='40001';end if;
   next_revision:=expected+1;
  elsif origin->>'kind'='copy' then
   if origin-array['kind','document_id','property_id']<>'{}' then raise exception 'INVALID_PDF_TEMPLATE_ORIGIN';end if;
   parent:=(origin->>'document_id')::uuid;
   if parent is null or (origin->>'property_id')::uuid=p or not coalesce(private.aqari_pdf_fill_allowed(w,(origin->>'property_id')::uuid),false)
    or not exists(select 1 from public.aqari_documents d join public.aqari_properties prop on prop.id=(origin->>'property_id')::uuid and prop.workspace_id=w
     where d.id=parent and d.workspace_id=w and d.status='uploaded' and d.entity_type='property' and d.entity_ref=prop.external_ref and d.mime_type='application/pdf'
      and d.metadata @> jsonb_build_object('property_id',prop.id::text,'pdf_field_template',true,'asset_role','property_contract')) then raise insufficient_privilege using message='ACCESS_DENIED';end if;
  elsif origin<>'{}' then raise exception 'INVALID_PDF_TEMPLATE_ORIGIN';end if;
  result:=private.aqari_pdf_templates_v400(w,act,data-'origin');
  insert into private.aqari_pdf_template_versions(document_id,workspace_id,property_id,family_id,revision,base_document_id,copied_from_document_id,created_by)
   values(doc,w,p,family,next_revision,case when origin->>'kind'='revision' then parent end,case when origin->>'kind'='copy' then parent end,auth.uid());
  return result||jsonb_build_object('revision',next_revision);
 end if;
 return private.aqari_pdf_templates_v400(w,act,data);
end$function$

CREATE OR REPLACE FUNCTION private.aqari_prepare_operational_alerts(w uuid, as_of_date date)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare m_count integer:=0;l_count integer:=0;v_count integer:=0;affected integer:=0;manager_id uuid;key text;row_data record;days_left integer;
begin
 if auth.uid() is null or not private.aqari_manager(w) then raise insufficient_privilege using message='ACCESS_DENIED';end if;
 perform private.aqari_require_sensitive_aal2(w);
 if as_of_date is null or as_of_date>(now() at time zone 'Asia/Kuwait')::date+1 then raise exception 'INVALID_ALERT_DATE' using errcode='22023';end if;
 select m.user_id into manager_id from public.aqari_memberships m where m.workspace_id=w and m.is_active and m.role::text in('owner','general_manager') order by case when m.user_id=auth.uid() then 0 else 1 end limit 1;
 if manager_id is null then raise exception 'ALERT_MANAGER_REQUIRED' using errcode='23514';end if;

 for row_data in select p.id,p.title,p.next_due_on,p.warning_days from private.aqari_maintenance_plans p where p.workspace_id=w and p.is_active loop
  days_left:=row_data.next_due_on-as_of_date;
  if days_left=0 or days_left=any(row_data.warning_days) then
   key:='maintenance:'||row_data.id||':'||row_data.next_due_on||':'||days_left;
   insert into private.aqari_notification_deliveries(id,workspace_id,kind,aggregate_id,recipient_id,channel,scheduled_for,idempotency_key)
    values(private.aqari_alert_uuid(key),w,'maintenance_due',row_data.id::text,manager_id,'push',(as_of_date::timestamp at time zone 'Asia/Kuwait'),key)
    on conflict(workspace_id,idempotency_key) do nothing;
   get diagnostics affected=row_count;m_count:=m_count+affected;
  end if;
 end loop;

 for row_data in
  select l.id,l.end_date from public.aqari_leases l where l.workspace_id=w and l.status='signed'
 loop
  days_left:=row_data.end_date-as_of_date;
  if days_left in (90,60,30) then
   key:='lease-expiry:'||row_data.id||':'||row_data.end_date||':'||days_left;
   insert into private.aqari_notification_deliveries(id,workspace_id,kind,aggregate_id,recipient_id,channel,scheduled_for,idempotency_key)
    values(private.aqari_alert_uuid(key),w,'lease_expiry',row_data.id::text,manager_id,'email',(as_of_date::timestamp at time zone 'Asia/Kuwait'),key)
    on conflict(workspace_id,idempotency_key) do nothing;
   get diagnostics affected=row_count;l_count:=l_count+affected;
  end if;
 end loop;

 for row_data in
  select c.id,c.ends_on from private.aqari_vendor_contracts c where c.workspace_id=w and c.status in('approved','active')
 loop
  days_left:=row_data.ends_on-as_of_date;
  if days_left in (90,60,30) then
   key:='vendor-contract-expiry:'||row_data.id||':'||row_data.ends_on||':'||days_left;
   insert into private.aqari_notification_deliveries(id,workspace_id,kind,aggregate_id,recipient_id,channel,scheduled_for,idempotency_key)
    values(private.aqari_alert_uuid(key),w,'vendor_contract_expiry',row_data.id::text,manager_id,'email',(as_of_date::timestamp at time zone 'Asia/Kuwait'),key)
    on conflict(workspace_id,idempotency_key) do nothing;
   get diagnostics affected=row_count;v_count:=v_count+affected;
  end if;
 end loop;

 insert into private.aqari_alert_preparation_runs(id,workspace_id,as_of,prepared_by,maintenance_count,lease_count,vendor_contract_count)
 values(private.aqari_alert_uuid('alert-run:'||w||':'||as_of_date),w,as_of_date,auth.uid(),m_count,l_count,v_count)
 on conflict(workspace_id,as_of) do nothing;
 return jsonb_build_object('as_of',as_of_date,'maintenance',m_count,'leases',l_count,'vendor_contracts',v_count);
end $function$

CREATE OR REPLACE FUNCTION private.aqari_prepare_state_write()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
begin
  new.updated_at := pg_catalog.now();
  new.updated_by := auth.uid();

  if tg_op = 'UPDATE' then
    new.revision := old.revision + 1;
  else
    new.revision := 1;
  end if;

  return new;
end;
$function$

CREATE OR REPLACE FUNCTION private.aqari_property_template_scope_guard()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare prop uuid;ptype text;tid uuid;contract_kind text;scoped boolean;
begin
 if tg_op='UPDATE' and new.unit_id=old.unit_id and coalesce(new.snapshot#>>'{contractTemplate,id}','')=coalesce(old.snapshot#>>'{contractTemplate,id}','') and coalesce(new.snapshot->>'contractKind','')=coalesce(old.snapshot->>'contractKind','') then return new;end if;
 select u.property_id into prop from public.aqari_units u where u.workspace_id=new.workspace_id and u.id=new.unit_id;
 if prop is null then return new;end if;
 select coalesce(m.property_type,'') into ptype from private.aqari_property_master m where m.workspace_id=new.workspace_id and m.property_id=prop;
 ptype:=coalesce(ptype,'');contract_kind:=coalesce(nullif(new.snapshot->>'contractKind',''),nullif(new.snapshot#>>'{contractTemplate,kind}',''));
 if contract_kind is null then return new;end if;
 select exists(select 1 from private.aqari_property_template_scopes s where s.workspace_id=new.workspace_id and s.kind=contract_kind and s.is_active and ((s.scope_kind='property' and s.property_id=prop) or (s.scope_kind='property_type' and lower(s.property_type)=lower(ptype)))) into scoped;
 if not scoped then return new;end if;
 tid:=nullif(new.snapshot#>>'{contractTemplate,id}','')::uuid;
 if tid is null or not exists(select 1 from private.aqari_property_template_scopes s where s.workspace_id=new.workspace_id and s.template_id=tid and s.kind=contract_kind and s.is_active and ((s.scope_kind='property' and s.property_id=prop) or (s.scope_kind='property_type' and lower(s.property_type)=lower(ptype)))) then raise check_violation using message='CONTRACT_TEMPLATE_NOT_ALLOWED_FOR_PROPERTY';end if;
 return new;
end $function$

CREATE OR REPLACE FUNCTION private.aqari_read_state_v267_unscoped(p_workspace_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare row_data public.aqari_app_state%rowtype;d jsonb;filtered jsonb;source_properties jsonb;
begin
 if not private.aqari_staff(p_workspace_id) then raise exception 'ACCESS_DENIED' using errcode='42501';end if;
 select * into row_data from public.aqari_app_state where workspace_id=p_workspace_id;
 if not found then return null;end if;
 d:=private.aqari_unwrap(row_data.payload);
 if private.aqari_manager(p_workspace_id) and private.aqari_can(p_workspace_id,'properties','read') then
  select coalesce(jsonb_agg(jsonb_build_array(p.name,'غير مدون',(select count(*) from public.aqari_units u where u.workspace_id=p.workspace_id and u.property_id=p.id),(select sum((r->>'current_rent_kd')::numeric) from jsonb_array_elements(s.content->'rows') r))),'[]') into source_properties
  from public.aqari_properties p join lateral(select st.content from public.aqari_property_statements st where st.workspace_id=p.workspace_id and st.property_id=p.id order by st.period desc limit 1)s on true
  where p.workspace_id=p_workspace_id and not exists(select 1 from jsonb_array_elements(coalesce(d->'properties','[]')) r where r->>0=p.name);
  d:=jsonb_set(d,'{properties}',coalesce(d->'properties','[]')||source_properties);
 end if;
 select coalesce(jsonb_object_agg(key,value),'{}') into filtered from jsonb_each(d) where private.aqari_can(p_workspace_id,private.aqari_state_section(key),'read');
 return jsonb_build_object('workspace_id',row_data.workspace_id,'payload',filtered,'revision',row_data.revision,'updated_by',row_data.updated_by,'updated_at',row_data.updated_at);
end $function$

CREATE OR REPLACE FUNCTION private.aqari_refresh_rent_due_schedule(w uuid, lid uuid)
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare l public.aqari_leases; changed integer:=0;
begin
  select * into l from public.aqari_leases where workspace_id=w and id=lid;
  if not found then return 0; end if;
  if l.status<>'signed' then
    delete from private.aqari_rent_due_periods where workspace_id=w and lease_id=lid;
    get diagnostics changed=row_count;
    return changed;
  end if;

  delete from private.aqari_rent_due_periods d
   where d.workspace_id=w and d.lease_id=lid
     and (d.period<date_trunc('month',l.start_date)::date or d.period>date_trunc('month',l.end_date)::date);

  insert into private.aqari_rent_due_periods(
    workspace_id,lease_id,period,due_amount,paid_amount,credit_amount,balance,status,generated_at,source_hash
  )
  select l.workspace_id,l.id,g.period,due.amount,paid.amount,credit.amount,
    due.amount-paid.amount-credit.amount,
    case
      when due.amount=0 then 'waived'
      when paid.amount+credit.amount=0 then 'due'
      when paid.amount+credit.amount<due.amount then 'partial'
      when paid.amount+credit.amount=due.amount then 'paid'
      else 'overpaid'
    end,
    now(),
    encode(sha256(convert_to(jsonb_build_object(
      'lease',l.id,'period',g.period,'due',due.amount,'paid',paid.amount,'credit',credit.amount,
      'snapshot',l.snapshot,'monthly_rent',l.monthly_rent
    )::text,'UTF8')),'hex')
  from lateral (
    select gs::date period
    from generate_series(
      date_trunc('month',l.start_date)::date,
      date_trunc('month',l.end_date)::date,
      interval '1 month'
    ) gs
  ) g
  cross join lateral (
    select private.aqari_reminder_due(l.snapshot,l.monthly_rent,g.period)::numeric(15,3) amount
  ) due
  cross join lateral (
    select coalesce(sum(p.amount),0)::numeric(15,3) amount
    from public.aqari_rent_payments p
    where p.workspace_id=w and p.lease_id=l.id and p.period=g.period
      and lower(coalesce(p.status,'')) not in ('cancelled','ملغى')
      and not exists(
        select 1 from private.aqari_receipt_cancellations c
        where c.workspace_id=w and c.payment_id=p.id
      )
  ) paid
  cross join lateral (
    select coalesce(sum(a.amount),0)::numeric(15,3) amount
    from private.aqari_credit_allocations a
    where a.workspace_id=w and a.lease_id=l.id and a.period=g.period
  ) credit
  on conflict(workspace_id,lease_id,period) do update set
    due_amount=excluded.due_amount,
    paid_amount=excluded.paid_amount,
    credit_amount=excluded.credit_amount,
    balance=excluded.balance,
    status=excluded.status,
    generated_at=excluded.generated_at,
    source_hash=excluded.source_hash;
  get diagnostics changed=row_count;
  return changed;
end $function$

CREATE OR REPLACE FUNCTION private.aqari_released_lease_guard()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare r private.aqari_vacating_settlements;
begin
 select * into r from private.aqari_vacating_settlements
  where workspace_id=old.workspace_id and lease_id=old.id and status='released';
 if not found then return case when tg_op='DELETE' then old else new end;end if;
 if tg_op='DELETE' then raise exception 'VACATING_CONTRACT_IMMUTABLE' using errcode='23514';end if;
 if new.workspace_id is distinct from old.workspace_id or new.external_ref is distinct from old.external_ref
  or new.tenant_id is distinct from old.tenant_id or new.unit_id is distinct from old.unit_id
  or new.contract_no is distinct from old.contract_no or new.start_date is distinct from old.start_date
  or new.end_date is distinct from old.end_date or new.monthly_rent is distinct from old.monthly_rent
  or new.deposit is distinct from old.deposit or new.snapshot is distinct from old.snapshot
  or new.import_source is distinct from old.import_source or new.vacated_on is distinct from r.vacate_date then
  raise exception 'VACATING_CONTRACT_IMMUTABLE' using errcode='23514';
 end if;
 new.status:='expired';new.vacated_on:=r.vacate_date;return new;
end $function$

CREATE OR REPLACE FUNCTION private.aqari_rent_receipt_pdf_source(p_workspace_id uuid, p_receipt_no text)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
 actor uuid:=auth.uid();
 payment_id uuid; lease_id uuid; lease_tenant uuid; payment_status text; receipt_snapshot jsonb; source_hash text;
begin
 if actor is null or btrim(coalesce(p_receipt_no,''))='' or length(p_receipt_no)>150 or p_receipt_no ~ '[[:cntrl:]]' then
  raise insufficient_privilege using message='ACCESS_DENIED';
 end if;
 select rp.id,rp.lease_id,rp.status,rp.receipt,l.tenant_id
 into payment_id,lease_id,payment_status,receipt_snapshot,lease_tenant
 from public.aqari_rent_payments rp
 join public.aqari_leases l on l.workspace_id=rp.workspace_id and l.id=rp.lease_id
 where rp.workspace_id=p_workspace_id and rp.reference=p_receipt_no;
 if not found then raise exception 'RECEIPT_NOT_FOUND' using errcode='P0002';end if;
 if not (private.aqari_can_lease(p_workspace_id,lease_id,'collections','read') or private.aqari_owns_tenant(p_workspace_id,lease_tenant)) then
  raise insufficient_privilege using message='ACCESS_DENIED';
 end if;
 if jsonb_typeof(receipt_snapshot) is distinct from 'object' or receipt_snapshot->>'id' is distinct from p_receipt_no then
  raise exception 'RECEIPT_SNAPSHOT_MISMATCH' using errcode='23514';
 end if;
 source_hash:=encode(sha256(convert_to(receipt_snapshot::text,'UTF8')),'hex');
 return jsonb_build_object('workspace_id',p_workspace_id,'receipt_no',p_receipt_no,'payment_id',payment_id,'lease_id',lease_id,'payment_status',payment_status,'snapshot_sha256',source_hash);
end $function$

CREATE OR REPLACE FUNCTION private.aqari_rent_receipt_pdf_system_source(p_workspace_id uuid, p_payment_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$ declare rp public.aqari_rent_payments%rowtype;l public.aqari_leases%rowtype;u public.aqari_units%rowtype;p public.aqari_properties%rowtype;t public.aqari_tenants%rowtype;saved jsonb;row_value jsonb;contract jsonb;ledger jsonb;amount_value numeric;begin
 select * into rp from public.aqari_rent_payments where workspace_id=p_workspace_id and id=p_payment_id;if not found or lower(coalesce(rp.status,'')) in('cancelled','canceled','ملغى') or exists(select 1 from private.aqari_receipt_cancellations c where c.workspace_id=rp.workspace_id and c.payment_id=rp.id) then raise check_violation using message='RECEIPT_PAYMENT_NOT_DELIVERABLE';end if;
 select * into l from public.aqari_leases where workspace_id=rp.workspace_id and id=rp.lease_id;if not found then raise check_violation using message='RECEIPT_LEASE_MISSING';end if;select * into u from public.aqari_units where workspace_id=l.workspace_id and id=l.unit_id;select * into p from public.aqari_properties where workspace_id=u.workspace_id and id=u.property_id;select * into t from public.aqari_tenants where workspace_id=l.workspace_id and id=l.tenant_id;if u.id is null or p.id is null or t.id is null then raise check_violation using message='RECEIPT_SCOPE_MISSING';end if;
 saved:=rp.receipt;ledger:=rp.record;row_value:=saved->'record';contract:=saved->'contract';if jsonb_typeof(saved)<>'object' or saved->>'template'<>'rent-voucher-v267-1' or saved->>'id'<>rp.reference or jsonb_typeof(row_value)<>'array' or jsonb_array_length(row_value)<>10 or jsonb_typeof(contract)<>'object' or jsonb_typeof(ledger)<>'object' or row_value->>0<>rp.reference or row_value->>1<>t.full_name or row_value->>4<>p.name or row_value->>6<>u.unit_no or row_value->>5<>rp.paid_at::text or row_value->>8<>to_char(rp.period,'YYYY-MM') or row_value->>9<>rp.payment_method or contract->>'id' is distinct from l.external_ref or contract->>'contract_no' is distinct from l.contract_no or contract->>'status'<>'signed' or contract->>'tenant'<>t.full_name or contract->>'property'<>p.name or contract->>'unit'<>u.unit_no or coalesce(ledger->>'receiptNo',ledger->>'voucherNo','')<>rp.reference or ledger->>'contractId' is distinct from l.external_ref or ledger->>'contractNo' is distinct from l.contract_no or ledger->>'tenant'<>t.full_name or ledger->>'property'<>p.name or ledger->>'unit'<>u.unit_no or ledger->>'period'<>to_char(rp.period,'YYYY-MM') or ledger->>'paidAt'<>rp.paid_at::text or ledger->>'status'<>row_value->>3 or ledger->>'method'<>rp.payment_method then raise check_violation using message='RECEIPT_SNAPSHOT_MISMATCH';end if;
 begin amount_value:=(row_value->>2)::numeric;exception when others then raise check_violation using message='RECEIPT_AMOUNT_INVALID';end;if amount_value<>rp.amount or coalesce((ledger->>'paid')::numeric,-1)<>rp.amount then raise check_violation using message='RECEIPT_AMOUNT_MISMATCH';end if;return jsonb_build_object('workspaceId',rp.workspace_id,'paymentId',rp.id,'receiptNo',rp.reference,'snapshotSha256',encode(sha256(convert_to(saved::text,'UTF8')),'hex'),'receipt',saved);end $function$

CREATE OR REPLACE FUNCTION private.aqari_rental_document_archive(w uuid, act text, d jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare row private.aqari_rental_document_archive;pid uuid;lid uuid;
begin
 if auth.uid() is null or not private.aqari_can(w,'contracts','read') then raise insufficient_privilege using message='ACCESS_DENIED';end if;
 if jsonb_typeof(d) is distinct from 'object' then raise invalid_parameter_value using message='INVALID_ARCHIVE_REQUEST';end if;
 if act='list' then
  pid:=nullif(d->>'property_id','')::uuid;lid:=nullif(d->>'lease_id','')::uuid;
  if pid is not null and not private.aqari_can_property(w,pid,'properties','read') then raise insufficient_privilege using message='ACCESS_DENIED';end if;
  if lid is not null and not private.aqari_can_lease(w,lid,'contracts','read') then raise insufficient_privilege using message='ACCESS_DENIED';end if;
  return jsonb_build_object('workspace_id',w,'user_id',auth.uid(),'items',coalesce((select jsonb_agg(to_jsonb(a)-'pdf_bytes'-'snapshot' order by issued_at desc) from private.aqari_rental_document_archive a
   where workspace_id=w and (pid is null or property_id=pid) and (lid is null or lease_id=lid) and private.aqari_can_property(w,property_id,'properties','read') and private.aqari_can_lease(w,lease_id,'contracts','read')),'[]'::jsonb));
 elsif act='get' then
  select * into row from private.aqari_rental_document_archive where workspace_id=w and id=(d->>'id')::uuid;
  if not found then raise no_data_found using message='ARCHIVED_DOCUMENT_NOT_FOUND';end if;
  if not private.aqari_can_property(w,row.property_id,'properties','read') or not private.aqari_can_lease(w,row.lease_id,'contracts','read') then raise insufficient_privilege using message='ACCESS_DENIED';end if;
  return jsonb_build_object('workspace_id',w,'user_id',auth.uid(),'record',(to_jsonb(row)-'pdf_bytes')||jsonb_build_object('pdf_base64',replace(encode(row.pdf_bytes,'base64'),E'\n','')));
 end if;
 raise invalid_parameter_value using message='INVALID_ARCHIVE_ACTION';
end $function$

CREATE OR REPLACE FUNCTION private.aqari_rental_document_source(w uuid, tid uuid, lid uuid, rid uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare l public.aqari_leases;u public.aqari_units;p public.aqari_properties;tn public.aqari_tenants;rp public.aqari_rent_payments;
 tv private.aqari_rental_template_versions;st private.aqari_system_rental_template_versions;c jsonb;src jsonb;template jsonb;state jsonb;scopes jsonb;ptype text;
begin
 if auth.uid() is null or not private.aqari_can_lease(w,lid,'contracts','read') then raise insufficient_privilege using message='ACCESS_DENIED';end if;
 select * into l from public.aqari_leases where workspace_id=w and id=lid;if not found then raise no_data_found using message='LEASE_NOT_FOUND';end if;
 select * into u from public.aqari_units where workspace_id=w and id=l.unit_id;
 select * into p from public.aqari_properties where workspace_id=w and id=u.property_id;
 select * into tn from public.aqari_tenants where workspace_id=w and id=l.tenant_id;
 if u.id is null or p.id is null or tn.id is null or not private.aqari_can_property(w,p.id,'properties','read') or not private.aqari_can_tenant(w,tn.id,'tenants','read') then raise insufficient_privilege using message='SOURCE_ACCESS_DENIED';end if;
 select private.aqari_unwrap(payload) into state from public.aqari_app_state where workspace_id=w;
 if (select count(*) from jsonb_array_elements(coalesce(state->'contractsV202','[]'))x where x->>'id' in(l.external_ref,l.id::text))<>1 then raise check_violation using message='CONTRACT_SOURCE_BINDING_MISMATCH';end if;
 select x into c from jsonb_array_elements(state->'contractsV202')x where x->>'id' in(l.external_ref,l.id::text);
 if c is distinct from l.snapshot or ((c->>'tenantId') is distinct from tn.external_ref and (c->>'tenantId') is distinct from tn.id::text)
  or (nullif(c->>'unitId','') is not null and c->>'unitId'<>u.id::text)
  or (nullif(c->>'propertyId','') is not null and c->>'propertyId'<>p.id::text) then raise check_violation using message='CONTRACT_SOURCE_BINDING_MISMATCH';end if;
 select * into tv from private.aqari_rental_template_versions where workspace_id=w and id=tid;
 if found then template:=private.aqari_rental_template_snapshot(tv);else
  select * into st from private.aqari_system_rental_template_versions where workspace_id=w and id=tid;
  if not found then raise no_data_found using message='PUBLISHED_TEMPLATE_REQUIRED';end if;template:=private.aqari_system_rental_template_snapshot(st);
 end if;
 select coalesce(property_type,'') into ptype from private.aqari_property_master where workspace_id=w and property_id=p.id;ptype:=coalesce(ptype,'');
 select coalesce(jsonb_agg(jsonb_build_object('id',s.id,'template_id',s.template_id,'revision',s.revision) order by s.id),'[]'::jsonb) into scopes
 from private.aqari_property_template_scopes s where s.workspace_id=w and s.kind=template->>'kind' and s.is_active and ((s.scope_kind='property' and s.property_id=p.id) or(s.scope_kind='property_type' and lower(s.property_type)=lower(ptype)));
 if jsonb_array_length(scopes)>0 and not exists(select 1 from jsonb_array_elements(scopes)x where x->>'template_id'=tid::text) then raise check_violation using message='CONTRACT_TEMPLATE_NOT_ALLOWED_FOR_PROPERTY';end if;
 if rid is not null then
  if not private.aqari_can(w,'collections','read') then raise insufficient_privilege using message='RECEIPT_ACCESS_DENIED';end if;
  select * into rp from public.aqari_rent_payments where workspace_id=w and id=rid and lease_id=l.id;
  if not found or coalesce(rp.status,'') not in('paid','partial','مدفوع','جزئي') or coalesce(rp.amount,0)<=0 or exists(select 1 from private.aqari_receipt_cancellations x where x.workspace_id=w and x.payment_id=rp.id) then raise check_violation using message='RECEIPT_SOURCE_BINDING_MISMATCH';end if;
 elsif template->>'kind'='rent_receipt' then raise check_violation using message='RECEIPT_REQUIRED';end if;
 src:=jsonb_build_object('template',template,'lease',to_jsonb(l),'contract',c,'property',private.aqari_property_master_snapshot(w,p.id),
  'unit',private.aqari_unit_master_snapshot(w,u.id),'property_row',to_jsonb(p),'unit_row',to_jsonb(u),'tenant',to_jsonb(tn),'template_scopes',scopes,'receipt',case when rid is null then 'null'::jsonb else to_jsonb(rp) end);
 return jsonb_build_object('workspace_id',w,'user_id',auth.uid(),'source',src,'source_sha256',encode(sha256(convert_to(src::text,'UTF8')),'hex'));
end $function$

CREATE OR REPLACE FUNCTION private.aqari_rental_templates_before_editor(w uuid, act text, d jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare r private.aqari_rental_template_versions;sr private.aqari_system_rental_template_versions;draft private.aqari_rental_template_drafts_v2;
 source jsonb;ident uuid;fid uuid;sid uuid;k text;kl text;ttl text;content jsonb;field_list jsonb;pres jsonb;part jsonb;rid uuid;expected integer;latest integer;manager boolean;actor text;why text;hash text;chash text;normalized jsonb;
begin
 if auth.uid() is null or not private.aqari_can(w,'contracts','read') then raise insufficient_privilege using message='ACCESS_DENIED';end if;
 manager:=private.aqari_manager(w) and private.aqari_can(w,'administration','write') and private.aqari_can(w,'contracts','write');
 if act='context' then return jsonb_build_object('workspace_id',w,'user_id',auth.uid(),'can_publish',manager,
  'revisable_ids',case when manager then coalesce((select jsonb_agg(id) from private.aqari_rental_template_versions where workspace_id=w),'[]'::jsonb) else '[]'::jsonb end,
  'items',coalesce((select jsonb_agg(item order by item->>'kind',item->>'family_id',(item->>'version')::int desc) from(
   select private.aqari_rental_template_snapshot(v) item from private.aqari_rental_template_versions v where workspace_id=w
   union all select private.aqari_system_rental_template_snapshot(s) from private.aqari_system_rental_template_versions s where workspace_id=w)q),'[]'::jsonb),
  'drafts',case when manager then coalesce((select jsonb_agg(private.aqari_template_draft_snapshot(q) order by updated_at desc) from private.aqari_rental_template_drafts_v2 q where workspace_id=w and status='draft'),'[]'::jsonb) else '[]'::jsonb end);end if;
 if jsonb_typeof(d) is distinct from 'object' or octet_length(d::text)>300000 then raise invalid_parameter_value using message='INVALID_TEMPLATE_REQUEST';end if;
 ident:=nullif(d->>'id','')::uuid;
 if act='get' then
  select * into r from private.aqari_rental_template_versions where workspace_id=w and id=ident;
  if found then return jsonb_build_object('workspace_id',w,'user_id',auth.uid(),'record',private.aqari_rental_template_snapshot(r));end if;
  select * into sr from private.aqari_system_rental_template_versions where workspace_id=w and id=ident;
  if not found then raise no_data_found using message='TEMPLATE_NOT_FOUND';end if;
  return jsonb_build_object('workspace_id',w,'user_id',auth.uid(),'record',private.aqari_system_rental_template_snapshot(sr));
 end if;
 if not manager then raise insufficient_privilege using message='إدارة نماذج العقود متاحة للمدير العام فقط.';end if;
 if act='history' then
  if exists(select 1 from private.aqari_rental_template_drafts_v2 where workspace_id=w and id=ident) then
   return jsonb_build_object('workspace_id',w,'user_id',auth.uid(),'revisions',coalesce((select jsonb_agg(to_jsonb(h)-'workspace_id'-'draft_id' order by revision desc) from private.aqari_rental_template_draft_history h where workspace_id=w and draft_id=ident),'[]'::jsonb));
  end if;
  select * into r from private.aqari_rental_template_versions where workspace_id=w and id=ident;
  if found then
   fid:=coalesce(r.family_id,private.aqari_template_family(w,r.kind));
   return jsonb_build_object('workspace_id',w,'user_id',auth.uid(),'revisions',coalesce((select jsonb_agg(jsonb_build_object('revision',v.version,'record',private.aqari_rental_template_snapshot(v),'recorded_at',v.published_at) order by v.version desc) from private.aqari_rental_template_versions v where workspace_id=w and (v.family_id=fid or(v.family_id is null and v.kind=r.kind and fid=private.aqari_template_family(w,r.kind)))),'[]'::jsonb));
  end if;
  select * into sr from private.aqari_system_rental_template_versions where workspace_id=w and id=ident;
  if not found then raise no_data_found using message='TEMPLATE_NOT_FOUND';end if;
  return jsonb_build_object('workspace_id',w,'user_id',auth.uid(),'revisions',jsonb_build_array(jsonb_build_object('revision',sr.version,'record',private.aqari_system_rental_template_snapshot(sr),'recorded_at',sr.imported_at)));
 end if;
 if act in('copy_draft','revise') then
  sid:=nullif(d->>'source_id','')::uuid;rid:=nullif(d->>'request_id','')::uuid;
  if ident is null or rid is null or sid is null or ident=sid then raise invalid_parameter_value using message='INVALID_TEMPLATE_COPY';end if;
  select * into draft from private.aqari_rental_template_drafts_v2 where workspace_id=w and id=ident;
  if found then
   if draft.request_id=rid and draft.created_by=auth.uid() then return jsonb_build_object('workspace_id',w,'user_id',auth.uid(),'record',private.aqari_template_draft_snapshot(draft));end if;
   raise unique_violation using message='TEMPLATE_COPY_ID_CONFLICT';
  end if;
  if act='copy_draft' then select private.aqari_template_draft_snapshot(q) into source from private.aqari_rental_template_drafts_v2 q where workspace_id=w and id=sid;end if;
  if source is null then
   select * into r from private.aqari_rental_template_versions where workspace_id=w and id=sid;
   if found then source:=private.aqari_rental_template_snapshot(r);else select * into sr from private.aqari_system_rental_template_versions where workspace_id=w and id=sid;if found then source:=private.aqari_system_rental_template_snapshot(sr);end if;end if;
  end if;
  if source is null then raise no_data_found using message='TEMPLATE_NOT_FOUND';end if;
  if act='revise' and r.id is null then raise invalid_parameter_value using message='REVISION_REQUIRES_PUBLISHED_USER_TEMPLATE';end if;
  fid:=case when act='copy_draft' then ident else coalesce(r.family_id,private.aqari_template_family(w,r.kind)) end;
  insert into private.aqari_rental_template_drafts_v2(id,workspace_id,kind,kind_label,title,fields,clauses,revision,request_id,created_by,updated_by,family_id,presentation,source_version_id)
  values(ident,w,source->>'kind',coalesce(source->>'kind_label',source->>'kind'),coalesce(d->>'title',source->>'title'),coalesce(source->'fields','[]'),source->'clauses',1,rid,auth.uid(),auth.uid(),fid,source->'presentation',case when act='revise' then r.id end) returning * into draft;
  return jsonb_build_object('workspace_id',w,'user_id',auth.uid(),'record',private.aqari_template_draft_snapshot(draft));
 end if;
 if act not in('save_draft','publish') then raise invalid_parameter_value using message='INVALID_TEMPLATE_ACTION';end if;
 k:=d->>'kind';kl:=d->>'kind_label';ttl:=d->>'title';content:=d->'clauses';field_list:=coalesce(d->'fields','[]'::jsonb);
 if ident is null or coalesce(k,'')!~'^[a-z0-9][a-z0-9_-]{0,63}$' or coalesce(length(btrim(kl)),0) not between 1 and 80 or ttl is null or length(ttl)>200
  or jsonb_typeof(content) is distinct from 'array' or jsonb_array_length(content)>50 or octet_length(content::text)>100000
  or jsonb_typeof(field_list) is distinct from 'array' or jsonb_array_length(field_list)>50 then raise invalid_parameter_value using message='INVALID_TEMPLATE_CONTENT';end if;
 for part in select value from jsonb_array_elements(content) loop
  if jsonb_typeof(part) is distinct from 'object' or exists(select 1 from jsonb_object_keys(part)x where x not in('title','text')) or jsonb_typeof(part->'title') is distinct from 'string' or jsonb_typeof(part->'text') is distinct from 'string' or length(part->>'title')>200 or length(part->>'text')>30000 then raise invalid_parameter_value using message='INVALID_TEMPLATE_CLAUSE';end if;
 end loop;
 for part in select value from jsonb_array_elements(field_list) loop
  if jsonb_typeof(part) is distinct from 'object' or exists(select 1 from jsonb_object_keys(part)x where x not in('key','label','type','required')) or coalesce(part->>'key','')!~'^[a-z][a-z0-9_]{1,49}$' or coalesce(length(btrim(part->>'label')),0) not between 1 and 100 or coalesce(part->>'type','') not in('text','number','date','money') or jsonb_typeof(part->'required') is distinct from 'boolean' then raise invalid_parameter_value using message='INVALID_TEMPLATE_FIELD';end if;
 end loop;
 if (select count(*) from jsonb_array_elements(field_list))<>(select count(distinct value->>'key') from jsonb_array_elements(field_list)) then raise invalid_parameter_value using message='DUPLICATE_TEMPLATE_FIELD';end if;
 if act='save_draft' then
  rid:=nullif(d->>'request_id','')::uuid;if rid is null or jsonb_typeof(d->'revision') is distinct from 'number' or d->>'revision'!~'^[0-9]+$' then raise invalid_parameter_value using message='INVALID_DRAFT_REQUEST';end if;expected:=(d->>'revision')::int;
  select * into draft from private.aqari_rental_template_drafts_v2 where workspace_id=w and id=ident for update;
  pres:=case when d ? 'presentation' then nullif(d->'presentation','null'::jsonb) else draft.presentation end;
  if not private.aqari_template_presentation_valid(pres,field_list) then raise invalid_parameter_value using message='INVALID_TEMPLATE_PRESENTATION';end if;
  if draft.id is null then
   fid:=coalesce(nullif(d->>'family_id','')::uuid,ident);
   if expected<>0 then raise serialization_failure using message='DRAFT_REVISION_CONFLICT';end if;
   if fid<>ident then raise invalid_parameter_value using message='USE_REVISE_FOR_TEMPLATE_FAMILY';end if;
   insert into private.aqari_rental_template_drafts_v2(id,workspace_id,kind,kind_label,title,fields,clauses,revision,request_id,created_by,updated_by,family_id,presentation)
   values(ident,w,k,kl,ttl,field_list,content,1,rid,auth.uid(),auth.uid(),fid,pres) returning * into draft;
  else
   if draft.request_id=rid then
    if draft.kind=k and draft.kind_label=kl and draft.title=ttl and draft.fields=field_list and draft.clauses=content and draft.presentation is not distinct from pres then return jsonb_build_object('workspace_id',w,'user_id',auth.uid(),'record',private.aqari_template_draft_snapshot(draft));end if;
    raise unique_violation using message='DRAFT_REQUEST_REUSED';
   end if;
   if draft.status<>'draft' or draft.revision<>expected then raise serialization_failure using message='DRAFT_REVISION_CONFLICT';end if;
   if d ? 'family_id' and nullif(d->>'family_id','')::uuid is distinct from coalesce(draft.family_id,draft.id) then raise check_violation using message='TEMPLATE_FAMILY_IMMUTABLE';end if;
   if draft.source_version_id is not null and draft.kind<>k then raise check_violation using message='TEMPLATE_FAMILY_KIND_IMMUTABLE';end if;
   update private.aqari_rental_template_drafts_v2 set kind=k,kind_label=kl,title=ttl,fields=field_list,clauses=content,presentation=pres,revision=revision+1,request_id=rid,updated_by=auth.uid(),updated_at=now() where id=ident returning * into draft;
  end if;
  return jsonb_build_object('workspace_id',w,'user_id',auth.uid(),'record',private.aqari_template_draft_snapshot(draft));
 end if;
 perform private.aqari_require_sensitive_aal2(w);
 if not private.aqari_template_tokens_valid(ttl,content,field_list) then raise invalid_parameter_value using message='INVALID_TEMPLATE_FIELD_TOKENS';end if;
 if d->'approved' is distinct from 'true'::jsonb or length(btrim(ttl))=0 or jsonb_array_length(content)=0 or exists(select 1 from jsonb_array_elements(content)x where length(btrim(x->>'title'))=0 or length(btrim(x->>'text'))=0) or content::text ~ '\{\{[[:space:]]*field_name[[:space:]]*\}\}' then raise invalid_parameter_value using message='REVIEW_COMPLETE_TEMPLATE_AND_PDF_FIRST';end if;
 why:=btrim(d->>'reason');sid:=nullif(d->>'source_draft_id','')::uuid;
 if sid is null or coalesce(length(why),0) not between 6 and 500 or jsonb_typeof(d->'expected_version') is distinct from 'number' or d->>'expected_version'!~'^[0-9]+$' then raise invalid_parameter_value using message='INVALID_TEMPLATE_APPROVAL';end if;
 perform 1 from public.aqari_app_state where workspace_id=w for update;if not found then raise no_data_found using message='WORKSPACE_NOT_FOUND';end if;
 select * into draft from private.aqari_rental_template_drafts_v2 where workspace_id=w and id=sid for update;
 pres:=case when d ? 'presentation' then nullif(d->'presentation','null'::jsonb) else draft.presentation end;fid:=coalesce(draft.family_id,draft.id);
 if draft.id is null or draft.kind<>k or draft.kind_label<>kl or draft.title<>ttl or draft.fields<>field_list or draft.clauses<>content or draft.presentation is distinct from pres or (d ? 'revision' and (d->>'revision')::int<>draft.revision) then raise serialization_failure using message='DRAFT_CHANGED_REVIEW_AGAIN';end if;
 if not private.aqari_template_presentation_valid(pres,field_list) then raise invalid_parameter_value using message='INVALID_TEMPLATE_PRESENTATION';end if;
 normalized:=jsonb_build_object('id',ident,'family_id',fid,'kind',k,'kind_label',kl,'title',ttl,'fields',field_list,'clauses',content,'presentation',pres,'source_draft_id',sid,'revision',draft.revision,'expected_version',(d->>'expected_version')::int,'reason',why,'approved',true);
 hash:=encode(sha256(convert_to(normalized::text,'UTF8')),'hex');
 select * into r from private.aqari_rental_template_versions where id=ident;
 if found then if r.workspace_id<>w or r.published_by<>auth.uid() or r.request_sha256<>hash then raise unique_violation using message='TEMPLATE_APPROVAL_REQUEST_REUSED';end if;return jsonb_build_object('workspace_id',w,'user_id',auth.uid(),'record',private.aqari_rental_template_snapshot(r));end if;
 if draft.status<>'draft' then raise serialization_failure using message='DRAFT_ALREADY_PUBLISHED';end if;
 select coalesce(max(v.version),0) into latest from private.aqari_rental_template_versions v where workspace_id=w and (v.family_id=fid or (v.family_id is null and v.kind=k and fid=private.aqari_template_family(w,k)));
 if latest<>(d->>'expected_version')::int then raise serialization_failure using message='TEMPLATE_VERSION_CONFLICT';end if;
 chash:=encode(sha256(convert_to((normalized-'id'-'source_draft_id'-'revision'-'expected_version'-'reason'-'approved')::text,'UTF8')),'hex');select display_name into actor from public.aqari_profiles where user_id=auth.uid();
 insert into private.aqari_rental_template_versions(id,workspace_id,family_id,kind,kind_label,version,title,fields,clauses,presentation,content_sha256,source_draft_v2_id,reason,request_sha256,published_by,published_by_name)
 values(ident,w,fid,k,kl,latest+1,ttl,field_list,content,pres,chash,sid,why,hash,auth.uid(),coalesce(actor,auth.uid()::text)) returning * into r;
 update private.aqari_rental_template_drafts_v2 set status='published',updated_by=auth.uid(),updated_at=now() where id=sid;
 return jsonb_build_object('workspace_id',w,'user_id',auth.uid(),'record',private.aqari_rental_template_snapshot(r));
end $function$

CREATE OR REPLACE FUNCTION private.aqari_rental_templates(w uuid, act text, d jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare result jsonb;record jsonb;
begin
 -- The existing implementation remains the sole authority for permissions,
 -- approval, idempotency and revisions. A validation exception below rolls
 -- back the entire delegated call, including its history/version writes.
 result:=private.aqari_rental_templates_before_editor(w,act,d);
 if act in('save_draft','publish','copy_draft','revise') then
  record:=result->'record';
  if record#>'{presentation,editor}' is not null and not private.aqari_template_editor_valid(record#>'{presentation,editor}',record->'clauses') then
   raise invalid_parameter_value using message='INVALID_TEMPLATE_PRESENTATION';
  end if;
 end if;
 return result;
end $function$

CREATE OR REPLACE FUNCTION private.aqari_require_sensitive_aal2(w uuid)
 RETURNS void
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
 recent_second_factor_at timestamptz;
 evaluation_time timestamptz := statement_timestamp();
begin
 if auth.uid() is null then raise insufficient_privilege using message='ACCESS_DENIED'; end if;
 if private.aqari_sensitive_actor(w) then
  if coalesce(auth.jwt()->>'aal','aal1')<>'aal2' then
   raise insufficient_privilege using message='MFA_REQUIRED';
  end if;
  select private.aqari_recent_second_factor_at() into recent_second_factor_at;
  if recent_second_factor_at is null
     or recent_second_factor_at < evaluation_time - interval '15 minutes'
     or recent_second_factor_at > evaluation_time + interval '1 minute' then
   raise insufficient_privilege using message='MFA_RECENT_REAUTH_REQUIRED';
  end if;
 end if;
end $function$

CREATE OR REPLACE FUNCTION private.aqari_require_unit_ready()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare readiness text;
begin
 if new.status in ('cancelled','expired') then return new;end if;
 -- Preserve existing leases and routine state projection/financial saves. A new
 -- lease, reactivation, progression from draft, move or date extension needs review.
 if tg_op='UPDATE' then
  if new.workspace_id=old.workspace_id and new.unit_id=old.unit_id and new.tenant_id=old.tenant_id
   and new.start_date>=old.start_date and new.end_date<=old.end_date
   and (new.status=old.status or (old.status not in ('draft','ready','cancelled','expired') and new.status not in ('draft','ready'))) then return new;end if;
 end if;
 -- Share a row lock with readiness recording so acceptance cannot race a
 -- readiness change. AFTER INSERT runs only for new rows, not UPSERT conflicts.
 perform 1 from public.aqari_units where workspace_id=new.workspace_id and id=new.unit_id for update;
 select r.state into readiness from private.aqari_unit_readiness r where r.workspace_id=new.workspace_id and r.unit_id=new.unit_id order by r.revision desc limit 1;
 if readiness is distinct from 'ready' then raise check_violation using message='UNIT_NOT_READY';end if;
 return new;
end$function$

CREATE OR REPLACE FUNCTION private.aqari_restrict_new_contract_kind()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
 d jsonb:=private.aqari_unwrap(new.payload);
 old_d jsonb:=private.aqari_unwrap(old.payload);
 c jsonb;
 previous jsonb;
begin
 for c in select value from jsonb_array_elements(coalesce(d->'contractsV202','[]'::jsonb)) loop
  previous:=null;
  select value into previous
   from jsonb_array_elements(coalesce(old_d->'contractsV202','[]'::jsonb))
   where value->>'id'=c->>'id'
   limit 1;
  if previous is not null then continue;end if;
  if c->>'source'='v267-cloud' and (
    coalesce(c->>'contractKind','') not in ('apartment','house','shop')
    or coalesce(c#>>'{contractTemplate,kind}','') not in ('apartment','house','shop')
  ) then
   raise check_violation using message='NEW_TRIAL_CONTRACT_KIND_MUST_BE_APARTMENT_HOUSE_OR_SHOP';
  end if;
 end loop;
 return new;
end $function$

CREATE OR REPLACE FUNCTION private.aqari_review_source_lease(p_workspace_id uuid, p_lease_id uuid, p_document_id uuid, p_action text, p_deposit numeric, p_note text, p_expected_revision bigint)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare l public.aqari_leases%rowtype; t public.aqari_tenants%rowtype; doc public.aqari_documents%rowtype;
 saved public.aqari_app_state%rowtype; d jsonb; next_snapshot jsonb; next_status text; review_id uuid; revision_after bigint;
begin
 if auth.uid() is null or not private.aqari_manager(p_workspace_id)
 or not private.aqari_can(p_workspace_id,'contracts','write') or not private.aqari_can(p_workspace_id,'documents','read')
 then raise exception 'ACCESS_DENIED' using errcode='42501';end if;
 if p_action is null or p_action not in ('approve','sign') or p_note is null or length(btrim(p_note)) not between 10 and 2000 then raise exception 'REVIEW_DETAILS_REQUIRED';end if;
 perform pg_advisory_xact_lock(hashtextextended(p_workspace_id::text,0));
 select * into strict saved from public.aqari_app_state where workspace_id=p_workspace_id for update;
 if saved.revision is distinct from p_expected_revision then raise exception 'REVISION_CONFLICT' using errcode='40001';end if;
 select * into strict l from public.aqari_leases where workspace_id=p_workspace_id and id=p_lease_id for update;
 if l.import_source is null then raise exception 'SOURCE_LEASE_REQUIRED';end if;
 if (p_action='approve' and l.status<>'draft') or (p_action='sign' and l.status<>'approved') then raise exception 'INVALID_REVIEW_TRANSITION';end if;
 select * into strict t from public.aqari_tenants where workspace_id=p_workspace_id and id=l.tenant_id;
 if nullif(btrim(t.full_name),'') is null or l.start_date is null or l.end_date is null or l.end_date<l.start_date
 or jsonb_array_length(coalesce(l.snapshot->'pending','[]'))>0 then raise exception 'SOURCE_FIELDS_PENDING';end if;
 if p_deposit is null or p_deposit<0 or p_deposit>999999999999.999 or p_deposit<>round(p_deposit,3) then raise exception 'DOCUMENTED_DEPOSIT_REQUIRED';end if;
 select * into strict doc from public.aqari_documents where workspace_id=p_workspace_id and id=p_document_id;
 if doc.status<>'uploaded' or doc.document_type<>'signed_contract' or doc.entity_type<>'lease' or doc.entity_ref<>l.external_ref
 or doc.checksum_sha256 is null or doc.size_bytes<=0 or not exists(select 1 from storage.objects where bucket_id=doc.storage_bucket and name=doc.storage_path)
 then raise exception 'VERIFIED_LEASE_DOCUMENT_REQUIRED';end if;
 if p_action='sign' and (p_deposit is distinct from l.deposit or not exists(select 1 from public.aqari_source_lease_reviews where workspace_id=p_workspace_id and lease_id=p_lease_id and action='approve' and document_id=p_document_id)) then raise exception 'APPROVED_DOCUMENT_REQUIRED';end if;
 next_status:=case p_action when 'approve' then 'approved' else 'signed' end;
 review_id:=gen_random_uuid();
 next_snapshot:=l.snapshot||jsonb_build_object('status',next_status,'deposit',p_deposit,'tenant',t.full_name,'tenantProfile',t.profile,
 'importStatus','reviewed','operationalReview',jsonb_build_object('id',review_id,'documentId',doc.id,'documentSha256',doc.checksum_sha256,'reviewedBy',auth.uid(),'reviewedAt',now(),'note',btrim(p_note),'action',p_action));
 -- Imported sourceValues/sourceReference remain intact; the dedicated audit retains before and after.
 update public.aqari_leases set status=next_status,deposit=p_deposit,snapshot=next_snapshot where workspace_id=p_workspace_id and id=p_lease_id;
 d:=private.aqari_unwrap(saved.payload);
 if (select count(*) from jsonb_array_elements(d->'contractsV202') x where x->>'id'=l.external_ref)<>1 then raise exception 'SOURCE_STATE_LINK_REQUIRED';end if;
 d:=jsonb_set(d,'{contractsV202}',(select jsonb_agg(case when value->>'id'=l.external_ref then next_snapshot else value end order by ordinality) from jsonb_array_elements(d->'contractsV202') with ordinality));
 -- Same locked transaction: projection verifies the reviewed snapshot against the lease row.
 update public.aqari_app_state set payload=d where workspace_id=p_workspace_id;
 select revision into revision_after from public.aqari_app_state where workspace_id=p_workspace_id;
 insert into public.aqari_source_lease_reviews(id,workspace_id,lease_id,document_id,action,reviewer_id,note,before_snapshot,after_snapshot)
 values(review_id,p_workspace_id,p_lease_id,p_document_id,p_action,auth.uid(),btrim(p_note),l.snapshot,next_snapshot);
 insert into public.aqari_operation_audit(workspace_id,user_id,action,revision) values(p_workspace_id,auth.uid(),'source_lease_'||p_action||':'||review_id::text,revision_after);
 return jsonb_build_object('lease_id',p_lease_id,'status',next_status,'review_id',review_id,'revision',revision_after);
end $function$

CREATE OR REPLACE FUNCTION private.aqari_run_maintenance_sla_escalations(p_now timestamp with time zone DEFAULT now())
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare r record;manager_id uuid;key text;notification_id uuid;inserted_count integer:=0;response_count integer:=0;resolution_count integer:=0;snap jsonb;
begin
 if p_now is null then raise invalid_parameter_value using message='INVALID_SLA_CLOCK';end if;
 for r in
  select t.*,s.escalation_channel,b.stage,b.threshold_minutes,b.breached_at
  from private.aqari_property_maintenance_tasks t
  join private.aqari_property_maintenance_sla s on s.workspace_id=t.workspace_id and s.property_id=t.property_id and s.is_active
  cross join lateral(
   select 'response'::text as stage,s.response_minutes as threshold_minutes,t.assigned_at+make_interval(mins=>s.response_minutes) as breached_at
   where t.assigned_at is not null and ((t.started_at is null and t.status='assigned' and p_now>=t.assigned_at+make_interval(mins=>s.response_minutes)) or (t.started_at is not null and t.started_at>=t.assigned_at+make_interval(mins=>s.response_minutes)))
   union all
   select 'resolution'::text,s.resolution_minutes,t.started_at+make_interval(mins=>s.resolution_minutes)
   where t.started_at is not null and ((t.completed_at is null and t.status='in_progress' and p_now>=t.started_at+make_interval(mins=>s.resolution_minutes)) or (t.completed_at is not null and t.completed_at>=t.started_at+make_interval(mins=>s.resolution_minutes)))
  ) b
 loop
  if exists(select 1 from private.aqari_maintenance_sla_escalations e where e.workspace_id=r.workspace_id and e.task_id=r.id and e.stage=r.stage) then continue;end if;
  select m.user_id into manager_id from public.aqari_memberships m where m.workspace_id=r.workspace_id and m.is_active and m.role::text in('owner','general_manager') order by case when m.role::text='general_manager' then 0 else 1 end,m.created_at limit 1;
  if manager_id is null then continue;end if;
  key:='maintenance-sla:'||r.id||':'||r.stage;notification_id:=gen_random_uuid();
  insert into private.aqari_notification_deliveries(id,workspace_id,kind,aggregate_id,recipient_id,channel,scheduled_for,idempotency_key) values(notification_id,r.workspace_id,'maintenance_sla_escalation',r.id::text,manager_id,r.escalation_channel,p_now,key) on conflict(workspace_id,idempotency_key) do nothing;
  select n.id into notification_id from private.aqari_notification_deliveries n where n.workspace_id=r.workspace_id and n.idempotency_key=key;
  snap:=jsonb_build_object('taskNo',r.task_no,'status',r.status,'assignedAt',r.assigned_at,'startedAt',r.started_at,'completedAt',r.completed_at,'dueOn',r.due_on,'stage',r.stage,'thresholdMinutes',r.threshold_minutes,'breachedAt',r.breached_at,'revisionAtDetection',r.revision);
  insert into private.aqari_maintenance_sla_escalations(workspace_id,property_id,task_id,task_revision,stage,threshold_minutes,breached_at,recipient_id,notification_id,snapshot) values(r.workspace_id,r.property_id,r.id,r.revision,r.stage,r.threshold_minutes,r.breached_at,manager_id,notification_id,snap) on conflict(workspace_id,task_id,stage) do nothing;
  if found then inserted_count:=inserted_count+1;if r.stage='response' then response_count:=response_count+1;else resolution_count:=resolution_count+1;end if;end if;
 end loop;
 return jsonb_build_object('preparedAt',p_now,'inserted',inserted_count,'response',response_count,'resolution',resolution_count);
end $function$

CREATE OR REPLACE FUNCTION private.aqari_server_mutation_audit_trigger()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  before_j jsonb:=case when tg_op in ('UPDATE','DELETE') then to_jsonb(old) end;
  after_j jsonb:=case when tg_op in ('INSERT','UPDATE') then to_jsonb(new) end;
  row_j jsonb:=coalesce(after_j,before_j);
  w uuid;
  entity text;
  actor uuid:=auth.uid();
  actor_name_value text;
  actor_role_value text;
  changes jsonb:='[]'::jsonb;
  before_hash text;
  after_hash text;
begin
  if coalesce(row_j->>'workspace_id','')='' then return coalesce(new,old); end if;
  w:=(row_j->>'workspace_id')::uuid;
  before_hash:=case when before_j is null then null else encode(sha256(convert_to(before_j::text,'UTF8')),'hex') end;
  after_hash:=case when after_j is null then null else encode(sha256(convert_to(after_j::text,'UTF8')),'hex') end;
  entity:=coalesce(nullif(row_j->>'id',''),nullif(row_j->>'user_id',''),nullif(row_j->>'document_no',''),nullif(row_j->>'external_ref',''),nullif(row_j->>'reference',''),'hash:'||substr(coalesce(after_hash,before_hash),1,24));
  if tg_op='UPDATE' then
    select coalesce(jsonb_agg(k order by k),'[]'::jsonb) into changes
    from (
      select key k from jsonb_object_keys(coalesce(before_j,'{}'::jsonb)) key
      union
      select key k from jsonb_object_keys(coalesce(after_j,'{}'::jsonb)) key
    ) q
    where before_j->q.k is distinct from after_j->q.k;
  end if;
  if actor is null then
    actor_name_value:='system';actor_role_value:=null;
  else
    select coalesce(nullif(p.display_name,''),actor::text) into actor_name_value from public.aqari_profiles p where p.user_id=actor;
    actor_name_value:=coalesce(actor_name_value,actor::text);
    select m.role::text into actor_role_value from public.aqari_memberships m where m.workspace_id=w and m.user_id=actor and m.is_active limit 1;
  end if;
  insert into private.aqari_server_mutation_audit(
    workspace_id,entity_schema,entity_table,entity_id,operation,actor_id,actor_name,actor_role,actor_kind,changed_fields,before_sha256,after_sha256
  ) values(
    w,tg_table_schema,tg_table_name,entity,tg_op,actor,actor_name_value,actor_role_value,case when actor is null then 'system' else 'authenticated' end,changes,before_hash,after_hash
  );
  return coalesce(new,old);
end $function$

CREATE OR REPLACE FUNCTION private.aqari_staff_account_preparations(w uuid, action text, data jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare actor uuid:=auth.uid();rid uuid;ident uuid;target_email text;label text;base_role text;why text;expected bigint;
 slug text;r private.aqari_staff_account_preparations;previous private.aqari_staff_preparation_audit;
 allowed private.aqari_allowed_users;before_value jsonb;answer jsonb;
begin
 if actor is null or not exists(select 1 from public.aqari_memberships m where m.workspace_id=w and m.user_id=actor and m.is_active and m.role::text='general_manager') then
  raise insufficient_privilege using message='ACCESS_DENIED';end if;
 if jsonb_typeof(data) is distinct from 'object' or action is null or action not in('list','prepare','cancel') then raise invalid_parameter_value using message='INVALID_STAFF_PREPARATION';end if;
 if action='list' then
  if data<>'{}'::jsonb then raise invalid_parameter_value using message='INVALID_STAFF_PREPARATION';end if;
  return jsonb_build_object('workspace_id',w,'user_id',actor,'items',coalesce((select jsonb_agg(private.aqari_staff_preparation_snapshot(p) order by p.created_at desc,p.id) from private.aqari_staff_account_preparations p where p.workspace_id=w),'[]'::jsonb));
 end if;
 -- Hold the authorizing membership throughout this transaction, including MFA.
 perform 1 from public.aqari_memberships m where m.workspace_id=w and m.user_id=actor and m.is_active and m.role::text='general_manager' for share;
 if not found then raise insufficient_privilege using message='ACCESS_DENIED';end if;
 perform private.aqari_require_sensitive_aal2(w);
 if jsonb_typeof(data->'request_id') is distinct from 'string' or jsonb_typeof(data->'reason') is distinct from 'string'
  or length(btrim(data->>'reason')) not between 3 and 500 then raise invalid_parameter_value using message='INVALID_STAFF_PREPARATION';end if;
 begin rid:=(data->>'request_id')::uuid;exception when invalid_text_representation then raise invalid_parameter_value using message='INVALID_STAFF_PREPARATION';end;
 if rid is null then raise invalid_parameter_value using message='INVALID_STAFF_PREPARATION';end if;
 why:=btrim(data->>'reason');
 perform pg_advisory_xact_lock(hashtextextended('aqari-staff-preparation-request:'||rid::text,0));
 select * into previous from private.aqari_staff_preparation_audit a where a.request_id=rid;
 if found then
  if previous.workspace_id<>w or previous.actor_id<>actor or previous.action<>action or previous.request_payload is distinct from data then raise serialization_failure using message='STAFF_PREPARATION_REQUEST_CONFLICT';end if;
  return previous.result;
 end if;
 select x.slug into slug from public.aqari_workspaces x where x.id=w for key share;
 if not found then raise insufficient_privilege using message='ACCESS_DENIED';end if;
 if action='prepare' then
  if exists(select 1 from jsonb_object_keys(data) k where k not in('request_id','email','display_name','role','reason'))
   or jsonb_typeof(data->'email') is distinct from 'string' or jsonb_typeof(data->'display_name') is distinct from 'string' or jsonb_typeof(data->'role') is distinct from 'string' then raise invalid_parameter_value using message='INVALID_STAFF_PREPARATION';end if;
  target_email:=lower(btrim(data->>'email'));label:=btrim(data->>'display_name');base_role:=data->>'role';
  if length(target_email)>254 or target_email!~'^[^[:space:]@]+@[^[:space:]@]+[.][^[:space:]@]+$'
   or length(label) not between 1 and 120 or base_role not in('viewer','accountant','property_manager') then raise invalid_parameter_value using message='INVALID_STAFF_PREPARATION';end if;
  perform pg_advisory_xact_lock(hashtextextended('aqari-staff-preparation:'||target_email,0));
  if exists(select 1 from auth.users u where lower(btrim(u.email))=target_email)
   or exists(select 1 from private.aqari_allowed_users a where a.email=target_email)
   or exists(select 1 from private.aqari_partner_access p where lower(btrim(p.email))=target_email)
   or exists(select 1 from public.aqari_tenants t where lower(btrim(t.email))=target_email)
   or exists(select 1 from private.aqari_staff_account_preparations p where p.email=target_email)
   then raise unique_violation using message='STAFF_EMAIL_UNAVAILABLE';end if;
  begin
   insert into private.aqari_allowed_users(email,display_name,role,workspace_slug,is_active)
   values(target_email,label,base_role::public.aqari_role,slug,true) returning * into allowed;
   insert into private.aqari_staff_account_preparations(workspace_id,email,display_name,role,request_id,created_by,allowlist_fingerprint)
   values(w,target_email,label,base_role::public.aqari_role,rid,actor,md5(to_jsonb(allowed)::text)) returning * into r;
  exception when unique_violation then raise unique_violation using message='STAFF_EMAIL_UNAVAILABLE';end;
 else
  if exists(select 1 from jsonb_object_keys(data) k where k not in('request_id','id','revision','reason'))
   or jsonb_typeof(data->'id') is distinct from 'string' or jsonb_typeof(data->'revision') is distinct from 'number'
   or coalesce(data->>'revision','')!~'^[1-9][0-9]{0,9}$' then raise invalid_parameter_value using message='INVALID_STAFF_PREPARATION';end if;
  begin ident:=(data->>'id')::uuid;exception when invalid_text_representation then raise invalid_parameter_value using message='INVALID_STAFF_PREPARATION';end;
  expected:=(data->>'revision')::bigint;
  select * into r from private.aqari_staff_account_preparations p where p.id=ident and p.workspace_id=w and p.created_by=actor;
  if not found then raise insufficient_privilege using message='STAFF_PREPARATION_NOT_CANCELLABLE';end if;
  perform pg_advisory_xact_lock(hashtextextended('aqari-staff-preparation:'||r.email,0));
  select * into r from private.aqari_staff_account_preparations p where p.id=ident and p.workspace_id=w and p.created_by=actor for update;
  if r.status='registered' or exists(select 1 from auth.users u where lower(btrim(u.email))=r.email) then raise invalid_parameter_value using message='STAFF_PREPARATION_ALREADY_REGISTERED';end if;
  if r.status<>'prepared' then raise invalid_parameter_value using message='STAFF_PREPARATION_NOT_CANCELLABLE';end if;
  if r.revision<>expected then raise serialization_failure using message='STAFF_PREPARATION_REVISION_CONFLICT';end if;
  select * into allowed from private.aqari_allowed_users a where a.email=r.email for update;
  if not found or md5(to_jsonb(allowed)::text) is distinct from r.allowlist_fingerprint then raise serialization_failure using message='STAFF_PREPARATION_ALLOWLIST_CHANGED';end if;
  before_value:=to_jsonb(r);
  update private.aqari_allowed_users set is_active=false where email=r.email;
  update private.aqari_staff_account_preparations set status='cancelled',revision=revision+1,request_id=rid,updated_at=now() where id=r.id returning * into r;
 end if;
 answer:=jsonb_build_object('workspace_id',w,'user_id',actor,'record',private.aqari_staff_preparation_snapshot(r));
 insert into private.aqari_staff_preparation_audit(workspace_id,preparation_id,action,actor_id,request_id,request_payload,reason,before_snapshot,after_snapshot,result)
 values(w,r.id,action,actor,rid,data,why,before_value,to_jsonb(r),answer);
 return answer;
end $function$

CREATE OR REPLACE FUNCTION private.aqari_staff_circular_guard()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
begin
 if tg_op='DELETE' then raise check_violation using message='CIRCULAR_HISTORY_IMMUTABLE';end if;
 if new.id<>old.id or new.workspace_id<>old.workspace_id or new.created_by<>old.created_by or new.created_at<>old.created_at or new.revision<>old.revision+1 then raise check_violation using message='INVALID_CIRCULAR_CHANGE';end if;
 if old.status<>'draft' and (old.status='archived' or new.status<>'archived' or (to_jsonb(new)-array['status','revision','updated_at']) is distinct from (to_jsonb(old)-array['status','revision','updated_at'])) then raise check_violation using message='PUBLISHED_CIRCULAR_IMMUTABLE';end if;
 return new;
end$function$

CREATE OR REPLACE FUNCTION private.aqari_staff_circulars_api(w uuid, action text, d jsonb DEFAULT '{}'::jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare n private.aqari_staff_circulars%rowtype;before_value jsonb;ident uuid;expected integer;who text;
 manager boolean;keys text[];targets uuid[];expiration timestamptz;why text:='';stamp timestamptz;
begin
 if auth.uid() is null or w is null or not exists(select 1 from public.aqari_memberships where workspace_id=w and user_id=auth.uid() and is_active) then raise insufficient_privilege using message='ACCESS_DENIED';end if;
 if action is null or action not in ('list','save','publish','archive','history','ack') or d is null or jsonb_typeof(d)<>'object' or octet_length(d::text)>65536 then raise invalid_parameter_value using message='INVALID_CIRCULAR_REQUEST';end if;
 keys:=case action when 'save' then array['id','revision','title','body','recipient_ids','expires_at'] when 'archive' then array['id','revision','reason'] when 'history' then array['id'] when 'list' then array[]::text[] else array['id','revision'] end;
 if exists(select 1 from jsonb_object_keys(d) k where not k=any(keys)) then raise invalid_parameter_value using message='INVALID_CIRCULAR_FIELDS';end if;
 manager:=private.aqari_manager(w) and private.aqari_can(w,'notifications','read');
 if action='list' then
  return jsonb_build_object('manager',manager,
   'staff',case when manager then coalesce((select jsonb_agg(jsonb_build_object('user_id',m.user_id,'name',coalesce(nullif(p.display_name,''),'موظف')) order by p.display_name,m.user_id) from public.aqari_memberships m left join public.aqari_profiles p on p.user_id=m.user_id where m.workspace_id=w and m.is_active),'[]') else '[]'::jsonb end,
   'notices',coalesce((select jsonb_agg(q.item order by q.updated_at desc,q.id) from (
    select x.id,x.updated_at,(case when manager then to_jsonb(x) else jsonb_build_object('id',x.id,'title',x.title,'body',x.body,'status',x.status,'revision',x.revision,'published_at',x.published_at,'expires_at',x.expires_at) end)||jsonb_build_object(
     'can_ack',x.status='published' and (x.expires_at is null or x.expires_at>now()) and exists(select 1 from private.aqari_staff_circular_recipients r where r.circular_id=x.id and r.notice_revision=x.published_revision and r.user_id=auth.uid()),
     'acknowledged_at',(select a.acknowledged_at from private.aqari_staff_circular_acknowledgements a where a.circular_id=x.id and a.notice_revision=x.published_revision and a.user_id=auth.uid()),
     'ack_count',case when manager then (select count(*) from private.aqari_staff_circular_acknowledgements a where a.circular_id=x.id and a.notice_revision=x.published_revision) else null end) item
    from private.aqari_staff_circulars x where x.workspace_id=w and (manager or (x.status='published' and x.published_at<=now() and (x.expires_at is null or x.expires_at>now()) and exists(select 1 from private.aqari_staff_circular_recipients r where r.circular_id=x.id and r.notice_revision=x.published_revision and r.user_id=auth.uid()))) order by x.updated_at desc,x.id limit 100
   )q),'[]'));
 end if;
 ident:=nullif(d->>'id','')::uuid;if ident is null then raise invalid_parameter_value using message='CIRCULAR_ID_REQUIRED';end if;
 if action='ack' then
  -- Lock membership and publication for the explicit acknowledgement transaction.
  perform 1 from public.aqari_memberships where workspace_id=w and user_id=auth.uid() and is_active for share;
  if not found then raise insufficient_privilege using message='ACCESS_DENIED';end if;
  select * into n from private.aqari_staff_circulars x where x.workspace_id=w and x.id=ident for share;
  if not found or n.status<>'published' or n.published_at>now() or (n.expires_at is not null and n.expires_at<=now()) or not exists(select 1 from private.aqari_staff_circular_recipients r where r.circular_id=n.id and r.notice_revision=n.published_revision and r.user_id=auth.uid()) then raise insufficient_privilege using message='ACCESS_DENIED';end if;
  expected:=nullif(d->>'revision','')::integer;if expected is distinct from n.published_revision then raise serialization_failure using message='REVISION_CONFLICT';end if;
  insert into private.aqari_staff_circular_acknowledgements(circular_id,notice_revision,user_id) values(n.id,n.published_revision,auth.uid()) on conflict do nothing;
  select acknowledged_at into stamp from private.aqari_staff_circular_acknowledgements a where a.circular_id=n.id and a.notice_revision=n.published_revision and a.user_id=auth.uid();
  return jsonb_build_object('acknowledged_at',stamp);
 end if;
 if not manager or (action<>'history' and not private.aqari_can(w,'notifications','write')) then raise insufficient_privilege using message='ACCESS_DENIED';end if;
 if action<>'history' then perform private.aqari_require_sensitive_aal2(w);end if;
 -- Serializes draft creation/retry as well as changes, without taking business-table locks.
 perform pg_advisory_xact_lock(hashtextextended('staff-circular:'||w::text||':'||ident::text,0));
 select * into n from private.aqari_staff_circulars x where x.workspace_id=w and x.id=ident for update;
 if action='history' then
  if n.id is null then raise insufficient_privilege using message='ACCESS_DENIED';end if;
  return jsonb_build_object('versions',coalesce((select jsonb_agg(to_jsonb(v) order by v.revision desc) from private.aqari_staff_circular_versions v where v.circular_id=n.id),'[]'),
   'recipients',coalesce((select jsonb_agg(jsonb_build_object('user_id',r.user_id,'user_name',r.user_name,'notice_revision',r.notice_revision,'acknowledged_at',a.acknowledged_at) order by r.user_name,r.user_id) from private.aqari_staff_circular_recipients r left join private.aqari_staff_circular_acknowledgements a using(circular_id,notice_revision,user_id) where r.circular_id=n.id),'[]'));
 end if;
 expected:=nullif(d->>'revision','')::integer;
 if action='save' then
  if jsonb_typeof(d->'title') is distinct from 'string' or jsonb_typeof(d->'body') is distinct from 'string' or length(btrim(d->>'title')) not between 1 and 200 or length(btrim(d->>'body')) not between 1 and 10000 or jsonb_typeof(d->'recipient_ids') is distinct from 'array' then raise check_violation using message='INVALID_CIRCULAR_CONTENT';end if;
  select array_agg(value::uuid order by value::uuid) into targets from jsonb_array_elements_text(d->'recipient_ids');
  if cardinality(targets) is null or cardinality(targets) not between 1 and 200 or array_position(targets,null) is not null or cardinality(targets)<>(select count(distinct x) from unnest(targets)x) or exists(select 1 from unnest(targets)t where not exists(select 1 from public.aqari_memberships m where m.workspace_id=w and m.user_id=t and m.is_active)) then raise check_violation using message='INVALID_CIRCULAR_RECIPIENTS';end if;
  expiration:=nullif(d->>'expires_at','')::timestamptz;
  if n.id is not null and n.status='draft' and n.revision=expected+1 and n.title=btrim(d->>'title') and n.body=btrim(d->>'body') and n.recipient_ids=targets and n.expires_at is not distinct from expiration then return to_jsonb(n);end if;
 elsif action='publish' and n.status='published' and n.revision=expected+1 then return to_jsonb(n);
 elsif action='archive' then
  why:=btrim(coalesce(d->>'reason',''));if length(why) not between 3 and 500 then raise check_violation using message='ARCHIVE_REASON_REQUIRED';end if;
  if n.status='archived' and n.revision=expected+1 and exists(select 1 from private.aqari_staff_circular_versions v where v.circular_id=n.id and v.revision=n.revision and v.action='archive' and v.reason=why) then return to_jsonb(n);end if;
 end if;
 if expected is distinct from coalesce(n.revision,0) then raise serialization_failure using message='REVISION_CONFLICT';end if;
 before_value:=case when n.id is null then null else to_jsonb(n) end;
 select coalesce(nullif(display_name,''),auth.uid()::text) into who from public.aqari_profiles where user_id=auth.uid();who:=coalesce(who,auth.uid()::text);
 if action='save' then
  if n.id is not null and n.status<>'draft' then raise check_violation using message='PUBLISHED_CIRCULAR_IMMUTABLE';end if;
  if n.id is null then insert into private.aqari_staff_circulars(id,workspace_id,title,body,recipient_ids,expires_at,created_by) values(ident,w,btrim(d->>'title'),btrim(d->>'body'),targets,expiration,auth.uid()) returning * into n;
  else update private.aqari_staff_circulars set title=btrim(d->>'title'),body=btrim(d->>'body'),recipient_ids=targets,expires_at=expiration,revision=revision+1,updated_at=now() where id=n.id returning * into n;end if;
 elsif action='publish' then
  if n.id is null or n.status<>'draft' then raise check_violation using message='CIRCULAR_DRAFT_REQUIRED';end if;
  if n.expires_at is not null and n.expires_at<=now() then raise check_violation using message='CIRCULAR_EXPIRED';end if;
  perform 1 from public.aqari_memberships m where m.workspace_id=w and m.user_id=any(n.recipient_ids) and m.is_active for share;
  if (select count(*) from public.aqari_memberships m where m.workspace_id=w and m.user_id=any(n.recipient_ids) and m.is_active)<>cardinality(n.recipient_ids) then raise check_violation using message='INVALID_CIRCULAR_RECIPIENTS';end if;
  update private.aqari_staff_circulars set status='published',published_at=now(),published_revision=revision+1,revision=revision+1,updated_at=now() where id=n.id returning * into n;
 else
  if n.id is null or n.status='archived' then raise check_violation using message='CIRCULAR_ARCHIVED';end if;
  update private.aqari_staff_circulars set status='archived',revision=revision+1,updated_at=now() where id=n.id returning * into n;
 end if;
 insert into private.aqari_staff_circular_versions(circular_id,revision,action,actor_id,actor_name,reason,before_snapshot,after_snapshot) values(n.id,n.revision,action,auth.uid(),who,why,before_value,to_jsonb(n));
 if action='publish' then insert into private.aqari_staff_circular_recipients(circular_id,notice_revision,user_id,user_name) select n.id,n.revision,m.user_id,coalesce(nullif(p.display_name,''),'موظف') from public.aqari_memberships m left join public.aqari_profiles p on p.user_id=m.user_id where m.workspace_id=w and m.user_id=any(n.recipient_ids) and m.is_active;end if;
 return to_jsonb(n);
end$function$

CREATE OR REPLACE FUNCTION private.aqari_staff_preparation_email_guard()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare target_email text:=lower(btrim(coalesce(new.email,'')));
begin
 if target_email='' then return new;end if;
 perform pg_advisory_xact_lock(hashtextextended('aqari-staff-preparation:'||target_email,0));
 if tg_table_schema='auth' and tg_op='INSERT' then return new;end if;
 if tg_table_schema='auth' and lower(btrim(coalesce(old.email,'')))=target_email then return new;end if;
 if exists(select 1 from private.aqari_staff_account_preparations p where p.email=target_email and p.status='prepared') then
  raise exception 'STAFF_EMAIL_UNAVAILABLE' using errcode='23505';
 end if;
 return new;
end $function$

CREATE OR REPLACE FUNCTION private.aqari_staff_preparation_registered()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare r private.aqari_staff_account_preparations;old_snapshot jsonb;bound_workspace uuid;allowed private.aqari_allowed_users;
begin
 select * into r from private.aqari_staff_account_preparations p where p.email=lower(btrim(coalesce(new.email,''))) and p.status='prepared' for update;
 if not found then return new;end if;
 select * into allowed from private.aqari_allowed_users where email=r.email;
 select id into bound_workspace from public.aqari_workspaces where slug=allowed.workspace_slug;
 if bound_workspace is distinct from r.workspace_id or md5(to_jsonb(allowed)::text) is distinct from r.allowlist_fingerprint
  or not exists(select 1 from public.aqari_memberships m where m.workspace_id=r.workspace_id and m.user_id=new.id and m.is_active and m.role=r.role)
  or exists(select 1 from public.aqari_portal_accounts a where a.user_id=new.id)
  or exists(select 1 from private.aqari_partner_access a where a.user_id=new.id)
  then raise exception 'STAFF_PREPARATION_BIND_FAILED' using errcode='42501';end if;
 old_snapshot:=to_jsonb(r);
 update private.aqari_staff_account_preparations set status='registered',registered_user_id=new.id,revision=revision+1,updated_at=now() where id=r.id returning * into r;
 insert into private.aqari_staff_preparation_audit(workspace_id,preparation_id,action,actor_id,reason,before_snapshot,after_snapshot)
 values(r.workspace_id,r.id,'registered',new.id,'Existing Auth signup completed for the prepared staff email.',old_snapshot,to_jsonb(r));
 return new;
end $function$

CREATE OR REPLACE FUNCTION private.aqari_staff_row_allowed(w uuid, k text, v jsonb, a text)
 RETURNS boolean
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare prop text;ref text;s text:=private.aqari_state_section(k);
begin
 if not private.aqari_staff_state_key(k) or private.aqari_staff_row_id(k,v) is null or not private.aqari_can(w,s,a) then return false;end if;
 if k in('tenantProfilesV267','tenants') then
  ref:=case when k='tenants' then v->>4 else v->>'id' end;
  return exists(select 1 from public.aqari_tenants t where t.workspace_id=w and t.external_ref=ref and private.aqari_can_tenant(w,t.id,s,a));
 elsif k='leases' then
  return exists(select 1 from public.aqari_leases l where l.workspace_id=w and l.external_ref=v->>4 and private.aqari_can_lease(w,l.id,s,a));
 end if;
 prop:=case when k='properties' then v->>0 when k='collections' then v->>4 when k='rentReceiptsV267' then v#>>'{contract,property}' else v->>'property' end;
 return exists(select 1 from public.aqari_properties p where p.workspace_id=w and p.name=prop and private.aqari_can_property(w,p.id,s,a));
end $function$

CREATE OR REPLACE FUNCTION private.aqari_system_rent_receipt_serial(p_w uuid, p_contract_ref text, p_operation_ref uuid, p_year integer)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare row_data private.aqari_rent_receipt_serial_reservations%rowtype;seq bigint;within_contract integer;result_no text;
begin
 if current_setting('role',true) is distinct from 'service_role' or p_operation_ref is null or btrim(coalesce(p_contract_ref,''))='' or p_year not between 2000 and 2200 then raise insufficient_privilege using message='SERVER_RECEIPT_SERIAL_DENIED';end if;
 select * into row_data from private.aqari_rent_receipt_serial_reservations r where r.operation_ref=p_operation_ref;if found then if row_data.workspace_id<>p_w or row_data.contract_ref<>p_contract_ref then raise check_violation using message='RECEIPT_SERIAL_SCOPE_MISMATCH';end if;return jsonb_build_object('receipt_no',row_data.receipt_no,'contract_sequence',row_data.contract_sequence);end if;
 perform pg_advisory_xact_lock(hashtextextended(p_w::text||':rent-receipt:'||p_contract_ref,0));select coalesce(max(r.contract_sequence),0)+1 into within_contract from private.aqari_rent_receipt_serial_reservations r where r.workspace_id=p_w and r.contract_ref=p_contract_ref;insert into private.aqari_global_serial_counters(kind,year,last_value) values('rent_receipt',p_year,0) on conflict(kind,year) do nothing;update private.aqari_global_serial_counters set last_value=last_value+1 where kind='rent_receipt' and year=p_year returning last_value into seq;if seq is null then raise exception 'RECEIPT_SERIAL_UNAVAILABLE';end if;result_no:='AQ-R-'||p_year::text||'-'||lpad(seq::text,8,'0');insert into private.aqari_rent_receipt_serial_reservations(receipt_no,workspace_id,contract_ref,operation_ref,year,global_serial,contract_sequence,reserved_by,reservation_actor_kind) values(result_no,p_w,p_contract_ref,p_operation_ref,p_year,seq,within_contract,null,'system') returning * into row_data;return jsonb_build_object('receipt_no',row_data.receipt_no,'contract_sequence',row_data.contract_sequence);
end $function$

CREATE OR REPLACE FUNCTION private.aqari_template_editor_valid(e jsonb, clauses jsonb DEFAULT NULL::jsonb)
 RETURNS boolean
 LANGUAGE plpgsql
 IMMUTABLE
 SET search_path TO ''
AS $function$
declare v jsonb;s jsonb;k text;prev jsonb:=null;ranges jsonb;role_name text;txt text;
begin
 if not private.aqari_editor_keys(e,array['version','style','ranges','page_breaks','trailing_blank_pages','logo','signers'],array['version']) or e->'version' is distinct from '1'::jsonb then return false;end if;
 if e ? 'style' and not private.aqari_editor_style_valid(e->'style') then return false;end if;
 if e ? 'ranges' then
  ranges:=e->'ranges';if jsonb_typeof(ranges) is distinct from 'array' then return false;end if;
  if jsonb_array_length(ranges)>300 then return false;end if;
  for v in select value from jsonb_array_elements(ranges) loop
   if not private.aqari_editor_keys(v,array['clause','part','start','end','style'],array['clause','part','start','end','style']) then return false;end if;
   if not private.aqari_editor_number(v->'clause',0,49,true) or coalesce(v->>'part','') not in('title','text')
    or not private.aqari_editor_number(v->'start',0,60000,true) or not private.aqari_editor_number(v->'end',1,60000,true)
    or not private.aqari_editor_style_valid(v->'style',true) then return false;end if;
   if (v->>'start')::numeric>=(v->>'end')::numeric then return false;end if;
   if clauses is not null then
    if jsonb_typeof(clauses) is distinct from 'array' then return false;end if;
    s:=clauses->(v->>'clause')::int;if jsonb_typeof(s->(v->>'part')) is distinct from 'string' then return false;end if;
    txt:=s->>(v->>'part');
    if not private.aqari_editor_source_boundary(txt,(v->>'start')::int) or not private.aqari_editor_source_boundary(txt,(v->>'end')::int) then return false;end if;
   end if;
  end loop;
  -- Preserve input range order, but reject overlap within any clause/part.
  for v in select value from jsonb_array_elements(ranges) order by (value->>'clause')::int,value->>'part',(value->>'start')::int loop
   if prev is not null and prev->'clause'=v->'clause' and prev->>'part'=v->>'part' and (prev->>'end')::int>(v->>'start')::int then return false;end if;prev:=v;
  end loop;
 end if;
 if e ? 'page_breaks' then
  s:=e->'page_breaks';if jsonb_typeof(s) is distinct from 'array' then return false;end if;
  if jsonb_array_length(s)>50 then return false;end if;prev:=null;
  for v in select value from jsonb_array_elements(s) loop
   if not private.aqari_editor_keys(v,array['clause','offset'],array['clause','offset']) or not private.aqari_editor_number(v->'clause',0,49,true) or not private.aqari_editor_number(v->'offset',0,60000,true) then return false;end if;
   if prev is not null and ((v->>'clause')::int<(prev->>'clause')::int or (v->>'clause')::int=(prev->>'clause')::int and (v->>'offset')::int<=(prev->>'offset')::int) then return false;end if;
   if clauses is not null then
    if jsonb_typeof(clauses) is distinct from 'array' or jsonb_typeof(clauses#>array[v->>'clause','text']) is distinct from 'string' then return false;end if;
    if not private.aqari_editor_source_boundary(clauses#>>array[v->>'clause','text'],(v->>'offset')::int) then return false;end if;
   end if;prev:=v;
  end loop;
 end if;
 if e ? 'trailing_blank_pages' and not private.aqari_editor_number(e->'trailing_blank_pages',0,10,true) then return false;end if;
 if e ? 'logo' then
  v:=e->'logo';if not private.aqari_editor_keys(v,array['x_mm','y_mm','width_mm','height_mm','repeat'],array['x_mm','y_mm','width_mm','height_mm','repeat']) then return false;end if;
  if not private.aqari_editor_number(v->'x_mm',8,190) or not private.aqari_editor_number(v->'y_mm',8,281) or not private.aqari_editor_number(v->'width_mm',12,100) or not private.aqari_editor_number(v->'height_mm',8,60) or coalesce(v->>'repeat','') not in('first','all') then return false;end if;
  if (v->>'x_mm')::numeric+(v->>'width_mm')::numeric>202.00000001 or (v->>'y_mm')::numeric+(v->>'height_mm')::numeric>289.00000001 then return false;end if;
 end if;
 if e ? 'signers' then
  v:=e->'signers';if not private.aqari_editor_keys(v,array['order','details'],array['order','details']) then return false;end if;
  if jsonb_typeof(v->'order') is distinct from 'array' or not private.aqari_editor_keys(v->'details',array['owner','tenant','receiver','accountant']) then return false;end if;
  if jsonb_array_length(v->'order')>4 or exists(select 1 from jsonb_array_elements(v->'order')x where x not in('"owner"','"tenant"','"receiver"','"accountant"')) or (select count(distinct x) from jsonb_array_elements(v->'order')x)<>jsonb_array_length(v->'order') then return false;end if;
  for role_name,s in select key,value from jsonb_each(v->'details') loop
   if not private.aqari_editor_keys(s,array['civil_id','nationality'],array['civil_id','nationality']) or jsonb_typeof(s->'civil_id') is distinct from 'boolean' or jsonb_typeof(s->'nationality') is distinct from 'boolean' then return false;end if;
  end loop;
 end if;
 return true;
end $function$

CREATE OR REPLACE FUNCTION private.aqari_template_presentation_valid_before_editor(p jsonb, f jsonb)
 RETURNS boolean
 LANGUAGE plpgsql
 IMMUTABLE
 SET search_path TO ''
AS $function$
declare t jsonb;k text;
begin
 if p is null or p='null'::jsonb or not(p ? 'typography') then
  return private.aqari_template_presentation_valid_before_typography(p,f);
 end if;
 if jsonb_typeof(p)<>'object' or octet_length(p::text)>65536 then return false;end if;
 t:=p->'typography';
 if jsonb_typeof(t) is distinct from 'object' then return false;end if;
 if not(t ?& array['font_pt','line_height','alignment','margin_mm'])
  or exists(select 1 from jsonb_object_keys(t)x where x not in('font_pt','line_height','alignment','margin_mm')) then return false;end if;
 foreach k in array array['font_pt','line_height','margin_mm'] loop
  if jsonb_typeof(t->k) is distinct from 'number' then return false;end if;
 end loop;
 if (t->>'font_pt')::numeric not between 10 and 18
  or (t->>'line_height')::numeric not between 1.2 and 2.2
  or (t->>'margin_mm')::numeric not between 12 and 25
  or coalesce(t->>'alignment','') not in('start','center','end','justify') then return false;end if;
 return private.aqari_template_presentation_valid_before_typography(p-'typography',f);
end $function$

CREATE OR REPLACE FUNCTION private.aqari_template_presentation_valid_before_typography(p jsonb, f jsonb)
 RETURNS boolean
 LANGUAGE plpgsql
 IMMUTABLE
 SET search_path TO ''
AS $function$
declare v jsonb;s jsonb;k text;role_name text;signer_part text;
begin
 if p is null or p='null'::jsonb then return true;end if;
 if jsonb_typeof(p)<>'object' or octet_length(p::text)>65536 or not (p ?& array['version','paper','language','logo','signers','placements']) or exists(select 1 from jsonb_object_keys(p)x where x not in('version','paper','language','logo','signers','placements'))
 or p->'version' is distinct from '1'::jsonb or p->>'paper' is distinct from 'A4' or coalesce(p->>'language','') not in('ar','en','bilingual') then return false;end if;
 if p ? 'logo' then
  s:=p->'logo';if jsonb_typeof(s)<>'object' or exists(select 1 from jsonb_object_keys(s)x where x not in('enabled','source')) or jsonb_typeof(s->'enabled') is distinct from 'boolean' or s->>'source' is distinct from 'property' then return false;end if;
 end if;
 if p ? 'signers' then
  s:=p->'signers';if jsonb_typeof(s)<>'object' or not(s ?& array['owner','tenant']) or exists(select 1 from jsonb_object_keys(s)x where x not in('owner','tenant','receiver','accountant')) then return false;end if;
  for v in select value from jsonb_each(s) loop
   if jsonb_typeof(v)<>'object' or exists(select 1 from jsonb_object_keys(v)x where x not in('name','signature','fingerprint')) or jsonb_typeof(v->'name') is distinct from 'boolean' or jsonb_typeof(v->'signature') is distinct from 'boolean' or jsonb_typeof(v->'fingerprint') is distinct from 'boolean' then return false;end if;
  end loop;
 end if;
 if p ? 'placements' then
  s:=p->'placements';if jsonb_typeof(s)<>'array' or jsonb_array_length(s)>120 then return false;end if;
  if (select count(*) from jsonb_array_elements(s))<>(select count(distinct x->>'id') from jsonb_array_elements(s)x) then return false;end if;
  for v in select value from jsonb_array_elements(s) loop
   if jsonb_typeof(v)<>'object' or exists(select 1 from jsonb_object_keys(v)x where x not in('id','field_key','page','x_mm','y_mm','width_mm','height_mm','font_pt','language'))
    or coalesce(v->>'id','')!~'^[a-zA-Z0-9_-]{1,64}$' or coalesce(v->>'language','') not in('ar','en','bilingual')
    or coalesce(v->>'page','')!~'^[0-9]+$' then return false;end if;
   foreach k in array array['page','x_mm','y_mm','width_mm','height_mm','font_pt'] loop if jsonb_typeof(v->k) is distinct from 'number' then return false;end if;end loop;
   if (v->>'page')::numeric not between 1 and 50 or (v->>'x_mm')::numeric<8 or (v->>'y_mm')::numeric<8 or (v->>'width_mm')::numeric<8 or (v->>'height_mm')::numeric<4
    or (v->>'x_mm')::numeric+(v->>'width_mm')::numeric>202 or (v->>'y_mm')::numeric+(v->>'height_mm')::numeric>289 or (v->>'font_pt')::numeric not between 8 and 36 then return false;end if;
   k:=coalesce(v->>'field_key','');
   if k!~'^[a-z][a-z0-9_]{1,49}$' or k in('field_name','__proto__','constructor','prototype') then return false;end if;
   if k~'^(owner|tenant|receiver|accountant)_(name|signature|fingerprint)$' and not exists(select 1 from jsonb_array_elements(f)x where x->>'key'=k) then
    role_name:=split_part(k,'_',1);signer_part:=split_part(k,'_',2);
    if p#>array['signers',role_name,signer_part] is distinct from 'true'::jsonb then return false;end if;
   elsif not exists(select 1 from jsonb_array_elements(f)x where x->>'key'=k) then return false;end if;
  end loop;
 end if;
 return true;
end $function$

CREATE OR REPLACE FUNCTION private.aqari_template_presentation_valid(p jsonb, f jsonb)
 RETURNS boolean
 LANGUAGE plpgsql
 IMMUTABLE
 SET search_path TO ''
AS $function$
declare extra_fields jsonb:=coalesce(f,'[]'::jsonb);role_name text;k text;
begin
 if p is null or p='null'::jsonb or not(p ? 'editor') then return private.aqari_template_presentation_valid_before_editor(p,f);end if;
 if jsonb_typeof(p) is distinct from 'object' or octet_length(p::text)>65536 or not private.aqari_template_editor_valid(p->'editor') then return false;end if;
 foreach role_name in array array['owner','tenant','receiver','accountant'] loop
  foreach k in array array['civil_id','nationality'] loop
   if p#>array['editor','signers','details',role_name,k]='true'::jsonb then extra_fields:=extra_fields||jsonb_build_array(jsonb_build_object('key',role_name||'_'||k));end if;
  end loop;
 end loop;
 -- Synthetic declarations are used only by validation; they are never stored.
 return private.aqari_template_presentation_valid_before_editor(p-'editor',extra_fields);
end $function$

CREATE OR REPLACE FUNCTION private.aqari_template_tokens_valid(title text, clauses jsonb, fields jsonb)
 RETURNS boolean
 LANGUAGE plpgsql
 IMMUTABLE
 SET search_path TO ''
AS $function$
declare txt text;token text[];k text;canonical text;seen text[]:='{}';
 aliases jsonb:='{"civil_id":"tenant_civil_id","nationality":"tenant_nationality","floor":"floor_no","tenant_passport":"tenant_passport_no","contract_start_date":"start_date","contract_end_date":"end_date","owner_representative_name":"representative_name"}';
begin
 for k in select x->>'key' from jsonb_array_elements(fields)x loop
  canonical:=coalesce(aliases->>k,k);
  if k in('field_name','constructor','prototype','__proto__') or canonical=any(seen) then return false;end if;seen:=array_append(seen,canonical);
 end loop;
 for txt in select title union all select x->>'title' from jsonb_array_elements(clauses)x union all select x->>'text' from jsonb_array_elements(clauses)x loop
  for token in select regexp_matches(txt,'\{\{([a-z][a-z0-9_]{1,49})\}\}','g') loop
   if not exists(select 1 from jsonb_array_elements(fields)x where x->>'key'=token[1]) then return false;end if;
  end loop;
  if regexp_replace(txt,'\{\{([a-z][a-z0-9_]{1,49})\}\}','','g') ~ '[{}]' then return false;end if;
 end loop;
 return true;
end $function$

